INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('nicepkg/ai-workflow/resource-scout', 'community', 'nicepkg', 'ai-workflow', 'nicepkg/ai-workflow', 'resource-scout', 0, 0, 39, '2026-03-08T01:57:15.296Z', '2026-03-08T02:01:14.036Z', '85e027b9ceca958179e7ad42cd391edb80063df47abd9ad786381307ca522ba9', '{"id":"nicepkg/ai-workflow/resource-scout","name":"resource-scout","description":{"en":"The resource-scout skill provides instant domain expertise for AI agents by searching and discovering existing Claude Code skills and MCP servers. This skill benefits developers by saving time and effort in re-teaching AI models.","zh":"Resource Scout 是一个快速搜索和发现现有 Claude Code 技能和 MCP 服务器的工具，支持 WebSearch、GitHub 和官方服务器。","ja":"Resource Scout は、Claude Code スキルと MCP サーバーを迅速に検索して発見するツールで、WebSearch、GitHub、公式サーバーをサポートしています。","ko":"Resource Scout는 Claude Code 기술 및 MCP 서버를 빠르게 검색하고 발견하는 도구로 WebSearch, GitHub 및 공식 서버를 지원합니다.","es":"Resource Scout es una habilidad que permite a los desarrolladores buscar y descubrir habilidades preconstruidas para Claude Code y servidores MCP antes de crear soluciones personalizadas.","fr":"Resource Scout est une compétence qui permet aux développeurs de rechercher et de découvrir des compétences préconstruites pour Claude Code et des serveurs MCP avant de créer des solutions personnalisées.","de":"Resource Scout ist eine Fähigkeit, die es Entwicklern ermöglicht, vorgefertigte Fähigkeiten für Claude Code und MCP-Server zu suchen und zu entdecken, bevor sie benutzerdefinierte Lösungen erstellen.","pt":"O Resource Scout é uma habilidade que permite aos desenvolvedores descobrir habilidades pré-construídas e servidores MCP com facilidade, melhorando a produtividade","ru":"Resource Scout - это навык, который позволяет разработчикам легко обнаруживать предварительно построенные навыки и сервера MCP, повышая производительность","ar":"Resource Scout هو مهارة يسمح للمطورين باكتشاف المهارات المسبقة والخادمات MCP بسهولة، مما يحسن الإنتاجية"},"seo":{"title":{"en":"resource-scout: Instant Domain Expertise for AI Agents | ...","zh":"Resource Scout 设置指南：AI 工具快速搜索","ja":"Resource Scout セットアップガイド：AI エージェントの迅速な検索","ko":"Resource Scout 설정 가이드: AI 에이전트快速 검색","es":"Guía de configuración de Resource Scout para agentes de i...","fr":"Guide de mise en route de Resource Scout pour les agents ...","de":"Einrichtungsleitfaden für Resource Scout für KI-Agents","pt":"Guia de Configuração do Resource Scout para Desenvolvedores","ru":"Настройка Resource Scout: Руководство для Разработчиков","ar":"دليل إعداد Resource Scout للطورين"},"description":{"en":"Discover 170+ pre-built skills for Claude Code, Cursor, Codex & 14+ AI tools with resource-scout. Learn how to search and utilize existing skills for instant...","zh":"Resource Scout 提供 170+ 预建技能，支持 Claude Code、Cursor、Codex 和 14+ AI 工具。快速搜索和发现现有技能","ja":"Resource Scout は 170+ の事前ビルド スキルを提供し、Claude Code、Cursor、Codex、14+ の AI エージェントをサポートします。迅速な検索と発見","ko":"Resource Scout는 170+의 사전 구축된 기술을 제공하며 Claude Code, Cursor, Codex 및 14+ AI 에이전트를 지원합니다. 빠른 검색 및 발견","es":"Descubre cómo utilizar Resource Scout para encontrar habilidades preconstruidas para Claude Code y 14+ herramientas de IA. Mejora tu productividad con nuestr...","fr":"Découvrez comment utiliser Resource Scout pour trouver des compétences préconstruites pour Claude Code et 14+ outils d''IA. Améliorez votre productivité avec ...","de":"Erfahren Sie, wie Sie Resource Scout verwenden, um vorgefertigte Fähigkeiten für Claude Code und 14+ KI-Tools zu finden. Verbessern Sie Ihre Produktivität mi...","pt":"Aprenda a utilizar o Resource Scout para descobrir habilidades pré-construídas e servidores MCP com facilidade. Melhore sua produtividade com nossa guia de c...","ru":"Узнайте, как использовать Resource Scout для поиска предварительно построенных навыков и серверов MCP. Улучшите свою производительность с нашей инструкцией","ar":"تعلم كيفية استخدام Resource Scout لاكتشاف المهارات المسبقة والخادمات MCP بسهولة. تحسين إنتاجيتك مع دليلنا"},"definition":{"en":"resource-scout is a skill that enables search and discovery of existing Claude Code skills and MCP servers, providing instant domain expertise for AI agents","zh":"Resource Scout 是一个 AI 工具，用于快速搜索和发现现有技能和 MCP 服务器","ja":"Resource Scout は、AI エージェントの迅速な検索と発見に使用されるツールです","ko":"Resource Scout는 빠른 검색 및 발견을 위해 사용되는 AI 에이전트 도구입니다","es":"Resource Scout es una herramienta de búsqueda que ayuda a los desarrolladores a encontrar habilidades preconstruidas para Claude Code y servidores MCP.","fr":"Resource Scout est un outil de recherche qui aide les développeurs à trouver des compétences préconstruites pour Claude Code et des serveurs MCP.","de":"Resource Scout ist ein Suchtool, das Entwicklern hilft, vorgefertigte Fähigkeiten für Claude Code und MCP-Server zu finden.","pt":"Resource Scout é uma habilidade que facilita a descoberta de habilidades pré-construídas e servidores MCP para desenvolvedores","ru":"Resource Scout - это навык, который облегчает поиск предварительно построенных навыков и серверов MCP для разработчиков","ar":"Resource Scout هو مهارة تسهل اكتشاف المهارات المسبقة والخادمات MCP للطورين"},"features":{"en":["Utilizes WebSearch with specific queries like `site:skillsmp.com [topic]` or `claude skill [topic]`","Leverages GitHub search with `awesome-claude-skills [topic]`","Browses skillhub.club and claudeskills.info for relevant skills","Supports MCP server search with `MCP server [tool/service name]`","Checks glama.ai/mcp/servers and mcpmarket.com for available MCP servers","References official GitHub repository at github.com/modelcontextprotocol/servers"],"zh":["支持 170+ 预建技能","快速搜索 Claude Code 技能","支持 MCP 服务器搜索","集成 WebSearch、GitHub 和官方服务器","支持 Claude Code、Cursor、Codex 和 14+ AI 工具"],"ja":["170+ の事前ビルド スキルをサポート","Claude Code スキルの迅速な検索","MCP サーバーの検索をサポート","WebSearch、GitHub、公式サーバーの統合","Claude Code、Cursor、Codex、14+ の AI エージェントをサポート"],"ko":["170+의 사전 구축된 기술 지원","Claude Code 기술의 빠른 검색","MCP 서버 검색 지원","WebSearch, GitHub 및 공식 서버 통합","Claude Code, Cursor, Codex 및 14+ AI 에이전트 지원"],"es":["Búsqueda de habilidades preconstruidas para Claude Code","Descubrimiento de servidores MCP","Integración con GitHub y skillhub.club","Compatibilidad con 14+ herramientas de IA","Búsqueda rápida con WebSearch y claude skill","Acceso a la comunidad de desarrolladores de Claude Code"],"fr":["Recherche de compétences préconstruites pour Claude Code","Découverte de serveurs MCP","Intégration avec GitHub et skillhub.club","Compatibilité avec 14+ outils d''IA","Recherche rapide avec WebSearch et claude skill","Accès à la communauté de développeurs de Claude Code"],"de":["Suche nach vorgefertigten Fähigkeiten für Claude Code","Entdeckung von MCP-Servern","Integration mit GitHub und skillhub.club","Kompatibilität mit 14+ KI-Tools","Schnellsuche mit WebSearch und claude skill","Zugang zur Entwicklergemeinschaft von Claude Code"],"pt":["Pesquisa de habilidades pré-construídas com Claude Code e Cursor","Descoberta de servidores MCP com Model Context Protocol","Integração com GitHub e glama.ai para busca de habilidades e servidores","Suporte a múltiplos ambientes de desenvolvimento, incluindo Codex e 14+ ferramentas de IA","Melhoria da produtividade com habilidades pré-construídas e servidores MCP","Compatibilidade com React, Python e CLI para desenvolvedores"],"ru":["Поиск предварительно построенных навыков с Claude Code и Cursor","Обнаружение серверов MCP с Model Context Protocol","Интеграция с GitHub и glama.ai для поиска навыков и серверов","Поддержка нескольких сред разработки, включая Codex и 14+ инструментов ИИ","Повышение производительности с предварительно построенными навыками и серверами MCP","Совместимость с React, Python и CLI для разработчиков"],"ar":["بحث المهارات المسبقة مع Claude Code و Cursor","اكتشاف الخادمات MCP مع بروتوكول سياق النموذج","التكامل مع GitHub و glama.ai للبحث عن المهارات والخادمات","دعم بيئات تطوير متعددة، بما في ذلك Codex و 14+ أدوات ذكاء اصطناعي","تحسين الإنتاجية مع المهارات المسبقة والخادمات MCP","التوافق مع React و Python و CLI للمطورين"]},"keywords":{"en":["how to use resource-scout","resource-scout setup guide","what is resource-scout","resource-scout alternative","resource-scout vs claude code","install resource-scout","resource-scout for AI agents","resource-scout and MCP servers","resource-scout and Claude Code skills"],"zh":["Resource Scout","AI 工具","Claude Code","MCP 服务器","快速搜索","预建技能","AI 技术","WebSearch","GitHub"],"ja":["Resource Scout","AI エージェント","Claude Code","MCP サーバー","迅速な検索","事前ビルド スキル","AI 技術","WebSearch","GitHub"],"ko":["Resource Scout","AI 에이전트","Claude Code","MCP 서버","빠른 검색","사전 구축된 기술","AI 기술","WebSearch","GitHub"],"es":["agentes de inteligencia artificial","herramientas de IA","Claude Code","servidores MCP","desarrollo de software","búsqueda de habilidades","integración con GitHub","compatibilidad con herramientas de IA","guía de configuración de Resource Scout"],"fr":["agents d''intelligence artificielle","outils d''IA","Claude Code","serveurs MCP","développement de logiciels","recherche de compétences","intégration avec GitHub","compatibilité avec outils d''IA","guide de mise en route de Resource Scout"],"de":["KI-Agents","KI-Tools","Claude Code","MCP-Server","Softwareentwicklung","Suche nach Fähigkeiten","Integration mit GitHub","Kompatibilität mit KI-Tools","Einrichtungsleitfaden für Resource Scout"],"pt":["Resource Scout","habilidades pré-construídas","servidores MCP","Claude Code","Cursor","Model Context Protocol","GitHub","glama.ai","desenvolvimento de software","produtividade","ferramentas de IA"],"ru":["Resource Scout","предварительно построенные навыки","сервера MCP","Claude Code","Cursor","Model Context Protocol","GitHub","glama.ai","разработка программного обеспечения","производительность","инструменты ИИ"],"ar":["Resource Scout","المهارات المسبقة","الخادمات MCP","Claude Code","Cursor","بروتوكول سياق النموذج","GitHub","glama.ai","تطوير البرمجيات","الإنتاجية","أدوات الذكاء الاصطناعي"]}},"owner":"nicepkg","repo":"ai-workflow","repoPath":"nicepkg/ai-workflow","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.296Z","topics":[],"category":"community","skillMd":{"name":"resource-scout","description":"Search and discover Claude Code skills and MCP servers from marketplaces, GitHub repositories, and registries. Use when (1) user asks to find skills for a specific task, (2) looking for MCP servers to connect external tools, (3) user mentions find skill, search MCP, discover tools, or what skills exist for X, (4) before creating a custom skill to check if one already exists.","bodyPreview":"# Resource Scout\n\nSearch and discover existing Claude Code skills and MCP servers before building custom solutions.\n\n## Quick Search Strategy\n\n**For Skills:**\n1. WebSearch: `site:skillsmp.com [topic]` or `claude skill [topic]`\n2. Check GitHub: `awesome-claude-skills [topic]`\n3. Browse: skillhub.club, claudeskills.info\n\n**For MCP:**\n1. WebSearch: `MCP server [tool/service name]`\n2. Check: glama.ai/mcp/servers, mcpmarket.com\n3. Official: github.com/modelcontextprotocol/servers\n\n## Skill Search Wor","body":"# Resource Scout\n\nSearch and discover existing Claude Code skills and MCP servers before building custom solutions.\n\n## Quick Search Strategy\n\n**For Skills:**\n1. WebSearch: `site:skillsmp.com [topic]` or `claude skill [topic]`\n2. Check GitHub: `awesome-claude-skills [topic]`\n3. Browse: skillhub.club, claudeskills.info\n\n**For MCP:**\n1. WebSearch: `MCP server [tool/service name]`\n2. Check: glama.ai/mcp/servers, mcpmarket.com\n3. Official: github.com/modelcontextprotocol/servers\n\n## Skill Search Workflow\n\n### Step 1: Define Need\n\nBefore searching, clarify:\n- What task needs to be accomplished?\n- What tools/services are involved?\n- Is it a common pattern (git, testing, API) or domain-specific?\n\n### Step 2: Search Marketplaces\n\n**Primary sources (largest catalogs):**\n\n| Source | URL | Best For |\n|--------|-----|----------|\n| SkillsMP | skillsmp.com | 71000+ skills, long-tail search |\n| SkillHub.club | skillhub.club | AI-evaluated, quality filter |\n| Claude Skills Hub | claudeskills.info | UI-friendly browsing |\n\n**Search patterns:**\n```\n# On SkillsMP\n[domain] skill          → \"marketing skill\", \"database skill\"\n[framework] claude      → \"react claude\", \"fastapi claude\"\n[task] automation       → \"deployment automation\"\n```\n\n### Step 3: Search GitHub\n\n**Curated lists:**\n- `github.com/keyuyuan/skillhub-awesome-skills` - 精选清单\n- `github.com/VoltAgent/awesome-claude-skills` - 生态大全\n- `github.com/ComposioHQ/awesome-claude-skills` - 大量通用技能\n\n**Ready-to-use repositories:**\n- `github.com/alirezarezvani/claude-skills` - Content/Marketing\n- `github.com/gked2121/claude-skills` - Workflow思维\n- `github.com/Microck/ordinary-claude-skills` - 超大集合\n- `github.com/sickn33/antigravity-awesome-skills` - 结构化\n\n**Search command:**\n```bash\n# Use WebSearch tool\nsite:github.com \"claude skill\" [topic]\nsite:github.com \"SKILL.md\" [topic]\n```\n\n### Step 4: Evaluate & Install\n\nWhen skill found:\n1. Check last update date (prefer recent)\n2. Review SKILL.md for quality\n3. Check if has scripts/references\n4. Install with skill-downloader or manual copy\n\n## MCP Server Search Workflow\n\n### Step 1: Identify Integration Need\n\nCommon patterns:\n- Database access → postgres, mysql, sqlite MCP\n- GitHub workflow → github MCP\n- Cloud services → AWS, GCP, Azure MCPs\n- Communication → slack, discord MCPs\n- File systems → filesystem MCP\n\n### Step 2: Search Official Sources\n\n**Primary:**\n- Official registry: `registry.modelcontextprotocol.io`\n- Official repo: `github.com/modelcontextprotocol/servers`\n\n**Directories:**\n| Source | URL | Features |\n|--------|-----|----------|\n| Glama | glama.ai/mcp/servers | Stars, downloads, updates |\n| MCP Market | mcpmarket.com | Skills + MCP combined |\n| mcpservers.org | mcpservers.org | Categorized |\n| PulseMCP | pulsemcp.com/servers | Daily updates |\n| Smithery | smithery.ai | Registry/distribution |\n\n### Step 3: Search GitHub\n\n```bash\n# Use WebSearch tool\nsite:github.com \"mcp server\" [service]\nsite:github.com \"@modelcontextprotocol\" [service]\n```\n\n**Awesome lists:**\n- `github.com/punkpeye/awesome-mcp-servers`\n- `github.com/wong2/awesome-mcp-servers`\n\n### Step 4: Verify & Configure\n\nWhen MCP found:\n1. Check compatibility (stdio vs HTTP)\n2. Review required environment variables\n3. Test connection locally\n4. Add to `.claude/settings.json`\n\n## Search by Category\n\n### Development Tools\n```\nSkills: \"code review skill\", \"git commit skill\", \"testing skill\"\nMCP: \"github mcp\", \"gitlab mcp\", \"jira mcp\"\n```\n\n### Databases\n```\nSkills: \"database skill\", \"sql skill\", \"migration skill\"\nMCP: \"postgres mcp\", \"mysql mcp\", \"mongodb mcp\"\n```\n\n### Content & Marketing\n```\nSkills: \"content creator skill\", \"seo skill\", \"social media skill\"\nMCP: \"wordpress mcp\", \"notion mcp\"\n```\n\n### Cloud & DevOps\n```\nSkills: \"deployment skill\", \"kubernetes skill\", \"terraform skill\"\nMCP: \"aws mcp\", \"gcp mcp\", \"azure mcp\"\n```\n\n### AI & Data\n```\nSkills: \"data analysis skill\", \"ml skill\"\nMCP: \"openai mcp\", \"huggingface mcp\"\n```\n\n## Complete Source Reference\n\nSee [references/sources.md](references/sources.md) for full directory of all skill and MCP sources with detailed descriptions.\n\n## Best Practices\n\n1. **Search before build** - Always check existing resources first\n2. **Prefer maintained** - Choose skills with recent updates\n3. **Check quality** - Review SKILL.md structure and content\n4. **Consider combining** - Multiple simple skills > one complex custom\n5. **Verify security** - Review MCP permissions and token scopes\n"},"lastSynced":"2026-03-08T02:01:14.036Z","agentAnalysis":{"suitability":{"en":"Perfect for Developer Agents needing instant domain expertise and access to existing Claude Code skills and MCP servers.","zh":"非常适合需要即时领域专业知识并访问现有 Claude Code 技能和 MCP 服务器的 Developer Agents。","ja":"開発者エージェントが即時のドメインの専門知識と既存の Claude Code スキルおよび MCP サーバーにアクセスする必要がある場合に最適です。","ko":"즉각적인 도메인 전문 지식과 기존 Claude Code 스킬 및 MCP 서버에 액세스해야 하는 개발자 에이전트에 적합합니다.","es":"Perfecto para Agentes de Desarrollador que necesitan experiencia instantánea en dominio y acceso a habilidades de Claude Code existentes y servidores MCP.","fr":"Parfait pour les agents de développement ayant besoin d''une expertise de domaine instantanée et d''un accès aux compétences Claude Code existantes et aux serveurs MCP.","de":"Perfekt für Entwickleragenten, die sofortige Domänenexpertise und Zugriff auf vorhandene Claude Code-Fähigkeiten und MCP-Server benötigen.","pt":"Perfeito para Agentes de Desenvolvedor que precisam de especialização de domínio instantânea e acesso às habilidades de código Claude existentes e servidores MCP.","ru":"Идеально подходит для агентов-разработчиков, которым необходимы мгновенные знания в конкретной области и доступ к существующим навыкам кода Claude и серверам MCP.","ar":"مثالي لعميل المطور الذين يحتاجون إلى خبرة مجال فوري ووصول إلى مهارات كلود كود الحالية وخادمات MCP."},"recommendation":{"en":"Empowers agents to discover and leverage existing Claude Code skills and MCP servers using web search, GitHub, and specialized platforms like skillhub.club and glama.ai, streamlining development with Model Context Protocol (MCP) and Claude skills.","zh":"赋予代理发现和利用现有的 Claude Code 技能和 MCP 服务器的能力，使用网络搜索、GitHub 和专门的平台，如 skillhub.club 和 glama.ai，通过 Model Context Protocol (MCP) 和 Claude 技能简化开发。","ja":"Web 検索、GitHub、および skillhub.club や glama.ai などの専用プラットフォームを使用して、既存の Claude Code スキルと MCP サーバーを発見して活用できるようにエージェントをEmpowerし、Model Context Protocol (MCP) と Claude スキルで開発を最適化します。","ko":"웹 검색, GitHub 및 skillhub.club 및 glama.ai 같은 전문 플랫폼을 사용하여 기존 Claude Code 스킬 및 MCP 서버를 발견하고 활용할 수 있는 에이전트를赋予权限하고 Model Context Protocol (MCP) 및 Claude 스킬을 통해 개발을 최적화합니다.","es":"Habilita a los agentes a descubrir y aprovechar las habilidades de Claude Code existentes y los servidores MCP utilizando la búsqueda web, GitHub y plataformas especializadas como skillhub.club y glama.ai, simplificando el desarrollo con el Protocolo de Contexto de Modelo (MCP) y las habilidades de Claude.","fr":"Permet aux agents de découvrir et d''exploiter les compétences Claude Code existantes et les serveurs MCP en utilisant la recherche web, GitHub et des plateformes spécialisées comme skillhub.club et glama.ai, rationalisant le développement avec le Protocole de Contexte de Modèle (MCP) et les compétences de Claude.","de":"Ermöglicht es Agenten, bestehende Claude Code-Fähigkeiten und MCP-Server mithilfe von Web-Suche, GitHub und spezialisierten Plattformen wie skillhub.club und glama.ai zu entdecken und zu nutzen, wodurch die Entwicklung mit dem Modellkontextprotokoll (MCP) und den Fähigkeiten von Claude rationalisiert wird.","pt":"Permite que os agentes descubram e utilizem habilidades de código Claude existentes e servidores MCP usando a pesquisa na web, GitHub e plataformas especializadas como skillhub.club e glama.ai, agilizando o desenvolvimento com Protocolo de Contexto de Modelo (MCP) e habilidades Claude.","ru":"Позволяет агентам обнаруживать и использовать существующие навыки кода Claude и серверы MCP с помощью поиска в интернете, GitHub и специализированных платформ, таких как skillhub.club и glama.ai, оптимизируя разработку с помощью Протокола контекста модели (MCP) и навыков Claude.","ar":"يتمكن العملاء من اكتشاف واستخدام مهارات كلود كود الحالية وخادمات MCP باستخدام البحث على الويب و GitHub ومنصات متخصصة مثل skillhub.club و glama.ai، مما يسرع من التطوير باستخدام بروتوكول سياق النموذج (MCP) ومهارات كلود."},"useCases":{"en":["Searching for existing Claude Code skills to avoid redundant development","Discovering MCP servers for integration with custom solutions","Browsing skill repositories like skillhub.club for inspiration and reference"],"zh":["搜索现有的 Claude Code 技能以避免冗余开发","发现 MCP 服务器以便与自定义解决方案集成","浏览技能仓库，如 skillhub.club，获取灵感和参考"],"ja":["冗長な開発を避けるために既存の Claude Code スキルを検索する","カスタム ソリューションとの統合のために MCP サーバーを発見する","skillhub.club などのスキル リポジトリを参照してインスピレーションを得る"],"ko":["중복 개발을 피하기 위해 기존 Claude Code 스킬을 검색합니다.","사용자 지정 솔루션과 통합하기 위해 MCP 서버를 발견합니다.","영감과 참조를 위해 skillhub.club 같은 스킬 저장소를 브라우징합니다."],"es":["Buscar habilidades de Claude Code existentes para evitar un desarrollo redundante","Descubrir servidores MCP para integrarlos con soluciones personalizadas","Navegar por repositorios de habilidades como skillhub.club para inspiración y referencia"],"fr":["Rechercher des compétences Claude Code existantes pour éviter un développement redondant","Découvrir des serveurs MCP pour les intégrer à des solutions personnalisées","Parcourir des référentiels de compétences comme skillhub.club pour s''inspirer et se référer"],"de":["Suchen nach bestehenden Claude Code-Fähigkeiten, um redundante Entwicklung zu vermeiden","MCP-Server entdecken, um sie in benutzerdefinierte Lösungen zu integrieren","Durchstöbern von Fähigkeits-Repositorys wie skillhub.club für Inspiration und Referenz"],"pt":["Pesquisar habilidades de código Claude existentes para evitar desenvolvimento redundante","Descobrir servidores MCP para integração com soluções personalizadas","Navegar por repositórios de habilidades como skillhub.club para inspiração e referência"],"ru":["Поиск существующих навыков кода Claude для избежания избыточного развития","Обнаружение серверов MCP для интеграции с индивидуальными решениями","Просмотр репозиториев навыков, таких как skillhub.club, для вдохновения и ссылки"],"ar":["بحث مهارات كلود كود الحالية لتجنب التطوير الزائد","اكتشاف خادمات MCP للتكامل مع الحلول المخصصة","استعراض مستودعات المهارات مثل skillhub.club للتنشئة والإشارة"]},"limitations":{"en":["Requires internet access for web search and GitHub lookup","Limited to discovering existing Claude Code skills and MCP servers","Dependence on the quality and availability of skills and servers on platforms like skillhub.club and glama.ai"],"zh":["需要互联网访问以进行网络搜索和 GitHub 查找","仅限发现现有的 Claude Code 技能和 MCP 服务器","依赖于 skillhub.club 和 glama.ai 等平台上的技能和服务器的质量和可用性"],"ja":["Web 検索と GitHub の検索のためにインターネット接続が必要","既存の Claude Code スキルと MCP サーバーのみを検索可能","skillhub.club や glama.ai などのプラットフォーム上のスキルとサーバーの品質と可用性に依存する"],"ko":["웹 검색 및 GitHub 조회를 위해 인터넷 액세스가 필요합니다.","기존 Claude Code 스킬 및 MCP 서버만 검색할 수 있습니다.","skillhub.club 및 glama.ai와 같은 플랫폼에서 스킬 및 서버의 품질 및 가용성에 의존합니다."],"es":["Requiere acceso a Internet para búsqueda web y búsqueda en GitHub","Limitado a la detección de habilidades de Claude Code existentes y servidores MCP","Dependencia de la calidad y disponibilidad de habilidades y servidores en plataformas como skillhub.club y glama.ai"],"fr":["Nécessite un accès à Internet pour la recherche web et la recherche sur GitHub","Limité à la découverte de compétences Claude Code existantes et de serveurs MCP","Dépendance de la qualité et de la disponibilité des compétences et des serveurs sur des plateformes comme skillhub.club et glama.ai"],"de":["Benötigt Internetzugang für Web-Suche und GitHub-Suche","Begrenzt auf die Entdeckung von bestehenden Claude Code-Fähigkeiten und MCP-Servern","Abhängigkeit von der Qualität und Verfügbarkeit von Fähigkeiten und Servern auf Plattformen wie skillhub.club und glama.ai"],"pt":["Requer acesso à internet para pesquisa na web e lookup no GitHub","Limitado a descobrir habilidades de código Claude existentes e servidores MCP","Dependência da qualidade e disponibilidade de habilidades e servidores em plataformas como skillhub.club e glama.ai"],"ru":["Требуется доступ к интернету для поиска в интернете и поиска в GitHub","Ограничен обнаружением существующих навыков кода Claude и серверов MCP","Зависимость от качества и доступности навыков и серверов на платформах, таких как skillhub.club и glama.ai"],"ar":["يتطلب الوصول إلى الإنترنت للبحث على الويب والبحث في GitHub","محدود باكتشاف مهارات كلود كود الحالية وخادمات MCP","اعتماد على جودة ومدى توفر المهارات وخادمات على منصات مثل skillhub.club و glama.ai"]},"version":4},"contentHash":"85e027b9ceca958179e7ad42cd391edb80063df47abd9ad786381307ca522ba9","qualityScore":39}');
