INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('nicepkg/ai-workflow/resource-scout', 'resource-scout', 'nicepkg', 'ai-workflow', 'community', 'resource-scout nicepkg ai-workflow community The resource-scout skill provides instant domain expertise for AI agents by searching and discovering existing Claude Code skills and MCP servers. This skill benefits developers by saving time and effort in re-teaching AI models. Resource Scout 是一个快速搜索和发现现有 Claude Code 技能和 MCP 服务器的工具，支持 WebSearch、GitHub 和官方服务器。 Resource Scout は、Claude Code スキルと MCP サーバーを迅速に検索して発見するツールで、WebSearch、GitHub、公式サーバーをサポートしています。 Resource Scout는 Claude Code 기술 및 MCP 서버를 빠르게 검색하고 발견하는 도구로 WebSearch, GitHub 및 공식 서버를 지원합니다. Resource Scout es una habilidad que permite a los desarrolladores buscar y descubrir habilidades preconstruidas para Claude Code y servidores MCP antes de crear soluciones personalizadas. Resource Scout est une compétence qui permet aux développeurs de rechercher et de découvrir des compétences préconstruites pour Claude Code et des serveurs MCP avant de créer des solutions personnalisées. Resource Scout ist eine Fähigkeit, die es Entwicklern ermöglicht, vorgefertigte Fähigkeiten für Claude Code und MCP-Server zu suchen und zu entdecken, bevor sie benutzerdefinierte Lösungen erstellen. O Resource Scout é uma habilidade que permite aos desenvolvedores descobrir habilidades pré-construídas e servidores MCP com facilidade, melhorando a produtividade Resource Scout - это навык, который позволяет разработчикам легко обнаруживать предварительно построенные навыки и сервера MCP, повышая производительность Resource Scout هو مهارة يسمح للمطورين باكتشاف المهارات المسبقة والخادمات MCP بسهولة، مما يحسن الإنتاجية how to use resource-scout resource-scout setup guide what is resource-scout resource-scout alternative resource-scout vs claude code install resource-scout resource-scout for AI agents resource-scout and MCP servers resource-scout and Claude Code skills Resource Scout AI 工具 Claude Code MCP 服务器 快速搜索 预建技能 AI 技术 WebSearch GitHub Utilizes WebSearch with specific queries like `site:skillsmp.com [topic]` or `claude skill [topic]` Leverages GitHub search with `awesome-claude-skills [topic]` Browses skillhub.club and claudeskills.info for relevant skills Supports MCP server search with `MCP server [tool/service name]` Checks glama.ai/mcp/servers and mcpmarket.com for available MCP servers References official GitHub repository at github.com/modelcontextprotocol/servers resource-scout is a skill that enables search and discovery of existing Claude Code skills and MCP servers, providing instant domain expertise for AI agents');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('AstraBert/scpr/web-scraping', 'community', 'AstraBert', 'scpr', 'AstraBert/scpr', 'web-scraping', 0, 0, 39, '2026-03-08T01:57:15.296Z', '2026-03-08T02:01:15.975Z', '6dc2339997a287c4c978537f6f6b4889f09ddb191ea0a85d598fc9654abed580', '{"id":"AstraBert/scpr/web-scraping","name":"web-scraping","description":{"en":"The web-scraping skill allows developers to scrape web pages using the scpr command line interface, supporting recursive and parallel scraping. It benefits developers and coding agents.","zh":"scpr命令行界面用于Web Scraping，支持基本抓取、递归抓取和并行抓取","ja":"scpr CLIはWeb Scrapingを実現するツールで、基本的な使い方から並行処理までサポートしています","ko":"scpr 명령줄 인터페이스는 Web Scraping을 위한 도구로 기본적인抓取부터並行処理까지 지원합니다","es":"La herramienta de web-scraping con CLI permite extraer datos de sitios web de manera rápida y sencilla","fr":"L''outil de web-scraping avec l''interface de ligne de commande permet d''extraire des données de sites web de manière rapide et simple","de":"Das Web-Scraping-Tool mit CLI ermöglicht die schnelle und einfache Extraktion von Daten von Websites","pt":"A ferramenta de web scraping com CLI permite extrair dados de páginas web de forma rápida e eficiente","ru":"Инструмент веб-скрапинга с помощью ИИ Агентов и CLI позволяет быстро и эффективно извлекать данные из веб-страниц","ar":"أداة الويب سكرابنج مع واجهة سطر الأوامر تسمح باسترجاع البيانات من صفحات الويب بسرعة وفعالية"},"seo":{"title":{"en":"Web-Scraping: Recursive Scraping Setup Guide | AI Agent S...","zh":"Web Scraping_SETUP GUIDE: 使用scpr命令行界面","ja":"Web Scrapingベストプラクティス: AIエージェントとscpr CLI","ko":"Web Scraping 시작하기: scpr 명령줄 인터페이스","es":"Guía de configuración de web-scraping con CLI","fr":"Mise en place du web-scraping avec l''interface de ligne d...","de":"Einrichtungsanleitung für Web-Scraping mit CLI","pt":"Guia de Configuração de Web Scraping com CLI","ru":"Настройка веб-скрапинга с помощью ИИ Агентов и CLI","ar":"دليل إعداد الويب سكرابنج باستخدام واجهة سطر الأوامر"},"description":{"en":"Unlock the power of web-scraping with our CLI and MCP tools. Learn how to scrape web pages recursively and in parallel with our expert guide.","zh":"学习如何使用scpr命令行界面进行Web Scraping，包括基本用法、递归抓取和并行抓取","ja":"Web Scrapingを実現するscpr CLIとAIエージェントの使い方を紹介します","ko":"scpr 명령줄 인터페이스를 사용하여 Web Scraping을 수행하는 방법을 알아보세요","es":"Aprenda a utilizar la herramienta de web-scraping con CLI para extraer datos de sitios web de manera eficiente","fr":"Découvrez comment utiliser l''outil de web-scraping avec l''interface de ligne de commande pour extraire des données de sites web de manière efficace","de":"Erfahren Sie, wie Sie das Web-Scraping-Tool mit CLI verwenden, um Daten von Websites effizient zu extrahieren","pt":"Aprenda a usar a ferramenta de web scraping com CLI para extrair dados de páginas web de forma eficiente","ru":"Узнайте, как использовать инструмент веб-скрапинга с помощью ИИ Агентов и CLI для эффективного извлечения данных из веб-страниц","ar":"تعرف على كيفية استخدام أداة الويب سكرابنج مع واجهة سطر الأوامر لاستخراج البيانات من صفحات الويب بفعالية"},"definition":{"en":"Web-scraping is a technique for extracting data from websites using tools like the scpr command line interface.","zh":"Web Scraping是指使用程序从网页中提取数据的过程，scpr命令行界面是此过程中的一个工具","ja":"Web Scrapingとは、プログラムを使用してWebページからデータを抽出することを指します","ko":"Web Scraping은 프로그램을 사용하여 웹 페이지에서 데이터를 추출하는 것을 의미합니다","es":"Web-scraping es una técnica para extraer datos de sitios web utilizando herramientas como la CLI","fr":"Le web-scraping est une technique pour extraire des données de sites web en utilisant des outils tels que l''interface de ligne de commande","de":"Web-Scraping ist eine Technik, um Daten von Websites mithilfe von Tools wie der CLI zu extrahieren","pt":"Web scraping é uma técnica de extração de dados de páginas web usando ferramentas como CLI","ru":"Веб-скрапинг - это техника извлечения данных из веб-страниц с помощью инструментов như ИИ Агенты и CLI","ar":"الويب سكرابنج هي تقنية لاستخراج البيانات من صفحات الويب باستخدام أدوات مثل واجهة سطر الأوامر"},"features":{"en":["Recursive scraping using the --recursive flag","Parallel scraping for improved performance","Support for scraping single pages with the --url flag","Output files in markdown format","Domain restriction using the --allowed flag","Depth limitation using the --max flag"],"zh":["支持基本抓取和递归抓取","并行抓取功能提高抓取速度","使用--url和--output参数指定抓取页面和输出文件","支持--recursive和--allowed参数实现递归抓取","使用--max参数限制递归抓取的深度"],"ja":["基本的なWeb Scrapingと再帰的なWeb Scrapingをサポート","並行処理によりWeb Scrapingの速度を向上","コマンドライン引数--urlと--outputでWebページと出力ファイルを指定","再帰的なWeb Scrapingを実現する--recursiveと--allowed引数","再帰的なWeb Scrapingの深度を--max引数で制限"],"ko":["기본적인 Web Scraping과 재귀적인 Web Scraping을 지원","並行処理로 Web Scraping의 속도를 향상","명령줄 인자 --url과 --output으로 웹 페이지와 출력 파일을 지정","재귀적인 Web Scraping을 구현하는 --recursive와 --allowed 인자","재귀적인 Web Scraping의 깊이를 --max 인자로 제한"],"es":["Uso de la CLI para extraer datos de sitios web","Scraping recursivo para extraer datos de páginas vinculadas","Scraping paralelo para acelerar el proceso","Opción para especificar dominios permitidos","Opción para establecer un límite máximo de profundidad"],"fr":["Utilisation de l''interface de ligne de commande pour extraire des données de sites web","Scraping récursif pour extraire des données de pages liées","Scraping parallèle pour accélérer le processus","Option pour spécifier les domaines autorisés","Option pour définir une limite de profondeur maximale"],"de":["Verwendung der CLI zur Extraktion von Daten von Websites","Rekursives Scraping zur Extraktion von Daten von verknüpften Seiten","Paralleles Scraping zur Beschleunigung des Prozesses","Option zur Angabe von erlaubten Domains","Option zur Festlegung einer maximalen Tiefe"],"pt":["Uso do comando `scpr` para scraping de páginas web","Suporte a scraping recursivo com opção `--recursive`","Suporte a scraping paralelo para aumentar a velocidade","Opção `--allowed` para especificar domínios permitidos","Opção `--max` para limitar a profundidade do scraping"],"ru":["Использование команды `scpr` для веб-скрапинга","Поддержка рекурсивного скрапинга с опцией `--recursive`","Поддержка параллельного скрапинга для увеличения скорости","Опция `--allowed` для указания разрешенных доменов","Опция `--max` для ограничения глубины скрапинга"],"ar":["استخدام الأمر `scpr` لاستخراج البيانات من صفحات الويب","دعم الستخراج التكراري مع خيار `--recursive`","دعم الستخراج المتوازي لزيادة السرعة","خيار `--allowed` لتحديد المجالات المسموح بها","خيار `--max` لتحديد حد العمق للاستخراج"]},"keywords":{"en":["how to use web-scraping","web-scraping vs beautiful soup","web-scraping setup guide","web-scraping install","what is web-scraping","web-scraping alternative","web-scraping recursive scraping","web-scraping parallel scraping","web-scraping CLI tool","web-scraping MCP"],"zh":["Web Scraping","scpr命令行界面","递归抓取","并行抓取","网页数据提取","AI工具","网页爬虫"],"ja":["Web Scraping","scpr CLI","再帰的なWeb Scraping","並行処理","Webページからのデータ抽出","AIエージェント","Webクローラー"],"ko":["Web Scraping","scpr 명령줄 인터페이스","재귀적인 Web Scraping","並行処理","웹 페이지からの 데이터 추출","AI 도구","웹 크롤러"],"es":["web-scraping","CLI","scraping recursivo","scraping paralelo","extracción de datos","herramientas de web-scraping","agentes de inteligencia artificial","herramientas de IA"],"fr":["web-scraping","interface de ligne de commande","scraping récursif","scraping parallèle","extraction de données","outils de web-scraping","agents d''intelligence artificielle","outils d''IA"],"de":["Web-Scraping","CLI","rekursives Scraping","paralleles Scraping","Datenextraktion","Web-Scraping-Tools","Künstliche Intelligenz Agenten","KI-Tools"],"pt":["web scraping","CLI","scraping de páginas web","ferramenta de web scraping","técnica de extração de dados","comando scpr","scraping recursivo","scraping paralelo"],"ru":["веб-скрапинг","ИИ Агенты","CLI","скрапинг веб-страниц","инструмент веб-скрапинга","техника извлечения данных","команда scpr","рекурсивный скрапинг","параллельный скрапинг"],"ar":["الويب سكرابنج","واجهة سطر الأوامر","أداة الويب سكرابنج","تقنية استخراج البيانات","أمر scpr","الستخراج التكراري","الستخراج المتوازي","استخراج البيانات من صفحات الويب"]}},"owner":"AstraBert","repo":"scpr","repoPath":"AstraBert/scpr","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.296Z","topics":[],"category":"community","skillMd":{"name":"web-scraping","description":"Scrape web pages based on a provided URL using the scpr CLI app.","bodyPreview":"When asked to scrape a web page, use the `scpr` command line interface.\n\nBasic usage (scrape a single page):\n\n```bash\nscpr --url https://example.com --output ./scraped\n```\n\nThis will scrape the page and save it as a markdown file in the `./scraped` folder.\n\n**Recursive scraping**\n\nTo scrape a page and all linked pages within the same domain:\n\n```bash\nscpr --url https://example.com --output ./scraped --recursive --allowed example.com --max 3\n```\n\n**Parallel scraping**\n\nSpeed up recursive scraping","body":"When asked to scrape a web page, use the `scpr` command line interface.\n\nBasic usage (scrape a single page):\n\n```bash\nscpr --url https://example.com --output ./scraped\n```\n\nThis will scrape the page and save it as a markdown file in the `./scraped` folder.\n\n**Recursive scraping**\n\nTo scrape a page and all linked pages within the same domain:\n\n```bash\nscpr --url https://example.com --output ./scraped --recursive --allowed example.com --max 3\n```\n\n**Parallel scraping**\n\nSpeed up recursive scraping with multiple threads:\n\n```bash\nscpr --url https://example.com --output ./scraped --recursive --allowed example.com --max 2 --parallel 5\n```\n\n**Additional options**\n\n- `--log` - Set logging level (info, debug, warn, error)\n- `--max` - Maximum depth of pages to follow (default: 1)\n- `--parallel` - Number of concurrent threads (default: 1)\n- `--allowed` - Allowed domains for recursive scraping (can be specified multiple times)\n\nFor more details, run:\n\n```bash\nscpr --help\n```\n\nOnce you are done with scraping, you should scan the output folder to find the content the user asked you for, here is an example flow:\n\n```bash\nscpr --url https://example.com --output ./scraped --recursive --allowed example.com --max 2\ncd ./scraped\ngrep -r \"pattern of interest\"\n```\n"},"lastSynced":"2026-03-08T02:01:15.975Z","agentAnalysis":{"suitability":{"en":"Perfect for Data Analysis Agents needing advanced web-scraping capabilities for recursive and parallel data extraction.","zh":"适合需要高级网页抓取功能的数据分析代理，尤其是递归和并行数据提取。","ja":"データ分析エージェントが高度なWebスクレイピング機能を必要とする場合に適しています。特に、再帰的および並列データ抽出に役立ちます。","ko":"데이터 분석 에이전트가 고급 웹 스크레이핑 기능을 필요로 할 때 적합하며, 특히 재귀적 및 병렬 데이터 추출에 유용합니다.","es":"Perfecto para Agentes de Análisis de Datos que necesitan capacidades de extracción web avanzadas para la extracción de datos recursiva y paralela.","fr":"Parfait pour les Agents d''Analyse de Données nécessitant des capacités de scraping web avancées pour l''extraction de données récursive et parallèle.","de":"Perfekt für Data-Analytics-Agents, die erweiterte Web-Scraping-Funktionen für rekursive und parallele Datenextraktion benötigen.","pt":"Perfeito para Agentes de Análise de Dados que necessitam de capacidades avançadas de web-scraping para extração de dados recursiva e paralela.","ru":"Идеально подходит для Агентов Анализа Данных, требующих расширенных возможностей веб-скрапинга для рекурсивного и параллельного извлечения данных.","ar":"مثالي لوسائل تحلیل البيانات التي تحتاج إلى قابليات تقطير الويب المتقدمة لاستخراج البيانات التكراري والتوازي."},"recommendation":{"en":"Empowers agents to scrape web pages using the scpr command line interface, supporting recursive and parallel scraping with markdown output, and handling protocols like https, while specifying allowed domains and setting max recursion depth.","zh":"赋予代理使用scpr命令行接口抓取网页的能力，支持递归和并行抓取，输出markdown格式，并处理https等协议，同时指定允许的域和设置最大递归深度。","ja":"scprコマンドラインインターフェイスを使用してWebページをスクレイピングするエージェントの機能を強化します。再帰的および並列スクレイピングをサポートし、Markdown形式で出力します。さらに、httpsなどのプロトコルを処理し、許可されたドメインを指定し、最大の再帰深度を設定します。","ko":"에이전트에게 scpr 명령줄 인터페이스를 사용하여 웹 페이지를 스크레이핑할 수 있는 능력을 부여하며, 재귀적 및 병렬 스크레이핑을 지원하고, 마크다운 형식으로 출력합니다. 또한 https 등의 프로토콜을 처리하며, 허용되는 도메인을 지정하고 최대 재귀 깊이를 설정할 수 있습니다.","es":"Habilita a los agentes a extraer páginas web utilizando la interfaz de línea de comandos scpr, que admite el scraping recursivo y paralelo con salida en markdown, y maneja protocolos como https, al especificar dominios permitidos y establecer la profundidad de recursividad máxima.","fr":"Permet aux agents d''extraire des pages web en utilisant l''interface de ligne de commande scpr, qui prend en charge le scraping récursif et parallèle avec une sortie markdown, et gère des protocoles comme https, tout en spécifiant les domaines autorisés et en définissant la profondeur de récursivité maximale.","de":"Ermächtigt Agenten, Webseiten mit der scpr-Kommandozeilenoberfläche zu scrapen, die rekursives und paralleles Scraping mit Markdown-Ausgabe unterstützt und Protokolle wie https handhabt, während sie erlaubte Domänen angibt und die maximale Rekursetiefe festlegt.","pt":"Habilita os agentes a extrair páginas da web usando a interface de linha de comando scpr, com suporte a scraping recursivo e paralelo com saída em markdown, e lidando com protocolos como https, enquanto especifica domínios permitidos e define a profundidade máxima de recursão.","ru":"Наделяет агентов возможностью извлекать веб-страницы с помощью командной строки scpr, поддерживая рекурсивный и параллельный скрапинг с выводом в markdown, и обрабатывая протоколы типа https, при этом указывая разрешенные домены и устанавливая максимальную глубину рекурсии.","ar":"يمنح الوسائل القدرة على استخراج صفحات الويب باستخدام واجهة سطر الأوامر scpr، مع دعم تقطير الويب التكراري والتوازي مع إخراج markdown، ومعالجة بروتوكولات مثل https، مع تحديد النطاقات المسموح بها وضبط أقصى عمق تكرار."},"useCases":{"en":["Scraping single web pages for data extraction","Performing recursive scraping of linked pages within the same domain","Speeding up data collection with parallel scraping"],"zh":["抓取单个网页以提取数据","在同一域内执行链接页面的递归抓取","使用并行抓取加速数据收集"],"ja":["データ抽出のために単一のWebページをスクレイピングする","同じドメイン内のリンクされたページの再帰的スクレイピングを実行する","並列スクレイピングを使用してデータ収集を加速する"],"ko":["데이터 추출을 위해 단일 웹 페이지를 스크레이핑한다","동일 도메인 내의 연결된 페이지의 재귀적 스크레이핑을 수행한다","병렬 스크레이핑을 사용하여 데이터 수집을 가속화한다"],"es":["Extracción de datos de una sola página web","Realización de scraping recursivo de páginas vinculadas dentro del mismo dominio","Aceleración de la recopilación de datos con scraping paralelo"],"fr":["Extraction de données d''une seule page web","Réalisations de scraping récursif de pages liées au sein du même domaine","Accélération de la collecte de données avec un scraping parallèle"],"de":["Datenextraktion aus einzelnen Webseiten","Durchführung von rekursivem Scraping von verknüpften Seiten innerhalb desselben Domäns","Beschleunigung der Datensammlung mit parallelem Scraping"],"pt":["Extração de dados de páginas da web únicas","Realização de scraping recursivo de páginas vinculadas dentro do mesmo domínio","Aceleração da coleta de dados com scraping paralelo"],"ru":["Извлечение данных из отдельных веб-страниц","Проведение рекурсивного скрапинга связанных страниц внутри одного домена","Ускорение сбора данных с помощью параллельного скрапинга"],"ar":["استخراج البيانات من صفحات الويب الفردية","إجراء تقطير الويب التكراري للصفحات المرتبطة داخل نفس المجال","تسريع جمع البيانات مع تقطير الويب التوازي"]},"limitations":{"en":["Requires scpr command line interface installation","Limited to scraping pages with specified allowed domains","Dependent on network connectivity for web page access"],"zh":["需要安装scpr命令行接口","仅限于抓取指定允许域的页面","依赖网络连接以访问网页"],"ja":["scprコマンドラインインターフェイスのインストールが必要","指定された許可されたドメインのページのみをスクレイピングできる","Webページにアクセスするためにネットワーク接続に依存する"],"ko":["scpr 명령줄 인터페이스의 설치가 필요하다","지정된 허용되는 도메인의 페이지만을 스크레이핑할 수 있다","웹 페이지에 접근하기 위해 네트워크 연결에 의존한다"],"es":["Requiere la instalación de la interfaz de línea de comandos scpr","Limitado a la extracción de páginas con dominios permitidos especificados","Dependiente de la conectividad de red para el acceso a páginas web"],"fr":["Nécessite l''installation de l''interface de ligne de commande scpr","Limité au scraping de pages avec des domaines autorisés spécifiés","Dépendant de la connectivité réseau pour l''accès aux pages web"],"de":["Benötigt die Installation der scpr-Kommandozeilenoberfläche","Begrenzt auf das Scraping von Seiten mit angegebenen erlaubten Domänen","Von der Netzwerkverbindung abhängig für den Zugriff auf Webseiten"],"pt":["Requer instalação da interface de linha de comando scpr","Limitado ao scraping de páginas com domínios permitidos especificados","Dependente da conectividade de rede para acesso a páginas da web"],"ru":["Требует установки командной строки scpr","Ограничен скрапингом страниц с указанными разрешенными доменами","Зависит от сетевого подключения для доступа к веб-страницам"],"ar":["يتطلب تثبيت واجهة سطر الأوامر scpr","محدود بتقطير صفحات مع تحديد مجالات مسموح بها","يعتمد على الاتصال الشبكي للوصول إلى صفحات الويب"]},"version":4},"contentHash":"6dc2339997a287c4c978537f6f6b4889f09ddb191ea0a85d598fc9654abed580","qualityScore":39}');
