INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('AstraBert/scpr/web-scraping', 'web-scraping', 'AstraBert', 'scpr', 'community', 'web-scraping AstraBert scpr community The web-scraping skill allows developers to scrape web pages using the scpr command line interface, supporting recursive and parallel scraping. It benefits developers and coding agents. scpr命令行界面用于Web Scraping，支持基本抓取、递归抓取和并行抓取 scpr CLIはWeb Scrapingを実現するツールで、基本的な使い方から並行処理までサポートしています scpr 명령줄 인터페이스는 Web Scraping을 위한 도구로 기본적인抓取부터並行処理까지 지원합니다 La herramienta de web-scraping con CLI permite extraer datos de sitios web de manera rápida y sencilla L''outil de web-scraping avec l''interface de ligne de commande permet d''extraire des données de sites web de manière rapide et simple Das Web-Scraping-Tool mit CLI ermöglicht die schnelle und einfache Extraktion von Daten von Websites A ferramenta de web scraping com CLI permite extrair dados de páginas web de forma rápida e eficiente Инструмент веб-скрапинга с помощью ИИ Агентов и CLI позволяет быстро и эффективно извлекать данные из веб-страниц أداة الويب سكرابنج مع واجهة سطر الأوامر تسمح باسترجاع البيانات من صفحات الويب بسرعة وفعالية how to use web-scraping web-scraping vs beautiful soup web-scraping setup guide web-scraping install what is web-scraping web-scraping alternative web-scraping recursive scraping web-scraping parallel scraping web-scraping CLI tool web-scraping MCP Web Scraping scpr命令行界面 递归抓取 并行抓取 网页数据提取 AI工具 网页爬虫 Recursive scraping using the --recursive flag Parallel scraping for improved performance Support for scraping single pages with the --url flag Output files in markdown format Domain restriction using the --allowed flag Depth limitation using the --max flag Web-scraping is a technique for extracting data from websites using tools like the scpr command line interface.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('T-Klug/aws-cur-report-generator/visualization', 'community', 'T-Klug', 'aws-cur-report-generator', 'T-Klug/aws-cur-report-generator', 'visualization', 0, 0, 39, '2026-03-08T01:57:15.299Z', '2026-03-08T02:01:23.876Z', '8d1946ffa8fdf5357755820f2891dc5e2a51bfe8f16786306278a8488c0be55a', '{"id":"T-Klug/aws-cur-report-generator/visualization","name":"visualization","description":{"en":"The visualization skill generates interactive charts using pyecharts and Apache ECharts, benefiting developers who need to create self-contained HTML with embedded JS. It supports various chart types, including bar charts.","zh":"使用pyecharts和Apache ECharts实现数据可视化，创建自包含的HTML报告","ja":"AIエージェントによるビジュアライゼーションを実現し、pyechartsとApache EChartsの機能を活用","ko":"pyecharts와 Apache ECharts를 사용하여 데이터 시각화를 구현하고 자체 포함 HTML 보고서를 생성","es":"La visualización es una habilidad que permite crear gráficos personalizados con pyecharts y Apache ECharts. Permite generar HTML autocontenidos con JavaScript incrustado.","fr":"La visualisation est une compétence qui permet de créer des graphiques personnalisés avec pyecharts et Apache ECharts. Elle permet de générer des HTML autocontenus avec du JavaScript intégré.","de":"Die Visualisierung ist eine Fähigkeit, die das Erstellen benutzerdefinierter Diagramme mit pyecharts und Apache ECharts ermöglicht. Sie ermöglicht die Generierung selbstenthaltener HTML mit eingebettetem JavaScript.","pt":"A visualização é uma habilidade que permite criar gráficos personalizados com pyecharts e Apache ECharts. Ela é útil para desenvolvedores que precisam integrar visualização em seus projetos.","ru":"Визуализация - это навык, который позволяет создавать индивидуальные графики с помощью ИИ Агентов и Apache ECharts. Он полезен для разработчиков, которым необходимо интегрировать визуализацию в свои проекты.","ar":"التصور هو مهارة تسمح بإنشاء مخططات مخصصة باستخدام مكتبات Python و Apache ECharts. انها مفيدة للمطورين الذين يحتاجون إلى دمج التصور في مشاريعهم."},"seo":{"title":{"en":"Visualization: Setup Guide for AI Agents | AI Agent Skill","zh":"数据可视化设置指南 - 使用pyecharts和Apache ECharts","ja":"AIエージェントによるビジュアライゼーションセットアップガイド - pyechartsとApache ECharts","ko":"데이터 시각화 설정 가이드 - pyecharts와 Apache ECharts","es":"Guía de configuración de visualización con pyecharts y Ap...","fr":"Guide de mise en place de la visualisation avec pyecharts...","de":"Einrichtungsleitfaden für Visualisierung mit pyecharts un...","pt":"Guia de Configuração de Visualização com Pyecharts","ru":"Настройка Визуализации с ИИ Агентами и Apache ECharts","ar":"دليل إعداد التصور مع مكتبات Python"},"description":{"en":"Unlock data insights with our visualization skill, featuring pyecharts and Apache ECharts. Learn how to generate self-contained HTML with embedded JS and get...","zh":"了解如何使用pyecharts和Apache ECharts实现数据可视化，并创建自包含的HTML报告","ja":"AIエージェントを使用してビジュアライゼーションを実現し、pyechartsとApache EChartsの機能を活用する方法を学習","ko":"pyecharts와 Apache ECharts를 사용하여 데이터 시각화를 구현하고 자체 포함 HTML 보고서를 생성하는 방법","es":"Aprende a crear gráficos personalizados con pyecharts y Apache ECharts. Descubre cómo generar HTML autocontenidos con JavaScript incrustado.","fr":"Découvrez comment créer des graphiques personnalisés avec pyecharts et Apache ECharts. Apprenez à générer des HTML autocontenus avec du JavaScript intégré.","de":"Erfahren Sie, wie Sie benutzerdefinierte Diagramme mit pyecharts und Apache ECharts erstellen. Entdecken Sie, wie Sie selbstenthaltene HTML mit eingebettetem...","pt":"Aprenda a criar gráficos personalizados com pyecharts e Apache ECharts. Descubra como integrar visualização em seus projetos de desenvolvimento.","ru":"Узнайте, как создавать индивидуальные графики с помощью ИИ Агентов и Apache ECharts. Откройте для себя, как интегрировать визуализацию в ваши разработки.","ar":"تعلم كيفية إنشاء مخططات مخصصة باستخدام مكتبات Python و Apache ECharts. اكتشف كيفية دمج التصور في مشاريع التطوير الخاصة بك."},"definition":{"en":"Visualization is a skill that generates interactive charts and graphs using technologies like pyecharts and Apache ECharts, enabling developers to create informative and engaging data visualizations.","zh":"数据可视化是指使用图表和图形来表示数据的过程，使用pyecharts和Apache ECharts可以实现","ja":"ビジュアライゼーションとは、グラフやチャートを使用してデータを表現するプロセスであり、AIエージェントを使用して実現可能","ko":"데이터 시각화는 그래프와 차트를 사용하여 데이터를 표현하는 과정이며 pyecharts와 Apache ECharts를 사용하여 구현","es":"La visualización es la capacidad de crear representaciones gráficas de datos con herramientas como pyecharts y Apache ECharts.","fr":"La visualisation est la capacité de créer des représentations graphiques de données avec des outils tels que pyecharts et Apache ECharts.","de":"Die Visualisierung ist die Fähigkeit, grafische Darstellungen von Daten mit Tools wie pyecharts und Apache ECharts zu erstellen.","pt":"O que é visualização? É uma habilidade que cria gráficos personalizados com pyecharts e Apache ECharts.","ru":"Что такое визуализация? Это навык, который создает индивидуальные графики с помощью ИИ Агентов и Apache ECharts.","ar":"ما هو التصور؟ هو مهارة تسمح بإنشاء مخططات مخصصة باستخدام مكتبات Python و Apache ECharts."},"features":{"en":["Generates self-contained HTML with embedded JS using Apache ECharts","Supports various chart types, including bar charts via pyecharts","Utilizes pyecharts options, such as title_opts and tooltip_opts, for customization","Creates interactive charts with add_xaxis and add_yaxis functions","Enables developers to set global options, including title and tooltip settings"],"zh":["使用pyecharts创建自包含的HTML报告","支持多种图表类型，包括条形图和线形图","使用Apache ECharts实现交互式图表","自定义图表标题和tooltip","支持多种数据格式，包括JSON和CSV"],"ja":["pyechartsを使用して自包含のHTMLレポートを作成","複数のチャートタイプをサポート、バーチャートとラインチャートなど","Apache EChartsを使用してインタラクティブなチャートを実現","チャートのタイトルとツールチップをカスタマイズ","複数のデータ形式をサポート、JSONとCSVなど"],"ko":["pyecharts를 사용하여 자체 포함 HTML 보고서를 생성","다양한 차트 유형 지원, 바 차트와 라인 차트 등","Apache ECharts를 사용하여 상호 작용형 차트를 구현","차트 제목과 툴팁을 사용자 지정","다양한 데이터 형식 지원, JSON과 CSV 등"],"es":["Creación de gráficos de barras personalizados con pyecharts","Generación de HTML autocontenidos con JavaScript incrustado","Uso de Apache ECharts para crear gráficos interactivos","Personalización de gráficos con opciones de título y tooltip","Compatibilidad con diferentes tipos de gráficos, incluyendo gráficos de barras","Integración con Python para una mayor flexibilidad"],"fr":["Création de graphiques à barres personnalisés avec pyecharts","Génération d''HTML autocontenus avec du JavaScript intégré","Utilisation d''Apache ECharts pour créer des graphiques interactifs","Personnalisation de graphiques avec des options de titre et de tooltip","Compatibilité avec différents types de graphiques, y compris les graphiques à barres","Intégration avec Python pour une plus grande flexibilité"],"de":["Erstellung benutzerdefinierter Balkendiagramme mit pyecharts","Generierung selbstenthaltener HTML mit eingebettetem JavaScript","Verwendung von Apache ECharts für interaktive Diagramme","Anpassung von Diagrammen mit Titel- und Tooltip-Optionen","Unterstützung für verschiedene Diagrammtypen, einschließlich Balkendiagrammen","Integration mit Python für eine größere Flexibilität"],"pt":["Criação de gráficos personalizados com pyecharts","Integração com Apache ECharts para visualização avançada","Saída em HTML com JavaScript incorporado","Suporte a gráficos de barras e outros tipos de gráficos","Personalização de títulos e opções de ferramentas"],"ru":["Создание индивидуальных графиков с помощью ИИ Агентов","Интеграция с Apache ECharts для продвинутой визуализации","Выход в HTML с встроенным JavaScript","Поддержка графиков и других типов графиков","Настройка заголовков и опций инструментов"],"ar":["إنشاء مخططات مخصصة باستخدام مكتبات Python","التكامل مع Apache ECharts للتصور المتقدم","الإخراج في HTML مع جافا سكريبت مضمن","دعم مخططات الشريط وغيرها من أنواع المخططات","تخصيص العناوين وخيارات الأدوات"]},"keywords":{"en":["how to use visualization in AI agents","what is visualization in data science","visualization alternative to matplotlib","visualization vs d3.js","visualization setup guide for developers","installing visualization libraries for Python"],"zh":["数据可视化","pyecharts","Apache ECharts","HTML报告","交互式图表","数据分析","可视化工具","AIエージェント","数据科学"],"ja":["ビジュアライゼーション","pyecharts","Apache ECharts","HTMLレポート","インタラクティブなチャート","データ分析","可視化ツール","AIエージェント","データサイエンス"],"ko":["데이터 시각화","pyecharts","Apache ECharts","HTML 보고서","상호 작용형 차트","데이터 분석","시각화 도구","AI 에이전트","데이터 과학"],"es":["visualización de datos","pyecharts","Apache ECharts","gráficos personalizados","HTML autocontenidos","JavaScript incrustado","creación de gráficos","personalización de gráficos","integración con Python"],"fr":["visualisation de données","pyecharts","Apache ECharts","graphiques personnalisés","HTML autocontenus","JavaScript intégré","création de graphiques","personnalisation de graphiques","intégration avec Python"],"de":["Datenvisualisierung","pyecharts","Apache ECharts","benutzerdefinierte Diagramme","selbstenthaltene HTML","eingebettetes JavaScript","Erstellung von Diagrammen","Anpassung von Diagrammen","Integration mit Python"],"pt":["visualização de dados","pyecharts","Apache ECharts","gráficos personalizados","desenvolvimento de software","integração de visualização","mecanismos de busca para desenvolvedores"],"ru":["визуализация данных","ИИ Агенты","Apache ECharts","индивидуальные графики","разработка программного обеспечения","интеграция визуализации","поисковые системы для разработчиков"],"ar":["تصور البيانات","مكتبات Python","Apache ECharts","مخططات مخصصة","تطوير البرمجيات","دمج التصور","محركات البحث للمطورين"]}},"owner":"T-Klug","repo":"aws-cur-report-generator","repoPath":"T-Klug/aws-cur-report-generator","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.299Z","topics":[],"category":"community","skillMd":{"name":"visualization","description":"Knowledge about pyecharts chart creation, HTML report generation, and visualization best practices","bodyPreview":"# Visualization Skill\n\n## Technology Stack\n\n- **pyecharts**: Python wrapper for Apache ECharts\n- **Apache ECharts**: JavaScript charting library\n- **Output**: Self-contained HTML with embedded JS\n\n## Chart Types Reference\n\n### Bar Charts\n```python\nfrom pyecharts.charts import Bar\nfrom pyecharts import options as opts\n\nchart = Bar()\nchart.add_xaxis(labels)\nchart.add_yaxis(\"Series Name\", values)\nchart.set_global_opts(\n    title_opts=opts.TitleOpts(title=\"Chart Title\"),\n    tooltip_opts=opts.Toolti","body":"# Visualization Skill\n\n## Technology Stack\n\n- **pyecharts**: Python wrapper for Apache ECharts\n- **Apache ECharts**: JavaScript charting library\n- **Output**: Self-contained HTML with embedded JS\n\n## Chart Types Reference\n\n### Bar Charts\n```python\nfrom pyecharts.charts import Bar\nfrom pyecharts import options as opts\n\nchart = Bar()\nchart.add_xaxis(labels)\nchart.add_yaxis(\"Series Name\", values)\nchart.set_global_opts(\n    title_opts=opts.TitleOpts(title=\"Chart Title\"),\n    tooltip_opts=opts.TooltipOpts(trigger=\"axis\"),\n    xaxis_opts=opts.AxisOpts(axislabel_opts=opts.LabelOpts(rotate=45)),\n)\n```\n\n### Line Charts\n```python\nfrom pyecharts.charts import Line\n\nchart = Line()\nchart.add_xaxis(dates)\nchart.add_yaxis(\"Actual\", values, is_smooth=True)\nchart.add_yaxis(\"7-Day MA\", moving_avg_7, is_smooth=True, linestyle_opts=opts.LineStyleOpts(type_=\"dashed\"))\n```\n\n### Pie Charts\n```python\nfrom pyecharts.charts import Pie\n\nchart = Pie()\nchart.add(\"\", list(zip(labels, values)))\nchart.set_global_opts(legend_opts=opts.LegendOpts(orient=\"vertical\", pos_left=\"left\"))\n```\n\n### Heatmaps\n```python\nfrom pyecharts.charts import HeatMap\n\nchart = HeatMap()\nchart.add_xaxis(x_labels)\nchart.add_yaxis(\"\", y_labels, value=[[x, y, val], ...])\nchart.set_global_opts(\n    visualmap_opts=opts.VisualMapOpts(min_=0, max_=max_val),\n)\n```\n\n### Scatter Plots (for anomalies)\n```python\nfrom pyecharts.charts import Scatter\n\nchart = Scatter()\nchart.add_xaxis(dates)\nchart.add_yaxis(\"Cost\", costs, symbol_size=10)\n# Add anomaly markers with different color/size\n```\n\n## Critical: Browser Compatibility\n\n**Always convert to lists for JavaScript:**\n```python\n# CORRECT\nchart.add_xaxis(df[''column''].tolist())\nchart.add_yaxis(\"Label\", df[''values''].tolist())\n\n# WRONG - causes rendering issues\nchart.add_xaxis(df[''column''].values)  # numpy array\nchart.add_xaxis(df[''column''])  # pandas Series\n```\n\n## Theme Options\n\nAvailable themes in pyecharts:\n- `macarons` (default) - Colorful, professional\n- `shine` - Bright colors\n- `roma` - Muted, elegant\n- `vintage` - Retro feel\n- `dark` - Dark background\n- `light` - Light, minimal\n\nUsage:\n```python\nfrom pyecharts.globals import ThemeType\nchart = Bar(init_opts=opts.InitOpts(theme=ThemeType.MACARONS))\n```\n\n## HTML Report Structure\n\n```python\ndef generate_html_report(self, output_path: str, top_n: int = 10) -> str:\n    # Create all charts\n    charts = [\n        self.create_cost_by_service_chart(top_n),\n        self.create_cost_by_account_chart(),\n        # ... more charts\n    ]\n\n    # Combine into page\n    page = Page(layout=Page.SimplePageLayout)\n    for chart in charts:\n        page.add(chart)\n\n    # Render to file\n    page.render(output_path)\n    return output_path\n```\n\n## Formatting Numbers\n\n```python\n# Currency formatting in tooltips\ntooltip_opts=opts.TooltipOpts(\n    trigger=\"axis\",\n    formatter=\"{b}: ${c:,.2f}\"\n)\n\n# Axis label formatting\nyaxis_opts=opts.AxisOpts(\n    axislabel_opts=opts.LabelOpts(formatter=\"${value:,.0f}\")\n)\n```\n\n## Common Issues & Solutions\n\n### Empty Charts\n1. Check browser console for JS errors\n2. Verify `.tolist()` on all data\n3. Hard refresh (Ctrl+Shift+R)\n4. Check data exists in HTML source\n\n### Chart Too Small\n```python\ninit_opts=opts.InitOpts(width=\"100%\", height=\"400px\")\n```\n\n### Labels Overlapping\n```python\nxaxis_opts=opts.AxisOpts(\n    axislabel_opts=opts.LabelOpts(rotate=45, interval=0)\n)\n```\n\n### Legend Too Long\n```python\nlegend_opts=opts.LegendOpts(\n    type_=\"scroll\",\n    orient=\"horizontal\",\n    pos_bottom=\"0%\"\n)\n```\n\n## Testing Visualizations\n\n```bash\n# Test chart creation\nuv run pytest tests/test_visualizer.py -v\n\n# Regenerate example report\nuv run pytest tests/test_examples.py -v -s\n\n# View in browser\nopen examples/example_report.html\n```\n"},"lastSynced":"2026-03-08T02:01:23.876Z","agentAnalysis":{"suitability":{"en":"Perfect for Data Analysis Agents needing interactive chart generation capabilities with pyecharts and Apache ECharts.","zh":"适合需要交互式图表生成能力的数据分析代理，使用pyecharts和Apache ECharts。","ja":"pyechartsとApache EChartsを使用したインタラクティブなチャート生成機能を必要とするデータ分析エージェントに最適。","ko":"pyecharts와 Apache ECharts를 사용하여 상호작용형 차트 생성 기능이 필요한 데이터 분석 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Análisis de Datos que necesitan capacidades de generación de gráficos interactivos con pyecharts y Apache ECharts.","fr":"Parfait pour les agents d''analyse de données ayant besoin de capacités de génération de graphiques interactifs avec pyecharts et Apache ECharts.","de":"Perfekt für Data Analysis Agents, die interaktive Diagrammgenerierungsfunktionen mit pyecharts und Apache ECharts benötigen.","pt":"Perfeito para Agentes de Análise de Dados que necessitam de capacidades de geração de gráficos interativos com pyecharts e Apache ECharts.","ru":"Идеально подходит для агентов анализа данных, которым необходимы возможности создания интерактивных графиков с помощью pyecharts и Apache ECharts.","ar":"مثالي لعميل تحليل البيانات الذين يحتاجون إلى قدرات توليد الرسوم البيانية التفاعلية مع pyecharts و Apache ECharts."},"recommendation":{"en":"Empowers agents to create self-contained HTML with embedded JS, supporting various chart types like bar charts, utilizing pyecharts and Apache ECharts for interactive visualizations.","zh":"赋予代理创建自包含HTML的能力，内嵌JS，支持各种图表类型，如条形图，利用pyecharts和Apache ECharts进行交互式可视化。","ja":"エージェントが自包含のHTMLを作成できるようにし、JSを内嵌し、pyechartsとApache EChartsを使用したインタラクティブな可視化をサポートする、例えばバーチャートなどの様々なチャートタイプ。","ko":"에이전트가 자체 포함 HTML을 생성할 수 있도록 하며, JS를 내장하고, pyecharts와 Apache ECharts를 사용한 상호작용형 시각화를 지원하며, 예를 들어 바 차트와 같은 다양한 차트 유형을 지원합니다.","es":"Habilita a los agentes a crear HTML autocontenidos con JS incrustado, que admiten varios tipos de gráficos como gráficos de barras, utilizando pyecharts y Apache ECharts para visualizaciones interactivas.","fr":"Permet aux agents de créer des HTML autocontenus avec du JS intégré, prenant en charge différents types de graphiques comme les graphiques à barres, en utilisant pyecharts et Apache ECharts pour des visualisations interactives.","de":"Ermöglicht es den Agenten, selbstenthaltene HTML mit eingebettetem JS zu erstellen, das verschiedene Diagrammarten wie Balken diagrams unterstützt, unter Verwendung von pyecharts und Apache ECharts für interaktive Visualisierungen.","pt":"Habilita os agentes a criar HTML autocontido com JS incorporado, suportando vários tipos de gráficos, como gráficos de barras, utilizando pyecharts e Apache ECharts para visualizações interativas.","ru":"Наделяет агентов возможностью создавать самодостаточный HTML с встроенным JS, поддерживающий различные типы графиков, такие как гистограммы, используя pyecharts и Apache ECharts для интерактивных визуализаций.","ar":"يمنح العميل pouvoir إنشاء HTML مكتفي ذاتيًا مع JS مدمج ، يدعم أنواعًا متعددة من الرسوم البيانية ، مثل الرسوم البيانية للعرض ، باستخدام pyecharts و Apache ECharts للتصورات التفاعلية."},"useCases":{"en":["Generating interactive bar charts for data insights","Creating self-contained HTML reports with embedded JS","Visualizing data trends using Apache ECharts"],"zh":["为数据洞察生成交互式条形图","创建自包含HTML报告，内嵌JS","使用Apache ECharts可视化数据趋势"],"ja":["データの洞察のためにインタラクティブなバーチャートを生成する","JSを内嵌した自包含のHTMLレポートを作成する","Apache EChartsを使用したデータの傾向の可視化"],"ko":["데이터洞察을 위한 상호작용형 바 차트 생성","JS를 내장한 자체 포함 HTML 보고서 생성","Apache ECharts를 사용한 데이터 趨勢 시각화"],"es":["Generación de gráficos de barras interactivos para información de datos","Creación de informes HTML autocontenidos con JS incrustado","Visualización de tendencias de datos mediante Apache ECharts"],"fr":["Génération de graphiques à barres interactifs pour des informations de données","Création de rapports HTML autocontenus avec du JS intégré","Visualisation de tendances de données à l''aide d''Apache ECharts"],"de":["Erzeugung interaktiver Balken diagrams für Dateninformationen","Erstellung selbstenthaltener HTML-Berichte mit eingebettetem JS","Visualisierung von Datentrends unter Verwendung von Apache ECharts"],"pt":["Geração de gráficos de barras interativos para insights de dados","Criação de relatórios HTML autocontidos com JS incorporado","Visualização de tendências de dados usando Apache ECharts"],"ru":["Генерация интерактивных гистограмм для анализа данных","Создание самодостаточных HTML-отчетов с встроенным JS","Визуализация тенденций данных с помощью Apache ECharts"],"ar":["توليد الرسوم البيانية التفاعلية للرأسية للحصول على رؤى البيانات","إنشاء تقارير HTML مكتفية ذاتيًا مع JS مدمج","تجسيد اتجاهات البيانات باستخدام Apache ECharts"]},"limitations":{"en":["Requires pyecharts and Apache ECharts libraries","Output limited to self-contained HTML with embedded JS"],"zh":["需要pyecharts和Apache ECharts库","输出仅限于自包含HTML，内嵌JS"],"ja":["pyechartsとApache EChartsライブラリが必要","出力はJSを内嵌した自包含のHTMLに限定される"],"ko":["pyecharts와 Apache ECharts 라이브러리가 필요","출력은 JS를 내장한 자체 포함 HTML로 제한됨"],"es":["Requiere las bibliotecas pyecharts y Apache ECharts","Salida limitada a HTML autocontenidos con JS incrustado"],"fr":["Nécessite les bibliothèques pyecharts et Apache ECharts","Sortie limitée à des HTML autocontenus avec du JS intégré"],"de":["Erfordert die Bibliotheken pyecharts und Apache ECharts","Ausgabe beschränkt auf selbstenthaltene HTML mit eingebettetem JS"],"pt":["Requer bibliotecas pyecharts e Apache ECharts","Saída limitada a HTML autocontido com JS incorporado"],"ru":["Требует библиотек pyecharts и Apache ECharts","Выходные данные ограничены самодостаточным HTML с встроенным JS"],"ar":["يتطلب مكتبات pyecharts و Apache ECharts","الخرج محدود بالرسوم البيانية HTML مكتفية ذاتيًا مع JS مدمج"]},"version":4},"contentHash":"8d1946ffa8fdf5357755820f2891dc5e2a51bfe8f16786306278a8488c0be55a","qualityScore":39}');
