INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('T-Klug/aws-cur-report-generator/visualization', 'visualization', 'T-Klug', 'aws-cur-report-generator', 'community', 'visualization T-Klug aws-cur-report-generator community The visualization skill generates interactive charts using pyecharts and Apache ECharts, benefiting developers who need to create self-contained HTML with embedded JS. It supports various chart types, including bar charts. 使用pyecharts和Apache ECharts实现数据可视化，创建自包含的HTML报告 AIエージェントによるビジュアライゼーションを実現し、pyechartsとApache EChartsの機能を活用 pyecharts와 Apache ECharts를 사용하여 데이터 시각화를 구현하고 자체 포함 HTML 보고서를 생성 La visualización es una habilidad que permite crear gráficos personalizados con pyecharts y Apache ECharts. Permite generar HTML autocontenidos con JavaScript incrustado. La visualisation est une compétence qui permet de créer des graphiques personnalisés avec pyecharts et Apache ECharts. Elle permet de générer des HTML autocontenus avec du JavaScript intégré. Die Visualisierung ist eine Fähigkeit, die das Erstellen benutzerdefinierter Diagramme mit pyecharts und Apache ECharts ermöglicht. Sie ermöglicht die Generierung selbstenthaltener HTML mit eingebettetem JavaScript. A visualização é uma habilidade que permite criar gráficos personalizados com pyecharts e Apache ECharts. Ela é útil para desenvolvedores que precisam integrar visualização em seus projetos. Визуализация - это навык, который позволяет создавать индивидуальные графики с помощью ИИ Агентов и Apache ECharts. Он полезен для разработчиков, которым необходимо интегрировать визуализацию в свои проекты. التصور هو مهارة تسمح بإنشاء مخططات مخصصة باستخدام مكتبات Python و Apache ECharts. انها مفيدة للمطورين الذين يحتاجون إلى دمج التصور في مشاريعهم. how to use visualization in AI agents what is visualization in data science visualization alternative to matplotlib visualization vs d3.js visualization setup guide for developers installing visualization libraries for Python 数据可视化 pyecharts Apache ECharts HTML报告 交互式图表 数据分析 可视化工具 AIエージェント 数据科学 Generates self-contained HTML with embedded JS using Apache ECharts Supports various chart types, including bar charts via pyecharts Utilizes pyecharts options, such as title_opts and tooltip_opts, for customization Creates interactive charts with add_xaxis and add_yaxis functions Enables developers to set global options, including title and tooltip settings Visualization is a skill that generates interactive charts and graphs using technologies like pyecharts and Apache ECharts, enabling developers to create informative and engaging data visualizations.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('expeor/aws-automation/tdd-workflow', 'community', 'expeor', 'aws-automation', 'expeor/aws-automation', 'tdd-workflow', 0, 0, 39, '2026-03-08T01:57:15.298Z', '2026-03-08T02:01:24.052Z', 'ade1547949da64b4913fd8754a5d1b60e5c4510d823c03435c511f50593e9391', '{"id":"expeor/aws-automation/tdd-workflow","name":"tdd-workflow","description":{"en":"The tdd-workflow skill provides a test-driven development guide for AWS automation, supporting multi-account and region setups. It helps developers follow the Iron Law of TDD.","zh":"TDD 工作流程是一种测试驱动开发方法，通过自动化测试实现高质量代码","ja":"TDD ワークフローは、自動化テストを使用して高品質なコードを実現するテスト駆動開発方法です","ko":"TDD 워크플로우는 자동화 테스트를 사용하여 높은 품질의 코드를 구현하는 테스트 주도 개발 방법입니다","es":"El flujo de trabajo TDD es una guía para la automatización de pruebas con AWS CLI y Excel","fr":"Le flux de travail TDD est un guide pour l''automatisation des tests avec AWS CLI et Excel","de":"Der TDD-Workflow ist ein Leitfaden für die Automatisierung von Tests mit AWS CLI und Excel","pt":"O fluxo de trabalho TDD é uma abordagem de desenvolvimento de software que prioriza a escrita de testes antes do código","ru":"Поток работы TDD - это подход к разработке программного обеспечения, который отдает предпочтение написанию тестов перед кодом","ar":"تدفق عمل TDD هو نهج في تطوير البرمجيات يؤكد على كتابة الاختبارات قبل الكود"},"seo":{"title":{"en":"tdd-workflow: Test-Driven Development Setup Guide | AI Ag...","zh":"TDD 工作流程 Setup Guide - AWS 自动化 CLI","ja":"TDD ワークフロー ベストプラクティス - AWS 自動化 CLI","ko":"TDD 워크플로우 설정 가이드 - AWS 운영 자동화 CLI","es":"Guía de configuración de TDD Workflow para automatización...","fr":"Guide de mise en place du flux de travail TDD pour l''auto...","de":"Einrichtungsleitfaden für TDD-Workflow zur Automatisierun...","pt":"Guia de Configuração do Fluxo de Trabalho TDD","ru":"Настройка Потока Работы TDD: Руководство по ИИ Агентам","ar":"دليل إعداد تدفق عمل TDD للآلات الذكية"},"description":{"en":"Learn how to implement the Iron Law of TDD with the tdd-workflow skill. Get started with Red-Green-Refactor and automate testing for your AWS projects now!","zh":"了解 TDD 工作流程的优势和实现方法，使用 AWS 自动化 CLI 实现自动化测试","ja":"TDD ワークフローを使用した自動化テストの実装方法を紹介します - AWS 自動化 CLI","ko":"TDD 워크플로우를 사용하여 자동화 테스트를 구현하는 방법을 알아보세요 - AWS 운영 자동화 CLI","es":"Aprende a implementar TDD Workflow con AWS CLI y Excel para informes de pruebas automatizadas","fr":"Découvrez comment mettre en place le flux de travail TDD avec AWS CLI et Excel pour des rapports de tests automatisés","de":"Erfahren Sie, wie Sie TDD-Workflow mit AWS CLI und Excel für automatisierte Testberichte implementieren","pt":"Aprenda a configurar o fluxo de trabalho TDD com nossas dicas e práticas recomendadas para desenvolvedores","ru":"Узнайте, как настроить поток работы TDD с нашими советами и лучшими практиками для разработчиков ИИ Агентов","ar":"تعلم كيفية إعداد تدفق عمل TDD باستخدام نصائحنا وأفضل الممارسات لملحقي الآلات الذكية"},"definition":{"en":"tdd-workflow is a test-driven development approach that enforces the Iron Law, ensuring no production code is written without a failing test first.","zh":"TDD 工作流程是一种软件开发方法，通过先写测试代码来驱动开发过程","ja":"TDD ワークフローは、テストコードを先に書いて開発プロセスを推進するソフトウェア開発方法です","ko":"TDD 워크플로우는 테스트 코드를 먼저 작성하여 개발 프로세스를 진행하는 소프트웨어 개발 방법입니다","es":"TDD Workflow es un enfoque de desarrollo que prioriza la escritura de pruebas antes del código","fr":"Le flux de travail TDD est une approche de développement qui donne la priorité à l''écriture de tests avant le code","de":"TDD-Workflow ist ein Ansatz für die Entwicklung, der das Schreiben von Tests vor dem Code priorisiert","pt":"TDD significa Test-Driven Development, uma abordagem de desenvolvimento de software","ru":"TDD означает Test-Driven Development, подход к разработке программного обеспечения","ar":"TDD يعني تطوير مدفوع بالاختبار، نهج في تطوير البرمجيات"},"features":{"en":["Enforces the Iron Law of TDD: NO PRODUCTION CODE WITHOUT A FAILING TEST FIRST","Supports Red-Green-Refactor workflow for test-driven development","Automates testing for AWS projects with multi-account and region support","Generates Excel reports for test results","Follows a strict testing philosophy: write tests before writing code"],"zh":["Red-Green-Refactor 工作流程","自动化测试实现","AWS 自动化 CLI 支持","多账户和多区域支持","Excel 报告生成"],"ja":["Red-Green-Refactor ワークフロー","自動化テストの実装","AWS 自動化 CLI のサポート","マルチアカウントとマルチリージョンのサポート","Excel レポートの生成"],"ko":["Red-Green-Refactor 워크플로우","자동화 테스트 구현","AWS 운영 자동화 CLI 지원","멀티 계정과 멀티 리전 지원","Excel 보고서 생성"],"es":["Soporte para múltiples cuentas y regiones de AWS","Generación de informes de pruebas en Excel","Implementación de pruebas unitarias con Python","Uso de la filosofía del Iron Law para garantizar la calidad del código","Seguimiento del ciclo de vida de las pruebas con Red-Green-Refactor"],"fr":["Prise en charge de plusieurs comptes et régions AWS","Génération de rapports de tests dans Excel","Mise en œuvre de tests unitaires avec Python","Utilisation de la philosophie du Iron Law pour garantir la qualité du code","Suivi du cycle de vie des tests avec Red-Green-Refactor"],"de":["Unterstützung für mehrere AWS-Konten und -Regionen","Erstellung von Testberichten in Excel","Implementierung von Einheitstests mit Python","Verwendung der Philosophie des Iron Law zur Gewährleistung der Codequalität","Verfolgung des Testlebenszyklus mit Red-Green-Refactor"],"pt":["Suporte a múltiplas contas e regiões","Criação de relatórios em Excel","Implementação do ciclo Red-Green-Refactor","Escrita de testes antes do código","Uso de CLI para automação","Integração com AWS"],"ru":["Поддержка нескольких учетных записей и регионов","Создание отчетов в Excel","Реализация цикла Red-Green-Refactor","Написание тестов перед кодом","Использование CLI для автоматизации","Интеграция с AWS"],"ar":["دعم حسابات ومناطق متعددة","إنشاء تقارير في Excel","تنفيذ دورة Red-Green-Refactor","كتابة الاختبارات قبل الكود","استخدام CLI للتحكم الآلي","التكامل مع AWS"]},"keywords":{"en":["how to use tdd-workflow","tdd-workflow setup guide","test-driven development for AWS","Red-Green-Refactor workflow","tdd-workflow vs traditional testing","automating testing with tdd-workflow","tdd-workflow install","what is tdd-workflow","tdd-workflow alternative"],"zh":["TDD 工作流程","自动化测试","AWS 自动化 CLI","测试驱动开发","Red-Green-Refactor","软件开发方法","AIエージェント"],"ja":["TDD ワークフロー","自動化テスト","AWS 自動化 CLI","テスト駆動開発","Red-Green-Refactor","ソフトウェア開発方法","AIエージェント"],"ko":["TDD 워크플로우","자동화 테스트","AWS 운영 자동화 CLI","테스트 주도 개발","Red-Green-Refactor","소프트웨어 개발 방법","AI 에이전트"],"es":["TDD Workflow","automatización de pruebas","AWS CLI","Excel","pruebas unitarias","Python","Iron Law","Red-Green-Refactor"],"fr":["Flux de travail TDD","automatisation des tests","AWS CLI","Excel","tests unitaires","Python","Iron Law","Red-Green-Refactor"],"de":["TDD-Workflow","Automatisierung von Tests","AWS CLI","Excel","Einheitstests","Python","Iron Law","Red-Green-Refactor"],"pt":["tdd workflow","desenvolvimento de software","test-driven development","aws cli","relatórios em excel","ciclo red-green-refactor","automatização de processos","desenvolvedores de software"],"ru":["tdd поток работы","разработка программного обеспечения","test-driven development","aws cli","отчеты в excel","цикл red-green-refactor","автоматизация процессов","разработчики программного обеспечения"],"ar":["تدفق عمل tdd","تطوير البرمجيات","تطوير مدفوع بالاختبار","aws cli","تقارير في إكسل","دورة red-green-refactor","التحكم الآلي للعمليات","مطوري البرمجيات"]}},"owner":"expeor","repo":"aws-automation","repoPath":"expeor/aws-automation","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.298Z","topics":[],"category":"community","skillMd":{"name":"tdd-workflow","description":"TDD 워크플로우 가이드. Red-Green-Refactor 철학, pytest, moto 모킹, 테스트 패턴.","bodyPreview":"# TDD 워크플로우\n\n테스트 주도 개발 가이드입니다.\n\n## 철학: The Iron Law\n\n```\nNO PRODUCTION CODE WITHOUT A FAILING TEST FIRST\n```\n\n테스트 전에 코드를 작성했다면? **삭제하고 다시 시작.**\n\n- \"참고용으로 보관\" 금지\n- \"적용하면서 테스트 작성\" 금지\n- 테스트로부터 새로 구현\n\n## Red-Green-Refactor\n\n### RED - 실패하는 테스트 작성\n\n하나의 행위만 테스트하는 최소한의 테스트 작성.\n\n```python\ndef test_find_unused_volumes_returns_unattached_volumes():\n    \"\"\"미연결 볼륨만 반환하는지 테스트\"\"\"\n    # Arrange\n    volumes = [\n        {\"VolumeId\": \"vol-1\", \"Attachments\": []},          # 미연결\n        {\"VolumeId\": \"vol-2\", \"Attach","body":"# TDD 워크플로우\n\n테스트 주도 개발 가이드입니다.\n\n## 철학: The Iron Law\n\n```\nNO PRODUCTION CODE WITHOUT A FAILING TEST FIRST\n```\n\n테스트 전에 코드를 작성했다면? **삭제하고 다시 시작.**\n\n- \"참고용으로 보관\" 금지\n- \"적용하면서 테스트 작성\" 금지\n- 테스트로부터 새로 구현\n\n## Red-Green-Refactor\n\n### RED - 실패하는 테스트 작성\n\n하나의 행위만 테스트하는 최소한의 테스트 작성.\n\n```python\ndef test_find_unused_volumes_returns_unattached_volumes():\n    \"\"\"미연결 볼륨만 반환하는지 테스트\"\"\"\n    # Arrange\n    volumes = [\n        {\"VolumeId\": \"vol-1\", \"Attachments\": []},          # 미연결\n        {\"VolumeId\": \"vol-2\", \"Attachments\": [{\"InstanceId\": \"i-1\"}]},  # 연결됨\n    ]\n\n    # Act\n    result = find_unused_volumes(volumes)\n\n    # Assert\n    assert len(result) == 1\n    assert result[0][\"VolumeId\"] == \"vol-1\"\n```\n\n**요구사항:**\n- 하나의 행위만 테스트\n- 명확한 이름 (무엇을_어떤상황에서_어떤결과)\n- 실제 코드 테스트 (가능하면 mock 최소화)\n\n### Verify RED - 반드시 실패 확인\n\n```bash\npytest tests/plugins/ec2/test_ebs_audit.py::test_find_unused_volumes -v\n```\n\n확인:\n- 테스트가 **실패**하는가? (에러가 아닌 실패)\n- 실패 이유가 **기능 미구현** 때문인가? (오타 아님)\n\n### GREEN - 최소한의 코드\n\n테스트를 통과시키는 **가장 단순한** 코드 작성.\n\n```python\ndef find_unused_volumes(volumes: list[dict]) -> list[dict]:\n    return [v for v in volumes if not v.get(\"Attachments\")]\n```\n\n**금지 사항:**\n- 미래를 위한 확장성 추가\n- 요청받지 않은 기능 추가\n- \"개선\"을 위한 리팩토링\n\n### Verify GREEN - 통과 확인\n\n```bash\npytest tests/plugins/ec2/test_ebs_audit.py -v\n```\n\n확인:\n- 테스트 통과\n- 다른 테스트도 통과\n- 경고/에러 없음\n\n### REFACTOR - 코드 개선\n\nGREEN 이후에만:\n- 중복 제거\n- 이름 개선\n- 헬퍼 추출\n\n**테스트는 항상 통과 상태 유지.**\n\n---\n\n## 프로젝트 테스트 구조\n\n```\ntests/\n├── conftest.py           # 공유 fixtures\n├── cli/                  # CLI 테스트\n├── core/                 # Core 모듈 테스트\n│   ├── parallel/         # 병렬 처리 테스트\n│   └── tools/            # 도구 테스트\n└── plugins/              # 플러그인 테스트\n    └── cloudwatch/       # CloudWatch 배치 메트릭 테스트\n```\n\n## AWS 모킹 (moto)\n\n### 기본 패턴\n\n```python\nimport boto3\nfrom moto import mock_aws\n\n@mock_aws\ndef test_describe_instances():\n    # moto가 AWS를 모킹\n    client = boto3.client(''ec2'', region_name=''ap-northeast-2'')\n\n    # 테스트 데이터 생성\n    client.run_instances(\n        ImageId=''ami-12345678'',\n        MinCount=1,\n        MaxCount=1,\n        InstanceType=''t2.micro'',\n    )\n\n    # 테스트 실행\n    response = client.describe_instances()\n    assert len(response[''Reservations'']) == 1\n```\n\n### Fixture 사용\n\n```python\n# tests/conftest.py\nimport pytest\nimport boto3\nfrom moto import mock_aws\n\n@pytest.fixture\ndef aws_credentials():\n    \"\"\"Mocked AWS Credentials\"\"\"\n    import os\n    os.environ[''AWS_ACCESS_KEY_ID''] = ''testing''\n    os.environ[''AWS_SECRET_ACCESS_KEY''] = ''testing''\n    os.environ[''AWS_SECURITY_TOKEN''] = ''testing''\n    os.environ[''AWS_SESSION_TOKEN''] = ''testing''\n\n@pytest.fixture\ndef mock_ec2(aws_credentials):\n    \"\"\"Mocked EC2 client\"\"\"\n    with mock_aws():\n        yield boto3.client(''ec2'', region_name=''ap-northeast-2'')\n\n@pytest.fixture\ndef mock_ctx():\n    \"\"\"Mocked CLI context\"\"\"\n    from unittest.mock import MagicMock\n    ctx = MagicMock()\n    ctx.provider.get_session.return_value = boto3.Session()\n    ctx.regions = [''ap-northeast-2'']\n    return ctx\n```\n\n## 테스트 명명 규칙\n\n```python\ndef test_함수명_상황_예상결과():\n    ...\n\n# 예시\ndef test_find_unused_volumes_when_no_attachments_returns_volume():\n    ...\n\ndef test_analyze_region_with_access_denied_returns_empty_list():\n    ...\n```\n\n## 테스트 실행\n\n```bash\n# 전체 테스트\npytest tests/ -v\n\n# 특정 파일\npytest tests/plugins/ec2/test_ebs_audit.py -v\n\n# 특정 함수\npytest tests/plugins/ec2/test_ebs_audit.py::test_unused_volumes -v\n\n# 커버리지\npytest tests/ --cov=core --cov=cli --cov=plugins --cov-report=html\n\n# 실패 시 즉시 중단\npytest tests/ -x\n\n# 마지막 실패 테스트만\npytest tests/ --lf\n```\n\n## 테스트 카테고리\n\n### 단위 테스트\n개별 함수/메서드 테스트:\n```python\ndef test_validate_account_id():\n    assert validate_account_id(''123456789012'') is True\n    assert validate_account_id(''invalid'') is False\n```\n\n### 통합 테스트\n모듈 간 상호작용 테스트:\n```python\n@mock_aws\ndef test_ebs_audit_full_workflow():\n    # 데이터 생성 → 분석 → 결과 검증\n```\n\n### E2E 테스트\n전체 CLI 플로우 테스트:\n```python\nfrom click.testing import CliRunner\nfrom core.cli.app import cli\n\ndef test_list_tools_command():\n    runner = CliRunner()\n    result = runner.invoke(cli, [''list-tools''])\n    assert result.exit_code == 0\n    assert ''ec2'' in result.output\n```\n\n## 고급 패턴\n\n### Parameterized 테스트\n\n```python\nimport pytest\n\n@pytest.mark.parametrize(\"volume,expected\", [\n    ({\"VolumeId\": \"vol-1\", \"Attachments\": []}, True),       # 미연결\n    ({\"VolumeId\": \"vol-2\", \"Attachments\": [{}]}, False),    # 연결됨\n    ({\"VolumeId\": \"vol-3\", \"Attachments\": None}, True),     # None 처리\n])\ndef test_is_volume_unused(volume, expected):\n    assert is_volume_unused(volume) == expected\n```\n\n### 예외 테스트\n\n```python\nimport pytest\nfrom botocore.exceptions import ClientError\n\ndef test_collect_with_access_denied_returns_empty():\n    \"\"\"AccessDenied 에러 시 빈 결과 반환\"\"\"\n    with pytest.raises(ClientError) as exc_info:\n        raise_access_denied()\n\n    assert exc_info.value.response[''Error''][''Code''] == ''AccessDenied''\n```\n\n### Async 테스트\n\n```python\nimport pytest\n\n@pytest.mark.asyncio\nasync def test_async_collect():\n    result = await async_collect_resources()\n    assert len(result) > 0\n```\n\n---\n\n## TDD 체크리스트\n\n### 작업 시작 전\n- [ ] 구현하려는 기능 명확히 이해\n- [ ] 실패하는 테스트 먼저 작성\n\n### RED 단계\n- [ ] 하나의 행위만 테스트\n- [ ] 테스트 이름이 행위를 설명\n- [ ] 테스트 실행 → 실패 확인\n- [ ] 실패 이유가 기능 미구현 (오타 아님)\n\n### GREEN 단계\n- [ ] 최소한의 코드만 작성\n- [ ] YAGNI 원칙 (필요 없는 것은 만들지 않음)\n- [ ] 테스트 통과 확인\n- [ ] 다른 테스트도 통과\n\n### REFACTOR 단계\n- [ ] GREEN 상태에서만 리팩토링\n- [ ] 리팩토링 후에도 테스트 통과\n- [ ] 중복 제거, 이름 개선\n\n### 완료 전\n- [ ] 모든 새 함수에 테스트 있음\n- [ ] 엣지 케이스 테스트 (빈 목록, None 등)\n- [ ] 에러 케이스 테스트 (AccessDenied 등)\n- [ ] 린트 통과 (ruff check)\n\n---\n\n## 흔한 합리화 (금지)\n\n| 합리화 | 현실 |\n|--------|------|\n| \"너무 단순해서 테스트 불필요\" | 단순한 코드도 깨진다. 테스트 30초면 됨. |\n| \"나중에 테스트 작성\" | 통과하는 테스트는 아무것도 증명 못함. |\n| \"수동 테스트했음\" | 기록 없음, 재실행 불가, 누락 가능. |\n| \"시간 낭비\" | TDD가 디버깅보다 빠름. |\n| \"이미 X시간 투자\" | 매몰 비용. 신뢰할 수 없는 코드 유지가 더 낭비. |\n\n---\n\n## 참조\n\n- `obra-superpowers/skills/test-driven-development/` - TDD 철학 상세\n- `wshobson-agents/plugins/python-development/skills/python-testing-patterns/` - pytest 고급 패턴\n- `core/parallel/errors.py` - ErrorCollector 테스트 예시\n- `tests/conftest.py` - 공유 fixtures\n"},"lastSynced":"2026-03-08T02:01:24.052Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing advanced test-driven development workflow capabilities for AWS automation","zh":"非常适合需要高级测试驱动开发工作流功能的 AWS 自动化开发代理","ja":"AWS 自動化の高度なテスト駆動開発ワークフロー機能を必要とする開発エージェントに最適","ko":"고급 테스트 주도 개발 워크플로 기능이 필요한 AWS 자동화 개발 에이전트에 적합","es":"Perfecto para Agentes de Desarrollo que necesitan capacidades de flujo de trabajo de desarrollo dirigido por pruebas avanzadas para la automatización de AWS","fr":"Parfait pour les agents de développement nécessitant des capacités de flux de travail de développement piloté par les tests avancées pour l''automatisation d''AWS","de":"Perfekt für Entwicklungssagenten, die erweiterte Workflows für testgetriebene Entwicklung für die AWS-Automatisierung benötigen","pt":"Perfeito para Agentes de Desenvolvimento que necessitam de capacidades de fluxo de trabalho de desenvolvimento orientado a testes avançados para automação do AWS","ru":"Идеально для агентов разработки, которым требуются расширенные возможности рабочего процесса разработки, управляемой тестированием, для автоматизации AWS","ar":"مثالي للوكلاء التطوير الذين يحتاجون إلى إمكانيات متقدمة لتدفق العمل التطوير القائم على الاختبار للتحكم الآلي في AWS"},"recommendation":{"en":"Empowers agents to follow the Iron Law of TDD, utilizing Red-Green-Refactor methodologies and supporting multi-account and region setups with Python","zh":"赋予代理按照铁律进行测试驱动开发，利用红绿重构方法，并支持多账户和区域设置，使用 Python","ja":"エージェントに鉄則に従ったテスト駆動開発を行う権限を与え、Red-Green-Refactor 方法を利用し、Python を使用してマルチアカウントおよびリージョン設定をサポート","ko":"에이전트가 철의 법칙을 따라 테스트 주도 개발을 수행할 수 있도록 하며, Red-Green-Refactor 방법을 사용하고 Python을 사용하여 다중 계정 및 리ージョン 설정을 지원","es":"Habilita a los agentes a seguir la Ley de Hierro de TDD, utilizando metodologías Red-Verde-Refactorizar y soportando configuraciones de varias cuentas y regiones con Python","fr":"Permet aux agents de suivre la Loi de Fer du TDD, en utilisant des méthodologies Red-Vert-Refactoriser et en prenant en charge les configurations de plusieurs comptes et régions avec Python","de":"Ermächtigt Agenten, dem Eisernen Gesetz von TDD zu folgen, indem sie Red-Grün-Refactor-Methoden verwenden und Multi-Konto- und Regionseinrichtungen mit Python unterstützen","pt":"Habilita os agentes a seguir a Lei de Ferro do TDD, utilizando metodologias Red-Green-Refactor e suportando configurações de múltiplas contas e regiões com Python","ru":"Наделяет агентов возможностью следовать Железному Закону TDD, используя методологии Red-Green-Refactor и поддерживая настройки нескольких учетных записей и регионов с Python","ar":"يمنح الوكلاء القدرة على اتباع قانون الحديد TDD ، باستخدام منهجيات Red-Green-Refactor ودعم الإعدادات المتعددة للحسابات والمناطق مع Python"},"useCases":{"en":["Automating AWS resource testing","Generating test cases for Iron Law compliance","Refactoring existing codebases for TDD adherence"],"zh":["自动化 AWS 资源测试","生成遵守铁律的测试用例","重构现有的代码库以遵守测试驱动开发"],"ja":["AWS リソースの自動テスト","鉄則に準拠したテストケースの生成","既存のコードベースのリファクタリングによるテスト駆動開発の遵守"],"ko":["AWS 리소스 자동 테스트","철의 법칙을 준수하는 테스트 케이스 생성","기존 코드베이스의 리팩토링을 통한 테스트 주도 개발의 준수"],"es":["Automatización de pruebas de recursos de AWS","Generación de casos de prueba para el cumplimiento de la Ley de Hierro","Reestructuración de bases de código existentes para el cumplimiento de TDD"],"fr":["Automatisation des tests de ressources AWS","Génération de cas de test pour le respect de la Loi de Fer","Réorganisation de bases de code existantes pour le respect de TDD"],"de":["Automatisierung von AWS-Ressourcentests","Erzeugung von Testfällen für die Einhaltung des Eisernen Gesetzes","Umstrukturierung bestehender Codebasen für die Einhaltung von TDD"],"pt":["Automatizar testes de recursos do AWS","Gerar casos de teste para conformidade com a Lei de Ferro","Refatorar bases de código existentes para conformidade com o TDD"],"ru":["Автоматизировать тестирование ресурсов AWS","Генерировать тестовые случаи для соответствия Железному Закону","Рефакторить существующие кодовые базы для соответствия TDD"],"ar":["تحكم آلي لاختبار الموارد AWS","توليد حالات اختبار لامتثال لقانون الحديد","إعادة هيكلة قواعد الكود الموجودة للامتثال لبروتوكول TDD"]},"limitations":{"en":["Requires Python environment","AWS automation setup necessary","Strict adherence to Iron Law principles"],"zh":["需要 Python 环境","需要 AWS 自动化设置","严格遵守铁律原则"],"ja":["Python 環境が必要","AWS 自動化の設定が必要","鉄則の原則に厳格に従う"],"ko":["Python 환경이 필요","AWS 자동화 설정이 필요","철의 법칙의 원칙을 엄격히 준수"],"es":["Requiere entorno de Python","Configuración de automatización de AWS necesaria","Cumplimiento estricto de los principios de la Ley de Hierro"],"fr":["Nécessite un environnement Python","Configuration d''automatisation d''AWS nécessaire","Respect strict des principes de la Loi de Fer"],"de":["Benötigt Python-Umgebung","AWS-Automatisierungseinrichtung erforderlich","Strenger Einhaltung der Grundsätze des Eisernen Gesetzes"],"pt":["Requer ambiente Python","Configuração de automação do AWS necessária","Adesão estrita aos princípios da Lei de Ferro"],"ru":["Требуется среда Python","Необходимо настроить автоматизацию AWS","Строгое соблюдени