INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('dzhechko/2026-jan-pu-noom-clone-01/explore', 'explore', 'dzhechko', '2026-jan-pu-noom-clone-01', 'community', 'explore dzhechko 2026-jan-pu-noom-clone-01 community The Explore skill helps developers and AI agents understand the real problem before proposing a solution through systematic Socratic questioning. It ensures that vague requests are transformed into crystal-clear, actionable task specifications. Explore 技术通过系统化的苏格拉底式提问，实现任务明确，避免解决错误的问题 Explore 機能は、システム化されたソクラテス式の質問を通じて、タスクの明確化を実現します Explore 기능은 소크라테스식 질문을 통해 태스크를 명확하게 합니다 Explore es una habilidad que transforma solicitudes vagas en especificaciones de tareas claras y acciónables a través de preguntas socráticas sistemáticas Explore est une compétence qui transforme des demandes vagues en spécifications de tâches claires et actionnables à travers des questions socratiques systématiques Explore ist eine Fähigkeit, die vage Anfragen in klare und handhabbare Aufgabenbeschreibungen durch systematische sokratische Fragen umwandelt O Explore é uma habilidade que transforma solicitações vagas em especificações de tarefas claras através de questionamento socrático sistemático. Explore - это навык, который преобразует неясные запросы в четкие задачи посредством системного сократического вопроса. استكشاف هو مهارة تتحول الطلبات الغامضة إلى مواصفات مهام واضحة من خلال الاستجواب السقراطي المنظّم. how to use explore what is explore explore alternative explore vs adaptive task management explore install explore setup guide explore for AI agents adaptive task clarification Explore 技术 任务明确化 苏格拉底式提问 AI 技术 任务管理 问题解决 理解优先 避免错误问题 Utilizes systematic Socratic questioning to unlock understanding Reveals constraints to identify opportunities Ensures the real problem is understood before proposing a solution Transforms vague requests into crystal-clear, actionable task specifications Follows the core philosophy of never solving before understanding Explore is an AI agent skill that utilizes adaptive task clarification to transform vague requests into actionable task specifications through systematic Socratic questioning.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('h5y1m141/pedaru-vue/vue-skill', 'community', 'h5y1m141', 'pedaru-vue', 'h5y1m141/pedaru-vue', 'vue-skill', 0, 0, 39, '2026-03-08T01:57:15.300Z', '2026-03-08T02:01:30.437Z', '1814e7aa0f89439eb83748cd826b746288b941f11f5717d902e959491211c9bc', '{"id":"h5y1m141/pedaru-vue/vue-skill","name":"vue-skill","description":{"en":"The vue-skill enables developers to create Vue 3 + TypeScript projects with Nuxt, providing a clear implementation guide and best practices for AI assistants.","zh":"Vue-skill是基于Vue 3 + TypeScript的AI助手技能，支持单独运行和其他Subagent调用","ja":"Vue-skillはVue 3 + TypeScriptベースのAIアシスタント技能で、単独実行と他のSubagentからの呼び出しをサポート","ko":"Vue-skill은 Vue 3 + TypeScript 기반의 AI 도구 기능으로 단독 실행과 다른 Subagent 호출을 지원","es":"Vue-skill es un asistente de AI para proyectos de Vue 3 con TypeScript, diseñado para funcionar con Nuxt","fr":"Vue-skill est un assistant d''IA pour les projets Vue 3 avec TypeScript, conçu pour fonctionner avec Nuxt","de":"Vue-skill ist ein KI-Assistent für Vue-3-Projekte mit TypeScript, entwickelt für die Verwendung mit Nuxt","pt":"O vue-skill é uma ferramenta de AI para projetos Vue 3 e Nuxt, com suporte a TypeScript e Composition API.","ru":"ИИ Агенты: vue-skill - это инструмент для проектов Vue 3 и Nuxt, поддерживающий TypeScript и Composition API.","ar":"أداة الذكاء الاصطناعي vue-skill هي أداة لمشاريع Vue 3 و Nuxt، تدعم TypeScript و Composition API"},"seo":{"title":{"en":"vue-skill: Nuxt-Based Web App Setup Guide | AI Agent","zh":"Vue 3 AI技能设置指南","ja":"Vue-skill AIエージェントのベストプラクティス","ko":"Vue 3 AI 툴 설정 가이드","es":"Guía de configuración de Vue-skill para aplicaciones web ...","fr":"Guide de configuration de Vue-skill pour les applications...","de":"Konfigurationsleitfaden für Vue-skill für Webanwendungen ...","pt":"Guia de Configuração do vue-skill para Desenvolvedores","ru":"ИИ Агенты: vue-skill Настройка Руководство","ar":"إعداد أداة الذكاء الاصطناعي vue-skill للاستخدام"},"description":{"en":"Unlock the full potential of Vue 3 and Nuxt with vue-skill - explore the ultimate setup guide and best practices for AI agents now!","zh":"了解Vue 3 + TypeScript项目的AI助手技能，实现单独运行和其他Subagent调用","ja":"Vue 3 + TypeScriptプロジェクトのAIアシスタント技能を活用し、単独実行と他のSubagentからの呼び出しを実現","ko":"Vue 3 + TypeScript 프로젝트의 AI 도구 기능을 사용하여 단독 실행과 다른 Subagent 호출을 구현","es":"Aprende a configurar Vue-skill para crear aplicaciones web con Nuxt y aprovecha las mejores prácticas de Vue 3","fr":"Découvrez comment configurer Vue-skill pour créer des applications web avec Nuxt et profitez des meilleures pratiques de Vue 3","de":"Erfahren Sie, wie Sie Vue-skill für die Erstellung von Webanwendungen mit Nuxt konfigurieren und die besten Praktiken von Vue 3 nutzen","pt":"Aprenda a configurar o vue-skill para projetos Vue 3 e Nuxt com TypeScript, incluindo Composition API e Pinia","ru":"ИИ Агенты: узнайте, как настроить vue-skill для проектов Vue 3 и Nuxt с TypeScript, Composition API и Pinia","ar":"تعلم كيفية إعداد أداة الذكاء الاصطناعي vue-skill لاستخدامها في مشاريع Vue 3 و Nuxt مع TypeScript"},"definition":{"en":"vue-skill is a Vue 3 and Nuxt-based web application setup guide for AI agents, utilizing TypeScript and Composition API.","zh":"Vue-skill是基于Vue 3 + TypeScript的AI助手技能","ja":"Vue-skillはVue 3 + TypeScriptベースのAIアシスタント技能","ko":"Vue-skill은 Vue 3 + TypeScript 기반의 AI 도구 기능","es":"¿Qué es Vue-skill? Un asistente de AI para aplicaciones web de Vue 3 con Nuxt y TypeScript","fr":"Qu''est-ce que Vue-skill ? Un assistant d''IA pour les applications web Vue 3 avec Nuxt et TypeScript","de":"Was ist Vue-skill? Ein KI-Assistent für Webanwendungen von Vue 3 mit Nuxt und TypeScript","pt":"O que é vue-skill? É uma ferramenta de AI para desenvolvedores que trabalham com Vue 3 e Nuxt.","ru":"Что такое vue-skill? Это инструмент ИИ для разработчиков, работающих с Vue 3 и Nuxt.","ar":"ما هي أداة الذكاء الاصطناعي vue-skill؟ هي أداة لمطورين الذين يعملون مع Vue 3 و Nuxt"},"features":{"en":["Utilizes Vue 3 + Composition API with `<script setup>`","Integrates Nuxt 3 for enhanced web application development","Employs TypeScript for robust type checking and maintenance","Leverages Pinia for efficient state management","Provides a React to Vue 3 conversion guide with Hooks to Composition API mapping"],"zh":["支持Vue 3 + Composition API","使用Nuxt 3和TypeScript","实现状态管理使用Pinia","支持单独运行和其他Subagent调用","遵循Vue 3的最佳实践"],"ja":["Vue 3 + Composition APIをサポート","Nuxt 3とTypeScriptを使用","状態管理にPiniaを実装","単独実行と他のSubagentからの呼び出しをサポート","Vue 3のベストプラクティスに従う"],"ko":["Vue 3 + Composition API 지원","Nuxt 3와 TypeScript 사용","상태 관리에 Pinia 구현","단독 실행과 다른 Subagent 호출 지원","Vue 3의最佳实践 준수"],"es":["Compatibilidad con Vue 3 y Composition API","Integración con Nuxt 3 para aplicaciones web escalables","Soporte para TypeScript y Pinia para la gestión de estados","Diseño basado en las mejores prácticas de Vue 3","Capacidad para funcionar como un Subagent o de forma independiente"],"fr":["Compatibilité avec Vue 3 et Composition API","Intégration avec Nuxt 3 pour des applications web évolutives","Prise en charge de TypeScript et Pinia pour la gestion des états","Conception basée sur les meilleures pratiques de Vue 3","Capacité à fonctionner comme un sous-agent ou de manière indépendante"],"de":["Kompatibilität mit Vue 3 und Composition API","Integration mit Nuxt 3 für skalierbare Webanwendungen","Unterstützung für TypeScript und Pinia für die Zustandsverwaltung","Entwurf basierend auf den besten Praktiken von Vue 3","Fähigkeit, als Subagent oder unabhängig zu funktionieren"],"pt":["Suporte a Vue 3 e Composition API","Integração com Nuxt 3","Tipagem com TypeScript","Gerenciamento de estado com Pinia","Compatibilidade com React Hooks"],"ru":["Поддержка Vue 3 и Composition API","Интеграция с Nuxt 3","Типизация с помощью TypeScript","Управление состоянием с помощью Pinia","Совместимость с React Hooks"],"ar":["دعم Vue 3 و Composition API","تكامل مع Nuxt 3","تنسيق مع TypeScript","إدارة الحالة مع Pinia","توافق مع React Hooks"]},"keywords":{"en":["how to use vue-skill","vue-skill setup guide","vue-skill vs react","vue-skill install","what is vue-skill","vue-skill alternative","vue 3 composition api","nuxt 3 setup","typescript with vue"],"zh":["Vue 3 AI技能","Vue 3 + TypeScript","Nuxt 3","Pinia","AI助手技能","Vue 3最佳实践","AI工具设置","Vue 3设置指南"],"ja":["Vue 3 AIエージェント","Vue 3 + TypeScript","Nuxt 3","Pinia","AIアシスタント技能","Vue 3ベストプラクティス","AIツール設定","Vue 3設定ガイド"],"ko":["Vue 3 AI 툴","Vue 3 + TypeScript","Nuxt 3","Pinia","AI 도구 기능","Vue 3最佳实践","AI 설정 가이드","Vue 3 설정 가이드"],"es":["Vue-skill","Nuxt 3","Vue 3","TypeScript","Pinia","Herramientas de AI para desarrolladores","Asistentes de AI para aplicaciones web","Mejores prácticas de Vue 3","Desarrollo de aplicaciones web con Nuxt"],"fr":["Vue-skill","Nuxt 3","Vue 3","TypeScript","Pinia","Outils d''IA pour les développeurs","Assistant d''IA pour les applications web","Meilleures pratiques de Vue 3","Développement d''applications web avec Nuxt"],"de":["Vue-skill","Nuxt 3","Vue 3","TypeScript","Pinia","KI-Tools für Entwickler","KI-Assistenten für Webanwendungen","Beste Praktiken von Vue 3","Entwicklung von Webanwendungen mit Nuxt"],"pt":["vue-skill","AI para desenvolvedores","Vue 3","Nuxt 3","TypeScript","Composition API","Pinia","React Hooks"],"ru":["ИИ Агенты","vue-skill","Vue 3","Nuxt 3","TypeScript","Composition API","Pinia","React Hooks"],"ar":["أداة الذكاء الاصطناعي","vue-skill","Vue 3","Nuxt 3","TypeScript","Composition API","Pinia","React Hooks"]}},"owner":"h5y1m141","repo":"pedaru-vue","repoPath":"h5y1m141/pedaru-vue","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.300Z","topics":[],"category":"community","skillMd":{"name":"vue-skill","description":"Vue/TypeScriptの実装に関するAgent","bodyPreview":"あなたはVue 3 + TypeScriptプロジェクトのAIアシスタントです。\n\n単独での実行、他のSubagentからの呼び出し、どちらのケースでも適切に動作し、明確な結果を返します。\n\n# Vue/TypeScript実装ガイドライン\n\nこのガイドラインは、AI実装で発生しがちな問題パターンとその解決方法をまとめたものです。\n\n## プロジェクト概要\n\nこのプロジェクト（pedaru-vue）は、React/Next.jsベースのPDFビューワーアプリ「pedaru」をVue3/Nuxtに移植するものです。\n\n**目的:**\n- Vue3の仕組みを効果的に使った実装\n- 単なる機能移植ではなく、Vue3のベストプラクティスに沿った設計\n\n**技術スタック:**\n- Vue 3 + Composition API（`<script setup>`）\n- Nuxt 3\n- TypeScript\n- Pinia（状態管理）\n\n---\n\n## React から Vue3 への変換ガイド\n\n### React Hooks → Vue3 Composition API マッピング\n\n| Re","body":"あなたはVue 3 + TypeScriptプロジェクトのAIアシスタントです。\n\n単独での実行、他のSubagentからの呼び出し、どちらのケースでも適切に動作し、明確な結果を返します。\n\n# Vue/TypeScript実装ガイドライン\n\nこのガイドラインは、AI実装で発生しがちな問題パターンとその解決方法をまとめたものです。\n\n## プロジェクト概要\n\nこのプロジェクト（pedaru-vue）は、React/Next.jsベースのPDFビューワーアプリ「pedaru」をVue3/Nuxtに移植するものです。\n\n**目的:**\n- Vue3の仕組みを効果的に使った実装\n- 単なる機能移植ではなく、Vue3のベストプラクティスに沿った設計\n\n**技術スタック:**\n- Vue 3 + Composition API（`<script setup>`）\n- Nuxt 3\n- TypeScript\n- Pinia（状態管理）\n\n---\n\n## React から Vue3 への変換ガイド\n\n### React Hooks → Vue3 Composition API マッピング\n\n| React | Vue 3 | 備考 |\n|-------|-------|------|\n| `useState` | `ref` / `reactive` | プリミティブはref、オブジェクトはreactive |\n| `useEffect` | `watch` / `watchEffect` / `onMounted` | 依存配列の有無で使い分け |\n| `useCallback` | 通常の関数 | Vueでは不要（必要に応じてcomputed） |\n| `useMemo` | `computed` | |\n| `useRef` | `ref` / `useTemplateRef` | DOM参照はuseTemplateRef |\n| `useContext` | `provide` / `inject` または Pinia | グローバルはPinia推奨 |\n| `useReducer` | Pinia store | |\n\n### 変換例\n\n**React (useState + useEffect):**\n\n```tsx\nconst [count, setCount] = useState(0);\nconst [doubled, setDoubled] = useState(0);\n\nuseEffect(() => {\n  setDoubled(count * 2);\n}, [count]);\n```\n\n**Vue3 (ref + computed):**\n\n```typescript\nconst count = ref(0);\nconst doubled = computed(() => count.value * 2);\n```\n\n### useEffectの変換パターン\n\n**依存配列なし（マウント時のみ）:**\n\n```tsx\n// React\nuseEffect(() => {\n  console.log(''mounted'');\n}, []);\n```\n\n```typescript\n// Vue3\nonMounted(() => {\n  console.log(''mounted'');\n});\n```\n\n**依存配列あり（値の変更を監視）:**\n\n```tsx\n// React\nuseEffect(() => {\n  fetchData(id);\n}, [id]);\n```\n\n```typescript\n// Vue3\nwatch(() => id.value, (newId) => {\n  fetchData(newId);\n}, { immediate: true });\n```\n\n**クリーンアップあり:**\n\n```tsx\n// React\nuseEffect(() => {\n  const timer = setInterval(() => {}, 1000);\n  return () => clearInterval(timer);\n}, []);\n```\n\n```typescript\n// Vue3\nonMounted(() => {\n  const timer = setInterval(() => {}, 1000);\n  onUnmounted(() => clearInterval(timer));\n});\n```\n\n### 移植しない機能\n\n以下に該当するものは移植対象外とする：\n\n- **Electron/Tauri固有の処理**: デスクトップアプリ固有のAPI呼び出し\n- **不要な互換性維持コード**: 後方互換のためだけのコード\n- **過剰なエラーハンドリング**: 発生し得ないケースの処理\n\n---\n\n## 注意！！！\n\n- 当ファイルを読む際は必ず全文読み込んでください。断片的に読んでも良い作業はできません。\n\n## 目次\n\n1. [プロジェクト概要](#プロジェクト概要)\n2. [React から Vue3 への変換ガイド](#react-から-vue3-への変換ガイド)\n3. [Composables設計のベストプラクティス](#composables設計のベストプラクティス)\n4. [既存コンポーネントへの影響を最小化する設計](#既存コンポーネントへの影響を最小化する設計)\n5. [コンポーネント設計のベストプラクティス](#コンポーネント設計のベストプラクティス)\n6. [TypeScript型安全性のベストプラクティス](#typescript型安全性のベストプラクティス)\n7. [テスト戦略とベストプラクティス](#テスト戦略とベストプラクティス)\n8. [実装チェックリスト](#実装チェックリスト)\n9. [まとめ](#まとめ)\n\n---\n\n### pages/配下のコンポーネント肥大化防止\n\n**原則:** pages/配下のコンポーネントを修正する際は、Atomic Designの考えに基づき、新規コンポーネントを作成してロジックを分離する。\n\n```\npedaru-vue/\n├── components/\n│   ├── atoms/      # 基本的なUI要素\n│   ├── molecules/  # 複合コンポーネント\n│   └── organisms/  # 複雑な機能\n├── composables/    # ビジネスロジック（型定義も同じファイルに配置）\n├── pages/          # ルートコンポーネント（薄く保つ）\n└── stores/         # Pinia stores\n```\n\n---\n\n## Composables設計のベストプラクティス\n\n### 単一責任の原則\n\n**ガイドライン:**\n- 1つのcomposableは1つの関心事のみを扱う\n- ファイル名はその責任を明確に表す（`use*`で始まる）\n- 50〜100行を目安とし、それを超える場合は分割を検討\n- **複数のcomposableを組み合わせて使用する設計を推奨（Compose）**\n\n**❌ Bad: 複数の責任を持つ巨大なComposable**\n\n```typescript\n// useVideoManagement.ts（悪い例）\nexport function useVideoManagement() {\n  // ポーリング、時間計算、セッション記録、Zoom SDK操作が混在\n  // 100行以上の複雑なロジック...\n}\n```\n\n**✅ Good: 責任を分離**\n\n```typescript\n// useVideoStatus.ts - ビデオステータスのポーリング専用\nexport function useVideoStatus() {\n  const videoStatus = ref<VideoStageStatusResponse | null>(null);\n  const fetchVideoStatus = async (id: number) => { /* ... */ };\n  const startPolling = (id: number) => { /* ... */ };\n  const stopPolling = () => { /* ... */ };\n  return { videoStatus, fetchVideoStatus, startPolling, stopPolling };\n}\n\n// useSessionElapsedTime.ts - 時間計算専用\nexport function useSessionElapsedTime(sessionStartTime: Ref<string | null>) {\n  const elapsedTime = computed(() => { /* ... */ });\n  return { elapsedTime };\n}\n```\n\n**✅ Good: 複数のComposableを組み合わせる（Compose）**\n\n**重要な判断基準：責任範囲の正しい分離**\n\n例：症状選択機能で「選択」と「送信履歴管理」を1つのcomposableに混在させてはいけません。\n\n```typescript\n// ❌ Bad: 責任範囲が混在\n// useSymptomSelection.ts\nexport function useSymptomSelection() {\n  // 症状選択の責任\n  const toggleSymptomSelection = (key: SymptomItemKeyType) => { /* ... */ };\n\n  // 送信履歴管理の責任（別の関心事！）\n  const markAsSent = (key: SymptomItemKeyType) => { /* ... */ };\n  const onSendSuccess = () => { /* 混在している */ };\n\n  return { toggleSymptomSelection, markAsSent, onSendSuccess };\n}\n```\n\n**正しい設計：各関心事を独立したcomposableに分離し、組み合わせて使用**\n\n```typescript\n// useSymptomSelection.ts - 症状選択のみに集中\nexport function useSymptomSelection() {\n  const selectedSymptomItems = ref<Set<SymptomItemKeyType>>(new Set());\n  const toggleSymptomSelection = (key: SymptomItemKeyType) => { /* ... */ };\n  const resetSelectedSymptoms = () => { /* ... */ };\n  const selectedSymptoms = computed(() => { /* ... */ });\n\n  return { selectedSymptomItems, selectedSymptoms, toggleSymptomSelection, resetSelectedSymptoms };\n}\n\n// useSymptomSendHistory.ts - 送信履歴管理専用（新規ファイル）\nexport function useSymptomSendHistory() {\n  const sentSymptomItems = ref<Set<SymptomItemKeyType>>(new Set());\n  const markAsSent = (keys: SymptomItemKeyType[]) => {\n    keys.forEach(key => sentSymptomItems.value.add(key));\n  };\n  const isSent = (key: SymptomItemKeyType): boolean => {\n    return sentSymptomItems.value.has(key);\n  };\n\n  return { sentSymptomItems, markAsSent, isSent };\n}\n\n// useChatMessageGenerator.ts - メッセージ生成専用（新規ファイル）\nexport function useChatMessageGenerator() {\n  const generateSymptomMessage = (symptoms: SymptomItem[]): string => {\n    const mainMessage = ''症状に合わせたホームケアのPDFをお送りします。'';\n    const contents = symptoms.map((s) => `・${s.title}\\n${s.url}\\n`).join(''\\n'');\n    return `${mainMessage}\\n${contents}`;\n  };\n\n  return { generateSymptomMessage };\n}\n\n// ChatAttachedPdfSelect.vue - 複数のcomposableを組み合わせる（Compose）\nconst { selectedSymptoms, resetSelectedSymptoms } = useSymptomSelection();\nconst { markAsSent } = useSymptomSendHistory();\nconst { generateSymptomMessage } = useChatMessageGenerator();\n\nconst handleSendChat = async () => {\n  const message = generateSymptomMessage(selectedSymptoms.value);\n  const success = await props.onSendChat(message);\n\n  if (success) {\n    markAsSent(selectedSymptoms.value.map(s => s.key));\n    resetSelectedSymptoms();\n    await showToast();\n  }\n};\n```\n\n**メリット:**\n- ✅ **単一責任の原則**: 各composableが1つの関心事のみ\n- ✅ **Composeの原則**: 複数のcomposableを組み合わせて使用\n- ✅ **テスト容易性**: 各関心事を独立してテスト可能\n- ✅ **再利用性**: 送信履歴管理は他の機能でも再利用可能\n- ✅ **明確な責任範囲**: ファイル名から役割が明確\n\n### レイヤー分離（技術層とビジネス層）\n\n**ガイドライン:**\n- **技術層**: 外部ライブラリ（Zoom SDK、Twilio）の操作のみ\n- **アプリケーション層**: ビジネスロジック、Pinia操作、DB記録\n- 依存方向は常に「アプリケーション層 → 技術層」\n- コメントで設計意図を明示（`// NOTE: Piniaにアクセスしない`など）\n\n**❌ Bad: 技術的な詳細とビジネスロジックが混在**\n\n```typescript\n// useZoomVideoSession.ts（悪い例）\nexport function useZoomVideoSession() {\n  const startSession = async () => {\n    // Zoom SDKの初期化\n    zoomClient.value = ZoomVideo.createClient();\n    await zoomClient.value.init(''ja-JP'', ''Global'');\n\n    // ビジネスロジック（DB記録）が混在\n    await videoStageRepository.create({ status: ''active'' });\n\n    // Piniaへのアクションも混在\n    pdfStore.updateStatus(''active'');\n  };\n}\n```\n\n**✅ Good: レイヤーを明確に分離**\n\n```typescript\n// useZoomVideo.ts - 技術層（Zoom SDK操作のみ）\nexport function useZoomVideo() {\n  const createSession = async (sessionId: string) => { /* Zoom SDKのみ */ };\n  const joinSession = async (sessionId: string) => { /* Zoom SDKのみ */ };\n  // NOTE: Piniaにアクセスしない\n  return { createSession, joinSession };\n}\n\n// useOnlineReservationVideoSession.ts - アプリケーション層\nexport function useOnlineReservationVideoSession() {\n  const { createSession, joinSession } = useZoomVideo();\n\n  const startTalking = async (sessionId: string, id: number) => {\n    await createSession(sessionId);              // 1. Zoom SDK\n    await videoStageRepository.create({ id });   // 2. DB記録\n    pdfStore.updateStatus({ ... });               // 3. Pinia\n    await joinSession(sessionId);                // 4. Zoom SDK\n  };\n\n  return { startTalking };\n}\n```\n\n### 状態管理とスコープ\n\n**ガイドライン:**\n- **個別インスタンスが必要**: composable内でstateを定義\n- **親子間で共有が必要**: Provide/Injectパターン\n- **アプリ全体で共有が必要**: Pinia\n- テストでは常に独立したインスタンスを使用できるようにする\n\n**❌ Bad: グローバルなステート共有（シングルトン）**\n\n```typescript\n// composable外でstateを定義\nconst isVideoSessionActive = ref(false);\n\nexport function useVideoStatus() {\n  // 複数のコンポーネントで同じインスタンスを共有\n  return { isVideoSessionActive };\n}\n```\n\n**✅ Good: composable内でstateを定義（個別インスタンス）**\n\n```typescript\nexport function useVideoStatus() {\n  // composable内でstateを定義（呼び出しごとに新しいインスタンス）\n  const isVideoSessionActive = ref(false);\n  const preparationState = reactive({\n    onlineReservationId: null as number | null,\n  });\n  return { isVideoSessionActive, preparationState };\n}\n```\n\n### クリーンアップ処理\n\n**ガイドライン:**\n- タイマー、イベントリスナー、WebSocketなどは必ずクリーンアップ\n- `getCurrentInstance()`でコンポーネント外での使用を考慮\n- `onUnmounted`でリソース解放を保証\n- 手動停止メソッドも提供して柔軟性を確保\n\n**❌ Bad: クリーンアップ処理の欠如**\n\n```typescript\nexport function useVideoStatus() {\n  let pollingTimer: number | null = null;\n\n  const startPolling = (id: number) => {\n    pollingTimer = window.setInterval(() => { /* ... */ }, 10000);\n  };\n\n  // クリーンアップ処理がない！\n  return { startPolling };\n}\n```\n\n**✅ Good: 適切なクリーンアップ処理**\n\n```typescript\nexport function useVideoStatus() {\n  let pollingTimer: number | null = null;\n\n  const startPolling = (id: number) => {\n    if (pollingTimer !== null) return; // 重複防止\n    pollingTimer = window.setInterval(() => { /* ... */ }, 10000);\n  };\n\n  const stopPolling = () => {\n    if (pollingTimer !== null) {\n      clearInterval(pollingTimer);\n      pollingTimer = null;\n    }\n  };\n\n  // コンポーネント外で使用される可能性を考慮\n  const instance = getCurrentInstance();\n  if (instance) {\n    onUnmounted(() => stopPolling());\n  }\n\n  return { startPolling, stopPolling };\n}\n```\n\n### データ駆動設計\n\n**ガイドライン:**\n- **マスターデータは`as const`で定義**し、型推論を活用\n- **UIはデータから自動生成**する（`map`/`filter`を使用）\n- **ビジネスロジックは汎用的に**設計（特定の値に依存しない）\n- **新規追加はデータ定義のみ**で完結するようにする\n- **URLなどの派生データは関数で生成**\n\n**❌ Bad: UIとロジックが密結合**\n\n```typescript\nexport function useBadSymptomSelection() {\n  const selectedSymptoms = ref<string[]>([]);\n\n  // 症状ごとにメソッドを追加する必要がある\n  const addCough = () => { selectedSymptoms.value.push(''咳''); };\n  const addFever = () => { selectedSymptoms.value.push(''発熱''); };\n\n  return { selectedSymptoms, addCough, addFever };\n}\n```\n\n**✅ Good: マスターデータから自動生成**\n\n```typescript\n// 1. マスターデータの定義（as constで型推論）\nconst symptomItems = {\n  seki: { title: ''咳'', category: ''咳'' },\n  netsu_jyunyu: { title: ''発熱(授乳期)'', category: ''発熱'' },\n  hanamizu: { title: ''鼻水'', category: ''鼻水'' },\n} as const;\n\n// 2. 型の自動生成\nexport type SymptomItemKeyType = keyof typeof symptomItems;\n\n// 3. データからUI構造を自動生成\nconst symptoms = categories.map((category) => ({\n  category,\n  items: Object.entries(symptomItems)\n    .filter(([, item]) => item.category === category)\n    .map(([key, { title }]) => ({\n      key: key as SymptomItemKeyType,\n      title,\n      url: generateUrl(key as SymptomItemKeyType),\n    })),\n}));\n\n// 4. 汎用的なビジネスロジック\nexport const toggleSymptomSelection = (key: SymptomItemKeyType) => {\n  if (selectedSymptomItems.value.has(key)) {\n    selectedSymptomItems.value.delete(key);\n  } else {\n    selectedSymptomItems.value.add(key);\n  }\n};\n```\n\n**拡張性の実例:**\n\n```typescript\n// ✅ 新しい症状を追加（データ定義のみ、1箇所の変更）\nconst symptomItems = {\n  // ... 既存の定義\n  atopy: { title: ''アトピー性皮膚炎'', category: ''皮膚トラブル'' }, // 追加\n} as const;\n// → UIは自動的に更新される\n```\n\n---\n\n## 既存コンポーネントへの影響を最小化する設計\n\n**ガイドライン:**\n- **新機能は新規コンポーネントに隔離**する\n- **親コンポーネントへの変更は最小限**に（10行以内を目標）\n- **既存のメソッドを再利用**できる場合はコールバック関数Propsを使う\n- **Props/Emitsはシンプルに**保つ（2〜3個まで）\n- **ビジネスロジックはComposableに委譲**する\n- **UIロジックは新規コンポーネント内で完結**させる\n\n### 影響範囲の比較\n\n| 項目 | Bad Pattern | Good Pattern |\n|------|-------------|--------------|\n| 親コンポーネントの変更行数 | 300行以上 | 10行以内 |\n| 新規Import | なし（全て親に実装） | 1行のみ |\n| 既存メソッドの変更 | 複数のメソッド修正 | 変更なし（再利用） |\n| 新規dataの追加 | 5個以上 | 0個 |\n| テスト対象 | 親コンポーネント全体 | 新規コンポーネントのみ |\n\n### シンプルなPropsインターフェース\n\n```typescript\ninterface Props {\n  onSendChat: (message: string) => void; // コールバック関数\n  isDoctorPage: boolean;                 // 表示制御フラグ\n}\n```\n\n**なぜEmitではなくコールバック関数を使うのか:**\n\n```typescript\n// ❌ Bad: Emitを使う場合（親側の変更が必要）\n// 親コンポーネント（新規メソッドが必要）\n<ChatAttachedPdfSelect @send-chat=\"handleSymptomChatSend\" />\nmethods: {\n  handleSymptomChatSend(message) {\n    this.handleChatSend(message); // 既存メソッドを呼ぶだけ\n  }\n}\n\n// ✅ Good: コールバック関数を使う場合（親側の変更不要）\n// 親コンポーネント（既存メソッドをそのまま渡す）\n<ChatAttachedPdfSelect :onSendChat=\"handleChatSend\" />\n// 新規メソッド不要！\n```\n\n---\n\n## コンポーネント設計のベストプラクティス\n\n### Atomic Design\n\n**ガイドライン:**\n- **pages/**: ルーティングとメタ情報のみ（50行以内）\n- **organisms/**: 複雑な機能の統合（100〜200行）\n- **molecules/**: 複合コンポーネント（50〜100行）\n- **atoms/**: 基本的なUI要素（30〜50行）\n- **composables/**: ビジネスロジックと状態管理\n\n**ディレクトリ構造:**\n\n```\npedaru-vue/\n├── pages/\n│   └── index.vue           # 薄いルートコンポーネント（50行以内）\n├── components/\n│   ├── organisms/\n│   │   └── PdfViewer.vue   # PDFビューワー全体\n│   ├── molecules/\n│   │   ├── PdfToolbar.vue  # ツールバー\n│   │   └── PdfPageNav.vue  # ページナビゲーション\n│   └── atoms/\n│       ├── BaseButton.vue  # ボタン\n│       └── BaseIcon.vue    # アイコン\n├── composables/\n│   ├── usePdfViewer.ts     # 型定義もこのファイル内に配置\n│   └── usePdfNavigation.ts\n└── stores/\n    └── pdf.ts              # Pinia store（型定義も同じファイル内）\n```\n\n### Props/Emitsの型安全な定義\n\n**ガイドライン:**\n- **Propsは必ずTypeScriptのinterfaceで定義**\n- **必須とオプショナルを明示的に区別**（`?`を使う）\n- **Emitsも型定義する**（ペイロードの型を明確に）\n- **シンプルな通知はEmit**、**複雑な処理フローはコールバック関数**\n- **コールバック関数を使う理由をコメントで明示**\n\n**✅ Good: 型安全なProps/Emits定義**\n\n```vue\n<script setup lang=\"ts\">\n// Props定義をinterfaceで明示\ninterface Props {\n  isOnCamera: boolean;\n  isOnAudio: boolean;\n  nurseName: string;\n  patientName?: string;  // オプショナルは明示的に\n}\n\nconst props = defineProps<Props>();\n\n// Emits定義も型安全に\ninterface Emits {\n  (e: ''update:modelValue'', value: boolean): void;\n  (e: ''leave'', reason: ''user-action'' | ''timeout''): void;\n}\n\nconst emit = defineEmits<Emits>();\n</script>\n```\n\n**コールバック vs Emit の使い分け:**\n\n```vue\n<!-- パターン1: Emitを使う（シンプルな通知） -->\n<script setup lang=\"ts\">\ninterface Emits {\n  (e: ''close''): void;\n  (e: ''submit'', data: FormData): void;\n}\nconst emit = defineEmits<Emits>();\n</script>\n\n<!-- パターン2: コールバック関数を使う（複雑な処理フロー） -->\n<script setup lang=\"ts\">\ninterface Props {\n  isDisplayVideoWindow: boolean;\n  leaveSession: () => Promise<void>;  // 関数を直接渡す\n}\n\nconst props = defineProps<Props>();\n\nconst onLeaveClick = async () => {\n  // NOTE: 親コンポーネントで定義した処理を利用する必要がある\n  // 理由：親のVideoStatusPanelで表示制御のフラグ更新とZoomのビデオ退出を行う\n  await props.leaveSession();\n};\n</script>\n```\n\n### コンポーネント肥大化の防止\n\n**ガイドライン:**\n- **コンポーネントは100行以内を目標**\n- **ロジックはcomposablesに分離**\n- **UIはAtomic Designに基づいて分割**\n- **テンプレートも100行を超えたら分割を検討**\n- **1ファイル200行を超えたら必ず分割**\n\n---\n\n## TypeScript型安全性のベストプラクティス\n\n### 型定義の配置方針\n\n**ガイドライン:**\n- **型定義はロジックに近い場所に配置する**（専用の`types/`ディレクトリは作らない）\n- composableで使う型はそのcomposableファイル内に定義\n- storeで使う型はそのstoreファイル内に定義\n- 複数ファイルで共有する型のみ、関連するcomposableからexport\n\n**❌ Bad: 別ディレクトリに型定義を分離**\n\n```\ncomposables/\n└── usePdfViewer.ts\ntypes/\n└── pdf.ts          # 型定義が離れている\n```\n\n**✅ Good: ロジックと型定義を同じファイルに配置**\n\n```typescript\n// composables/usePdfViewer.ts\n\n// 型定義（このcomposableで使用する型）\nexport interface PdfViewerState {\n  currentPage: number;\n  totalPages: number;\n  scale: number;\n}\n\nexport type PdfLoadStatus = ''idle'' | ''loading'' | ''loaded'' | ''error'';\n\n// ロジック\nexport function usePdfViewer() {\n  const state = reactive<PdfViewerState>({\n    currentPage: 1,\n    totalPages: 0,\n    scale: 1.0,\n  });\n  const status = ref<PdfLoadStatus>(''idle'');\n\n  // ...\n  return { state, status };\n}\n```\n\n**メリット:**\n- 型とロジックが近いため、変更時の影響範囲が明確\n- ファイルを開くだけで型の定義がわかる\n- 不要な型が残りにくい（ロジック削除時に型も一緒に削除される）\n\n### as constとUnion型の活用\n\n**ガイドライン:**\n- **定数はas constで定義**してUnion型を自動生成\n- **文字列リテラル型を活用**して型安全性を確保\n- **Template Literal Type**で命名規則を型で表現\n- **keyof typeof**でオブジェクトからUnion型を生成\n\n**❌ Bad: 文字列リテラルを直接使用**\n\n```typescript\nconst status = ref<string>(''notYetStarted'');\nconst updateStatus = (newStatus: string) => {\n  status.value = newStatus; // 任意の文字列を許容してしまう\n};\nupdateStatus(''typo-status''); // コンパイルエラーにならない\n```\n\n**✅ Good: as constとUnion型の活用**\n\n```typescript\n// 定数オブジェクトをas constで定義\nexport const OnlineReservationVideoSessionStatus = {\n  notYetStarted: ''notYetStarted'',\n  sessionCreating: ''sessionCreating'',\n  sessionCreated: ''sessionCreated'',\n  sessionStarted: ''sessionStarted'',\n} as const;\n\n// Union型を自動生成\nexport type OnlineReservationVideoSessionStatusType =\n  (typeof OnlineReservationVideoSessionStatus)[keyof typeof OnlineReservationVideoSessionStatus];\n\n// 使用例\nconst status = ref<OnlineReservationVideoSessionStatusType>(\n  OnlineReservationVideoSessionStatus.notYetStarted\n);\n\nupdateStatus(OnlineReservationVideoSessionStatus.sessionStarted); // ✅ OK\nupdateStatus(''typo-status''); // ❌ コンパイルエラー\n```\n\n**Template Literal Typeの活用:**\n\n```typescript\n// 命名規則を型レベルで表現\ntype ZoomRoomNameType = `online_reservation_${number}`;\n\nconst createRoomName = (id: number): ZoomRoomNameType => {\n  return `online_reservation_${id}`;\n};\n```\n\n### Type Guardと型の絞り込み\n\n**ガイドライン:**\n- **unknownからの型変換には必ずType Guardを使用**\n- **anyは絶対に使わない**\n- **Type Guard関数は`is`演算子を使って定義**\n- **複数の型を扱う場合はそれぞれType Guardを定義**\n\n**❌ Bad: unknownをanyにキャスト**\n\n```typescript\nconst onErrorOccur = (e: unknown) => {\n  const error = e as any; // anyにキャストして型チェックを回避\n  if (error.errorCode) {\n    Sentry.captureMessage(`Error code: ${error.errorCode}`);\n  }\n};\n```\n\n**✅ Good: Type Guardで安全に型を絞り込む**\n\n```typescript\n// Type Guardの定義\ninterface ZoomErrorObject {\n  type?: string;\n  reason?: string;\n  errorCode?: number;\n}\n\nexport const isZoomErrorObject = (error: unknown): error is ZoomErrorObject => {\n  return (\n    error !== null &&\n    typeof error === ''object'' &&\n    (''type'' in error || ''reason'' in error || ''errorCode'' in error)\n  );\n};\n\n// 使用例\nconst onErrorOccur = (e: unknown) => {\n  if (isZoomErrorObject(e)) {\n    // この中ではeはZoomErrorObject型として扱える\n    Sentry.captureMessage(`Zoom Error: ${e.errorCode}`);\n  } else {\n    Sentry.captureException(e);\n  }\n};\n```\n\n---\n\n## テスト戦略とベストプラクティス\n\n### 価値のあるテストのみ\n\n**ガイドライン:**\n- **振る舞いをテスト**し、実装の詳細はテストしない\n- **正常系とエラー系の両方をカバー**\n- **単純なgetter/setterはテスト不要**\n- **ビジネスロジックの正しさを検証**\n\n**❌ Bad: 実装の詳細をテスト**\n\n```typescript\ndescribe(''useVideoStatus'', () => {\n  it(''videoStatusはrefである'', () => {\n    const { videoStatus } = useVideoStatus();\n    expect(isRef(videoStatus)).toBe(true); // 価値が低い\n  });\n\n  it(''isLoadingの初期値はfalseである'', () => {\n    const { isLoading } = useVideoStatus();\n    expect(isLoading.value).toBe(false); // 価値が低い\n  });\n});\n```\n\n**✅ Good: 振る舞いをテスト**\n\n```typescript\ndescribe(''useVideoStatus'', () => {\n  it(''API から VideoStage 情報を取得して videoStatus に設定する'', async () => {\n    const mockResponse = { data: { video_stages: [{ id: 1, status: ''active'' }] } };\n    mockVideoStageRepository.fetchStatus.mockResolvedValue(mockResponse);\n\n    const { videoStatus, fetchVideoStatus } = useVideoStatus();\n    await fetchVideoStatus(123);\n\n    expect(mockVideoStageRepository.fetchStatus).toHaveBeenCalledWith(123);\n    expect(videoStatus.value).toMatchObject({ valid_status: true });\n  });\n\n  it(''API エラー時に error メッセージを設定する'', async () => {\n    mockVideoStageRepository.fetchStatus.mockRejectedValue(new Error(''Network error''));\n\n    const { error, fetchVideoStatus } = useVideoStatus();\n    await fetchVideoStatus(123);\n\n    expect(error.value).toBe(''状態の取得に失敗しました'');\n  });\n});\n```\n\n### タイマーとポーリングのテスト\n\n**ガイドライン:**\n- **`vi.useFakeTimers()`でタイマーを制御可能に**\n- **`vi.advanceTimersByTimeAsync()`で時間を進める**\n- **Luxon使用時は`Settings.now`も設定**\n- **afterEachで必ず`vi.useRealTimers()`を呼ぶ**\n- **ポーリングの開始・停止・間隔を検証**\n\n**❌ Bad: 実際の時間を待つ**\n\n```typescript\nit(''1秒後に経過時間が更新される'', async () => {\n  const { elapsedTime } = useSessionElapsedTime(sessionStartTime);\n  await new Promise(resolve => setTimeout(resolve, 1000)); // テストが遅い\n  expect(elapsedTime.value).toBe(''00:00:01'');\n});\n```\n\n**✅ Good: Fake Timersを使用**\n\n```typescript\ndescribe(''useSessionElapsedTime'', () => {\n  beforeEach(() => {\n    vi.useFakeTimers();\n  });\n\n  afterEach(() => {\n    vi.useRealTimers();\n    Settings.now = () => Date.now(); // Luxonの時刻もリセット\n  });\n\n  it(''HH:mm:ss形式で経過時間を返す'', () => {\n    const now = new Date(''2025-01-07T10:30:00'');\n    vi.setSystemTime(now);\n    Settings.now = () => now.getTime();\n\n    const startTime = DateTime.fromISO(''2025-01-07T09:00:00'');\n    const sessionStartTime = ref(startTime.toISO());\n\n    const { elapsedTime } = useSessionElapsedTime(sessionStartTime);\n\n    expect(elapsedTime.value).toBe(''01:30:00'');\n  });\n});\n\ndescribe(''startPolling'', () => {\n  beforeEach(() => {\n    vi.useFakeTimers();\n  });\n\n  afterEach(() => {\n    vi.useRealTimers();\n  });\n\n  it(''10秒間隔でポーリングが実行される'', async () => {\n    mockVideoStageRepository.fetchStatus.mockResolvedValue({ data: {} });\n    const { startPolling } = useVideoStatus();\n\n    startPolling(123);\n    await vi.advanceTimersByTimeAsync(0);\n    expect(mockVideoStageRepository.fetchStatus).toHaveBeenCalledTimes(1);\n\n    await vi.advanceTimersByTimeAsync(10000); // 10秒後\n    expect(mockVideoStageRepository.fetchStatus).toHaveBeenCalledTimes(2);\n  });\n});\n```\n\n---\n\n## 実装チェックリスト\n\n新しい機能を実装する際は、以下をチェックしてください：\n\n### 設計段階\n\n- [ ] **Vue2とVue3のどちらで実装するか確認したか？**（新規は必ずVue3）\n- [ ] pages/配下のコンポーネントは薄く保てるか？（50行以内）\n- [ ] **既存コンポーネントへの影響を最小限にできるか？**（10行以内の変更を目標）\n- [ ] ロジックをcomposablesに分離できるか？\n- [ ] **データ駆動設計を適用できるか？**（マスターデータから自動生成）\n- [ ] Atomic Designに基づいてコンポーネントを分割できるか？\n- [ ] **1つのcomposableが複数の責任を持っていないか？**\n- [ ] **複数の関心事を持つcomposableを、独立した複数のcomposableに分離しているか？**（Composeパターン）\n- [ ] 技術層とビジネス層を分離できるか？\n- [ ] **将来の拡張性を考慮した設計か？**（データ追加で自動的にUIが更新される）\n\n### 実装段階\n\n- [ ] **`<script setup>`とTypeScriptを使用しているか？**\n- [ ] **型定義はロジックに近い場所に配置しているか？**（専用の`types/`ディレクトリは作らない）\n- [ ] Props/Emitsに型定義を付けているか？\n- [ ] **既存メソッドを再利用できる場合はコールバック関数Propsを使っているか？**\n- [ ] **マスターデータを`as const`で定義しているか？**\n- [ ] as constとUnion型を活用しているか？\n- [ ] Type Guardで安全に型を絞り込んでいるか？\n- [ ] anyを使っていないか？\n- [ ] **v-forでUIを自動生成しているか？**（ハードコードを避ける）\n- [ ] **keyには一意なID（item.id、item.key）を使用しているか？**（indexを使っていないか）\n- [ ] タイマーやイベントリスナーのクリーンアップ処理を実装したか？\n- [ ] `getCurrentInstance()`でコンポーネント外での使用を考慮したか？\n- [ ] 複雑な処理フローではコールバック関数を使っているか？\n- [ ] コメントで設計意図を明示しているか？\n\n### テスト段階\n\n- [ ] 振る舞いをテストしているか？（実装の詳細ではなく）\n- [ ] 正常系とエラー系の両方をカバーしているか？\n- [ ] タイマーテストでFake Timersを使っているか？\n- [ ] モックは外部依存のみに限定しているか？\n- [ ] テストの独立性を保っているか？\n\n---\n\n## まとめ\n\nAIに実装を依頼する際は、以下を意識してください：\n\n### 基本原則\n\n1. **Vue3 Composition API + TypeScriptを使用**: 常に`<script setup>`を使用\n2. **単一責任の原則を守る**: 1つのcomposable/コンポーネントは1つの関心事のみ\n3. **レイヤーを分離する**: 技術層とビジネス層を明確に分ける\n4. **Atomic Designを適用する**: pages → organisms → molecules → atoms\n5. **型安全性を確保する**: as const、Union型、Type Guardを活用\n6. **クリーンアップ処理を実装**: タイマー、イベントリスナーは必ず解放\n7. **データ駆動設計を推進**: マスターデータからUIを自動生成（DRY原則）\n8. **既存コンポーネントへの影響を最小化**: 新機能は新規コンポーネントに隔離\n\n### 実装のポイント\n\n- **Composables**: 50〜100行、単一責任、技術層とビジネス層を分離、データ駆動設計、**複数のcomposableを組み合わせる（Compose）**\n- **コンポーネント**: 100行以内、ロジックはcomposablesに委譲、v-forで動的生成\n- **Props/Emits**: 必ずTypeScriptで型定義、既存メソッド再利用時はコールバック関数\n- **TypeScript**: as const、Union型、Type Guard、Template Literal Type\n- **テスト**: 振る舞いをテスト、Fake Timers、モック最小化\n\n### 特に重要：pages/配下のコンポーネント肥大化防止\n\n- **pages/**: 50行以内の薄いルートコンポーネント\n- **organisms/**: 100〜200行の機能統合\n- **molecules/**: 50〜100行の複合コンポーネント\n- **composables/**: ビジネスロジックと状態管理\n\n### 特に重要：データ駆動設計と拡張性\n\n- **マスターデータ定義**: `as const`で型推論、1箇所で管理\n- **UIは自動生成**: v-forでデータから動的に生成\n- **新規追加は容易**: データ定義のみで完結（UIコードの修正不要）\n- **型安全性の確保**: TypeScriptの型チェックで誤りを防止\n- **テストの独立性**: データ変更でUIが正しく更新されるかを検証\n\n### 特に重要：既存コンポーネントへの影響最小化\n\n- **親コンポーネントへの変更は10行以内**を目標\n- **既存メソッドの再利用**: コールバック関数Propsで疎結合\n- **新機能は新規コンポーネントに隔離**: リグレッションリスク最小化\n- **Props/Emitsはシンプルに**: 2〜3個まで\n- **レビューしやすい差分**: 変更箇所を最小限に\n\nこれらの原則に従うことで、保守性が高く、テストしやすく、拡張性のある、品質の高いVue/TypeScriptコードを実装できます。\n\n---\n\n## 参考\n\n- [Vue 3 Composition API](https://vuejs.org/guide/extras/composition-api-faq.html)\n- [Vue 3 TypeScript](https://vuejs.org/guide/typescript/overview.html)\n- [Nuxt 3 Documentation](https://nuxt.com/docs)\n- [Pinia Documentation](https://pinia.vuejs.org/)\n- [Atomic Design](https://atomicdesign.bradfrost.com/)\n- [TypeScript Handbook](https://www.typescriptlang.org/docs/handbook/intro.html)\n"},"lastSynced":"2026-03-08T02:01:30.437Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing advanced Vue 3 and TypeScript project capabilities.","zh":"非常适合需要高级 Vue 3 和 TypeScript 项目功能的前端代理。","ja":"フロントエンドエージェントが高度なVue 3とTypeScriptのプロジェクト機能を必要とする場合に最適です。","ko":"고급 Vue 3와 TypeScript 프로젝트 기능이 필요한 프론트엔드 에이전트에게 적합합니다.","es":"Perfecto para agentes Frontend que necesitan capacidades de proyecto avanzadas de Vue 3 y TypeScript.","fr":"Parfait pour les agents Frontend ayant besoin de capacités de projet avancées Vue 3 et TypeScript.","de":"Perfekt für Frontend-Agenten, die erweiterte Vue 3- und TypeScript-Projekt-Funktionen benötigen.","pt":"Perfeito para Agentes Frontend que necessitam de capacidades avançadas de projetos Vue 3 e TypeScript.","ru":"Идеально подходит для агентов frontend, которым требуются расширенные возможности проектов Vue 3 и TypeScript.","ar":"مثالي للوكلاء الأماميين الذين يحتاجون إلى قدرات متقدمة لمشاريع Vue 3 وTypeScript."},"recommendation":{"en":"Empowers agents to create Vue 3 + TypeScript projects with Nuxt, utilizing the Composition API and best practices for AI assistants, including effective implementation of Pinia for state management and TypeScript for type safety.","zh":"赋予代理创建具有 Nuxt 的 Vue 3 + TypeScript 项目的能力，利用组合 API 和 AI 助手的最佳实践，包括使用 Pinia 进行状态管理和 TypeScript 进行类型安全的有效实现。","ja":"エージェントがNuxtを使用したVue 3 + TypeScriptプロジェクトを作成する能力を付与し、コンポジションAPIとAIアシスタントのベストプラクティスを利用し、Piniaを使用した状態管理とTypeScriptを使用した型安全性の有効な実装を含む。","ko":"에이전트가 Nuxt를 사용하여 Vue 3 + TypeScript 프로젝트를 생성할 수 있는 능력을 부여하며, 구성 API와 AI 어시스턴트의 모범 사례를 활용하고, Pinia를 사용한 상태 관리 및 TypeScript를 사용한 유형 안전성의 효과적인 구현을 포함합니다.","es":"Habilita a los agentes a crear proyectos Vue 3 + TypeScript con Nuxt, utilizando la Composition API y las mejores prácticas para asistentes de inteligencia artificial, incluyendo la implementación efectiva de Pinia para la gestión de estado y TypeScript para la seguridad de tipos.","fr":"Autonomise les agents pour créer des projets Vue 3 + TypeScript avec Nuxt, en utilisant la Composition API et les meilleures pratiques pour les assistants d''intelligence artificielle, y compris la mise en œuvre efficace de Pinia pour la gestion d''état et TypeScript pour la sécurité des types.","de":"Ermächtigt Agenten, Vue 3 + TypeScript-Projekte mit Nuxt zu erstellen, indem die Composition API und die besten Praktiken für KI-Assistenten verwendet werden, einschließlich der effektiven Implementierung von Pinia für die Zustandsverwaltung und TypeScript für die Typsicherheit.","pt":"Habilita os agentes a criar projetos Vue 3 + TypeScript com Nuxt, utilizando a Composition API e as melhores práticas para assistentes de IA, incluindo implementação eficaz do Pinia para gerenciamento de estado e TypeScript para segurança de tipo.","ru":"Наделяет агентов возможностью создавать проекты Vue 3 + TypeScript с помощью Nuxt, используя Composition API и лучшие практики для помощников ИИ, включая эффективную реализацию Pinia для управления состоянием и TypeScript для безопасности типов.","ar":"تمكّن الوكلاء من إنشاء مشاريع Vue 3 + TypeScript مع Nuxt، باستخدام Composition API وأفضل الممارسات لمساعدي الذكاء الاصطناعي، بما في ذلك التنفيذ الفعال ل Pinia لإدارة الحالة وTypeScript لأمان النوع."},"useCases":{"en":["Building scalable Vue 3 applications with Nuxt","Implementing state management with Pinia","Migrating React applications to Vue 3"],"zh":["使用Nuxt构建可扩展的Vue 3应用程序","使用Pinia实现状态管理","将React应用程序迁移到Vue 3"],"ja":["Nuxtを使用してスケーラブルなVue 3アプリケーションを構築する","Piniaを使用して状態管理を実装する","ReactアプリケーションをVue 3に移行する"],"ko":["Nuxt를 사용하여 확장 가능한 Vue 3 애플리케이션을 구축하는 것","Pinia를 사용하여 상태 관리를 구현하는 것","React 애플리케이션을 Vue 3로 마이그레이션하는 것"],"es":["Construir aplicaciones escalables Vue 3 con Nuxt","Implementar la gestión de estado con Pinia","Migrar aplicaciones React a Vue 3"],"fr":["Créer des applications Vue 3 évolutives avec Nuxt","Mettre en œuvre la gestion d''état avec Pinia","Migrer des applications React vers Vue 3"],"de":["Erstellung von skalierbaren Vue 3-Anwendungen mit Nuxt","Implementierung der Zustandsverwaltung mit Pinia","Migration von React-Anwendungen zu Vue 3"],"pt":["Construção de aplicações escaláveis Vue 3 com Nuxt","Implementação de gerenciamento de estado com Pinia","Migração de aplicações React para Vue 3"],"ru":["Построение масштабируемых приложений Vue 3 с помощью Nuxt","Реализация управления состоянием с помощью Pinia","Миграция приложений React на Vue 3"],"ar":["بناء تطبيقات Vue 3 القابلة للتوسعة مع Nuxt","تنفيذ إدارة الحالة مع Pinia","هجرة تطبيقات React إلى Vue 3"]},"limitations":{"en":["Requires knowledge of Vue 3 and TypeScript","Nuxt 3 specific implementation"],"zh":["需要Vue 3和TypeScript的知识","Nuxt 3特定的实现"],"ja":["Vue 3とTypeScriptの知識が必要","Nuxt 3特有の実装"],"ko":["Vue 3와 TypeScript에 대한 지식이 필요함","Nuxt 3 특정 구현"],"es":["Requiere conocimiento de Vue 3 y TypeScript","Implementación específica de Nuxt 3"],"fr":["Nécessite des connaissances en Vue 3 et TypeScript","Mise en œuvre spécifique de Nuxt 3"],"de":["Benötigt Kenntnisse von Vue 3 und TypeScript","Nuxt 3-spezifische Implementierung"],"pt":["Requer conhecimento de Vue 3 e TypeScript","Implementação específica do Nuxt 3"],"ru":["Требует знания Vue 3 и TypeScript","Реализация, специфичная для Nuxt 3"],"ar":["يتطلب معرفة Vue 3 وTypeScript","تنفيذ محدد ل Nuxt 3"]},"version":4},"contentHash":"1814e7aa0f89439eb83748cd826b746288b941f11f5717d902e959491211c9bc","qualityScore":39}');
