INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('h5y1m141/pedaru-vue/vue-skill', 'vue-skill', 'h5y1m141', 'pedaru-vue', 'community', 'vue-skill h5y1m141 pedaru-vue community The vue-skill enables developers to create Vue 3 + TypeScript projects with Nuxt, providing a clear implementation guide and best practices for AI assistants. Vue-skill是基于Vue 3 + TypeScript的AI助手技能，支持单独运行和其他Subagent调用 Vue-skillはVue 3 + TypeScriptベースのAIアシスタント技能で、単独実行と他のSubagentからの呼び出しをサポート Vue-skill은 Vue 3 + TypeScript 기반의 AI 도구 기능으로 단독 실행과 다른 Subagent 호출을 지원 Vue-skill es un asistente de AI para proyectos de Vue 3 con TypeScript, diseñado para funcionar con Nuxt Vue-skill est un assistant d''IA pour les projets Vue 3 avec TypeScript, conçu pour fonctionner avec Nuxt Vue-skill ist ein KI-Assistent für Vue-3-Projekte mit TypeScript, entwickelt für die Verwendung mit Nuxt O vue-skill é uma ferramenta de AI para projetos Vue 3 e Nuxt, com suporte a TypeScript e Composition API. ИИ Агенты: vue-skill - это инструмент для проектов Vue 3 и Nuxt, поддерживающий TypeScript и Composition API. أداة الذكاء الاصطناعي vue-skill هي أداة لمشاريع Vue 3 و Nuxt، تدعم TypeScript و Composition API how to use vue-skill vue-skill setup guide vue-skill vs react vue-skill install what is vue-skill vue-skill alternative vue 3 composition api nuxt 3 setup typescript with vue Vue 3 AI技能 Vue 3 + TypeScript Nuxt 3 Pinia AI助手技能 Vue 3最佳实践 AI工具设置 Vue 3设置指南 Utilizes Vue 3 + Composition API with `<script setup>` Integrates Nuxt 3 for enhanced web application development Employs TypeScript for robust type checking and maintenance Leverages Pinia for efficient state management Provides a React to Vue 3 conversion guide with Hooks to Composition API mapping vue-skill is a Vue 3 and Nuxt-based web application setup guide for AI agents, utilizing TypeScript and Composition API.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('nathanvale/vtm-cli/git-expert', 'community', 'nathanvale', 'vtm-cli', 'nathanvale/vtm-cli', 'git-expert', 0, 0, 39, '2026-03-08T01:57:15.300Z', '2026-03-08T02:01:31.208Z', 'd648d9625c6a89a1f5090f7c35d10b3bc7bcf398e3bc15c3cbbca336b47bee04', '{"id":"nathanvale/vtm-cli/git-expert","name":"git-expert","description":{"en":"The git-expert skill provides token-efficient task management for AI-assisted development with Claude Code, helping developers manage their git workflow efficiently.","zh":"Git Expert技能提供智能的Git命令建议，帮助开发者管理Git工作流","ja":"Git Expertスキルは、スマートなGitコマンドの提案を提供し、開発者がGitワークフローを管理できるようにします","ko":"Git Expert 기능은智能적인 Git 명령어 제안을 제공하여 개발자가 Git 워크플로우를 관리할 수 있도록 합니다","es":"El skill Git Expert ofrece gestión de tareas eficiente para el desarrollo asistido por AI con Claude Code, incluyendo sugerencias de comandos inteligentes","fr":"Le skill Git Expert propose une gestion de tâches efficace pour le développement assisté par IA avec Claude Code, y compris des suggestions de commandes intelligentes","de":"Der Git-Expert-Skill bietet eine effiziente Aufgabenverwaltung für die AI-gestützte Entwicklung mit Claude Code, einschließlich intelligenter Kommandovorschläge","pt":"O Git Expert é uma habilidade que ajuda a gerenciar o fluxo de trabalho Git com sugestões de comandos inteligentes do Claude Code.","ru":"Git Expert - это навык, который помогает управлять рабочим процессом Git с помощью умных предложений команд от Claude Code.","ar":"خبير جيت هو مهارة تساعد في إدارة تدفق عمل جيت باستخدام اقتراحات الأوامر الذكية من كلود كود."},"seo":{"title":{"en":"git-expert: AI-Assisted Git Workflow Management | AI Agen...","zh":"Git Expert技能：AI智能Git工作流管理","ja":"Git Expertスキル：AIエージェントによるGitワークフローの最適化","ko":"Git Expert 기능: AI 도구를 통한 Git 워크플로우 최적화","es":"Guía de configuración de Git Expert para desarrollo asist...","fr":"Guide d