INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('nathanvale/vtm-cli/git-expert', 'git-expert', 'nathanvale', 'vtm-cli', 'community', 'git-expert nathanvale vtm-cli community The git-expert skill provides token-efficient task management for AI-assisted development with Claude Code, helping developers manage their git workflow efficiently. Git Expert技能提供智能的Git命令建议，帮助开发者管理Git工作流 Git Expertスキルは、スマートなGitコマンドの提案を提供し、開発者がGitワークフローを管理できるようにします Git Expert 기능은智能적인 Git 명령어 제안을 제공하여 개발자가 Git 워크플로우를 관리할 수 있도록 합니다 El skill Git Expert ofrece gestión de tareas eficiente para el desarrollo asistido por AI con Claude Code, incluyendo sugerencias de comandos inteligentes Le skill Git Expert propose une gestion de tâches efficace pour le développement assisté par IA avec Claude Code, y compris des suggestions de commandes intelligentes Der Git-Expert-Skill bietet eine effiziente Aufgabenverwaltung für die AI-gestützte Entwicklung mit Claude Code, einschließlich intelligenter Kommandovorschläge O Git Expert é uma habilidade que ajuda a gerenciar o fluxo de trabalho Git com sugestões de comandos inteligentes do Claude Code. Git Expert - это навык, который помогает управлять рабочим процессом Git с помощью умных предложений команд от Claude Code. خبير جيت هو مهارة تساعد في إدارة تدفق عمل جيت باستخدام اقتراحات الأوامر الذكية من كلود كود. how to use git-expert git-expert setup guide git-expert alternative git-expert vs git tools git-expert install what is git-expert git-expert for AI agents git workflow management Claude Code integration Git Expert AI智能Git Git工作流管理 智能Git命令 Git状态查询 Git分支管理 Smart command suggestions for git status via `/git:status` Branch switching capabilities with `/git:switch` New branch creation using `/git:create-branch` Commit management with special instructions via `/git:commit` Git history viewing with `/git:log` git-expert is a skill that enables AI-assisted development with smart command suggestions for managing git workflows, including status, branch switching, and commit management.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('yejune/do-focus/do-lang-swift', 'community', 'yejune', 'do-focus', 'yejune/do-focus', 'do-lang-swift', 0, 0, 39, '2026-03-08T01:57:15.301Z', '2026-03-08T02:01:37.581Z', 'e62de8b38ac6a5ec78a5d4a4cfb07da0bc622ed8447ebaeb897797cfb61d84e4', '{"id":"yejune/do-focus/do-lang-swift","name":"do-lang-swift","description":{"en":"The do-lang-swift AI Agent skill is a Swift 6.0+ development specialist for iOS and macOS. It automatically activates on Swift files, Xcode workspaces, and projects to provide expert assistance with modern SwiftUI, Combine, and Swift Concurrency features.","zh":"do-lang-swift 是一个 Swift 6+ 开发专家，支持 SwiftUI、Combine 和 Swift Concurrency。它可以自动触发 Swift 文件和 iOS/macOS 项目。","ja":"do-lang-swift は Swift 6+ 開発のエキスパートで、SwiftUI、Combine、Swift Concurrency をサポートします。Swift ファイルや iOS/macOS プロジェクトを自動的にトリガーできます。","ko":"do-lang-swift는 Swift 6+ 개발 전문가로, SwiftUI, Combine, Swift Concurrency를 지원합니다. Swift 파일과 iOS/macOS 프로젝트를 자동으로 트리거할 수 있습니다.","es":"do-lang-swift es un experto en desarrollo de Swift 6+ para iOS y macOS con SwiftUI, Combine y Swift Concurrency. Aprende a aprovechar sus capacidades","fr":"do-lang-swift est un expert en développement Swift 6+ pour iOS et macOS avec SwiftUI, Combine et Swift Concurrency. Découvrez comment l''utiliser","de":"do-lang-swift ist ein Experte für die Entwicklung von Swift 6+ für iOS und macOS mit SwiftUI, Combine und Swift Concurrency. Erfahren Sie, wie Sie es nutzen können","pt":"O do-lang-swift é um especialista em desenvolvimento Swift 6+ para iOS e macOS, com suporte a SwiftUI, Combine e Swift Concurrency","ru":"ИИ Агент do-lang-swift - это специалист по разработке на Swift 6+ для iOS и macOS, с поддержкой SwiftUI, Combine и Swift Concurrency","ar":"أداة الذكاء الاصطناعي do-lang-swift هي خبير في برمجة Swift 6+ لتطبيقات iOS و macOS، مع دعم SwiftUI و Combine و Swift Concurrency