INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('yejune/do-focus/do-lang-swift', 'do-lang-swift', 'yejune', 'do-focus', 'community', 'do-lang-swift yejune do-focus community The do-lang-swift AI Agent skill is a Swift 6.0+ development specialist for iOS and macOS. It automatically activates on Swift files, Xcode workspaces, and projects to provide expert assistance with modern SwiftUI, Combine, and Swift Concurrency features. do-lang-swift 是一个 Swift 6+ 开发专家，支持 SwiftUI、Combine 和 Swift Concurrency。它可以自动触发 Swift 文件和 iOS/macOS 项目。 do-lang-swift は Swift 6+ 開発のエキスパートで、SwiftUI、Combine、Swift Concurrency をサポートします。Swift ファイルや iOS/macOS プロジェクトを自動的にトリガーできます。 do-lang-swift는 Swift 6+ 개발 전문가로, SwiftUI, Combine, Swift Concurrency를 지원합니다. Swift 파일과 iOS/macOS 프로젝트를 자동으로 트리거할 수 있습니다. do-lang-swift es un experto en desarrollo de Swift 6+ para iOS y macOS con SwiftUI, Combine y Swift Concurrency. Aprende a aprovechar sus capacidades do-lang-swift est un expert en développement Swift 6+ pour iOS et macOS avec SwiftUI, Combine et Swift Concurrency. Découvrez comment l''utiliser do-lang-swift ist ein Experte für die Entwicklung von Swift 6+ für iOS und macOS mit SwiftUI, Combine und Swift Concurrency. Erfahren Sie, wie Sie es nutzen können O do-lang-swift é um especialista em desenvolvimento Swift 6+ para iOS e macOS, com suporte a SwiftUI, Combine e Swift Concurrency ИИ Агент do-lang-swift - это специалист по разработке на Swift 6+ для iOS и macOS, с поддержкой SwiftUI, Combine и Swift Concurrency أداة الذكاء الاصطناعي do-lang-swift هي خبير في برمجة Swift 6+ لتطبيقات iOS و macOS، مع دعم SwiftUI و Combine و Swift Concurrency what is do-lang-swift how to use do-lang-swift for SwiftUI do-lang-swift vs other swift ai tools do-lang-swift install guide do-lang-swift setup for Xcode do-lang-swift Swift Concurrency support do-lang-swift Combine framework do-lang-swift auto-trigger swift files Swift 6+ 开发 SwiftUI Combine Swift Concurrency iOS 开发 macOS 开发 Xcode Swift 6.0 SwiftUI 6 Expert support for Swift 6.0 features like typed throws and data-race safety SwiftUI 6 development with the @Observable macro and NavigationStack Reactive programming using the Combine framework with publishers and subscribers Swift Concurrency implementation with async/await and actors Auto-triggers on Swift files (.swift), iOS/macOS projects, and Xcode workspaces do-lang-swift is an AI Agent skill designed for Swift 6.0+ development. It specializes in iOS and macOS projects, providing expert support for SwiftUI 6, the Combine framework, and Swift''s native concurrency model, including async/await and actors.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('proffesor-for-testing/agentic-qe/QE Contract Testing', 'community', 'proffesor-for-testing', 'agentic-qe', 'proffesor-for-testing/agentic-qe', 'QE Contract Testing', 0, 0, 39, '2026-03-08T01:57:15.309Z', '2026-03-08T02:02:25.564Z', 'e9205afaa4499aa08a269e8441cc0c8a7923bf8d1fb360e777ae6242aa806890', '{"id":"proffesor-for-testing/agentic-qe/QE Contract Testing","name":"QE Contract Testing","description":{"en":"QE Contract Testing is an AI-powered testing capability for validating API contracts, schemas, and backward compatibility. It supports consumer-driven contracts and API versioning verification","zh":"QE 合同测试是 Agentic QE Fleet 的一个功能，支持消费者驱动的合同、模式验证和 API 版本验证","ja":"QE 契約テストは Agentic QE Fleet の機能であり、消費者主導の契約、スキーマの検証、API バージョンの検証を可能にします","ko":"QE 계약 테스트는 Agentic QE Fleet의 기능으로 소비자 주도 계약, 스키마 유효성 검사 및 API 버전 확인을 지원합니다","es":"QE Contract Testing es una habilidad de Agentic QE Fleet que permite probar contratos de API y validar esquemas","fr":"Le testing de contrats QE est une compétence d''Agentic QE Fleet qui permet de tester les contrats d''API et de valider les schémas","de":"QE Contract Testing ist eine Fähigkeit von Agentic QE Fleet, die das Testen von API-Verträgen und die Validierung von Schemata ermöglicht","pt":"O Teste de Contrato QE é uma capacidade de teste alimentada por IA para validar contratos de API, esquemas e compatibilidade reversa. Ele suporta contratos orientados ao consumidor e verificação de versionamento de API","ru":"Тестирование контрактов QE — это функция тестирования на основе ИИ для проверки контрактов API, схем и обратной совместимости. Она поддерживает контракты, ориентированные на потребителя, и проверку версий API","ar":"اختبار العقد QE هو khảية اختبار مدعومة بالذكاء الاصطناعي للتحقق من عقود API والمخططات والتوافق العكسي. يدعم عقودًا مدفوعة بالعملاء والتحقق من إصدار API"},"seo":{"title":{"en":"QE Contract Testing Setup Guide","zh":"QE 合同测试设置指南 - AIエージェント","ja":"QE 契約テスト設定ガイド - AIエージェント","ko":"QE 계약 테스트 설정 가이드 - AI 에이전트","es":"Configuración de QE Contract Testing con AIエージェント","fr":"Guide de démarrage rapide pour le testing de contrats QE","de":"Einrichtung von QE Contract Testing mit KI-Agenten","pt":"Guia de Configuração de Teste de Contrato QE","ru":"Настройка тестирования контрактов QE: руководство","ar":"دليل إعداد اختبار العقد QE"},"description":{"en":"Learn how to use QE Contract Testing for API contract validation, schema checking, and backward compatibility verification","zh":"学习如何使用 QE 合同测试进行 API 合同验证、模式检查和向后兼容性验证 - AI工具","ja":"QE 契約テストを使用して API 契約の検証、スキーマの確認、バックワード互換性の検証を行う方法を学ぶ - AIエージェント","ko":"QE 계약 테스트를 사용하여 API 계약 유효성 검사, 스키마 확인 및 후방 호환성 확인 방법을 배우다 - AI 에이전트","es":"Aprende a utilizar QE Contract Testing para validar esquemas y verificar la compatibilidad hacia atrás en tus APIs","fr":"Découvrez comment utiliser le testing de contrats QE pour valider les schémas et vérifier la compatibilité ascendante","de":"Erfahren Sie, wie Sie QE Contract Testing verwenden, um Schemata zu validieren und die Abwärtskompatibilität zu überprüfen","pt":"Aprenda a usar o Teste de Contrato QE para validação de contrato de API, verificação de esquema e compatibilidade reversa","ru":"Узнайте, как использовать тестирование контрактов QE для проверки контрактов API, схем и обратной совместимости","ar":"تعرف على كيفية استخدام اختبار العقد QE للتحقق من عقد API والتحقق من مخطط والتوافق العكسي"},"definition":{"en":"QE Contract Testing is an AI-powered testing capability for validating API contracts and schemas","zh":"QE 合同测试是一种用于验证 API 合同和确保向后兼容性的测试能力","ja":"QE 契約テストは API 契約の検証とバックワード互換性の確保のためのテスト機能です","ko":"QE 계약 테스트는 API 계약의 유효성 검사 및 후방 호환성을 보장하는 테스트 기능입니다","es":"QE Contract Testing es una técnica de pruebas que verifica la compatibilidad y validez de los contratos de API","fr":"Le testing de contrats QE est une technique de test qui vérifie la compatibilité et la validité des contrats d''API","de":"QE Contract Testing ist eine Testtechnik, die die Kompatibilität und Gültigkeit von API-Verträgen überprüft","pt":"O Teste de Contrato QE é uma capacidade de teste alimentada por IA para validar contratos de API e esquemas","ru":"Тестирование контрактов QE — это функция тестирования на основе ИИ для проверки контрактов API и схем","ar":"اختبار العقد QE هو khảية اختبار مدعومة بالذكاء الاصطناعي للتحقق من عقود API والمخططات"},"features":{"en":["Consumer-driven contract testing","Schema validation and verification","Backward compatibility checking","API versioning verification","Support for GraphQL APIs","Event schema validation"],"zh":["消费者驱动的合同","模式验证","向后兼容性检查","API 版本验证","GraphQL API 测试","事件模式验证"],"ja":["消費者主導の契約","スキーマの検証","バックワード互換性の確認","API バージョンの検証","GraphQL API テスト","イベントスキーマの検証"],"ko":["소비자 주도 계약","스키마 유효성 검사","후방 호환성 확인","API 버전 확인","GraphQL API 테스트","이벤트 스키마 확인"],"es":["Generación de contratos de API a partir de archivos OpenAPI","Validación de esquemas y compatibilidad hacia atrás","Verificación de versiones de API y esquemas de eventos","Soporte para GraphQL APIs","Generación de contratos para locales específicos"],"fr":["Génération de contrats d''API à partir de fichiers OpenAPI","Validation de schémas et de la compatibilité ascendante","Vérification des versions d''API et des schémas d''événements","Prise en charge des API GraphQL","Génération de contrats pour des locales spécifiques"],"de":["Generierung von API-Verträgen aus OpenAPI-Dateien","Validierung von Schemata und Abwärtskompatibilität","Überprüfung von API-Versionen und Ereignisschemata","Unterstützung für GraphQL-APIs","Generierung von Verträgen für bestimmte Länder"],"pt":["Teste de contrato orientado ao consumidor","Validação e verificação de esquema","Verificação de compatibilidade reversa","Verificação de versionamento de API","Suporte a APIs GraphQL","Validação de esquema de evento"],"ru":["Тестирование контрактов, ориентированное на потребителя","Проверка и верификация схем","Проверка обратной совместимости","Проверка версий API","Поддержка API GraphQL","Верификация схемы события"],"ar":["اختبار العقد الموجه للعميل","التحقق من مخطط والتحقق","التحقق من التوافق العكسي","التحقق من إصدار API","دعم API GraphQL","التحقق من مخطط الحدث"]},"keywords":{"en":["QE Contract Testing","API contract testing","schema validation","backward compatibility checking","API versioning verification","GraphQL API testing","consumer-driven contract testing"],"zh":["QE 合同测试","API 合同验证","模式验证","向后兼容性测试","API 版本","GraphQL API 测试","事件模式验证","Agentic QE Fleet","消费者驱动的合同"],"ja":["QE 契約テスト","API 契約の検証","スキーマの検証","バックワード互換性の確認","API バージョン","GraphQL API テスト","イベントスキーマの検証","Agentic QE Fleet","消費者主導の契約"],"ko":["QE 계약 테스트","API 계약 유효성 검사","스키마 유효성 검사","후방 호환성 확인","API 버전","GraphQL API 테스트","이벤트 스키마 확인","Agentic QE Fleet","소비자 주도 계약"],"es":["pruebas de contratos de API","validación de esquemas","compatibilidad hacia atrás","testing de API","QE Contract Testing","Agentic QE Fleet","AIエージェント","pruebas de software"],"fr":["test de contrats d''API","validation de schémas","compatibilité ascendante","test d''API","testing de contrats QE","Agentic QE Fleet","IA","test de logiciel"],"de":["API-Vertrags-Tests","Schemavalidierung","Abwärtskompatibilität","API-Testing","QE Contract Testing","Agentic QE Fleet","KI-Agenten","Software-Tests"],"pt":["Teste de Contrato QE","teste de contrato de API","validação de esquema","verificação de compatibilidade reversa","verificação de versionamento de API","teste de API GraphQL","teste de contrato orientado ao consumidor"],"ru":["Тестирование контрактов QE","тестирование контрактов API","проверка схем","проверка обратной совместимости","проверка версий API","тестирование API GraphQL","тестирование контрактов, ориентированное на потребителя"],"ar":["اختبار العقد QE","اختبار عقد API","التحقق من مخطط","التحقق من التوافق العكسي","التحقق من إصدار API","اختبار API GraphQL","اختبار العقد الموجه للعميل"]}},"owner":"proffesor-for-testing","repo":"agentic-qe","repoPath":"proffesor-for-testing/agentic-qe","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.309Z","topics":[],"category":"community","skillMd":{"name":"QE Contract Testing","description":"Consumer-driven contract testing for APIs including REST, GraphQL, and event-driven systems with schema validation.","bodyPreview":"# QE Contract Testing\n\n## Purpose\n\nGuide the use of v3''s contract testing capabilities including consumer-driven contracts, schema validation, backward compatibility checking, and API versioning verification.\n\n## Activation\n\n- When testing API contracts\n- When validating schema changes\n- When checking backward compatibility\n- When testing GraphQL APIs\n- When verifying event schemas\n\n## Quick Start\n\n```bash\n# Generate contract from API\naqe contract generate --api openapi.yaml --output contracts/","body":"# QE Contract Testing\n\n## Purpose\n\nGuide the use of v3''s contract testing capabilities including consumer-driven contracts, schema validation, backward compatibility checking, and API versioning verification.\n\n## Activation\n\n- When testing API contracts\n- When validating schema changes\n- When checking backward compatibility\n- When testing GraphQL APIs\n- When verifying event schemas\n\n## Quick Start\n\n```bash\n# Generate contract from API\naqe contract generate --api openapi.yaml --output contracts/\n\n# Verify provider against contracts\naqe contract verify --provider http://localhost:3000 --contracts contracts/\n\n# Check breaking changes\naqe contract breaking --old api-v1.yaml --new api-v2.yaml\n\n# Test GraphQL schema\naqe contract graphql --schema schema.graphql --operations queries/\n```\n\n## Agent Workflow\n\n```typescript\n// Contract generation\nTask(\"Generate API contracts\", `\n  Analyze the REST API and generate consumer contracts:\n  - Parse OpenAPI specification\n  - Identify critical endpoints\n  - Generate Pact contracts\n  - Include example requests/responses\n  Output to contracts/ directory.\n`, \"qe-api-contract\")\n\n// Breaking change detection\nTask(\"Check API compatibility\", `\n  Compare API v2.0 against v1.0:\n  - Detect removed endpoints\n  - Check parameter changes\n  - Verify response schema changes\n  - Identify deprecations\n  Report breaking vs non-breaking changes.\n`, \"qe-api-compatibility\")\n```\n\n## Contract Testing Types\n\n### 1. Consumer-Driven Contracts (Pact)\n\n```typescript\nawait contractTester.consumerDriven({\n  consumer: ''web-app'',\n  provider: ''user-service'',\n  contracts: ''contracts/web-app-user-service.json'',\n  verification: {\n    providerBaseUrl: ''http://localhost:3000'',\n    providerStates: providerStateHandlers,\n    publishResults: true\n  }\n});\n```\n\n### 2. Schema Validation\n\n```typescript\nawait contractTester.validateSchema({\n  type: ''openapi'',\n  schema: ''api/openapi.yaml'',\n  requests: actualRequests,\n  validation: {\n    requestBody: true,\n    responseBody: true,\n    headers: true,\n    statusCodes: true\n  }\n});\n```\n\n### 3. GraphQL Contract Testing\n\n```typescript\nawait graphqlTester.testContracts({\n  schema: ''schema.graphql'',\n  operations: ''queries/**/*.graphql'',\n  validation: {\n    queryValidity: true,\n    responseShapes: true,\n    nullability: true,\n    deprecations: true\n  }\n});\n```\n\n### 4. Event Contract Testing\n\n```typescript\nawait contractTester.eventContracts({\n  schema: ''events/schemas/'',\n  events: {\n    ''user.created'': {\n      schema: ''UserCreatedEvent.json'',\n      examples: [''examples/user-created.json'']\n    },\n    ''order.completed'': {\n      schema: ''OrderCompletedEvent.json'',\n      examples: [''examples/order-completed.json'']\n    }\n  },\n  compatibility: ''backward''\n});\n```\n\n## Breaking Change Detection\n\n```yaml\nbreaking_changes:\n  always_breaking:\n    - endpoint_removed\n    - required_param_added\n    - response_field_removed\n    - type_changed\n\n  potentially_breaking:\n    - optional_param_removed\n    - response_field_added\n    - enum_value_removed\n\n  non_breaking:\n    - endpoint_added\n    - optional_param_added\n    - response_field_made_optional\n    - documentation_changed\n```\n\n## Contract Report\n\n```typescript\ninterface ContractReport {\n  summary: {\n    contracts: number;\n    passed: number;\n    failed: number;\n    warnings: number;\n  };\n  consumers: {\n    name: string;\n    contracts: ContractResult[];\n    compatibility: ''compatible'' | ''breaking'' | ''unknown'';\n  }[];\n  breakingChanges: {\n    type: string;\n    location: string;\n    description: string;\n    impact: ''high'' | ''medium'' | ''low'';\n    migration: string;\n  }[];\n  deprecations: {\n    item: string;\n    deprecatedIn: string;\n    removeIn: string;\n    replacement: string;\n  }[];\n}\n```\n\n## CI/CD Integration\n\n```yaml\ncontract_verification:\n  consumer_side:\n    - generate_contracts\n    - publish_to_broker\n    - can_i_deploy_check\n\n  provider_side:\n    - fetch_contracts_from_broker\n    - verify_against_provider\n    - publish_results\n\n  pre_release:\n    - check_breaking_changes\n    - verify_all_consumers\n    - update_compatibility_matrix\n```\n\n## Pact Broker Integration\n\n```typescript\nawait contractTester.withBroker({\n  brokerUrl: ''https://pact-broker.example.com'',\n  auth: { token: process.env.PACT_TOKEN },\n  operations: {\n    publish: true,\n    canIDeploy: true,\n    webhooks: true\n  }\n});\n```\n\n## Coordination\n\n**Primary Agents**: qe-api-contract, qe-api-compatibility, qe-graphql-tester\n**Coordinator**: qe-contract-coordinator\n**Related Skills**: qe-test-generation, qe-security-compliance\n"},"lastSynced":"2026-03-08T02:02:25.564Z","agentAnalysis":{"suitability":{"en":"Perfect for API Testing Agents needing advanced contract validation and backward compatibility checking capabilities.","zh":"适用于需要高级合同验证和向后兼容性检查功能的 API 测试代理。","ja":"API テスト エージェントが高度な契約検証および下位互換性の確認機能を必要とする場合に最適です。","ko":"고급 계약 유효성 검사 및 하위 호환성 확인 기능이 필요한 API 테스트 에이전트에 적합합니다.","es":"Perfecto para Agentes de Pruebas de API que necesitan capacidades de validación de contrato avanzadas y compatibilidad hacia atrás.","fr":"Parfait pour les Agents de Test d''API nécessitant une validation de contrat avancée et une vérification de compatibilité descendante.","de":"Perfekt für API-Testagenten, die erweiterte Vertragsvalidierungs- und Abwärtskompatibilitätsprüffunktionen benötigen.","pt":"Perfeito para Agentes de Teste de API que necessitam de validação avançada de contrato e capacidades de verificação de compatibilidade para trás.","ru":"Идеально подходит для агентов тестирования API, которым требуются продвинутые возможности проверки контракта и обратной совместимости.","ar":"مثالي لعمليات وكيل اختبار واجهة برمجة التطبيقات التي تحتاج إلى التحقق المتقدم من العقد والتحقق من التوافق العكسي."},"recommendation":{"en":"Empowers agents to validate API contracts, schemas, and backward compatibility using consumer-driven contracts and API versioning verification, supporting protocols like GraphQL and file formats such as OpenAPI definitions.","zh":"赋予代理验证 API 契约、模式和向后兼容性，使用消费者驱动的契约和 API 版本验证，支持诸如 GraphQL 和 OpenAPI 定义之类的协议和文件格式。","ja":"エージェントが API 契約、スキーマ、下位互換性を検証できるようにし、消費者主導の契約と API バージョンの検証を使用し、GraphQL や OpenAPI 定義などのプロトコルとファイル形式をサポートします。","ko":"에이전트가 API 계약, 스키마 및 하위 호환성을 검증할 수 있도록 하며, 소비자 주도 계약 및 API 버전 검증을 사용하고, GraphQL 및 OpenAPI 정의와 같은 프로토콜 및 파일 형식을 지원합니다.","es":"Habilita a los agentes a validar contratos de API, esquemas y compatibilidad hacia atrás utilizando contratos impulsados por el consumidor y verificación de versiones de API, y admite protocolos como GraphQL y formatos de archivo como definiciones de OpenAPI.","fr":"Permet aux agents de valider les contrats d''API, les schémas et la compatibilité descendante en utilisant des contrats impulsés par le consommateur et une vérification de version d''API, et prend en charge des protocoles tels que GraphQL et des formats de fichier tels que les définitions OpenAPI.","de":"Ermöglicht es Agenten, API-Verträge, Schemata und Abwärtskompatibilität zu validieren, indem sie von Verbrauchern getriebene Verträge und API-Versionenprüfung verwenden und unterstützt Protokolle wie GraphQL und Dateiformate wie OpenAPI-Definitionen.","pt":"Habilita os agentes a validar contratos de API, esquemas e compatibilidade para trás usando contratos orientados pelo consumidor e verificação de versionamento de API, suportando protocolos como GraphQL e formatos de arquivo como definições OpenAPI.","ru":"Наделяет агентов возможностью проверять контракты API, схемы и обратную совместимость с помощью контрактов, ориентированных на потребителя, и верификации версий API, поддерживая протоколы, такие как GraphQL, и форматы файлов, такие как определения OpenAPI.","ar":"يمنح الوكيل القدرة على التحقق من عقود واجهة برمجة التطبيقات والأنماط والتوافق العكسي باستخدام عقود مدفوعة بالاستهلاك والتحقق من إصدار واجهة برمجة التطبيقات، مع دعم بروتوكولات مثل GraphQL وتنسيقات الملفات مثل تعريفات OpenAPI."},"useCases":{"en":["Automating API contract testing","Validating schema changes for backward compatibility","Verifying event schemas for consistency","Testing GraphQL APIs for contract compliance"],"zh":["自动化 API 契约测试","验证模式更改以实现向后兼容性","验证事件模式以实现一致性","测试 GraphQL API 以实现契约合规性"],"ja":["API 契約のテストを自動化する","下位互換性のためにスキーマの変更を検証する","一貫性のためにイベント スキーマを検証する","契約の準拠を確保するために GraphQL API をテストする"],"ko":["API 계약 테스트 자동화","하위 호환성을 위해 스키마 변경 사항을 검증","일관성을 위해 이벤트 스키마를 검증","계약 준수를 위해 GraphQL API를 테스트"],"es":["Automatizar las pruebas de contrato de API","Validar los cambios de esquema para la compatibilidad hacia atrás","Verificar los esquemas de eventos para la coherencia","Probar las API de GraphQL para el cumplimiento del contrato"],"fr":["Automatiser les tests de contrat d''API","Valider les modifications de schéma pour la compatibilité descendante","Vérifier les schémas d''événements pour la cohérence","Tester les API GraphQL pour la conformité du contrat"],"de":["Automatisieren von API-Vertragstests","Validieren von Schemänderungen für Abwärtskompatibilität","Überprüfen von Ereignisschemata auf Konsistenz","Testen von GraphQL-APIs auf Vertragskonformität"],"pt":["Automatizar teste de contrato de API","Validar alterações de esquema para compatibilidade para trás","Verificar esquemas de evento para consistência","Testar APIs GraphQL para conformidade de contrato"],"ru":["Автоматизировать тестирование контракта API","Проверять изменения схемы для обратной совместимости","Верифицировать схемы событий для последовательности","Тестировать API GraphQL для соблюдения контракта"],"ar":["أتمتة اختبار عقد واجهة برمجة التطبيقات","التحقق من تغييرات مخطط للتوافق العكسي","التحقق من مخططات الحدث للتسلسل المتناسق","اختبار واجهات برمجة التطبيقات GraphQL للامتثال للعقد"]},"limitations":{"en":["Requires API definitions in OpenAPI format","Limited to API contract testing and validation"],"zh":["需要 OpenAPI 格式的 API 定义","仅限 API 契约测试和验证"],"ja":["OpenAPI 形式の API 定義が必要","API 契約のテストと検証に限定される"],"ko":["OpenAPI 형식의 API 정의가 필요","API 계약 테스트 및 검증에만 제한"],"es":["Requiere definiciones de API en formato OpenAPI","Limitado a pruebas y validación de contrato de API"],"fr":["Nécessite des définitions d''API au format OpenAPI","Limité aux tests et à la validation de contrat d''API"],"de":["Benötigt API-Definitionen im OpenAPI-Format","Begrenzt auf API-Vertragstests und -validierung"],"pt":["Exige definições de API no formato OpenAPI","Limitado ao teste e validação de contrato de API"],"ru":["Требует определений API в формате OpenAPI","Ограничен только тестированием и проверкой контракта API"],"ar":["يتطلب تعريفات واجهة برمجة التطبيقات بتنسيق OpenAPI","محدود لاختبار و تحقق عقد واجهة برمجة التطبيقات فقط"]},"version":4},"contentHash":"e9205afaa4499aa08a269e8441cc0c8a7923bf8d1fb360e777ae6242aa806890","qualityScore":39}');
