INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('proffesor-for-testing/agentic-qe/QE Contract Testing', 'QE Contract Testing', 'proffesor-for-testing', 'agentic-qe', 'community', 'QE Contract Testing proffesor-for-testing agentic-qe community QE Contract Testing is an AI-powered testing capability for validating API contracts, schemas, and backward compatibility. It supports consumer-driven contracts and API versioning verification QE 合同测试是 Agentic QE Fleet 的一个功能，支持消费者驱动的合同、模式验证和 API 版本验证 QE 契約テストは Agentic QE Fleet の機能であり、消費者主導の契約、スキーマの検証、API バージョンの検証を可能にします QE 계약 테스트는 Agentic QE Fleet의 기능으로 소비자 주도 계약, 스키마 유효성 검사 및 API 버전 확인을 지원합니다 QE Contract Testing es una habilidad de Agentic QE Fleet que permite probar contratos de API y validar esquemas Le testing de contrats QE est une compétence d''Agentic QE Fleet qui permet de tester les contrats d''API et de valider les schémas QE Contract Testing ist eine Fähigkeit von Agentic QE Fleet, die das Testen von API-Verträgen und die Validierung von Schemata ermöglicht O Teste de Contrato QE é uma capacidade de teste alimentada por IA para validar contratos de API, esquemas e compatibilidade reversa. Ele suporta contratos orientados ao consumidor e verificação de versionamento de API Тестирование контрактов QE — это функция тестирования на основе ИИ для проверки контрактов API, схем и обратной совместимости. Она поддерживает контракты, ориентированные на потребителя, и проверку версий API اختبار العقد QE هو khảية اختبار مدعومة بالذكاء الاصطناعي للتحقق من عقود API والمخططات والتوافق العكسي. يدعم عقودًا مدفوعة بالعملاء والتحقق من إصدار API QE Contract Testing API contract testing schema validation backward compatibility checking API versioning verification GraphQL API testing consumer-driven contract testing QE 合同测试 API 合同验证 模式验证 向后兼容性测试 API 版本 GraphQL API 测试 事件模式验证 Agentic QE Fleet 消费者驱动的合同 Consumer-driven contract testing Schema validation and verification Backward compatibility checking API versioning verification Support for GraphQL APIs Event schema validation QE Contract Testing is an AI-powered testing capability for validating API contracts and schemas');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('vechain/inspector-app/karpathy-guidelines', 'community', 'vechain', 'inspector-app', 'vechain/inspector-app', 'karpathy-guidelines', 0, 0, 39, '2026-03-08T01:57:15.310Z', '2026-03-08T02:02:27.574Z', 'ada2bbcebc34310151b3ec66d6d2f9368f2a210edf95d60318fcb1fd6bfd9459', '{"id":"vechain/inspector-app/karpathy-guidelines","name":"karpathy-guidelines","description":{"en":"The karpathy-guidelines skill provides a smart contract explorer tool for interacting with contracts on VeChain networks, benefiting developers who want to reduce common LLM coding mistakes.","zh":"karpathy-guidelines 是一套智能合约开发的行为指南，旨在减少常见的 LLM 编码错误","ja":"karpathy-guidelines は、AI エージェントを使用したスマートコントラクト開発のための行動ガイドラインです","ko":"karpathy-guidelines 는 스마트 컨트랙트 개발을 위한 행동 가이드라인입니다","es":"karpathy-guidelines es una herramienta de exploración de contratos inteligentes que permite interactuar con contratos en redes VeChain, basada en las pautas de comportamiento de Andrej Karpathy","fr":"karpathy-guidelines est un outil d''exploration de contrats intelligents qui permet d''interagir avec des contrats sur les réseaux VeChain, basé sur les lignes directrices de comportement d''Andrej Karpathy","de":"karpathy-guidelines ist ein Tool zur Erkundung von Smart Contracts, das die Interaktion mit Verträgen in VeChain-Netzwerken ermöglicht, basierend auf den Verhaltensrichtlinien von Andrej Karpathy","pt":"O karpathy-guidelines é uma ferramenta de exploração de smart contracts que ajuda a interagir com contratos na rede VeChain, fornecendo diretrizes comportamentais para reduzir erros de codificação comuns em LLM.","ru":"ИИ Агент karpathy-guidelines - это инструмент для изучения смарт-контрактов, который помогает взаимодействовать с контрактами в сети VeChain, предоставляя поведенческие рекомендации для снижения распространенных ошибок кодирования в LLM.","ar":"وكلاء الذكاء الاصطناعي karpathy-guidelines هو أداة لاستكشاف العقود الذكية التي تساعد على التفاعل مع العقود على شبكة VeChain، وتقدم إرشادات سلوكية لتقليل الأخطاء الشائعة في كتابة كود LLM."},"seo":{"title":{"en":"karpathy-guidelines: Smart Contract Explorer Setup Guide ...","zh":"karpathy-guidelines 智能合约开发最佳实践","ja":"karpathy-guidelines AIエージェントによるスマートコントラクト開発ガイド","ko":"karpathy-guidelines 스마트 컨트랙트 개발을 위한 가이드","es":"Guía de configuración de karpathy-guidelines para explora...","fr":"Guide de démarrage de karpathy-guidelines pour l''explorat...","de":"Einrichtungsanleitung für karpathy-guidelines zur Erkundu...","pt":"Guia de Configuração do karpathy-guidelines: Melhores Prá...","ru":"Настройка karpathy-guidelines: Руководство по Безопасному...","ar":"دليل إعداد karpathy-guidelines: إرشادات لتطوير التطبيقات ..."},"description":{"en":"Discover how karpathy-guidelines helps you interact with VeChain contracts, reducing LLM coding mistakes - explore the guidelines and start coding with confi...","zh":"karpathy-guidelines 提供智能合约开发的行为指南，减少常见的 LLM 编码错误","ja":"karpathy-guidelines は AI エージェントを使用したスマートコントラクト開発のための行動ガイドラインを提供します","ko":"karpathy-guidelines 는 스마트 컨트랙트 개발을 위한 행동 가이드라인을 제공하여 일반적인 LLM 코딩 오류를减少합니다","es":"Descubre cómo interactuar con contratos en redes VeChain con karpathy-guidelines, una herramienta de exploración de contratos inteligentes","fr":"Découvrez comment interagir avec des contrats sur les réseaux VeChain avec karpathy-guidelines, un outil d''exploration de contrats intelligents","de":"Erfahren Sie, wie Sie mit karpathy-guidelines, einem Tool zur Erkundung von Smart Contracts, mit Verträgen in VeChain-Netzwerken interagieren","pt":"Aprenda a configurar o karpathy-guidelines para evitar erros comuns de codificação em LLM e melhorar a segurança dos seus smart contracts","ru":"Узнайте, как настроить karpathy-guidelines, чтобы избежать распространенных ошибок кодирования в LLM и повысить безопасность своих смарт-контрактов","ar":"تعرف على كيفية 구성 karpathy-guidelines لتجنب الأخطاء الشائعة في كتابة كود LLM وتحسين أمان عقودك الذكية"},"definition":{"en":"karpathy-guidelines is a set of behavioral guidelines to reduce common LLM coding mistakes, derived from Andrej Karpathy''s observations on LLM coding pitfalls","zh":"karpathy-guidelines 是一套智能合约开发的行为指南","ja":"karpathy-guidelines は AI エージェントを使用したスマートコントラクト開発のための行動ガイドライン","ko":"karpathy-guidelines 는 스마트 컨트랙트 개발을 위한 행동 가이드라인","es":"karpathy-guidelines es un conjunto de pautas de comportamiento para reducir errores de codificación comunes en LLM, derivadas de las observaciones de Andrej Karpathy","fr":"karpathy-guidelines est un ensemble de lignes directrices de comportement pour réduire les erreurs de codage courantes dans LLM, dérivées des observations d''Andrej Karpathy","de":"karpathy-guidelines ist eine Sammlung von Verhaltensrichtlinien zur Reduzierung häufiger Codierfehler in LLM, abgeleitet aus den Beobachtungen von Andrej Karpathy","pt":"O karpathy-guidelines é um conjunto de diretrizes comportamentais para desenvolvedores que visam reduzir erros comuns de codificação em LLM.","ru":"ИИ Агент karpathy-guidelines - это набор поведенческих рекомендаций для разработчиков, направленных на снижение распространенных ошибок кодирования в LLM.","ar":"وكلاء الذكاء الاصطناعي karpathy-guidelines هو مجموعة من الإرشادات السلوكية للمطورين التي تهدف إلى تقليل الأخطاء الشائعة في كتابة كود LLM."},"features":{"en":["Provides a smart contract explorer tool for interacting with contracts on VeChain networks","Follows guidelines to reduce common LLM coding mistakes, such as assuming or hiding confusion","Surfaces tradeoffs and explicitly states assumptions before implementing","Allows for judgment in trivial tasks, biasing toward caution over speed","Derives guidelines from Andrej Karpathy''s observations on LLM coding pitfalls"],"zh":["明确表述假设","不要隐藏困惑","表面化权衡","在实现前明确假设","如果存在多种解释，明确说明"],"ja":["仮定を明確に表現する","混乱を隠さない","トレードオフを表面化する","実装前に仮定を明確にする","複数の解釈が存在する場合、明確に説明する"],"ko":["가정문을 명확하게 표명","혼란을 숨기지 않음","트레이드 오프를 표면화","구현 전에 가정을 명확히 함","여러 해석이 존재하는 경우 명확히 설명"],"es":["Interacción con contratos en redes VeChain","Basado en las pautas de comportamiento de Andrej Karpathy","Reducción de errores de codificación comunes en LLM","Herramienta de exploración de contratos inteligentes","Análisis de tradeoffs y suposiciones explícitas"],"fr":["Interaction avec des contrats sur les réseaux VeChain","Basé sur les lignes directrices de comportement d''Andrej Karpathy","Réduction des erreurs de codage courantes dans LLM","Outil d''exploration de contrats intelligents","Analyse de compromis et hypothèses explicites"],"de":["Interaktion mit Verträgen in VeChain-Netzwerken","Basierend auf den Verhaltensrichtlinien von Andrej Karpathy","Reduzierung häufiger Codierfehler in LLM","Tool zur Erkundung von Smart Contracts","Analyse von Tradeoffs und expliziten Annahmen"],"pt":["Fornecer diretrizes comportamentais para reduzir erros de codificação comuns em LLM","Interagir com contratos na rede VeChain","Surface tradeoffs e evitar suposições","Fornecer uma abordagem cautelosa para codificação","Ajuda a evitar erros de codificação em tarefas triviais"],"ru":["Предоставление поведенческих рекомендаций для снижения распространенных ошибок кодирования в LLM","Взаимодействие с контрактами в сети VeChain","Surface tradeoffs и избегание предположений","Предоставление осторожного подхода к кодированию","Помощь в избегании ошибок кодирования в тривиальных задачах"],"ar":["تقديم إرشادات سلوكية لتقليل الأخطاء الشائعة في كتابة كود LLM","التفاعل مع العقود على شبكة VeChain","surface tradeoffs وتجنب الافتراضات","تقديم نهج حذر لكتابة الكود","مساعدة في تجنب الأخطاء في كتابة الكود في المهام التافهة"]},"keywords":{"en":["how to use karpathy-guidelines","what is karpathy-guidelines","karpathy-guidelines alternative","karpathy-guidelines vs smart contract explorer","karpathy-guidelines install","karpathy-guidelines setup guide","VeChain contract interaction","LLM coding mistake reduction"],"zh":["智能合约开发","LLM 编码错误","行为指南","karpathy-guidelines","AI 工具","智能合约开发最佳实践"],"ja":["スマートコントラクト開発","LLM コーディングエラー","行動ガイドライン","karpathy-guidelines","AI エージェント","スマートコントラクト開発ガイド"],"ko":["스마트 컨트랙트 개발","LLM 코딩 오류","행동 가이드라인","karpathy-guidelines","AI 도구","스마트 컨트랙트 개발 가이드"],"es":["karpathy-guidelines","contratos inteligentes","redes VeChain","herramienta de exploración","LLM","codificación","Andrej Karpathy","pautas de comportamiento","Agentes de IA","Herramientas de IA"],"fr":["karpathy-guidelines","contrats intelligents","réseaux VeChain","outil d''exploration","LLM","codage","Andrej Karpathy","lignes directrices de comportement","Agents de l''IA","Outils de l''IA"],"de":["karpathy-guidelines","Smart Contracts","VeChain-Netzwerke","Tool zur Erkundung","LLM","Codierung","Andrej Karpathy","Verhaltensrichtlinien","KI-Agents","KI-Tools"],"pt":["karpathy-guidelines","LLM","VeChain","smart contracts","desenvolvimento de software","segurança de código","erros de codificação","diretrizes comportamentais"],"ru":["ИИ Агент karpathy-guidelines","LLM","VeChain","смарт-контракты","разработка программного обеспечения","безопасность кода","ошибки кодирования","поведенческие рекомендации"],"ar":["وكلاء الذكاء الاصطناعي karpathy-guidelines","LLM","VeChain","العقود الذكية","تطوير البرمجيات","أمان الكود","أخطاء الكود","الإرشادات السلوكية"]}},"owner":"vechain","repo":"inspector-app","repoPath":"vechain/inspector-app","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.310Z","topics":[],"category":"community","skillMd":{"name":"karpathy-guidelines","description":"Behavioral guidelines to reduce common LLM coding mistakes. Use when writing, reviewing, or refactoring code to avoid overcomplication, make surgical changes, surface assumptions, and define verifiable success criteria.","bodyPreview":"# Karpathy Guidelines\n\nBehavioral guidelines to reduce common LLM coding mistakes, derived from [Andrej Karpathy''s observations](https://x.com/karpathy/status/2015883857489522876) on LLM coding pitfalls.\n\n**Tradeoff:** These guidelines bias toward caution over speed. For trivial tasks, use judgment.\n\n## 1. Think Before Coding\n\n**Don''t assume. Don''t hide confusion. Surface tradeoffs.**\n\nBefore implementing:\n\n- State your assumptions explicitly. If uncertain, ask.\n- If multiple interpretations exi","body":"# Karpathy Guidelines\n\nBehavioral guidelines to reduce common LLM coding mistakes, derived from [Andrej Karpathy''s observations](https://x.com/karpathy/status/2015883857489522876) on LLM coding pitfalls.\n\n**Tradeoff:** These guidelines bias toward caution over speed. For trivial tasks, use judgment.\n\n## 1. Think Before Coding\n\n**Don''t assume. Don''t hide confusion. Surface tradeoffs.**\n\nBefore implementing:\n\n- State your assumptions explicitly. If uncertain, ask.\n- If multiple interpretations exist, present them - don''t pick silently.\n- If a simpler approach exists, say so. Push back when warranted.\n- If something is unclear, stop. Name what''s confusing. Ask.\n\n## 2. Simplicity First\n\n**Minimum code that solves the problem. Nothing speculative.**\n\n- No features beyond what was asked.\n- No abstractions for single-use code.\n- No \"flexibility\" or \"configurability\" that wasn''t requested.\n- No error handling for impossible scenarios.\n- If you write 200 lines and it could be 50, rewrite it.\n\nAsk yourself: \"Would a senior engineer say this is overcomplicated?\" If yes, simplify.\n\n## 3. Surgical Changes\n\n**Touch only what you must. Clean up only your own mess.**\n\nWhen editing existing code:\n\n- Don''t \"improve\" adjacent code, comments, or formatting.\n- Don''t refactor things that aren''t broken.\n- Match existing style, even if you''d do it differently.\n- If you notice unrelated dead code, mention it - don''t delete it.\n\nWhen your changes create orphans:\n\n- Remove imports/variables/functions that YOUR changes made unused.\n- Don''t remove pre-existing dead code unless asked.\n\nThe test: Every changed line should trace directly to the user''s request.\n\n## 4. Goal-Driven Execution\n\n**Define success criteria. Loop until verified.**\n\nTransform tasks into verifiable goals:\n\n- \"Add validation\" → \"Write tests for invalid inputs, then make them pass\"\n- \"Fix the bug\" → \"Write a test that reproduces it, then make it pass\"\n- \"Refactor X\" → \"Ensure tests pass before and after\"\n\nFor multi-step tasks, state a brief plan:\n\n```\n1. [Step] → verify: [check]\n2. [Step] → verify: [check]\n3. [Step] → verify: [check]\n```\n\nStrong success criteria let you loop independently. Weak criteria (\"make it work\") require constant clarification.\n"},"lastSynced":"2026-03-08T02:02:27.574Z","agentAnalysis":{"suitability":{"en":"Perfect for LLM-focused AI Agents needing guidelines to reduce common coding mistakes and improve smart contract interactions on VeChain networks.","zh":"非常适合专注于LLM的AI代理，需要指导方针以减少常见编码错误并改善在VeChain网络上的智能合约交互。","ja":"LLMに焦点を当てたAIエージェントに最適で、一般的なコーディングミスを減らし、VeChainネットワーク上のスマートコントラクトの対話を改善するためのガイドラインを必要とします。","ko":"LLM 중심 AI 에이전트에 완벽하게 적합하며, 일반적인 코딩 실수를 줄이고 VeChain 네트워크에서의 스마트 계약 상호 작용을 개선하기 위한 지침이 필요합니다.","es":"Perfecto para agentes de inteligencia artificial centrados en LLM que necesitan pautas para reducir errores de codificación comunes y mejorar las interacciones de contratos inteligentes en redes VeChain.","fr":"Parfait pour les agents d''intelligence artificielle axés sur LLM qui ont besoin de lignes directrices pour réduire les erreurs de codage courantes et améliorer les interactions de contrats intelligents sur les réseaux VeChain.","de":"Perfekt für LLM-fokussierte KI-Agents, die Richtlinien benötigen, um gängige Codierfehler zu reduzieren und die Interaktionen von Smart Contracts in VeChain-Netzwerken zu verbessern.","pt":"Perfeito para Agentes de IA com foco em LLM que necessitam de diretrizes para reduzir erros de codificação comuns e melhorar as interações de contrato inteligente nas redes VeChain.","ru":"Идеально для агентов ИИ, ориентированных на LLM, которым необходимы рекомендации по снижению общих ошибок кодирования и улучшению взаимодействия с контрактами на сетях VeChain.","ar":"مثالي للوكلاء الذكية التي تركز على LLM التي تحتاج إلى إرشادات لتقليص الأخطاء الشائعة في كتابة الشيفرة وتحسين تفاعلات العقود الذكية على شبكات VeChain."},"recommendation":{"en":"Empowers agents to implement Andrej Karpathy''s guidelines, surfacing tradeoffs and avoiding assumptions in LLM coding, leveraging smart contract explorer tools for VeChain networks and reducing errors through explicit assumption stating and tradeoff analysis.","zh":"使代理能够实施Andrej Karpathy的指导方针，揭示LLM编码中的权衡并避免假设，利用VeChain网络的智能合约浏览器工具，并通过明确陈述假设和权衡分析来减少错误。","ja":"エージェントがAndrej Karpathyのガイドラインを実装し、LLMコーディングにおけるトレードオフを表面化させ、仮定を回避し、VeChainネットワークのスマートコントラクトエクスプローラーツールを活用し、明示的な仮定の表明とトレードオフ分析を通じてエラーを削減することを可能にします。","ko":"에이전트가 Andrej Karpathy의 지침을 구현하여 LLM 코딩에서의 트레이드오프를 표면화하고 가정을 피하며, VeChain 네트워크용 스마트 계약 탐색기 도구를 활용하고, 명시적인 가정 진술과 트레이드오프 분석을 통해 오류를 줄일 수 있도록 합니다.","es":"Habilita a los agentes a implementar las pautas de Andrej Karpathy, poniendo de relieve las compensaciones y evitando suposiciones en la codificación de LLM, aprovechando las herramientas de explorador de contratos inteligentes para las redes VeChain y reduciendo los errores a través de la declaración explícita de suposiciones y el análisis de compensaciones.","fr":"Permet aux agents de mettre en œuvre les lignes directrices d''Andrej Karpathy, mettant en évidence les compromis et évitant les hypothèses dans la codification LLM, en exploitant les outils d''explorateur de contrats intelligents pour les réseaux VeChain et en réduisant les erreurs grâce à l''énoncé explicite des hypothèses et à l''analyse des compromis.","de":"Ermächtigt Agents, die Richtlinien von Andrej Karpathy umzusetzen, Trade-offs aufzudecken und Annahmen in der LLM-Codierung zu vermeiden, indem sie Werkzeuge für die Smart-Contract-Explorer für VeChain-Netzwerke nutzen und Fehler durch explizite Angabe von Annahmen und Trade-off-Analyse reduzieren.","pt":"Habilita agentes a implementar as diretrizes de Andrej Karpathy, expondo compensações e evitando suposições na codificação LLM, utilizando ferramentas de explorador de contrato inteligente para redes VeChain e reduzindo erros por meio de declarações de suposição explícita e análise de compensações.","ru":"Наделяет агентов возможностью реализовать рекомендации Андрея Карпаты, выявляя компромиссы и избегая предположений при кодировании LLM, используя инструменты для изучения контрактов на сетях VeChain и снижая ошибки посредством явного указания предположений и анализа компромиссов.","ar":"تمكّن الوكلاء من تنفيذ إرشادات Andrej Karpathy، وكشف المساومات وتجنب الافتراضات في كتابة الشيفرة LLM، واستخدام أدوات مستكشف عقد ذكية لشبكات VeChain وتقليل الأخطاء من خلال إعلان افتراضات صريحة وتحليل المساومات."},"useCases":{"en":["Debugging LLM coding mistakes by applying Karpathy''s guidelines","Generating explicit assumptions for smart contract interactions on VeChain","Analyzing tradeoffs in LLM coding decisions for improved contract reliability"],"zh":["通过应用Karpathy的指导方针调试LLM编码错误","为VeChain上的智能合约交互生成明确的假设","分析LLM编码决策中的权衡以提高合约可靠性"],"ja":["Karpathyのガイドラインを適用したLLMコーディングミスのデバッグ","VeChain上のスマートコントラクト対話のための明示的な仮定の生成","契約の信頼性向上のためのLLMコーディング決定におけるトレードオフの分析"],"ko":["Karpathy의 지침을 적용하여 LLM 코딩 실수 디버깅","VeChain에서의 스마트 계약 상호 작용을 위한 명시적인 가정 생성","계약 신뢰성 향상을 위한 LLM 코딩 결정의 트레이드오프 분석"],"es":["Depuración de errores de codificación de LLM mediante la aplicación de las pautas de Karpathy","Generación de suposiciones explícitas para interacciones de contratos inteligentes en VeChain","Análisis de compensaciones en decisiones de codificación de LLM para una mayor confiabilidad del contrato"],"fr":["Débogage des erreurs de codage LLM en appliquant les lignes directrices de Karpathy","Génération d''hypothèses explicites pour les interactions de contrats intelligents sur VeChain","Analyse des compromis dans les décisions de codage LLM pour une fiabilité de contrat améliorée"],"de":["Fehlerbehebung bei LLM-Codierfehlern durch Anwendung der Richtlinien von Karpathy","Erzeugung expliziter Annahmen für Smart-Contract-Interaktionen in VeChain","Analyse von Trade-offs bei LLM-Codierentscheidungen für eine verbesserte Vertragstreue"],"pt":["Depuração de erros de codificação LLM aplicando as diretrizes de Karpathy","Geração de suposições explícitas para interações de contrato inteligente na VeChain","Análise de compensações em decisões de codificação LLM para confiabilidade de contrato aprimorada"],"ru":["Отладка ошибок кодирования LLM с помощью рекомендаций Карпаты","Генерация явных предположений для взаимодействия с контрактами на VeChain","Анализ компромиссов при принятии решений по кодированию LLM для повышения надежности контракта"],"ar":["تصحيح أخطاء كتابة الشيفرة LLM بتطبيق إرشادات Karpathy","توليد افتراضات صريحة لتفاعلات العقود الذكية على شبكات VeChain","تحليل المساومات في قرارات كتابة الشيفرة LLM لتحسين موثوقية العقد"]},"limitations":{"en":["Biases toward caution over speed, potentially impacting performance in trivial tasks","Requires judgment for trivial tasks to balance caution and speed"],"zh":["偏向谨慎而非速度，可能影响简单任务中的性能","需要对简单任务进行判断以平衡谨慎和速度"],"ja":["速度よりも慎重さへの偏りにより、些細なタスクでのパフォーマンスに影響を与える可能性","些細なタスクでは慎重さと速度のバランスを取るための判断が必要"],"ko":["속도보다 신중함에 대한 편향으로 인해 사소한 작업에서 성능에 영향을 미칠 수 있음","사소한 작업에서는 신중함과 속도의 균형을 맞추기 위한 판단이 필요"],"es":["Sesgos hacia la precaución sobre la velocidad, lo que podría afectar el rendimiento en tareas triviales","Requiere juicio para tareas triviales para equilibrar la precaución y la velocidad"],"fr":["Biais en faveur de la prudence plutôt que de la vitesse, ce qui pourrait avoir un impact sur les performances dans les tâches triviales","Nécessite un jugement pour les tâches triviales pour équilibrer la prudence et la vitesse"],"de":["Voreingenommenheit gegenüber Vorsicht anstelle von Geschwindigkeit, was sich möglicherweise auf die Leistung bei trivialen Aufgaben auswirken könnte","Erfordert Urteilsvermögen für triviale Aufgaben, um Vorsicht und Geschwindigkeit auszugleichen"],"pt":["Vieses em direção à prudência em detrimento da velocidade, potencialmente impactando o desempenho em tarefas triviais","Requer julgamento para tarefas triviais para equilibrar prudência e velocidade"],"ru":["Предвзятость в сторону осторожности вместо скорости, потенциально влияющая на производительность при выполнении тривиальных задач","Требуется суждение для тривиальных задач, чтобы сбалансировать осторожность и скорость"],"ar":["انحياز نحو الحذر على حساب السرعة، مما قد يؤثر على الأداء في المهام التافهة","يتطلب الحكم لتحقيق توازن بين الحذر والسرعة في المهام التافهة"]},"version":4},"contentHash":"ada2bbcebc34310151b3ec66d6d2f9368f2a210edf95d60318fcb1fd6bfd9459","qualityScore":39}');
