INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ohare93/juggle/sandbox-setup', 'sandbox-setup', 'ohare93', 'juggle', 'community', 'sandbox-setup ohare93 juggle community The sandbox-setup skill analyzes codebases to detect programming languages and generates tailored permissions for .claude/settings.json, benefiting AI agent developers. Sandbox Setup 能够分析代码库并生成定制的权限设置，以优化 CLI Ralph Loops 的执行 Sandbox Setup はコードベースを分析し、AIエージェントのためのカスタマイズされた権限設定を生成します Sandbox Setup은 코드베이스를 분석하고 최적의 권한 설정을 생성하여 CLI Ralph Loops를 최적화합니다 sandbox-setup analiza su base de código para detectar lenguajes de programación y genera permisos personalizados para .claude/settings.json sandbox-setup analyse votre base de code pour détecter les langages de programmation et génère des autorisations personnalisées pour .claude/settings.json sandbox-setup analysiert Ihren Codebasis, um Programmiersprachen zu erkennen und generiert benutzerdefinierte Berechtigungen für .claude/settings.json O sandbox-setup é uma habilidade que configura o repositório para execução autônoma de agentes de IA, detectando linguagens de programação e gerenciando permissões Sandbox-setup - это навык, который настраивает репозиторий для автономного выполнения ИИ Агентов, обнаруживая языки программирования и управляя разрешениями sandbox-setup هو مهارة تكوين المستودع لتنفيذ وكلاء الذكاء الاصطناعي بشكل مستقل ، والكشف عن لغات البرمجة وإدارة الأذونات how to use sandbox-setup sandbox-setup setup guide autonomous agent execution Claude Code configuration sandbox-setup alternative sandbox-setup vs other AI agent skills sandbox-setup install what is sandbox-setup sandbox-setup for AI agents Sandbox Setup CLI Ralph Loops 代码库分析 权限设置 Go 编程语言 Python 编程语言 Node.js 编程语言 Rust 编程语言 Analyzes codebases to detect programming languages like Go, Python, Node.js, and Rust Detects package managers such as go mod, npm, pip, and cargo Generates tailored permissions for .claude/settings.json Allows commands for detected tools like build tools and test runners Configures network access for package registries sandbox-setup is a skill that configures Claude Code for autonomous agent execution, detecting languages like Go, Python, and Node.js.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('testomatio/explorbot/xpath-testing', 'community', 'testomatio', 'explorbot', 'testomatio/explorbot', 'xpath-testing', 0, 0, 39, '2026-03-08T01:57:15.311Z', '2026-03-08T02:02:32.855Z', 'dffaf17d3499e58fd5b1e7a36ee73eb986e8cf7231784f475f0313b106229eed', '{"id":"testomatio/explorbot/xpath-testing","name":"xpath-testing","description":{"en":"The xpath-testing skill enables AI agents to test XPath expressions against HTML files in a test-data directory, helping developers find specific elements. This skill is designed for iterative testing, starting broad and narrowing down to unique XPath expressions.","zh":"XPath 测试技能是用于测试 HTML 文件的 AI 工具，通过 XPath 表达式找到特定元素。","ja":"XPath テストスキルは、HTML ファイルをテストする AI ツールで、XPath 式を使用して特定の要素を見つけます。","ko":"XPath 테스트 스킬은 HTML 파일을 테스트하는 AI 도구로 XPath 표현식을 사용하여 특정 요소를 찾습니다.","es":"xpath-testing es una herramienta de prueba de navegador que utiliza expresiones XPath para encontrar elementos en archivos HTML","fr":"xpath-testing est un outil de test de navigateur qui utilise des expressions XPath pour trouver des éléments dans des fichiers HTML","de":"xpath-testing ist ein Browser-Test-Tool, das XPath-Ausdrücke verwendet, um Elemente in HTML-Dateien zu finden","pt":"O XPath Testing é uma habilidade de teste de navegador que permite testar expressões XPath em arquivos HTML","ru":"ИИ Агенты для XPath Testing позволяют тестировать XPath выражения в HTML файлах","ar":"اختبار XPath هو مهارة لاختبار المتصفحات التي تسمح باختبار التعبيرات XPath في ملفات HTML"},"seo":{"title":{"en":"xpath-testing: Iterative XPath Testing Setup Guide | AI A...","zh":"XPath 测试技能设置指南 - AIエージェント","ja":"XPath テストスキルベストプラクティス - AIエージェント","ko":"XPath 테스트 스킬 설정 가이드 - AI 에이전트","es":"Guía de configuración de xpath-testing para pruebas de na...","fr":"Configurer xpath-testing pour les tests de navigateur","de":"Einrichten von xpath-testing für Browser-Tests","pt":"Guia de Configuração do XPath Testing para Ferramentas de IA","ru":"Настройка ИИ Агентов для XPath Testing","ar":"دليل إعداد اختبار XPath للأدوات الذكية"},"description":{"en":"Unlock efficient XPath testing with our AI agent skill. Learn how to iteratively query XPath expressions against HTML files and find specific elements with e...","zh":"使用 XPath 测试技能对 HTML 文件进行测试，找到特定元素。了解工作流程和规则，提高测试效率。","ja":"XPath テストスキルを使用して HTML ファイルをテストし、特定の要素を見つけてください。ワークフローとルールを学び、テストの効率を向上させます。","ko":"XPath 테스트 스킬을 사용하여 HTML 파일을 테스트하고 특정 요소를 찾습니다. 작업 흐름과 규칙을 배우고 테스트 효율을 향상합니다.","es":"Aprende a utilizar xpath-testing para probar expresiones XPath en archivos HTML con nuestra guía paso a paso","fr":"Découvrez comment utiliser xpath-testing pour tester des expressions XPath dans des fichiers HTML avec notre guide étape par étape","de":"Erfahren Sie, wie Sie xpath-testing verwenden, um XPath-Ausdrücke in HTML-Dateien mit unserem Schritt-für-Schritt-Leitfaden zu testen","pt":"Aprenda a configurar o XPath Testing para testar expressões XPath em arquivos HTML com ferramentas de IA","ru":"Узнайте, как настроить ИИ Агенты для тестирования XPath выражений в HTML файлах","ar":"تعرف على كيفية إعداد اختبار XPath لاختبار التعبيرات XPath في ملفات HTML باستخدام الأدوات الذكية"},"definition":{"en":"xpath-testing is a skill that allows AI agents to iteratively test XPath expressions against HTML files to find specific elements, following a set of rules to ensure efficient testing.","zh":"XPath 测试技能是指使用 XPath 表达式测试 HTML 文件的技术","ja":"XPath テストスキルとは、XPath 式を使用して HTML ファイルをテストする技術です","ko":"XPath 테스트 스킬은 XPath 표현식을 사용하여 HTML 파일을 테스트하는 기술입니다","es":"xpath-testing es una herramienta de prueba de navegador que utiliza expresiones XPath","fr":"xpath-testing est un outil de test de navigateur qui utilise des expressions XPath","de":"xpath-testing ist ein Browser-Test-Tool, das XPath-Ausdrücke verwendet","pt":"XPath Testing é uma ferramenta de teste que usa expressões XPath para encontrar elementos em arquivos HTML","ru":"ИИ Агенты для XPath Testing - это инструмент для тестирования, использующий XPath выражения для поиска элементов в HTML файлах","ar":"اختبار XPath هو أداة اختبار تستخدم التعبيرات XPath للعثور على عناصر في ملفات HTML"},"features":{"en":["Tests XPath expressions against HTML files in the test-data directory","Iteratively queries XPath expressions to find specific elements","Starts with broad queries and narrows down to unique XPath expressions","Uses a CLI tool to query HTML files, without reading them directly","Allows listing of files in the test-data directory to see available options","Works in a game-like scenario, where the AI agent iteratively refines its queries"],"zh":["使用 CLI 工具查询 HTML 文件","支持迭代查询 XPath 表达式","可以列出 test-data/ 目录下的文件","通过 XPath 表达式找到特定元素","支持工作流程的设计"],"ja":["CLI ツールを使用して HTML ファイルをクエリする","XPath 式の反復クエリをサポートする","test-data/ ディレクトリ内のファイルを列挙する","XPath 式を使用して特定の要素を見つける","ワークフローの設計をサポートする"],"ko":["CLI 도구를 사용하여 HTML 파일을 쿼리한다","XPath 표현식의 반복 쿼리를 지원한다","test-data/ 디렉토리 내의 파일을 열거한다","XPath 표현식을 사용하여 특정 요소를 찾는다","작업 흐름의 설계를 지원한다"],"es":["Prueba de expresiones XPath en archivos HTML","Uso de la herramienta de línea de comandos para consultar archivos HTML","Iteración para encontrar el elemento correcto y una ruta XPath única","Compatibilidad con archivos HTML en el directorio ''test-data/''","Soporte para listado de archivos en el directorio ''test-data/''"],"fr":["Test d''expressions XPath dans des fichiers HTML","Utilisation de l''outil de ligne de commande pour interroger des fichiers HTML","Itération pour trouver l''élément correct et un chemin XPath unique","Compatibilité avec des fichiers HTML dans le répertoire ''test-data/''","Prise en charge de la liste de fichiers dans le répertoire ''test-data/''"],"de":["Testen von XPath-Ausdrücken in HTML-Dateien","Verwendung der Kommandozeilen-Tool zum Abfragen von HTML-Dateien","Iteratives Vorgehen, um das richtige Element und einen eindeutigen XPath zu finden","Unterstützung für HTML-Dateien im Verzeichnis ''test-data/''","Unterstützung für die Auflistung von Dateien im Verzeichnis ''test-data/''"],"pt":["Teste de expressões XPath em arquivos HTML","Uso do CLI para consultar arquivos HTML","Trabalho iterativo para encontrar elementos específicos","Suporte a listagem de arquivos em ''test-data/''","Encontrar elementos únicos com XPath"],"ru":["Тестирование XPath выражений в HTML файлах","Использование CLI для запроса HTML файлов","Итеративная работа для поиска конкретных элементов","Поддержка списка файлов в ''test-data/''","Поиск уникальных элементов с помощью XPath"],"ar":["اختبار التعبيرات XPath في ملفات HTML","استخدام CLI لاستعلام ملفات HTML","العمل التكراري للعثور على عناصر محددة","دعم قائمة الملفات في ''test-data/''","العثور على عناصر فريدة باستخدام XPath"]},"keywords":{"en":["how to use xpath-testing","xpath-testing setup guide","xpath-testing alternative","xpath-testing vs selenium","xpath-testing install","what is xpath-testing","xpath-testing tutorial","xpath-testing for AI agents","xpath-testing best practices","xpath-testing for HTML testing"],"zh":["XPath 测试","AI 测试工具","HTML 文件测试","CLI 工具","XPath 表达式","测试工作流程"],"ja":["XPath テスト","AI テストツール","HTML ファイルテスト","CLI ツール","XPath 式","テストワークフロー"],"ko":["XPath 테스트","AI 테스트 도구","HTML 파일 테스트","CLI 도구","XPath 표현식","테스트 작업 흐름"],"es":["xpath-testing","pruebas de navegador","expresiones XPath","herramientas de prueba","desarrollo web","test de navegador","xpath en html","herramienta de línea de comandos"],"fr":["xpath-testing","tests de navigateur","expressions XPath","outils de test","développement web","test de navigateur","xpath dans html","outil de ligne de commande"],"de":["xpath-testing","Browser-Tests","XPath-Ausdrücke","Test-Tools","Web-Entwicklung","Browser-Test","xpath in html","Kommandozeilen-Tool"],"pt":["xpath testing","ferramentas de ia","teste de navegador","expressões xpath","arquivos html","cli","test-data","desenvolvimento web"],"ru":["xpath testing","ии агенты","тестирование браузера","xpath выражения","html файлы","cli","test-data","веб-разработка"],"ar":["اختبار xpath","أدوات ذكية","اختبار متصفح","تعبيرات xpath","ملفات html","cli","test-data","تطوير ويب"]}},"owner":"testomatio","repo":"explorbot","repoPath":"testomatio/explorbot","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.311Z","topics":[],"category":"community","skillMd":{"name":"xpath-testing","description":"Interactive XPath testing against HTML files in test-data/. Find elements by iteratively querying XPath expressions.","bodyPreview":"# XPath Testing Skill\n\nTest XPath expressions against HTML files in `test-data/` to find specific elements. You play a \"game\" — given a user''s request, iteratively query XPath until you find the right element and a unique XPath for it.\n\n## Rules\n\n- **NEVER read HTML files directly** — only use the CLI tool to query them\n- You may list files in `test-data/` to see what''s available\n- Work iteratively: start broad, then narrow down\n\n## Workflow\n\n### 1. Identify Target\n\nAsk the user:\n- Which HTML fi","body":"# XPath Testing Skill\n\nTest XPath expressions against HTML files in `test-data/` to find specific elements. You play a \"game\" — given a user''s request, iteratively query XPath until you find the right element and a unique XPath for it.\n\n## Rules\n\n- **NEVER read HTML files directly** — only use the CLI tool to query them\n- You may list files in `test-data/` to see what''s available\n- Work iteratively: start broad, then narrow down\n\n## Workflow\n\n### 1. Identify Target\n\nAsk the user:\n- Which HTML file in `test-data/`? (list files if needed)\n- What element are they looking for?\n\n### 2. Explore with Broad Queries\n\nStart with broad XPath patterns to understand the page:\n\n```bash\nbun .claude/skills/xpath-testing/xpath-query.ts test-data/<file> \"//button\"\nbun .claude/skills/xpath-testing/xpath-query.ts test-data/<file> \"//a[@href]\"\nbun .claude/skills/xpath-testing/xpath-query.ts test-data/<file> \"//*[@role]\"\n```\n\n### 3. Narrow Down\n\nUse the tool output to refine your XPath until you find the target element. Run as many queries as needed.\n\n### 4. Present Result\n\nOnce you find the element, present:\n\n1. **Brief explanation** of what the element is\n2. **Element outer HTML** from the tool output\n3. **Unique XPath** that matches exactly 1 element\n\n### 5. Verify Uniqueness\n\n**MANDATORY**: Run the tool one final time with your unique XPath to confirm it returns exactly 1 result. If it returns more than 1, refine further.\n\n## CLI Tool Reference\n\n```bash\nbun .claude/skills/xpath-testing/xpath-query.ts <html-file> <xpath-expression>\n```\n\nExit codes:\n- `0` — elements found\n- `1` — no matches\n- `2` — invalid XPath or error\n\n## XPath Cheat Sheet\n\n### Basic Element Selectors\n```\n//button                          All buttons\n//a[@href]                        All links with href\n//input                           All inputs\n//select                          All select dropdowns\n//form                            All forms\n```\n\n### ARIA and Accessibility\n```\n//*[@role=''button'']               Elements with button role\n//*[@role=''link'']                 Elements with link role\n//*[@role=''navigation'']           Navigation landmarks\n//*[@aria-label]                  Elements with aria-label\n//*[@aria-label=''Close'']          Specific aria-label\n//*[@aria-expanded=''true'']        Expanded elements\n```\n\n### Attribute Matching\n```\n//input[@type=''email'']            Email inputs\n//input[@name=''username'']         Input by name\n//*[@id=''main-content'']           Element by ID\n//*[contains(@class, ''btn'')]      Class contains \"btn\"\n//*[starts-with(@id, ''user-'')]    ID starts with \"user-\"\n```\n\n### Text Content\n```\n//*[text()=''Submit'']              Exact text match\n//*[contains(text(), ''Save'')]     Text contains \"Save\"\n//button[contains(., ''Delete'')]   Button containing \"Delete\" (includes descendants)\n//a[normalize-space()=''Login'']    Link with normalized text \"Login\"\n```\n\n### Structural / Combined\n```\n//form//input[@type=''email'']      Email input inside a form\n//nav//a[@href]                   Links inside nav\n//table//tr                       Table rows\n//*[@role=''dialog'']//button       Buttons inside dialogs\n//ul/li                           Direct child list items\n//div[@class=''modal'']//input      Inputs inside modal div\n```\n\n### Positional\n```\n(//button)[1]                     First button\n(//button)[last()]                Last button\n//ul/li[position()<=3]            First 3 list items\n//table//tr[2]/td[3]              Cell at row 2, col 3\n```\n\n### Logical Operators\n```\n//input[@type=''text'' or @type=''email'']    Text or email inputs\n//button[not(@disabled)]                   Non-disabled buttons\n//*[@role=''button'' and @aria-label]        Buttons with aria-label\n```\n"},"lastSynced":"2026-03-08T02:02:32.855Z","agentAnalysis":{"suitability":{"en":"Ideal for Web Scraping Agents needing precise HTML element extraction via XPath expressions.","zh":"适合于需要通过XPath表达式精确提取HTML元素的Web Scraping Agents。","ja":"XPath式を使用してHTML要素を正確に抽出する必要があるWeb Scrapingエージェントに最適です。","ko":"XPath 표현식을 사용하여 HTML 요소를精确하게 추출해야 하는 Web Scraping 에이전트에 적합합니다.","es":"Ideal para Agentes de Scraping Web que necesitan una extracción precisa de elementos HTML mediante expresiones XPath.","fr":"Idéal pour les agents de scraping Web nécessitant une extraction précise d''éléments HTML via des expressions XPath.","de":"Ideal für Web-Scraping-Agents, die eine präzise Extraktion von HTML-Elementen über XPath-Ausdrücke benötigen.","pt":"Ideal para Agentes de Web Scraping que necessitam de extração precisa de elementos HTML via expressões XPath.","ru":"Идеально для агентов веб-скрапинга, которым требуется точная извлечение элементов HTML с помощью XPath-выражений.","ar":"مثالي للوكلاء لاستخلاص الويب الذين يحتاجون إلى استخراج عناصر HTML دقيق عبر تعابير XPath."},"recommendation":{"en":"Empowers agents to iteratively test XPath expressions against HTML files using a CLI tool, providing a unique XPath for specific elements without directly reading HTML files, and leveraging iterative querying for precise element identification.","zh":"赋予代理迭代测试XPath表达式与HTML文件的能力，使用CLI工具提供特定元素的唯一XPath表达式，而无需直接读取HTML文件，并利用迭代查询实现精确的元素识别。","ja":"エージェントに、CLIツールを使用してXPath式をHTMLファイルに対して繰り返しテストする機能を提供し、HTMLファイルを直接読み込まずに、特定の要素に対して一意のXPath式を提供し、繰り返しクエリを使用して要素を正確に識別します。","ko":"에이전트에게 CLI 도구를 사용하여 XPath 표현식을 HTML 파일에 대해 반복적으로 테스트하는 기능을 제공하여 HTML 파일을 직접 읽지 않고 특정 요소에 대한 고유한 XPath 표현식을 제공하며, 반복 쿼리를 사용하여 요소를 정확하게 식별합니다.","es":"Habilita a los agentes a probar iterativamente expresiones XPath contra archivos HTML utilizando una herramienta CLI, proporcionando un XPath único para elementos específicos sin leer directamente los archivos HTML, y aprovechando la consulta iterativa para la identificación precisa de elementos.","fr":"Permet aux agents de tester de manière itérative des expressions XPath contre des fichiers HTML à l''aide d''un outil CLI, en fournissant un XPath unique pour des éléments spécifiques sans lire directement les fichiers HTML, et en exploitant l''interrogation itérative pour une identification précise d''éléments.","de":"Ermächtigt die Agents, XPath-Ausdrücke iterativ gegen HTML-Dateien mithilfe eines CLI-Tools zu testen, wodurch ein eindeutiger XPath für bestimmte Elemente bereitgestellt wird, ohne die HTML-Dateien direkt zu lesen, und die iterative Abfrage für die präzise Identifizierung von Elementen nutzt.","pt":"Habilita os agentes a testar iterativamente expressões XPath contra arquivos HTML usando uma ferramenta CLI, fornecendo um XPath único para elementos específicos sem ler diretamente os arquivos HTML, e aproveitando a consulta iterativa para identificação precisa de elementos.","ru":"Наделяет агентов возможностью итеративно тестировать XPath-выражения против HTML-файлов с помощью инструмента CLI, предоставляя уникальный XPath для конкретных элементов без прямого чтения HTML-файлов, и использует итеративные запросы для точной идентификации элементов.","ar":"يمنح الوكلاء القدرة على اختبار التعبيرات XPath بشكل متكرر ضد ملفات HTML باستخدام أداة CLI ، وتوفير XPath فريد للعناصر المحددة دون قراءة ملفات HTML مباشرة ، واستخدام الاستفسار المتكرر لتحديد العناصر بدقة."},"useCases":{"en":["Testing XPath expressions against multiple HTML files","Iteratively narrowing down broad XPath queries to unique expressions","Identifying specific elements within HTML files using CLI tools"],"zh":["对多个HTML文件测试XPath表达式","迭代地缩小广泛的XPath查询以获得唯一的表达式","使用CLI工具在HTML文件中识别特定元素"],"ja":["複数のHTMLファイルに対してXPath式をテストする","広範なXPathクエリを繰り返し縮小して一意の式を取得する","CLIツールを使用してHTMLファイル内の特定の要素を識別する"],"ko":["여러 개의 HTML 파일에 대해 XPath 표현식을 테스트하는 것","넓은 XPath 쿼리를 반복적으로 좁혀서 고유한 표현식을 얻는 것","CLI 도구를 사용하여 HTML 파일 내의 특정 요소를 식별하는 것"],"es":["Pruebas de expresiones XPath contra varios archivos HTML","Reducir iterativamente consultas XPath amplias a expresiones únicas","Identificación de elementos específicos dentro de archivos HTML utilizando herramientas CLI"],"fr":["Test des expressions XPath contre plusieurs fichiers HTML","Réduction itérative de requêtes XPath larges à des expressions uniques","Identification d''éléments spécifiques à l''intérieur de fichiers HTML à l''aide d''outils CLI"],"de":["Testen von XPath-Ausdrücken gegen mehrere HTML-Dateien","Iteratives Verfeinern von breiten XPath-Abfragen zu eindeutigen Ausdrücken","Identifizierung von bestimmten Elementen innerhalb von HTML-Dateien unter Verwendung von CLI-Tools"],"pt":["Testar expressões XPath contra vários arquivos HTML","Reduzir gradualmente consultas XPath amplas para expressões únicas","Identificar elementos específicos dentro de arquivos HTML usando ferramentas CLI"],"ru":["Тестировать XPath-выражения против нескольких HTML-файлов","Постепенно сужать широкие XPath-запросы до уникальных выражений","Определить конкретные элементы внутри HTML-файлов с помощью инструме