INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('testomatio/explorbot/xpath-testing', 'xpath-testing', 'testomatio', 'explorbot', 'community', 'xpath-testing testomatio explorbot community The xpath-testing skill enables AI agents to test XPath expressions against HTML files in a test-data directory, helping developers find specific elements. This skill is designed for iterative testing, starting broad and narrowing down to unique XPath expressions. XPath 测试技能是用于测试 HTML 文件的 AI 工具，通过 XPath 表达式找到特定元素。 XPath テストスキルは、HTML ファイルをテストする AI ツールで、XPath 式を使用して特定の要素を見つけます。 XPath 테스트 스킬은 HTML 파일을 테스트하는 AI 도구로 XPath 표현식을 사용하여 특정 요소를 찾습니다. xpath-testing es una herramienta de prueba de navegador que utiliza expresiones XPath para encontrar elementos en archivos HTML xpath-testing est un outil de test de navigateur qui utilise des expressions XPath pour trouver des éléments dans des fichiers HTML xpath-testing ist ein Browser-Test-Tool, das XPath-Ausdrücke verwendet, um Elemente in HTML-Dateien zu finden O XPath Testing é uma habilidade de teste de navegador que permite testar expressões XPath em arquivos HTML ИИ Агенты для XPath Testing позволяют тестировать XPath выражения в HTML файлах اختبار XPath هو مهارة لاختبار المتصفحات التي تسمح باختبار التعبيرات XPath في ملفات HTML how to use xpath-testing xpath-testing setup guide xpath-testing alternative xpath-testing vs selenium xpath-testing install what is xpath-testing xpath-testing tutorial xpath-testing for AI agents xpath-testing best practices xpath-testing for HTML testing XPath 测试 AI 测试工具 HTML 文件测试 CLI 工具 XPath 表达式 测试工作流程 Tests XPath expressions against HTML files in the test-data directory Iteratively queries XPath expressions to find specific elements Starts with broad queries and narrows down to unique XPath expressions Uses a CLI tool to query HTML files, without reading them directly Allows listing of files in the test-data directory to see available options Works in a game-like scenario, where the AI agent iteratively refines its queries xpath-testing is a skill that allows AI agents to iteratively test XPath expressions against HTML files to find specific elements, following a set of rules to ensure efficient testing.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Hopin-inc/civicship-api/performance-diff', 'community', 'Hopin-inc', 'civicship-api', 'Hopin-inc/civicship-api', 'performance-diff', 0, 0, 39, '2026-03-08T01:57:15.311Z', '2026-03-08T02:02:33.471Z', '6130f30f95c69ce4862c5f4fcd70297e440e1fdb7b9942a1c140038eb95a04ac', '{"id":"Hopin-inc/civicship-api/performance-diff","name":"performance-diff","description":{"en":"The performance-diff skill compares code performance before and after changes, helping developers detect regressions. It analyzes benchmark results, query counts, and response times.","zh":"performance-diff是一种代码性能比较工具，用于比较代码变化前后的性能，检测性能劣化","ja":"performance-diffはコードのパフォーマンスを比較するツールで、コード変更前後のパフォーマンスを比較し、リグレッションを検出します","ko":"performance-diff는 코드 성능 비교 도구로, 코드 변경 전후의 성능을 비교하여 성능 저하를 탐지합니다","es":"Performance-diff es una herramienta de comparación de rendimiento que analiza el rendimiento de tu código antes y después de los cambios","fr":"Performance-diff est un outil de comparaison de performances qui analyse les performances de votre code avant et après les modifications","de":"Performance-diff ist ein Leistungsvergleichstool, das die Leistung Ihres Codes vor und nach Änderungen analysiert","pt":"O performance-diff é uma ferramenta para comparar o desempenho antes e depois de alterações no código, detectando regressões e melhorias","ru":"Performance-diff - это инструмент для сравнения производительности перед и после изменений в коде, обнаружения регрессий и улучшений","ar":"أداة performance-diff هي أداة لمقارنة الأداء قبل وبعد التعديلات على الكود، وتحديد الرجрессيات والتحسينات"},"seo":{"title":{"en":"performance-diff: Performance Comparison Setup Guide | AI...","zh":"性能比较工具performance-diff安装指南","ja":"パフォーマンス比較ツールperformance-diffの設定方法","ko":"성능 비교 도구 performance-diff 설정 가이드","es":"Guía de configuración de performance-diff para optimizar ...","fr":"Guide de configuration de performance-diff pour l''optimis...","de":"Leitfaden für die Einrichtung von performance-diff zur Le...","pt":"Guia de Configuração do performance-diff para Otimização ...","ru":"ИИ Агенты: Настройка performance-diff для сравнения произ...","ar":"إعداد أداة performance-diff لتحسين الأداء"},"description":{"en":"Discover how to use performance-diff to compare code changes and detect regressions. Learn to analyze benchmark results, query counts, and response times wit...","zh":"了解performance-diff的使用方法和功能，实现代码性能比较和优化","ja":"performance-diffを使用してコードのパフォーマンスを比較し、最適化しましょう","ko":"performance-diff를 사용하여 코드 성능 비교와 최적화를 thực hiện하세요","es":"Aprende a utilizar performance-diff para comparar el rendimiento de tu código y detectar regresiones con nuestra guía paso a paso","fr":"Découvrez comment utiliser performance-diff pour comparer les performances de votre code et détecter les régressions avec notre guide étape par étape","de":"Erfahren Sie, wie Sie performance-diff verwenden, um die Leistung Ihres Codes zu vergleichen und Leistungsverschlechterungen zu erkennen, mit unserem Schritt...","pt":"Aprenda a configurar o performance-diff para comparar o desempenho antes e depois de alterações no código e detectar regressões","ru":"Узнайте, как настроить performance-diff для сравнения производительности перед и после изменений в коде и обнаружения регрессий","ar":"تعرف على كيفية تعيين أداة performance-diff لمقارنة الأداء قبل وبعد التعديلات على الكود وكشف الرجрессيات"},"definition":{"en":"performance-diff is a skill that compares the performance of code changes, providing insights into benchmark results, query counts, and response times to detect regressions.","zh":"performance-diff是一种代码性能比较工具","ja":"performance-diffはコードのパフォーマンスを比較するツールです","ko":"performance-diff는 코드 성능 비교 도구입니다","es":"Performance-diff es una herramienta de análisis de rendimiento que compara el rendimiento de diferentes versiones de código","fr":"Performance-diff est un outil d''analyse de performances qui compare les performances de différentes versions de code","de":"Performance-diff ist ein Leistungsanalyse-Tool, das die Leistung unterschiedlicher Codeversionen vergleicht","pt":"O que é performance-diff? É uma ferramenta para comparar o desempenho de diferentes versões de código","ru":"Что такое performance-diff? Это инструмент для сравнения производительности разных версий кода","ar":"ما هي أداة performance-diff؟ هي أداة لمقارنة الأداء لإصدارات مختلفة من الكود"},"features":{"en":["Compares code performance using Git diff and gh pr diff commands","Analyzes benchmark results, query counts, and response times","Supports automatic PR performance comparison with --pr option","Allows branch comparison using --before and --after options","Enables domain-specific comparison with wallet and other domains"],"zh":["支持PR和分支间的性能比较","可以分析Benchmark结果、查询数量和响应时间","支持特定域名的性能比较","使用Git diff获取代码变化","支持CLI命令行操作"],"ja":["PRとブランチ間のパフォーマンス比較をサポート","ベンチマーク結果、クエリ数、レスポンスタイムを分析","特定ドメインのパフォーマンス比較をサポート","Git diffを使用してコード変更を取得","CLIコマンドライン操作をサポート"],"ko":["PR와 브랜치 간의 성능 비교 지원","벤치마크 결과, 쿼리 수, 응답 시간 분석","특정 도메인의 성능 비교 지원","Git diff를 사용하여 코드 변경 사항을 가져옵니다","CLI 명령행操作 지원"],"es":["Comparación de rendimiento de código antes y después de los cambios","Análisis de resultados de benchmark","Detección de regresiones en el rendimiento","Soporte para comparación de ramas y pull requests","Uso de Git para obtener diferencias de código"],"fr":["Comparaison des performances de code avant et après les modifications","Analyse des résultats de benchmark","Détection de régressions des performances","Prise en charge de la comparaison de branches et de pull requests","Utilisation de Git pour obtenir les différences de code"],"de":["Vergleich der Leistung von Code vor und nach Änderungen","Analyse von Benchmark-Ergebnissen","Erkennung von Leistungsverschlechterungen","Unterstützung für den Vergleich von Branches und Pull-Requests","Verwendung von Git zum Abrufen von Code-Unterschieden"],"pt":["Comparação de desempenho antes e depois de alterações no código","Detecção de regressões e melhorias","Análise de resultados de benchmark","Suporte a comparação entre branches e PRs","Uso de comandos CLI para execução"],"ru":["Сравнение производительности перед и после изменений в коде","Обнаружение регрессий и улучшений","Анализ результатов бенчмарка","Поддержка сравнения между ветками и PR","Использование команд CLI для выполнения"],"ar":["مقارنة الأداء قبل وبعد التعديلات على الكود","تحديد الرجрессيات والتحسينات","تحليل نتائج اختبار البenchmark","دعم لمقارنة بين الفروع والطلبات السابقة","استخدام أوامر CLI للتشغيل"]},"keywords":{"en":["how to use performance-diff","performance-diff setup guide","performance comparison tools","code regression detection","benchmark result analysis","performance-diff alternative","performance-diff vs other tools","install performance-diff","performance-diff tutorial"],"zh":["代码性能比较","performance-diff","AIエージェント","代码优化","性能检测","Git diff","CLI命令行"],"ja":["コードのパフォーマンス比較","performance-diff","AIエージェント","コード最適化","パフォーマンス検出","Git diff","CLIコマンドライン"],"ko":["코드 성능 비교","performance-diff","AI 에이전트","코드 최적화","성능 탐지","Git diff","CLI 명령행"],"es":["performance-diff","herramientas de análisis de rendimiento","optimización de código","detección de regresiones","comparación de rendimiento","benchmark","Git","desarrollo de software"],"fr":["performance-diff","outils d''analyse de performances","optimisation de code","détection de régressions","comparaison de performances","benchmark","Git","développement de logiciels"],"de":["performance-diff","Leistungsanalyse-Tools","Code-Optimierung","Erkennung von Leistungsverschlechterungen","Leistungsvergleich","Benchmark","Git","Software-Entwicklung"],"pt":["performance-diff","otimização de desempenho","comparação de desempenho","detecção de regressões","benchmark","CLI","desenvolvimento de software","ferramentas de desenvolvimento"],"ru":["performance-diff","Оптимизация производительности","Сравнение производительности","Обнаружение регрессий","Бенчмарк","CLI","Разработка программного обеспечения","ИИ Агенты"],"ar":["performance-diff","تحسين الأداء","مقارنة الأداء","كشف الرجрессيات","اختبار البenchmark","CLI","تطوير البرمجيات","أدوات التطوير","العملاء الذكية"]}},"owner":"Hopin-inc","repo":"civicship-api","repoPath":"Hopin-inc/civicship-api","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.311Z","topics":[],"category":"community","skillMd":{"name":"performance-diff","description":"変更前後のパフォーマンスを比較し、リグレッションを検出","bodyPreview":"# civicship-api パフォーマンス比較\n\nコード変更前後の**パフォーマンスを比較**し、リグレッション（性能劣化）を検出します。ベンチマーク結果、クエリ数、レスポンスタイムを分析します。\n\n## 使用方法\n\n```bash\n# PRのパフォーマンス比較（自動）\n/performance-diff --pr 123\n\n# ブランチ間の比較\n/performance-diff --before main --after feature/point-expiration\n\n# 特定ドメインの比較\n/performance-diff wallet --before HEAD~1 --after HEAD\n```\n\n**引数:**\n- `$ARGUMENTS`: ドメイン名、PRでは番号、または `--before`/`--after` オプション\n\n---\n\n## パフォーマンス比較プロセス\n\n### ステップ1: 変更内容の取得\n\nGitでのDiffを取得:\n\n```bash\n# PRの差分取得\ngh pr diff 123\n\n# ブランチ間の差分\ngit diff main.","body":"# civicship-api パフォーマンス比較\n\nコード変更前後の**パフォーマンスを比較**し、リグレッション（性能劣化）を検出します。ベンチマーク結果、クエリ数、レスポンスタイムを分析します。\n\n## 使用方法\n\n```bash\n# PRのパフォーマンス比較（自動）\n/performance-diff --pr 123\n\n# ブランチ間の比較\n/performance-diff --before main --after feature/point-expiration\n\n# 特定ドメインの比較\n/performance-diff wallet --before HEAD~1 --after HEAD\n```\n\n**引数:**\n- `$ARGUMENTS`: ドメイン名、PRでは番号、または `--before`/`--after` オプション\n\n---\n\n## パフォーマンス比較プロセス\n\n### ステップ1: 変更内容の取得\n\nGitでのDiffを取得:\n\n```bash\n# PRの差分取得\ngh pr diff 123\n\n# ブランチ間の差分\ngit diff main..feature/point-expiration\n\n# 変更されたファイルのみ\ngit diff --name-only main..feature/point-expiration\n```\n\n**変更サマリー:**\n\n```markdown\n## 変更概要\n\n### 変更されたファイル（10ファイル）\n\n**Application Layer:**\n- `src/application/domain/account/wallet/service.ts` (+50, -10)\n- `src/application/domain/account/wallet/usecase.ts` (+20, -5)\n- `src/application/domain/account/wallet/data/repository.ts` (+30, -8)\n\n**Infrastructure Layer:**\n- `prisma/schema.prisma` (+5, -0)\n\n**Presentation Layer:**\n- `src/application/domain/account/wallet/schema/type.graphql` (+10, -0)\n\n---\n\n### 変更の種類\n\n- [ ] データベーススキーマ変更（カラム追加）\n- [ ] 新しいクエリ追加\n- [ ] ビジネスロジック変更\n- [ ] GraphQL API拡張\n```\n\n---\n\n### ステップ2: パフォーマンステストの実行\n\n変更前後でベンチマークを実行:\n\n```bash\n# 変更前（main）のパフォーマンステスト\ngit checkout main\npnpm test:performance > performance-before.txt\n\n# 変更後（feature branch）のパフォーマンステスト\ngit checkout feature/point-expiration\npnpm test:performance > performance-after.txt\n\n# 差分比較\ndiff performance-before.txt performance-after.txt\n```\n\n**パフォーマンステスト結果:**\n\n```markdown\n## パフォーマンステスト結果\n\n### Test: GraphQL Query `wallet(id: \"...\")`\n\n#### 変更前（main）\n\\`\\`\\`\nRequests: 1000\nSuccess: 1000 (100%)\nDuration: 5.2s\nAvg: 5.2ms\nP50: 4.8ms\nP95: 8.5ms\nP99: 12.3ms\n\\`\\`\\`\n\n#### 変更後（feature/point-expiration）\n\\`\\`\\`\nRequests: 1000\nSuccess: 1000 (100%)\nDuration: 5.5s\nAvg: 5.5ms (+5.8%)\nP50: 5.0ms (+4.2%)\nP95: 9.0ms (+5.9%)\nP99: 13.1ms (+6.5%)\n\\`\\`\\`\n\n**評価:** 🟡 軽微な劣化（+5.8%）\n**原因:** 有効期限チェックの追加（日付比較）\n**許容範囲:** ✅ Yes（+10%以内）\n\n---\n\n### Test: GraphQL Mutation `walletCreate`\n\n#### 変更前\n\\`\\`\\`\nRequests: 100\nDuration: 2.1s\nAvg: 21ms\n\\`\\`\\`\n\n#### 変更後\n\\`\\`\\`\nRequests: 100\nDuration: 2.3s\nAvg: 23ms (+9.5%)\n\\`\\`\\`\n\n**評価:** 🟡 軽微な劣化（+9.5%）\n**原因:** expiresAt カラムの書き込み追加\n**許容範囲:** ✅ Yes（+10%以内）\n\n---\n\n### Test: Batch Process `expirePoints`\n\n#### 変更前\n\\`\\`\\`\n該当なし（新規処理）\n\\`\\`\\`\n\n#### 変更後\n\\`\\`\\`\nWallets Processed: 1000\nDuration: 8.5s\nAvg per wallet: 8.5ms\n\\`\\`\\`\n\n**評価:** 🟢 新規処理（ベースラインとして記録）\n```\n\n---\n\n### ステップ3: クエリ数の比較\n\nSQLクエリ数の変化を分析:\n\n```markdown\n## クエリ数の比較\n\n### GraphQL Query `wallet(id: \"...\")`\n\n#### 変更前\n\\`\\`\\`\nSELECT * FROM t_wallets WHERE id = ''...''  -- 1クエリ\n\\`\\`\\`\n\n**Total:** 1クエリ\n\n---\n\n#### 変更後\n\\`\\`\\`\nSELECT * FROM t_wallets WHERE id = ''...''  -- 1クエリ\n\\`\\`\\`\n\n**Total:** 1クエリ（変更なし）\n\n**評価:** ✅ クエリ数増加なし\n\n---\n\n### GraphQL Mutation `pointTransfer`\n\n#### 変更前\n\\`\\`\\`\n1. SELECT * FROM t_wallets WHERE userId = ''from-user''\n2. SELECT * FROM t_wallets WHERE userId = ''to-user''\n3. UPDATE t_wallets SET balance = ... WHERE id = ''from-wallet''\n4. UPDATE t_wallets SET balance = ... WHERE id = ''to-wallet''\n5. INSERT INTO t_point_transactions ...\n\\`\\`\\`\n\n**Total:** 5クエリ\n\n---\n\n#### 変更後\n\\`\\`\\`\n1. SELECT * FROM t_wallets WHERE userId = ''from-user''\n2. SELECT * FROM t_wallets WHERE userId = ''to-user''\n   （有効期限チェック追加: メモリ内で実行、クエリ不要）\n3. UPDATE t_wallets SET balance = ... WHERE id = ''from-wallet''\n4. UPDATE t_wallets SET balance = ... WHERE id = ''to-wallet''\n5. INSERT INTO t_point_transactions ...\n\\`\\`\\`\n\n**Total:** 5クエリ（変更なし）\n\n**評価:** ✅ クエリ数増加なし\n```\n\n---\n\n### ステップ4: N+1問題の検出\n\n新たにN+1問題が導入されていないか確認:\n\n```markdown\n## N+1問題の検出\n\n### 検証: User.wallets\n\n**変更内容:**\n\\`\\`\\`diff\nUser: {\n  wallet: (parent, _, ctx) => {\n-   return prisma.t_wallets.findUnique({ where: { userId: parent.id } });\n+   return ctx.loaders.wallet.load(parent.id);\n  }\n}\n\\`\\`\\`\n\n**評価:**\n- 変更前: N+1問題あり\n- 変更後: DataLoader使用、N+1問題解消 ✅\n\n**パフォーマンス改善:**\n- 100ユーザー取得時のクエリ数: 100回 → 1回\n- レスポンスタイム: 5秒 → 50ms（100倍改善）\n\n**評価:** 🟢 大幅改善\n```\n\n---\n\n### ステップ5: データベースインデックスの影響\n\nインデックス追加によるパフォーマンス改善を確認:\n\n```markdown\n## インデックスの影響\n\n### 追加されたインデックス\n\n\\`\\`\\`prisma\nmodel t_wallets {\n  // ...\n+ @@index([expiresAt])\n}\n\\`\\`\\`\n\n---\n\n### クエリパフォーマンス比較\n\n#### Query: `SELECT * FROM t_wallets WHERE expiresAt < NOW()`\n\n**変更前（インデックスなし）:**\n\\`\\`\\`\nSeq Scan on t_wallets  (cost=0.00..25.50 rows=10 width=100)\nExecution Time: 45.2 ms\n\\`\\`\\`\n\n**変更後（インデックスあり）:**\n\\`\\`\\`\nIndex Scan using idx_wallets_expires_at on t_wallets  (cost=0.15..8.17 rows=10 width=100)\nExecution Time: 2.1 ms\n\\`\\`\\`\n\n**評価:** 🟢 大幅改善（21倍高速化）\n```\n\n---\n\n### ステップ6: メモリ使用量の比較\n\nメモリフットプリントの変化:\n\n```markdown\n## メモリ使用量\n\n### ヒープメモリ\n\n**変更前:**\n- Used Heap: 120 MB\n- Heap Limit: 512 MB\n- Usage: 23%\n\n**変更後:**\n- Used Heap: 125 MB (+4.2%)\n- Heap Limit: 512 MB\n- Usage: 24%\n\n**評価:** 🟢 許容範囲内（+5%以下）\n\n---\n\n### オブジェクト数\n\n**変更前:**\n- Total Objects: 150,000\n\n**変更後:**\n- Total Objects: 152,000 (+1.3%)\n\n**評価:** 🟢 微増（問題なし）\n```\n\n---\n\n### ステップ7: リグレッション判定\n\n総合的なパフォーマンス評価:\n\n```markdown\n## リグレッション判定\n\n### 判定基準\n\n| メトリクス | 閾値 | 変更前 | 変更後 | 差分 | 判定 |\n|-----------|------|--------|--------|------|------|\n| Avg Response Time | +10% | 5.2ms | 5.5ms | +5.8% | ✅ Pass |\n| P95 Response Time | +15% | 8.5ms | 9.0ms | +5.9% | ✅ Pass |\n| P99 Response Time | +20% | 12.3ms | 13.1ms | +6.5% | ✅ Pass |\n| Query Count | +0 | 5 | 5 | 0 | ✅ Pass |\n| Memory Usage | +10% | 120MB | 125MB | +4.2% | ✅ Pass |\n| Error Rate | +0% | 0% | 0% | 0% | ✅ Pass |\n\n---\n\n### 総合評価\n\n**スコア:** 95 / 100 🟢 Excellent\n\n**判定:** ✅ **パフォーマンスリグレッションなし**\n\n**コメント:**\n- 軽微な劣化はあるが、全て許容範囲内\n- 有効期限チェックの追加によるオーバーヘッドは予想通り\n- インデックス追加により一部クエリは大幅改善\n- N+1問題の解消により全体的なパフォーマンス向上\n\n**推奨アクション:**\n- マージ可能\n- 本番環境での監視継続\n```\n\n---\n\n### ステップ8: パフォーマンス改善の提案\n\nさらなる最適化の提案:\n\n```markdown\n## パフォーマンス改善提案\n\n### 提案1: キャッシュ導入\n\n**現状:**\n- 有効期限チェックを毎回実行\n\n**提案:**\n\\`\\`\\`typescript\n// Redis キャッシュ（TTL: 60秒）\nconst cacheKey = \\`wallet:expiration:\\${walletId}\\`;\nconst cached = await redis.get(cacheKey);\nif (cached) return JSON.parse(cached);\n\nconst wallet = await this.repo.findById(ctx, walletId, tx);\nawait redis.setex(cacheKey, 60, JSON.stringify(wallet));\nreturn wallet;\n\\`\\`\\`\n\n**効果:**\n- レスポンスタイム: 5.5ms → 0.5ms（11倍改善）\n- データベース負荷: 90%削減\n\n---\n\n### 提案2: SELECT句の最適化\n\n**現状:**\n\\`\\`\\`typescript\nreturn tx.t_wallets.findUnique({ where: { id } });\n\\`\\`\\`\n\n**提案:**\n\\`\\`\\`typescript\nreturn tx.t_wallets.findUnique({\n  where: { id },\n  select: {\n    id: true,\n    balance: true,\n    expiresAt: true,\n    // 必要なフィールドのみ\n  }\n});\n\\`\\`\\`\n\n**効果:**\n- データ転送量: 80%削減\n- メモリ使用量: 削減\n```\n\n---\n\n### ステップ9: 比較レポート生成\n\n```markdown\n# パフォーマンス比較レポート\n\n**PR:** #123\n**ブランチ:** feature/point-expiration\n**比較:** main vs feature/point-expiration\n**実施日:** 2026-01-15\n\n---\n\n## エグゼクティブサマリー\n\n### 総合評価\n\n**判定:** ✅ **マージ可能**\n\n**スコア:** 95 / 100\n\n**リグレッション:** なし（軽微な劣化は許容範囲内）\n\n---\n\n## 詳細比較\n\n### レスポンスタイム\n\n| エンドポイント | 変更前 | 変更後 | 差分 | 判定 |\n|---------------|--------|--------|------|------|\n| wallet(id) | 5.2ms | 5.5ms | +5.8% | ✅ |\n| walletCreate | 21ms | 23ms | +9.5% | ✅ |\n| pointTransfer | 45ms | 46ms | +2.2% | ✅ |\n\n---\n\n### クエリ数\n\n| エンドポイント | 変更前 | 変更後 | 差分 | 判定 |\n|---------------|--------|--------|------|------|\n| wallet(id) | 1 | 1 | 0 | ✅ |\n| pointTransfer | 5 | 5 | 0 | ✅ |\n\n---\n\n### パフォーマンス改善\n\n- **N+1問題解消:** User.wallets（100倍改善）\n- **インデックス追加:** expiresAt クエリ（21倍改善）\n\n---\n\n## 推奨アクション\n\n### 即座に実施\n- ✅ PR をマージ可能\n- 🔔 本番環境で監視継続（24時間）\n\n### 将来的に検討\n- キャッシュ導入（さらなる最適化）\n- SELECT句の最適化\n\n---\n\n## 承認\n\n- [ ] テックリード\n- [ ] DevOpsリード\n```\n\n---\n\n## 活用例\n\n### 例1: PRのパフォーマンス比較\n\n```bash\n/performance-diff --pr 123\n```\n\n**出力:**\n- 変更前後の比較\n- リグレッション判定\n- マージ可否の判断\n\n---\n\n### 例2: リリース前の検証\n\n```bash\n/performance-diff --before v1.0.0 --after main\n```\n\n**出力:**\n- バージョン間の比較\n- パフォーマンス推移\n\n---\n\n## 参考資料\n\n- [Performance Testing Best Practices](https://k6.io/docs/testing-guides/performance-testing/)\n- [Database Query Performance](https://www.postgresql.org/docs/current/performance-tips.html)\n- [GraphQL Performance](https://www.apollographql.com/docs/apollo-server/performance/caching/)\n"},"lastSynced":"2026-03-08T02:02:33.471Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing advanced code performance comparison capabilities.","zh":"适合需要高级代码性能比较功能的开发代理。","ja":"開発エージェントが高度なコードのパフォーマンス比較機能を必要とする場合に適しています。","ko":"고급 코드 성능 비교 기능이 필요한 개발 에이전트에게 적합합니다.","es":"Perfecto para agentes de desarrollo que necesitan capacidades avanzadas de comparación de rendimiento de código.","fr":"Parfait pour les agents de développement ayant besoin de capacités de comparaison de performances de code avancées.","de":"Perfekt für Entwicklungssagenten, die erweiterte Code-Leistungsvergleichsfunktionen benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que precisam de capacidades avançadas de comparação de desempenho de código.","ru":"Идеально для агентов разработки, которым требуются продвинутые возможности сравнения производительности кода.","ar":"متوافق تماما مع وكلاء التطوير الذين يحتاجون إلى إمكانيات متقدمة لمقارنة أداء الكود."},"recommendation":{"en":"Empowers agents to detect regressions by comparing benchmark results, query counts, and response times using Git diff and command-line interfaces like gh and git.","zh":"通过比较基准测试结果、查询次数和响应时间，使用 Git diff 和命令行接口（如 gh 和 git）来检测回归，赋予代理检测回归的能力。","ja":"Git diff とコマンドラインインターフェイス（gh や git など）を使用してベンチマーク結果、クエリ数、応答時間を比較して回帰を検出する能力をエージェントに与えます。","ko":"Git diff와 명령줄 인터페이스(gh 및 git 등)를 사용하여 벤치마크 결과, 쿼리 수 및 응답 시간을 비교하여 회귀를 감지하는 능력을 에이전트에게 부여합니다.","es":"Habilita a los agentes a detectar regresiones comparando resultados de benchmark, recuentos de consultas y tiempos de respuesta utilizando Git diff y interfaces de línea de comandos como gh y git.","fr":"Permet aux agents de détecter les régressions en comparant les résultats de benchmark, les comptes de requêtes et les temps de réponse en utilisant Git diff et des interfaces de ligne de commande comme gh et git.","de":"Ermächtigt Agenten, Regressionsfeststellungen durch Vergleichen von Benchmark-Ergebnissen, Abfragezählungen und Antwortzeiten unter Verwendung von Git diff und Kommandozeilen-Schnittstellen wie gh und git vorzunehmen.","pt":"Habilita os agentes a detectar regressões comparando resultados de benchmark, contagens de consultas e tempos de resposta usando Git diff e interfaces de linha de comando como gh e git.","ru":"Наделяет агентов возможностью обнаруживать регрессии, сравнивая результаты бенчмарка, количество запросов и время ответа с помощью Git diff и командной строки, такой как gh и git.","ar":"تمكين الوكلاء من 