INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Hopin-inc/civicship-api/performance-diff', 'performance-diff', 'Hopin-inc', 'civicship-api', 'community', 'performance-diff Hopin-inc civicship-api community The performance-diff skill compares code performance before and after changes, helping developers detect regressions. It analyzes benchmark results, query counts, and response times. performance-diff是一种代码性能比较工具，用于比较代码变化前后的性能，检测性能劣化 performance-diffはコードのパフォーマンスを比較するツールで、コード変更前後のパフォーマンスを比較し、リグレッションを検出します performance-diff는 코드 성능 비교 도구로, 코드 변경 전후의 성능을 비교하여 성능 저하를 탐지합니다 Performance-diff es una herramienta de comparación de rendimiento que analiza el rendimiento de tu código antes y después de los cambios Performance-diff est un outil de comparaison de performances qui analyse les performances de votre code avant et après les modifications Performance-diff ist ein Leistungsvergleichstool, das die Leistung Ihres Codes vor und nach Änderungen analysiert O performance-diff é uma ferramenta para comparar o desempenho antes e depois de alterações no código, detectando regressões e melhorias Performance-diff - это инструмент для сравнения производительности перед и после изменений в коде, обнаружения регрессий и улучшений أداة performance-diff هي أداة لمقارنة الأداء قبل وبعد التعديلات على الكود، وتحديد الرجрессيات والتحسينات how to use performance-diff performance-diff setup guide performance comparison tools code regression detection benchmark result analysis performance-diff alternative performance-diff vs other tools install performance-diff performance-diff tutorial 代码性能比较 performance-diff AIエージェント 代码优化 性能检测 Git diff CLI命令行 Compares code performance using Git diff and gh pr diff commands Analyzes benchmark results, query counts, and response times Supports automatic PR performance comparison with --pr option Allows branch comparison using --before and --after options Enables domain-specific comparison with wallet and other domains performance-diff is a skill that compares the performance of code changes, providing insights into benchmark results, query counts, and response times to detect regressions.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Wania-Kazmi/claude-code-autonomous-agent-workflow/database-patterns', 'community', 'Wania-Kazmi', 'claude-code-autonomous-agent-workflow', 'Wania-Kazmi/claude-code-autonomous-agent-workflow', 'database-patterns', 0, 0, 39, '2026-03-08T01:57:15.312Z', '2026-03-08T02:02:34.155Z', '2f3ff015718d3bb7b3d985c52a7a0dae25bbdce6fa63ea0a3822ae75258d3472', '{"id":"Wania-Kazmi/claude-code-autonomous-agent-workflow/database-patterns","name":"database-patterns","description":{"en":"The database-patterns skill generates complete projects with custom skills, agents, and security-reviewed code, benefiting developers who need robust database design principles. It applies normalization, UUIDs, and timestamps for optimal schema design.","zh":"数据库模式自动项目生成器，帮助您创建具有自定义技能、安全审查代码和高覆盖率的完整项目","ja":"データベースパターン自動プロジェクト生成ツールは、カスタムスキル、セキュリティレビュー済みコード、高カバレッジを持つ完全なプロジェクトを作成するのに役立ちます","ko":"데이터베이스 패턴 자동 프로젝트 생성기는 커스텀 스킬, 보안 검토 코드 및 높은 커버리지가 있는 완전한 프로젝트를 생성하는 데 도움이 됩니다","es":"Nuestro generador de proyectos autónomo crea proyectos personalizados con patrones de base de datos normalizados y seguros","fr":"Notre générateur de projets autonome crée des projets personnalisés avec des modèles de base de données normalisés et sécurisés","de":"Unser autonome Projektgenerator erstellt benutzerdefinierte Projekte mit normalisierten und sicheren Datenbankmustern","pt":"O skill de padrões de banco de dados fornece uma abordagem autônoma para geração de projetos, com foco em normalização, UUIDs e timestamps","ru":"Навык шаблонов базы данных предоставляет автономный подход к генерации проектов, с фокусом на нормализации, UUID и метках времени","ar":"مهارة أنماط قاعدة البيانات توفر نهجًا مستقلًا لتوليد المشاريع، مع التركيز على التنسيق والكتل الفريدة والتوقيت"},"seo":{"title":{"en":"database-patterns: Optimized Schema Design for AI Agents ...","zh":"数据库模式设置指南 - 自动项目生成器","ja":"データベースパターン設定ガイド - 自動プロジェクト生成ツール","ko":"데이터베이스 패턴 설정 가이드 - 자동 프로젝트 생성기","es":"Guía de configuración de patrones de base de datos con AI...","fr":"Guide de configuration des modèles de base de données ave...","de":"Konfigurationsleitfaden für Datenbankmuster mit KI-Tool","pt":"Guia de Configuração de Padrões de Banco de Dados para Fe...","ru":"Настройка шаблонов базы данных для ИИ Агентов","ar":"دليل إعداد أنماط قاعدة البيانات لأدوات الذكاء الاصطناعي"},"description":{"en":"Discover how database-patterns generates secure, test-driven projects with 80%+ coverage. Learn how to apply normalization, UUIDs, and timestamps for robust ...","zh":"使用数据库模式自动项目生成器，轻松创建具有自定义技能、安全审查代码和80%+覆盖率的完整项目","ja":"データベースパターン自動プロジェクト生成ツールを使用して、カスタムスキル、セキュリティレビュー済みコード、80%以上のカバレッジを持つ完全なプロジェクトを作成します","ko":"데이터베이스 패턴 자동 프로젝트 생성기를 사용하여 커스텀 스킬, 보안 검토 코드 및 80% 이상의 커버리지가 있는 완전한 프로젝트를 쉽게 생성합니다","es":"Aprende a configurar patrones de base de datos con normalización 3NF, UUID y timestamps con nuestro generador de proyectos autónomo","fr":"Découvrez comment configurer des modèles de base de données avec normalisation 3NF, UUID et timestamps avec notre générateur de projets autonome","de":"Erfahren Sie, wie Sie Datenbankmuster mit Normalisierung 3NF, UUID und Timestamps mit unserem autonomen Projektgenerator konfigurieren","pt":"Aprenda a criar projetos com padrões de banco de dados robustos e seguros, utilizando UUIDs, normalização e timestamps","ru":"Создавайте проекты с надежными и безопасными шаблонами базы данных, используя UUID, нормализацию и метки времени","ar":"تعلم كيفية إنشاء مشاريع بقواعد بيانات قوية وأمنة باستخدام UUIDs والتنسيق والتوقيت"},"definition":{"en":"database-patterns is a skill that generates autonomous projects with best practices for database design, including normalization, UUIDs, and timestamps, for secure and efficient data management.","zh":"数据库模式是指数据库的设计原则和最佳实践，包括模式设计、 normalization 和使用 UUID","ja":"データベースパターンとは、データベースの設計原則とベストプラクティスを指し、スキーマ設計、正規化、UUID の使用などを含みます","ko":"데이터베이스 패턴은 데이터베이스의 설계 원칙과 모범 사례를 말하며, 스키마 디자인, 정규화 및 UUID 사용 등을 포함합니다","es":"Un patrón de base de datos es un conjunto de reglas y principios para diseñar esquemas de base de datos","fr":"Un modèle de base de données est un ensemble de règles et de principes pour concevoir des schémas de base de données","de":"Ein Datenbankmuster ist eine Sammlung von Regeln und Prinzipien zur Gestaltung von Datenbankschemata","pt":"Padrões de banco de dados são princípios de design que visam melhorar a integridade e escalabilidade dos dados","ru":"Шаблоны базы данных - это принципы設計, направленные на улучшение целостности и масштабируемости данных","ar":"أنماط قاعدة البيانات هي مبادئ التصميم التي تهدف إلى تحسين السلامة والقابلية للتوسع للبيانات"},"features":{"en":["Applies normalization principles (3NF minimum) for efficient data storage","Utilizes UUIDs for distributed systems and auto-increment for simple cases","Includes timestamps on every table for robust data tracking","Generates projects with custom skills, agents, and security-reviewed code","Supports test-driven development (TDD) with 80%+ coverage","Enforces schema design principles for optimal database performance"],"zh":["支持 normalization（3NF 最小）","使用 UUID 而不是自增 ID","为每个表添加时间戳","提供 80% 以上的代码覆盖率","包含安全审查代码","支持自定义技能和钩子"],"ja":["正規化（3NF 最小）をサポート","UUID を使用して自動増加 ID を代替","各テーブルにタイムスタンプを追加","80% 以上のコードカバレッジを提供","セキュリティレビュー済みコードを含む","カスタムスキルとフックをサポート"],"ko":["정규화(3NF 최소)를 지원","UUID를 사용하여 자동 증분 ID를 대체","각 테이블에 타임스탬프를 추가","80% 이상의 코드 커버리지 제공","보안 검토 코드를 포함","커스텀 스킬과 훅을 지원"],"es":["Normalización 3NF para evitar grupos repetidos y dependencias parciales","Uso de UUID en lugar de autoincremento para sistemas distribuidos","Inclusión de timestamps en cada tabla para auditoría y seguimiento","Generación de proyectos personalizados con código revisado y pruebas de cobertura","Soporte para TDD y cobertura de código del 80% o más","Revisión de seguridad del código generado"],"fr":["Normalisation 3NF pour éviter les groupes répétés et les dépendances partielles","Utilisation d''UUID au lieu de l''auto-incrémentation pour les systèmes distribués","Inclusion de timestamps dans chaque table pour l''audit et le suivi","Génération de projets personnalisés avec code révisé et tests de couverture","Prise en charge de TDD et de couverture de code d''au moins 80%","Révision de sécurité du code généré"],"de":["Normalisierung 3NF, um wiederholte Gruppen und teilweise Abhängigkeiten zu vermeiden","Verwendung von UUID anstelle von Auto-Increment für verteilte Systeme","Einbeziehung von Timestamps in jede Tabelle für Auditing und Nachverfolgung","Erstellung benutzerdefinierter Projekte mit überprüftem Code und Abdeckungstests","Unterstützung für TDD und Codeabdeckung von mindestens 80%","Sicherheitsprüfung des generierten Codes"],"pt":["Normalização de dados (3NF mínimo)","Uso de UUIDs em vez de auto-increment","Inclusão de timestamps em todas as tabelas","Suporte à geração de projetos autônoma","Cobertura de testes de unidade (TDD) de 80%+","Revisão de segurança do código"],"ru":["Нормализация данных (3NF минимально)","Использование UUID вместо авто-инкремента","Включение меток времени во все таблицы","Поддержка автономной генерации проектов","Покрытие модульных тестов (TDD) 80%+","Проверка безопасности кода"],"ar":["تنسيق البيانات (3NF أدنى حد)","استخدام الكتل الفريدة بدلاً من الزيادة التلقائية","إدراج التوقيت في جميع الجداول","دعم توليد المشاريع المستقلة","تغطية اختبارات الوحدة (TDD) 80%+","مراجعة أمان الكود"]},"keywords":{"en":["database-patterns setup guide","what is database-patterns","database-patterns vs other skills","how to use database-patterns for schema design","database-patterns install for AI agents","database-patterns alternative for robust database design","database-patterns tutorial for developers","database-patterns best practices for normalization","database-patterns and UUID implementation","database-patterns for secure data management"],"zh":["数据库模式","自动项目生成","自定义技能","安全审查代码","代码覆盖率","UUID"," normalization","数据库设计"],"ja":["データベースパターン","自動プロジェクト生成","カスタムスキル","セキュリティレビュー済みコード","コードカバレッジ","UUID","正規化","データベース設計"],"ko":["데이터베이스 패턴","자동 프로젝트 생성","커스텀 스킬","보안 검토 코드","코드 커버리지","UUID","정규화","데이터베이스 설계"],"es":["patrones de base de datos","normalización 3NF","UUID","timestamps","generador de proyectos autónomo","TDD","cobertura de código","seguridad de código","diseño de esquemas de base de datos","IA Agent"],"fr":["modèles de base de données","normalisation 3NF","UUID","timestamps","générateur de projets autonome","TDD","couverture de code","sécurité de code","conception de schémas de base de données","Outil IA"],"de":["Datenbankmuster","Normalisierung 3NF","UUID","Timestamps","autonomer Projektgenerator","TDD","Codeabdeckung","Sicherheit von Code","Datenbankschemadesign","KI-Tool"],"pt":["padrões de banco de dados","normalização de dados","UUIDs","timestamps","geração de projetos autônoma","TDD","segurança do código","ferramentas de IA","desenvolvimento de software"],"ru":["шаблоны базы данных","нормализация данных","UUID","метки времени","автономная генерация проектов","TDD","проверка безопасности кода","ИИ Агенты","разработка программного обеспечения"],"ar":["أنماط قاعدة البيانات","تنسيق البيانات","الكتل الفريدة","التوقيت","توليد المشاريع المستقلة","TDD","مراجعة أمان الكود","أدوات الذكاء الاصطناعي","تطوير البرمجيات"]}},"owner":"Wania-Kazmi","repo":"claude-code-autonomous-agent-workflow","repoPath":"Wania-Kazmi/claude-code-autonomous-agent-workflow","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.312Z","topics":[],"category":"community","skillMd":{"name":"database-patterns","description":"|","bodyPreview":"# Database Patterns & Best Practices\n\n## Schema Design Principles\n\n### 1. Normalization (3NF minimum)\n- No repeating groups\n- No partial dependencies\n- No transitive dependencies\n\n### 2. Use UUIDs vs Auto-Increment\n```sql\n-- GOOD: UUID for distributed systems\nid UUID PRIMARY KEY DEFAULT gen_random_uuid()\n\n-- OK: Auto-increment for simple cases\nid SERIAL PRIMARY KEY\n```\n\n### 3. Timestamps on Every Table\n```sql\nCREATE TABLE users (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  name VARCHAR(10","body":"# Database Patterns & Best Practices\n\n## Schema Design Principles\n\n### 1. Normalization (3NF minimum)\n- No repeating groups\n- No partial dependencies\n- No transitive dependencies\n\n### 2. Use UUIDs vs Auto-Increment\n```sql\n-- GOOD: UUID for distributed systems\nid UUID PRIMARY KEY DEFAULT gen_random_uuid()\n\n-- OK: Auto-increment for simple cases\nid SERIAL PRIMARY KEY\n```\n\n### 3. Timestamps on Every Table\n```sql\nCREATE TABLE users (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  name VARCHAR(100) NOT NULL,\n  email VARCHAR(255) UNIQUE NOT NULL,\n  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),\n  updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()\n);\n```\n\n## Prisma ORM Patterns\n\n### Schema Definition\n\n```prisma\n// prisma/schema.prisma\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\nmodel User {\n  id        String   @id @default(uuid())\n  email     String   @unique\n  name      String\n  role      Role     @default(USER)\n  posts     Post[]\n  profile   Profile?\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([email])\n  @@map(\"users\")\n}\n\nmodel Post {\n  id        String   @id @default(uuid())\n  title     String\n  content   String?\n  published Boolean  @default(false)\n  author    User     @relation(fields: [authorId], references: [id])\n  authorId  String\n  tags      Tag[]\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([authorId])\n  @@index([published])\n  @@map(\"posts\")\n}\n\nenum Role {\n  USER\n  ADMIN\n}\n```\n\n### CRUD Operations\n\n```typescript\nimport { PrismaClient } from ''@prisma/client''\n\nconst prisma = new PrismaClient()\n\n// Create\nasync function createUser(data: { name: string; email: string }) {\n  return prisma.user.create({\n    data,\n    select: {\n      id: true,\n      name: true,\n      email: true,\n      createdAt: true\n    }\n  })\n}\n\n// Read with relations\nasync function getUserWithPosts(id: string) {\n  return prisma.user.findUnique({\n    where: { id },\n    include: {\n      posts: {\n        where: { published: true },\n        orderBy: { createdAt: ''desc'' },\n        take: 10\n      },\n      profile: true\n    }\n  })\n}\n\n// Update\nasync function updateUser(id: string, data: Partial<User>) {\n  return prisma.user.update({\n    where: { id },\n    data\n  })\n}\n\n// Delete (soft delete pattern)\nasync function deleteUser(id: string) {\n  return prisma.user.update({\n    where: { id },\n    data: { deletedAt: new Date() }\n  })\n}\n```\n\n### Transactions\n\n```typescript\n// Interactive transaction\nasync function transferFunds(fromId: string, toId: string, amount: number) {\n  return prisma.$transaction(async (tx) => {\n    const from = await tx.account.update({\n      where: { id: fromId },\n      data: { balance: { decrement: amount } }\n    })\n\n    if (from.balance < 0) {\n      throw new Error(''Insufficient funds'')\n    }\n\n    await tx.account.update({\n      where: { id: toId },\n      data: { balance: { increment: amount } }\n    })\n\n    return tx.transaction.create({\n      data: { fromId, toId, amount }\n    })\n  })\n}\n\n// Sequential transaction\nasync function createUserWithProfile(data: CreateUserInput) {\n  return prisma.$transaction([\n    prisma.user.create({ data: data.user }),\n    prisma.profile.create({ data: data.profile })\n  ])\n}\n```\n\n### Pagination\n\n```typescript\n// Cursor-based (recommended for large datasets)\nasync function getUsers(cursor?: string, limit = 20) {\n  const users = await prisma.user.findMany({\n    take: limit + 1,\n    cursor: cursor ? { id: cursor } : undefined,\n    orderBy: { createdAt: ''desc'' },\n    skip: cursor ? 1 : 0 // Skip the cursor itself\n  })\n\n  const hasMore = users.length > limit\n  const data = hasMore ? users.slice(0, -1) : users\n\n  return {\n    data,\n    nextCursor: hasMore ? data[data.length - 1].id : null\n  }\n}\n\n// Offset-based\nasync function getUsersWithOffset(page = 1, limit = 20) {\n  const [users, total] = await Promise.all([\n    prisma.user.findMany({\n      skip: (page - 1) * limit,\n      take: limit\n    }),\n    prisma.user.count()\n  ])\n\n  return {\n    data: users,\n    meta: { total, page, limit, totalPages: Math.ceil(total / limit) }\n  }\n}\n```\n\n## Query Optimization\n\n### Avoid N+1 Queries\n\n```typescript\n// BAD: N+1 problem\nconst users = await prisma.user.findMany()\nfor (const user of users) {\n  const posts = await prisma.post.findMany({\n    where: { authorId: user.id }\n  })\n}\n\n// GOOD: Include in single query\nconst users = await prisma.user.findMany({\n  include: { posts: true }\n})\n\n// GOOD: Select only needed fields\nconst users = await prisma.user.findMany({\n  select: {\n    id: true,\n    name: true,\n    posts: {\n      select: {\n        id: true,\n        title: true\n      }\n    }\n  }\n})\n```\n\n### Use Indexes Properly\n\n```prisma\nmodel Post {\n  id        String @id\n  authorId  String\n  status    Status\n  createdAt DateTime\n\n  // Compound index for common query patterns\n  @@index([authorId, status])\n  @@index([status, createdAt])\n}\n```\n\n```sql\n-- For frequently queried columns\nCREATE INDEX idx_posts_author_status ON posts(author_id, status);\n\n-- For text search\nCREATE INDEX idx_posts_title_gin ON posts USING gin(to_tsvector(''english'', title));\n\n-- For JSON columns\nCREATE INDEX idx_metadata_gin ON posts USING gin(metadata);\n```\n\n### Batch Operations\n\n```typescript\n// Batch create\nawait prisma.user.createMany({\n  data: users,\n  skipDuplicates: true\n})\n\n// Batch update with raw SQL (when needed)\nawait prisma.$executeRaw`\n  UPDATE posts \n  SET status = ''archived'' \n  WHERE created_at < NOW() - INTERVAL ''1 year''\n`\n\n// Batch delete\nawait prisma.user.deleteMany({\n  where: {\n    deletedAt: { not: null },\n    deletedAt: { lt: thirtyDaysAgo }\n  }\n})\n```\n\n## Migration Patterns\n\n### Prisma Migrations\n\n```bash\n# Create migration\nnpx prisma migrate dev --name add_user_role\n\n# Apply in production\nnpx prisma migrate deploy\n\n# Reset database (dev only)\nnpx prisma migrate reset\n```\n\n### Safe Schema Changes\n\n```typescript\n// Step 1: Add nullable column\nmodel User {\n  newField String?  // nullable first\n}\n\n// Step 2: Backfill data\nawait prisma.$executeRaw`\n  UPDATE users SET new_field = ''default'' WHERE new_field IS NULL\n`\n\n// Step 3: Make non-nullable\nmodel User {\n  newField String @default(\"default\")\n}\n```\n\n### Rollback Strategy\n\n```sql\n-- Always create down migrations\n-- up.sql\nALTER TABLE users ADD COLUMN phone VARCHAR(20);\n\n-- down.sql\nALTER TABLE users DROP COLUMN phone;\n```\n\n## Connection Management\n\n### Connection Pooling\n\n```typescript\n// Singleton pattern for Prisma\nconst globalForPrisma = globalThis as unknown as {\n  prisma: PrismaClient | undefined\n}\n\nexport const prisma = globalForPrisma.prisma ?? new PrismaClient({\n  log: [''error'', ''warn''],\n  datasources: {\n    db: {\n      url: process.env.DATABASE_URL\n    }\n  }\n})\n\nif (process.env.NODE_ENV !== ''production'') {\n  globalForPrisma.prisma = prisma\n}\n```\n\n### Serverless Configuration\n\n```typescript\n// For serverless (Vercel, AWS Lambda)\nimport { PrismaClient } from ''@prisma/client''\nimport { Pool } from ''@neondatabase/serverless''\nimport { PrismaNeon } from ''@prisma/adapter-neon''\n\nconst pool = new Pool({ connectionString: process.env.DATABASE_URL })\nconst adapter = new PrismaNeon(pool)\nconst prisma = new PrismaClient({ adapter })\n```\n\n## Soft Delete Pattern\n\n```prisma\nmodel User {\n  id        String    @id @default(uuid())\n  email     String    @unique\n  deletedAt DateTime?\n\n  @@index([deletedAt])\n}\n```\n\n```typescript\n// Middleware for automatic filtering\nprisma.$use(async (params, next) => {\n  if (params.model === ''User'') {\n    if (params.action === ''findMany'' || params.action === ''findFirst'') {\n      params.args.where = {\n        ...params.args.where,\n        deletedAt: null\n      }\n    }\n  }\n  return next(params)\n})\n\n// Soft delete\nasync function softDelete(id: string) {\n  return prisma.user.update({\n    where: { id },\n    data: { deletedAt: new Date() }\n  })\n}\n\n// Hard delete (permanent)\nasync function hardDelete(id: string) {\n  return prisma.user.delete({ where: { id } })\n}\n```\n\n## Audit Trail Pattern\n\n```prisma\nmodel AuditLog {\n  id         String   @id @default(uuid())\n  entityType String\n  entityId   String\n  action     String   // CREATE, UPDATE, DELETE\n  changes    Json?\n  userId     String?\n  createdAt  DateTime @default(now())\n\n  @@index([entityType, entityId])\n  @@index([userId])\n  @@index([createdAt])\n}\n```\n\n```typescript\n// Middleware for automatic audit logging\nprisma.$use(async (params, next) => {\n  const result = await next(params)\n  \n  if ([''create'', ''update'', ''delete''].includes(params.action)) {\n    await prisma.auditLog.create({\n      data: {\n        entityType: params.model!,\n        entityId: result.id,\n        action: params.action.toUpperCase(),\n        changes: params.args.data,\n        userId: getCurrentUserId()\n      }\n    })\n  }\n  \n  return result\n})\n```\n\n## Multi-Tenant Pattern\n\n```prisma\nmodel Organization {\n  id    String @id @default(uuid())\n  name  String\n  users User[]\n  posts Post[]\n}\n\nmodel User {\n  id             String       @id @default(uuid())\n  organization   Organization @relation(fields: [organizationId], references: [id])\n  organizationId String\n\n  @@index([organizationId])\n}\n```\n\n```typescript\n// Row-level security with Prisma extension\nconst prismaWithTenant = prisma.$extends({\n  query: {\n    $allModels: {\n      async $allOperations({ args, query, model }) {\n        const tenantId = getTenantId()\n        \n        if (tenantId && hasTenantField(model)) {\n          args.where = { ...args.where, organizationId: tenantId }\n        }\n        \n        return query(args)\n      }\n    }\n  }\n})\n```\n\n## Raw SQL When Needed\n\n```typescript\n// Complex aggregations\nconst stats = await prisma.$queryRaw<Stats[]>`\n  SELECT \n    DATE_TRUNC(''day'', created_at) as date,\n    COUNT(*) as count,\n    SUM(amount) as total\n  FROM transactions\n  WHERE created_at >= ${startDate}\n  GROUP BY DATE_TRUNC(''day'', created_at)\n  ORDER BY date DESC\n`\n\n// Full-text search\nconst results = await prisma.$queryRaw<Post[]>`\n  SELECT * FROM posts\n  WHERE to_tsvector(''english'', title || '' '' || content) \n    @@ plainto_tsquery(''english'', ${searchTerm})\n  ORDER BY ts_rank(\n    to_tsvector(''english'', title || '' '' || content),\n    plainto_tsquery(''english'', ${searchTerm})\n  ) DESC\n  LIMIT ${limit}\n`\n```\n\n## Checklist\n\n- [ ] UUIDs for distributed systems\n- [ ] Timestamps on all tables\n- [ ] Proper indexes for query patterns\n- [ ] N+1 queries avoided (use include/join)\n- [ ] Transactions for multi-step operations\n- [ ] Soft delete where appropriate\n- [ ] Connection pooling configured\n- [ ] Migrations tested (up and down)\n- [ ] Audit logging for sensitive data\n- [ ] Query performance monitored\n"},"lastSynced":"2026-03-08T02:02:34.155Z","agentAnalysis":{"suitability":{"en":"Perfect for Data Analysis Agents needing robust database design principles with normalization and UUID implementation.","zh":"非常适合需要强大的数据库设计原则、规范化和UUID实现的数据分析代理。","ja":"データ分析エージェントが堅牢なデータベース設計原則、正規化、UUIDの実装を必要とする場合に最適です。","ko":"데이터 분석 에이전트가 강력한 데이터베이스 설계 원칙, 정규화 및 UUID 구현을 필요로 할 때 완벽합니다.","es":"Perfecto para Agentes de Análisis de Datos que necesitan principios de diseño de base de datos robustos con normalización e implementación de UUID.","fr":"Parfait pour les Agents d''Analyse de Données nécessitant des principes de conception de base de données robustes avec normalisation et mise en œuvre d''UUID.","de":"Perfekt für Data-Analytics-Agents, die robuste Datenbankdesign-Prinzipien mit Normalisierung und UUID-Implementierung benötigen.","pt":"Perfeito para Agentes de Análise de Dados que necessitam de princípios robustos de design de banco de dados com normalização e implementação de UUID.","ru":"Идеально подходит для агентов анализа данных, требующих прочных принципов проектирования базы данных с нормализацией и реализацией UUID.","ar":"مثالي للوكلاء تحليل البيانات الذين يحتاجون إلى مبادئ تصميم قاعدة البيانات القوية مع التطبيع وتطبيق UUID."},"recommendation":{"en":"Empowers agents to design optimal database schemas using normalization techniques, UUIDs for distributed systems, and timestamps for data tracking, ensuring data consistency and integrity across various applications and protocols like SQL.","zh":"赋予代理设计最优数据库架构的能力，使用正规化技术、分布式系统中的UUID、数据跟踪的时间戳，确保数据的一致性和完整性，跨越各种应用程序和协议，如SQL。","ja":"エージェントが正規化技術、分散システムのUUID、データ追跡のタイムスタンプを使用して最適なデータベーススキーマを設計できるようにし、SQLなどのさまざまなアプリケーションやプロトコルでデータの一貫性と完全性を確保します。","ko":"에이전트가 정규화 기법, 분산 시스템의 UUID, 데이터 추적을 위한 타임스탬프를 사용하여 최적의 데이터베이스 스키마를 설계할 수 있도록 하며, SQL과 같은 다양한 애플리케이션 및 프로토콜에서 데이터 일관성 및 무결성을 보장합니다.","es":"Habilita a los agentes a diseñar esquemas de base de datos óptimos utilizando técnicas de normalización, UUID para sistemas distribuidos y marcas de tiempo para el seguimiento de datos, garantizando la consistencia y la integridad de los datos en varias aplicaciones y protocolos como SQL.","fr":"Permet aux agents de concevoir des schémas de base de données optimaux en utilisant des techniques de normalisation, des UUID pour les systèmes distribués et des horodatages pour le suivi des données, assurant ainsi la cohérence et l''intégrité des données dans diverses applications et protocoles comme SQL.","de":"Ermächtigt die Agenten, optimale Datenbankschemata unter Verwendung von Normalisierungstechniken, UUIDs für verteilte Systeme und Zeitstempel für die Datenverfolgung zu entwerfen, um die Datenkonsistenz und -integrität über verschiedene Anwendungen und Protokolle wie SQL hinweg sicherzustellen.","pt":"Habilita os agentes a projetarem esquemas de banco de dados ótimos usando técnicas de normalização, UUIDs para sistemas distribuídos e carimbos de data/hora para rastreamento de dados, garantindo a consistência e integridade dos dados em várias aplicações e protocolos como SQL.","ru":"Наделяет агентов возможностью проектировать оптимальные схемы базы данных с использованием методов нормализации, UUID для распределенных систем и временных меток для отслеживания данных, обеспечивая согласованность и целостность данных в различных приложениях и протоколах, таких как SQL.","ar":"تمكين الوكلاء من تصميم مخططات قاعدة البيانات المثالية باستخدام تقنيات التطبيع والuuid لنظم الموزعة وتواقيت لتتبع البيانات، مما يضمن συνέافة و سلامة البيانات عبر تطبيقات وبروتوكولات متعددة مثل SQL."},"useCases":{"en":["Designing normalized database schemas for large-scale applications","Implementing UUID-based primary keys for distributed systems","Automating timestamp tracking for data modification and creation"],"zh":["为大规模应用程序设计规范化的数据库架构","为分布式系统实现基于UUID的主键","自动化数据修改和创建的时间戳跟踪"],"ja":["大規模アプリケーションのための正規化されたデータベーススキーマを設計する","分散システムのためのUUIDベースの主キーを実装する","データの変更と作成のタイムスタンプ追跡を自動化する"],"ko":["대규모 애플리케이션을 위한 정규화된 데이터베이스 스키마 설계","분산 시스템을 위한 UUID 기반의 기본 키 구현","데이터 수정 및 생성의 타임스탬프 추적 자동화"],"es":["Diseñar esquemas de base de datos normalizados para aplicaciones a gran escala","Implementar claves primarias basadas en UUID para sistemas distribuidos","Automatizar el seguimiento de marcas de tiempo para la modificación y creación de datos"],"fr":["Concevoir des schémas de base de données normalisés pour des applications à grande échelle","Mettre en œuvre des clés primaires basées sur les UUID pour les systèmes distribués","Automatiser le suivi des horodatages pour la modification et la création de données"],"de":["Entwerfen normalisierter Datenbankschemata für groß angelegte Anwendungen","Implementieren von UUID-basierten Primärschlüsseln für verteilte Systeme","Automatisieren der Zeitstempel-Verfolgung für die Datenänderung und -erstellung"],"pt":["Projetar esquemas de banco de dados normalizados para aplicações em larga escala","Implementar chaves primárias baseadas em UUID para sistemas distribuídos","Automatizar o rastreamento de carimbos de data/hora para modificação e criação de dados"],"ru":["Проектировать нормализованные схемы базы данных для крупномасштабных приложений","Реализовывать первичные ключи на основе UUID для распределенных систем","Автоматизировать отслеживание временных меток для изменения и создания данных"],"ar":["تصميم مخططات قاعدة البيانات المتناسقة للمتطلبات الكبيرة","تنفيذ المفاتيح الأساسية المستندة إلى uuid لأنظمة الموزعة","تحسين تتبع الطوابع الزمنية لتعديل وإنشاء البيانات"]},"limitations":{"en":["Requires understanding of database design principles","Limited to relational databases with support for UUID and timestamp data types"],"zh":["需要了解数据库设计原则","仅限于支持UUID和时间戳数据类型的关系数据库"],"ja":["データベース設計原則の理解が必要","UUIDとタイムスタンプデータ型をサポートする関係データベースに限定される"],"ko":["데이터베이스 설계 원칙에 대한 이해가 필요","UUID 및 타임스탬프 데이터 유형을 지원하는 관계형 데이터베이스에만 제한"],"es":["Requiere una comprensión de los principios de diseño de base de datos","Limitado a bases de datos relacionales con soporte para tipos de datos UUID y marca de tiempo"],"fr":["Nécessite une compréhension des principes de conception de base de données","Limité aux bases de données relationnelles avec prise en charge des types de données UUID et horodatage"],"de":["Erfordert ein Verständnis der Datenbankdesign-Prinzipien","Begrenzt auf relationale Datenbanken mit Unterstützung für UUID- und Zeitstempel-Datentypen"],"pt":["Exige compreensão dos princípios de design de banco de dados","Limitado a bancos de dados relacionais com suporte para tipos de dados UUID e carimbo de data/hora"],"ru":["Требует понимания принципов проектирования базы данных","Ограничен базами данных с поддержкой типов данных UUID и временных меток"],"ar":["يتطلب فهم مبادئ تصميم قاعدة البيانات","محدود بقواعد البيانات العلائقية التي تدعم أنواع البيانات uuid وطوابع زمنية"]},"version":4},"contentHash":"2f3ff015718d3bb7b3d985c52a7a0dae25bbdce6fa63ea0a3822ae75258d3472","qualityScore":39}');
