INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('front-depiction/cli-stock/atom-state', 'atom-state', 'front-depiction', 'cli-stock', 'community', 'atom-state front-depiction cli-stock community atom-state is a reactive state management library for Effect that integrates with React, allowing developers to build real-time stock trading apps. It benefits developers working with Effect-TS and React Atom-State 是一个使用 Effect-TS 构建的实时股票交易应用，用于测试代理配置和模式。它使用 Effect Atom 作为状态管理库，与 React 无缝集成 Atom-State は、Effect-TS を使用して構築されたリアルタイム株取引アプリであり、エージェント配置とパターンをテストするために使用されます。Effect Atom を状態管理ライブラリとして使用し、React とシームレスに統合されます Atom-State는 Effect-TS를 사용하여 구축된 실시간 주식 거래 애플리케이션으로, 에이전트 구성 및 패턴을 테스트하는 데 사용됩니다. 상태 관리 라이브러리로서 Effect Atom를 사용하며 React와 무중단으로 통합됩니다 atom-state es una biblioteca de gestión de estado reactivo para Effect que se integra perfectamente con React. Permite crear aplicaciones de trading en tiempo real con un estado de átomo estable y reactivo l''état d''atome est une bibliothèque de gestion d''état réactif pour Effect qui s''intègre sans effort avec React. Il permet de créer des applications de trading en temps réel avec un état d''atome stable et réactif atom-state ist eine Bibliothek für reaktives Zustandsmanagement für Effect, die nahtlos mit React integriert ist. Sie ermöglicht die Erstellung von Echtzeit-Handelsanwendungen mit einem stabilen und reaktiven Atomzustand O Atom-State é uma biblioteca de gerenciamento de estado reativo para Effect que integra-se perfeitamente com React. Ele fornece contêineres estáveis para estado reativo. Atom-State - это реактивная библиотека управления состоянием для Effect, которая без проблем интегрируется с React. Она предоставляет стабильные контейнеры для реактивного состояния. Atom-State هو مكتبة إدارة الحالة التفاعلية ل Effect التي تتكامل بشكل مثالي مع React. وهي توفر حاويات مستقرة للحالة التفاعلية. how to use atom-state what is atom-state atom-state vs React State atom-state install guide Effect-TS state management reactive state management with React atom-state alternative atom-state setup for AI agents Atom-State Effect-TS 实时股票交易应用 状态管理 React TypeScript AIエージェント AI工具 Utilizes Effect-TS for building real-time stock trading apps Provides reactive state management with React integration Creates atoms that work by reference for stable state management Allows multiple components to reference the same atom for synchronized updates Supports the creation of atoms using the Atom.make() function Enables seamless integration with React using @effect-atom/atom-react atom-state is a reactive state management library for Effect that seamlessly integrates with React, providing stable containers for reactive state');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('az9713/whatsapp-claude-old/video-script', 'community', 'az9713', 'whatsapp-claude-old', 'az9713/whatsapp-claude-old', 'video-script', 0, 0, 39, '2026-03-08T01:57:15.315Z', '2026-03-08T02:02:44.411Z', '1fb55823834ace58c8018061665765e04856c5794f11d9c3baad9b7f3e6d30bd', '{"id":"az9713/whatsapp-claude-old/video-script","name":"video-script","description":{"en":"The video-script skill generates professional video scripts with voiceover narration and visual directions for AI agents, supporting educational, news, tutorial, and entertainment styles.","zh":"视频脚本技能允许开发者使用标准视频脚本格式创建专业的视频脚本，包括语音导航和视觉方向","ja":"ビデオスクリプトスキルは、開発者が標準的なビデオスクリプト形式を使用して、プロフェッショナルのビデオスクリプトを作成できるようにします。ナレーションや視覚的な指示を含みます","ko":"비디오 스크립트 스킬은 개발자가 표준 비디오 스크립트 형식을 사용하여 전문적인 비디오 스크립트를 작성할 수 있도록 해줍니다. 음성 안내와 시각적 지시를 포함합니다","es":"El video-script permite crear guiones de video profesionales con narración y direcciones visuales para agentes de IA","fr":"Le video-script permet de créer des scripts de vidéo professionnels avec narration et directions visuelles pour les outils d''IA","de":"Das video-script ermöglicht die Erstellung von professionellen Video-Skripten mit Voiceover-Erzählung und visuellen Anweisungen für KI-Agenten","pt":"O video-script permite a criação de scripts de vídeo com narração por voz e direções visuais para agente de IA","ru":"Видео-сценарий позволяет создавать видеосценарии с голосовым сопровождением и визуальными указаниями для ИИ Агентов","ar":"سيناريو الفيديو يسمح بإنشاء سيناريوهات فيديو مع إرشادات صوتية ومرئية للوكيل الذكاء الاصطناعي"},"seo":{"title":{"en":"video-script: Standardized Video Scripting for AI Agents ...","zh":"视频脚本技能：使用WhatsApp-Claude桥接实现自主AI代理任务","ja":"ビデオスクリプトスキル：WhatsApp-Claudeブリッジを使用した自律AIエージェントタスク","ko":"비디오 스크립트 스킬: WhatsApp-Claude 브릿지를 사용한 자율적인 AI 에이전트 작업","es":"Guía de configuración de video-script para