INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('az9713/whatsapp-claude-old/video-script', 'video-script', 'az9713', 'whatsapp-claude-old', 'community', 'video-script az9713 whatsapp-claude-old community The video-script skill generates professional video scripts with voiceover narration and visual directions for AI agents, supporting educational, news, tutorial, and entertainment styles. 视频脚本技能允许开发者使用标准视频脚本格式创建专业的视频脚本，包括语音导航和视觉方向 ビデオスクリプトスキルは、開発者が標準的なビデオスクリプト形式を使用して、プロフェッショナルのビデオスクリプトを作成できるようにします。ナレーションや視覚的な指示を含みます 비디오 스크립트 스킬은 개발자가 표준 비디오 스크립트 형식을 사용하여 전문적인 비디오 스크립트를 작성할 수 있도록 해줍니다. 음성 안내와 시각적 지시를 포함합니다 El video-script permite crear guiones de video profesionales con narración y direcciones visuales para agentes de IA Le video-script permet de créer des scripts de vidéo professionnels avec narration et directions visuelles pour les outils d''IA Das video-script ermöglicht die Erstellung von professionellen Video-Skripten mit Voiceover-Erzählung und visuellen Anweisungen für KI-Agenten O video-script permite a criação de scripts de vídeo com narração por voz e direções visuais para agente de IA Видео-сценарий позволяет создавать видеосценарии с голосовым сопровождением и визуальными указаниями для ИИ Агентов سيناريو الفيديو يسمح بإنشاء سيناريوهات فيديو مع إرشادات صوتية ومرئية للوكيل الذكاء الاصطناعي how to use video-script video-script setup guide video-script alternative video-script vs screenplay what is video-script video-script install video-script for AI agents video-script WhatsApp integration video-script Claude Code CLI 视频脚本技能 AI代理 WhatsApp-Claude桥接 标准视频脚本格式 语音导航 视觉方向 CLI命令行接口 自主AI代理任务 Generates video scripts in a standard format with estimated duration and style Supports educational, news, tutorial, and entertainment video script styles Includes voiceover narration and visual directions for clear script guidance Enables integration with WhatsApp messaging and Claude Code CLI for autonomous AI tasks Provides a structured script format with intro, sections, and production notes video-script is a skill that enables the creation of standardized video scripts with structured formats and autonomous AI agent tasks integration.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('smoreg/biLangGen/upload-prepare', 'community', 'smoreg', 'biLangGen', 'smoreg/biLangGen', 'upload-prepare', 0, 0, 39, '2026-03-08T01:57:15.315Z', '2026-03-08T02:02:46.649Z', 'b157b988cbf8b35432a98ed6676feac83899ef02273dbba839c8e95fe2f2ddda', '{"id":"smoreg/biLangGen/upload-prepare","name":"upload-prepare","description":{"en":"The upload-prepare skill prepares and validates YouTube uploads without actually uploading, creating a checklist for user verification, benefiting developers and content creators.","zh":"Upload Prepare AI Agent帮助您为YouTube上传做好准备和验证，包括项目识别、验证和检查清单创建","ja":"Upload Prepare AIエージェントは、YouTubeアップロードの準備と検証を支援します。プロジェクト識別、検証、チェックリストを作成します","ko":"Upload Prepare AI 에이전트는 YouTube 업로드를 위한 준비와 검증을 도와줍니다. 프로젝트 식별, 검증 및 체크리스트 생성을 포함합니다","es":"La herramienta de preparación de subida de YouTube verifica la existencia del proyecto y crea una lista de verificación para la verificación del usuario.","fr":"L''outil de préparation de téléchargement YouTube vérifie l''existence du projet et crée une liste de vérification pour la vérification de l''utilisateur.","de":"Das YouTube-Upload-Vorbereitungstool überprüft die Existenz des Projekts und erstellt eine Prüfliste für die Benutzerverifizierung.","pt":"O upload prepare é uma ferramenta de ia que ajuda a preparar e validar uploads para YouTube. Crie uma lista de verificação abrangente para verificação do usuário.","ru":"Загрузка подготовлена - это ИИ Агент, который помогает подготовить и проверить загрузки для YouTube. Создает комплексный чек-лист для верификации пользователя.","ar":"التحميل للمستعد هو أداة ذكاء اصطناعي تساعد على إعداد وتحقق من التحميلات لليوتيوب. انشئ قائمة تحقق شاملة للتحقق من المستخدم."},"seo":{"title":{"en":"upload-prepare: YouTube Upload Preparation Setup Guide | ...","zh":"YouTube上传准备和验证设置指南 - Upload Prepare","ja":"YouTubeアップロード準備と検証のベストプラクティス - Upload Prepare","ko":"YouTube 업로드 준비 및 검증 설정 가이드 - Upload Prepare","es":"Herramientas de preparación de subida de YouTube: Guía de...","fr":"Outil de préparation de téléchargement YouTube: Meilleure...","de":"YouTube-Upload-Vorbereitung: Setup-Anleitung für Entwickler","pt":"Guia de Configuração do Upload Prepare - Ferramentas de Ia","ru":"Руководство по настройке загрузки - ИИ Агенты для YouTube","ar":"دليل إعداد التحميل للمستعد - أدوات الذكاء الاصطناعي"},"description":{"en":"Get ready to upload to YouTube with confidence! Use upload-prepare to validate your project and create a comprehensive checklist, try it now!","zh":"使用Upload Prepare AI Agent进行YouTube上传准备和验证，创建全面检查清单以确保上传成功","ja":"Upload Prepare AIエージェントを使用してYouTubeアップロードを準備し、検証し、問題なくアップロードできるようにします","ko":"Upload Prepare AI 에이전트를 사용하여 YouTube 업로드를 준비하고 검증하여 업로드 성공을 보장합니다","es":"Aprende a preparar y validar tus subidas de YouTube con nuestra herramienta de AI. Crea listas de verificación completas para la verificación del usuario.","fr":"Découvrez comment préparer et valider vos téléchargements YouTube avec notre outil d''IA. Créez des listes de vérification complètes pour la vérification de l...","de":"Erfahren Sie, wie Sie Ihre YouTube-Uploads mit unserem AI-Tool vorbereiten und validieren. Erstellen Sie umfassende Prüflisten für die Benutzerverifizierung.","pt":"Aprenda a configurar o upload prepare para YouTube com nossa ferramenta de ia. Verifique a lista de preparação antes de fazer upload.","ru":"Настройте загрузку для YouTube с помощью нашего ИИ Агента. Создайте комплексный чек-лист для верификации пользователя.","ar":"تعلم كيفية إعداد التحميل للمستعد لليوتيوب باستخدام أداة الذكاء الاصطناعي. قم بفحص قائمة التحقق قبل التحميل."},"definition":{"en":"upload-prepare is a skill that prepares and validates everything for YouTube upload, creating a comprehensive checklist for user verification.","zh":"Upload Prepare是用于YouTube上传准备和验证的AI Agent，创建检查清单以确保上传成功","ja":"Upload Prepareは、YouTubeアップロードの準備と検証に使用されるAIエージェントで、チェックリストを作成してアップロードの成功を確保します","ko":"Upload Prepare는 YouTube 업로드 준비 및 검증을 위한 AI 에이전트로, 체크리스트를 생성하여 업로드 성공을 보장합니다","es":"La preparación de subida de YouTube es una herramienta de AI que prepara y valida los proyectos para la subida a YouTube.","fr":"La préparation de téléchargement YouTube est un outil d''IA qui prépare et valide les projets pour le téléchargement sur YouTube.","de":"Die YouTube-Upload-Vorbereitung ist ein AI-Tool, das Projekte für den Upload auf YouTube vorbereitet und validiert.","pt":"O que é upload prepare? É uma ferramenta de ia que prepara e valida uploads para YouTube.","ru":"Что такое загрузка подготовлена? Это ИИ Агент, который подготавливает и проверяет загрузки для YouTube.","ar":"ما هو التحميل للمستعد? هو أداة ذكاء اصطناعي تساعد على إعداد وتحقق من التحميلات لليوتيوب."},"features":{"en":["Creates comprehensive checklist for user verification","Validates project existence in `proj` context","Supports activation triggers like ''prepare upload'' and ''validate for youtube''","Detects project name from user or context","Generates checklist for YouTube upload preparation"],"zh":["支持YouTube上传准备和验证","创建全面检查清单以确保上传成功","支持项目识别和验证","支持多种触发器，包括\"prepare upload\"和\"check before upload\"","支持多语言，包括英语、中文、日语和韩语","使用CLI进行上传准备和验证"],"ja":["YouTubeアップロードの準備と検証をサポート","アップロードの成功を確保するためのチェックリストを作成","プロジェクト識別と検証をサポート","複数のトリガーをサポート， \"prepare upload\"や\"check before upload\"を含む","複数の言語をサポート， 英語、中国語、日本語、韓国語を含む","CLIを使用してアップロードの準備と検証を行う"],"ko":["YouTube 업로드 준비 및 검증을 지원","업로드 성공을 보장하는 체크리스트 생성","프로젝트 식별 및 검증을 지원","여러 트리거를 지원, \"prepare upload\" 및 \"check before upload\" 포함","여러 언어를 지원, 영어, 중국어, 일본어 및 한국어 포함","CLI를 사용하여 업로드 준비 및 검증 수행"],"es":["Verificación de la existencia del proyecto","Creación de una lista de verificación para la verificación del usuario","Compatibilidad con comandos de voz como ''prepare upload'' y ''check before upload''","Integración con la plataforma de YouTube","Soporte para la detección de proyectos a partir del contexto"],"fr":["Vérification de l''existence du projet","Création d''une liste de vérification pour la vérification de l''utilisateur","Compatibilité avec les commandes vocales comme ''prepare upload'' et ''check before upload''","Intégration avec la plateforme YouTube","Prise en charge de la détection de projets à partir du contexte"],"de":["Überprüfung der Existenz des Projekts","Erstellung einer Prüfliste für die Benutzerverifizierung","Kompatibilität mit Sprachbefehlen wie ''prepare upload'' und ''check before upload''","Integration mit der YouTube-Plattform","Unterstützung für die Projekt-Erkennung aus dem Kontext"],"pt":["Cria uma lista de verificação abrangente para verificação do usuário","Verifica a existência do projeto no contexto","Detecta o nome do projeto do usuário","Suporta comandos de ativação como ''prepare upload'' e ''check before upload''"],"ru":["Создает комплексный чек-лист для верификации пользователя","Проверяет существование проекта в контексте","Определяет имя проекта пользователя","Поддерживает команды активации, такие как ''prepare upload'' и ''check before upload''"],"ar":["ينشئ قائمة تحقق شاملة للتحقق من المستخدم","يتحقق من وجود المشروع في السياق","يكتشف اسم مشروع المستخدم","يدعم أوامر التنشيط مثل ''prepare upload'' و ''check before upload''"]},"keywords":{"en":["how to use upload-prepare","upload-prepare setup guide","what is upload-prepare","upload-prepare alternative","upload-prepare vs youtube uploader","upload-prepare install","youtube upload preparation","upload-prepare validation","upload-prepare checklist"],"zh":["YouTube上传准备","YouTube上传验证","Upload Prepare AI Agent","YouTube上传设置","YouTube上传最佳实践","CLI上传准备","项目识别","检查清单创建","AI工具"],"ja":["YouTubeアップロード準備","YouTubeアップロード検証","Upload Prepare AIエージェント","YouTubeアップロード設定","YouTubeアップロードベストプラクティス","CLIアップロード準備","プロジェクト識別","チェックリスト作成","AIエージェント"],"ko":["YouTube 업로드 준비","YouTube 업로드 검증","Upload Prepare AI 에이전트","YouTube 업로드 설정","YouTube 업로드 최적화","CLI 업로드 준비","프로젝트 식별","체크리스트 생성","AI 도구"],"es":["herramientas de subida de YouTube","preparación de subida de YouTube","validación de subida de YouTube","lista de verificación de subida de YouTube","IA para subida de YouTube","YouTube Upload-Vorbereitung","subida de videos a YouTube","optimización de subida de YouTube"],"fr":["outils de téléchargement YouTube","préparation de téléchargement YouTube","validation de téléchargement YouTube","liste de vérification de téléchargement YouTube","IA pour téléchargement YouTube","téléchargement de vidéos sur YouTube","optimisation de téléchargement YouTube"],"de":["YouTube-Upload-Tools","YouTube-Upload-Vorbereitung","YouTube-Upload-Validierung","YouTube-Upload-Prüfliste","AI für YouTube-Upload","YouTube-Video-Upload","YouTube-Upload-Optimierung"],"pt":["upload prepare","ferramentas de ia","youtube upload","lista de verificação","verificação do usuário","configuração do upload"],"ru":["загрузка подготовлена","ИИ Агенты","youtube загрузка","чек-лист","верификация пользователя","настройка загрузки"],"ar":["التحميل للمستعد","أدوات الذكاء الاصطناعي","تحميل اليوتيوب","قائمة التحقق","تحقق من المستخدم","إعداد التحميل"]}},"owner":"smoreg","repo":"biLangGen","repoPath":"smoreg/biLangGen","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.315Z","topics":[],"category":"community","skillMd":{"name":"upload-prepare","description":"Prepare YouTube upload for bilingual audiobook video. Runs youtube-metadata skill, builds upload command, validates all files, checks languages by reading translations from middle of book, verifies wordcards play, shows thumbnail/background/output. Does NOT upload - only preparation and checklist. Use when user wants to prepare upload, check before upload, or validate video for YouTube.","bodyPreview":"# Upload Prepare - YouTube Upload Preparation & Validation\n\n## Overview\n\nPrepare and validate everything for YouTube upload without actually uploading. Creates comprehensive checklist for user verification.\n\n## Activation Triggers\n\n- \"prepare upload\"\n- \"check before upload\"\n- \"validate for youtube\"\n- \"upload checklist\"\n- \"готовь к загрузке\"\n- \"проверь перед аплоадом\"\n\n## Workflow\n\n### Step 1: Identify Project\n\n1. Get project name from user or detect from context\n2. Verify project exists in `proj","body":"# Upload Prepare - YouTube Upload Preparation & Validation\n\n## Overview\n\nPrepare and validate everything for YouTube upload without actually uploading. Creates comprehensive checklist for user verification.\n\n## Activation Triggers\n\n- \"prepare upload\"\n- \"check before upload\"\n- \"validate for youtube\"\n- \"upload checklist\"\n- \"готовь к загрузке\"\n- \"проверь перед аплоадом\"\n\n## Workflow\n\n### Step 1: Identify Project\n\n1. Get project name from user or detect from context\n2. Verify project exists in `projects/` directory\n3. Load project metadata from SQLite database\n\n```bash\n# Check project exists\nls projects/{project_name}/\n\n# Get meta from DB\nsqlite3 projects/{project_name}/project.db \"SELECT key, value FROM meta;\"\n```\n\n### Step 2: Validate Languages\n\n1. Read source and target language from project meta\n2. Read 2-3 translations from MIDDLE of the book (not beginning!)\n3. Display translations for user to verify correct language\n\n```bash\n# Get total sentences\nsqlite3 projects/{project_name}/project.db \"SELECT value FROM meta WHERE key=''total_sentences'';\"\n\n# Read translations from middle (e.g., sentences 100-102)\nsqlite3 projects/{project_name}/project.db \"SELECT sentence_idx, text FROM sentences WHERE lang=''{target_lang}'' LIMIT 3 OFFSET 100;\"\n```\n\n### Step 3: Validate Files\n\nCheck all required files exist:\n\n```bash\n# Video output\nls -lh projects/{project_name}/video/output.mp4\n\n# Background image\nls -la projects/{project_name}/video/background.*\n\n# Timeline with wordcards\nhead -30 projects/{project_name}/audio/timeline.json | grep -E \"(wordcard_start|wordcard_duration)\"\n\n# Wordcard audio files\nls projects/{project_name}/audio/wordcards/ | head -5\n```\n\n### Step 4: Verify Wordcards\n\n1. Check timeline.json contains wordcard_start and wordcard_duration fields\n2. Play one wordcard audio from middle of book for verification\n\n```bash\n# Check timeline has wordcard data\ngrep -c \"wordcard_start\" projects/{project_name}/audio/timeline.json\n\n# Play wordcard from middle (user listens)\nafplay projects/{project_name}/audio/wordcards/0000100_combined.mp3\n```\n\n### Step 5: Find Thumbnail\n\n1. Determine language pair from project (e.g., ru_en, ru_es-latam)\n2. Check `thumbnails/{lang_pair}/` directory for matching thumbnail\n3. If not found, generate using thumbnail generator\n\n```bash\n# Find thumbnail in language-specific folder\n# Structure: thumbnails/ru_en/, thumbnails/ru_es-latam/\nls -la thumbnails/{source}_{target}/ | grep -i {project_base_name}\n```\n\n**If thumbnail NOT found, generate it:**\n\n```python\n# Quick one-liner to generate single thumbnail\npython3 -c \"\nfrom pathlib import Path\nfrom video.thumbnail_variants import prepare_background, variant_13, load_fonts\nfrom PIL import ImageDraw\n\nfonts = load_fonts()\nimg = prepare_background(Path(''txt_source/{book_name}.png''))\ndraw = ImageDraw.Draw(img)\n\n# For RU→EN use tgt_lang=''ENGLISH''\n# For RU→ES-LATAM use tgt_lang=''LATAM SPANISH''\nimg = variant_13(img, draw, fonts,\n    author_en=''{Author English}'',\n    title_en=''{Title English}'',\n    src_lang=''RUSSIAN'',\n    tgt_lang=''ENGLISH'',  # or ''LATAM SPANISH''\n    title_ru=''{Название}'',\n    author_ru=''{Автор}''\n)\nimg = img.convert(''RGB'')\nimg.save(''thumbnails/ru_en/{book_name}.png'', quality=95)\n\"\n```\n\n**Batch generation (all books):**\n```bash\n# Generate all thumbnails for specific language pair\npython3 scripts/generate_thumbnails.py thumbnails/ru_es-latam  # default LATAM SPANISH\n```\n\nTo add target language option to batch script, edit `generate_thumbnails.py`.\n\n### Step 6: Generate Metadata\n\nInvoke youtube-metadata skill to generate title, description, tags:\n\n```\nSkill(skill: \"youtube-metadata\")\n```\n\nFollow youtube-metadata workflow to generate proper metadata.\n\n### Step 7: Build Upload Command\n\nConstruct the upload command (do NOT execute):\n\n```bash\npython3 scripts/youtube_upload.py upload {project_name} {thumbnail_path} --playlist \"{playlist_name}\"\n```\n\nPlaylist selection:\n- RU → EN: `--playlist \"RU - EN\"`\n- RU → ES-LATAM: `--playlist \"RU - ES (LATAM)\"`\n- Other: ask user\n\n### Step 8: Display Checklist\n\nOutput comprehensive checklist for user:\n\n```\n============================================================\nUPLOAD PREPARATION CHECKLIST\n============================================================\n\nPROJECT: {project_name}\nLANGUAGES: {SOURCE} → {TARGET}\n\n------------------------------------------------------------\nFILES (clickable paths)\n------------------------------------------------------------\n[✓/✗] Video:      file://{full_video_path} ({size})\n[✓/✗] Background: file://{full_background_path}\n[✓/✗] Thumbnail:  file://{full_thumbnail_path}\n[✓/✗] Timeline: {has wordcard data}\n[✓/✗] Wordcards: {count} files\n\n------------------------------------------------------------\nLANGUAGE VERIFICATION (from middle of book)\n------------------------------------------------------------\nSentence 100: \"{source_text}\"\nTranslation:  \"{target_text}\"\n\nSentence 101: \"{source_text}\"\nTranslation:  \"{target_text}\"\n\n>>> Verify translations are in {target_lang}! <<<\n\n------------------------------------------------------------\nWORDCARD AUDIO\n------------------------------------------------------------\n[✓/✗] Timeline has wordcard timing\n[✓/✗] Wordcard files exist\n[PLAYED] Wordcard sample from sentence 100\n\n------------------------------------------------------------\nMETADATA (use youtube-metadata skill format!)\n------------------------------------------------------------\nTitle: [Bilingual][{SOURCE}→{TARGET}] {Author} - {Title}\n\nDescription:\n🎧 AI-generated bilingual audio for passive language learning.\nEach sentence: first {source_language}, then {target_language}.\n\n⚠️ Neural TTS - minor errors possible. Premium voices coming soon.\n\n📩 Want other languages or texts? Drop a comment!\n\n#{hashtag1} #Bilingual #LanguageLearning #{hashtag2}\n\nTags: (from youtube-metadata skill, NO # symbols)\nPlaylist: {playlist}\n\n------------------------------------------------------------\nUPLOAD COMMAND (copy & run when ready)\n------------------------------------------------------------\npython3 scripts/youtube_upload.py upload {project_name} {thumbnail_path} \\\n  --title \"[Bilingual][{SOURCE}→{TARGET}] {Author} - {Title}\" \\\n  --playlist \"{playlist}\" \\\n  --privacy public\n\n============================================================\n```\n\n**Upload command flags:**\n- `--title` — REQUIRED! Title in youtube-metadata format\n- `--thumbnail` — path to thumbnail image (positional arg)\n- `--playlist` — playlist name (RU - EN, RU - ES (LATAM), etc.)\n- `--privacy` — private/unlisted/public (use public for immediate publish)\n- `--schedule` — optional: \"tomorrow\", \"tomorrow 14:00\", \"18:00\", \"+2h\", or ISO datetime\n- `--dry-run` — preview without uploading\n- `-y` — skip confirmation\n\n**Optimal premiere times for language learning content:**\n- Best days: Wednesday, Thursday, Friday\n- Best time: 10:00-14:00 (target audience timezone)\n- For RU→EN: 14:00 MSK (11:00 UTC) — catches both Russian and European learners\n- For RU→ES LATAM: 18:00 MSK (15:00 UTC, 12:00 Argentina) — catches LATAM afternoon\n\n**CRITICAL:** Metadata MUST follow youtube-metadata skill format exactly:\n- Title: `[Bilingual][{SOURCE}→{TARGET}] {Author} - {Title}`\n- Author and Title MUST be in ENGLISH\n- Description: standard template from youtube-metadata skill\n- Tags: from youtube-metadata skill (NO hashtag symbols)\n\n## Quality Checklist\n\nBefore showing final checklist, verify:\n\n- [ ] Video file exists and size > 10MB\n- [ ] Background image exists\n- [ ] Thumbnail exists\n- [ ] Timeline contains wordcard_start fields (if wordcards enabled)\n- [ ] Wordcard audio files exist (if wordcards enabled)\n- [ ] Translations are in correct target language\n- [ ] Metadata generated via youtube-metadata skill\n- [ ] Upload command is valid\n\n## Anti-Patterns to Avoid\n\n- **Don''t** execute the upload command\n- **Don''t** skip language verification\n- **Don''t** use translations from beginning (use middle of book)\n- **Don''t** skip wordcard audio playback\n- **Don''t** generate metadata manually (use youtube-metadata skill)\n\n## Example Execution\n\n```\nUser: prepare upload nabokov_uzhas_ru_en\n\nClaude:\nStarting upload preparation for nabokov_uzhas_ru_en...\n\n[Validates project exists]\n[Reads meta: ru → en, 209 sentences]\n[Reads translations from middle - sentences 100-102]\n[Checks video: 192MB ✓] → file:///Users/.../video/output.mp4\n[Checks background ✓] → file:///Users/.../video/background.png\n[Checks thumbnail ✓] → file:///Users/.../thumbnails/ru_en/nabokov_uzhas.png\n[Checks timeline: has wordcard_start ✓]\n[Plays wordcard audio from sentence 100]\n[Invokes youtube-metadata skill]\n[Builds upload command]\n\n============================================================\nUPLOAD PREPARATION CHECKLIST\n============================================================\n[Full checklist output...]\n============================================================\n\nAll checks passed! Review the checklist and run the upload command when ready.\n```\n\n## Summary\n\nThis skill prepares everything for YouTube upload:\n1. Validates all files exist\n2. Verifies languages by checking translations from middle of book\n3. Confirms wordcards are included\n4. Generates metadata via youtube-metadata skill\n5. Builds upload command\n6. Displays comprehensive checklist\n\nUser makes final decision to upload.\n"},"lastSynced":"2026-03-08T02:02:46.649Z","agentAnalysis":{"suitability":{"en":"Ideal for Media Management Agents requiring precise YouTube upload validation and preparation capabilities.","zh":"适合需要精确YouTube上传验证和准备能力的媒体管理代理。","ja":"YouTubeアップロードの正確な検証と準備機能を必要とするメディア管理エージェントに最適です。","ko":"정확한 YouTube 업로드 검증 및 준비 기능이 필요한 미디어 관리 에이전트에 적합합니다.","es":"Ideal para agentes de gestión de medios que requieren capacidades de validación y preparación de subida a YouTube precisas.","fr":"Idéal pour les agents de gestion des médias nécessitant une validation et une préparation de téléchargement YouTube précises.","de":"Ideal für Media-Management-Agents, die präzise YouTube-Upload-Validierungs- und Vorbereitungsfunktionen erfordern.","pt":"Ideal para Agentes de Gerenciamento de Mídia que exigem capacidades de validação e preparação de upload do YouTube precisas.","ru":"Идеально подходит для агентов управления медиа, требующих точной валидации и подготовки загрузки в YouTube.","ar":"مثالي للوكلاء لإدارة الوسائط الذين يتطلبون возможات التحقق والتحضير الدقيق للتحميل على يوتيوب."},"recommendation":{"en":"Empowers agents to validate YouTube uploads without actual upload, creating comprehensive checklists for user verification, utilizing protocols like HTTP for metadata analysis and checklist generation in formats like CSV or JSON.","zh":"赋予代理验证YouTube上传的能力，而无需实际上传，创建用户验证的综合清单，利用HTTP等协议进行元数据分析和清单生成，支持CSV或JSON等格式。","ja":"エージェントが実際のアップロードなしでYouTubeアップロードを検証できるようにし、HTTPなどのプロトコルを使用してメタデータ分析とチェックリスト生成を行い、CSVまたはJSONなどの形式でユーザー検証のための包括的なチェックリストを作成します。","ko":"에이전트가 실제 업로드 없이 YouTube 업로드를 검증할 수 있도록 하며, HTTP 등 프로토콜을 사용하여 메타데이터 분석 및 체크리스트 생성을 수행하고, CSV 또는 JSON 등의 형식으로 사용자 검증을 위한 포괄적인 체크리스트를 생성합니다.","es":"Permite a los agentes validar las subidas a YouTube sin subir realmente, creando listas de verificación exhaustivas para la verificación de los usuarios, utilizando protocolos como HTTP para el análisis de metadatos y la generación de listas de verificación en formatos como CSV o JSON.","fr":"Permet aux agents de valider les téléchargements YouTube sans téléchargement réel, en créant des listes de vérification complètes pour la vérification des utilisateurs, en utilisant des protocoles comme HTTP pour l''analyse des métadonnées et la génération de listes de vérification au format CSV ou JSON.","de":"Ermächtigt Agenten, YouTube-Uploads zu validieren, ohne tatsächlich hochzuladen, und erstellt umfassende Prüflisten für die Benutzerverifizierung, indem Protokolle wie HTTP für die Metadatenanalyse und die Prüflisten-Generierung in Formaten wie CSV oder JSON verwendet werden.","pt":"Habilita os agentes a validar uploads do YouTube sem upload real, criando listas de verificação abrangentes para verificação do usuário, utilizando protocolos como HTTP para análise de metadados e geração de listas de verificação em formatos como CSV ou JSON.","ru":"Наделяет агентов возможностью проверять загрузки в YouTube без фактической загрузки, создавая всесторонние списки проверки для верификации пользователя, используя протоколы như HTTP для анализа метаданных и генерации списков проверки в форматах seperti CSV или JSON.","ar":"يمنح الوكلاء القدرة على التحقق من التحميلات على يوتيوب بدون تحميل فعلي، ويخلق قائمة شاملة للتحقق من المستخدم، باستخدام بروتوكولات مثل HTTP للتحليل الأساسي والتحقق من قائمة التنسيق مثل CSV أو JSON."},"useCases":{"en":["Validating video metadata before upload","Generating pre-upload checklists for content creators","Automating YouTube upload preparation for developers"],"zh":["上传前验证视频元数据","为内容创建者生成上传前检查清单","为开发者自动化YouTube上传准备"],"ja":["アップロード前のビデオメタデータの検証","コンテンツクリエイターのためのアップロード前チェックリストの生成","開発者のためのYouTubeアップロード準備の自動化"],"ko":["업로드 전 비디오 메타데이터 검증","콘텐츠 제작자의 업로드 전 체크리스트 생성","개발者の YouTube 업로드 준비 자동화"],"es":["Validar metadatos de video antes de la subida","Generar listas de verificación pre-subida para creadores de contenido","Automatizar la preparación de subida a YouTube para desarrolladores"],"fr":["Valider les métadonnées vidéo avant le téléchargement","Générer des listes de vérification pré-téléchargement pour les créateurs de contenu","Automatiser la préparation du téléchargement YouTube pour les développeurs"],"de":["Video-Metadaten vor dem Upload validieren","Vor-Upload-Prüflisten für Content-Ersteller generieren","YouTube-Upload-Vorbereitung für Entwickler automatisieren"],"pt":["Validar metadados de vídeo antes do upload","Gerar listas de verificação pré-upload para criadores de conteúdo","Automatizar a preparação de upload do YouTube para desenvolvedores"],"ru":["Проверка метаданных видео перед загрузкой","Генерация списков проверки перед загрузкой для создателей контента","Автоматизация подготовки загрузки в YouTube для разработчиков"],"ar":["التحقق من بيانات الفيديو الأساسية قبل التحميل","توليد قائمة للتحقق قبل التحميل لمصنعي المحتوى","تأهيل التحضير للتحميل على يوتيوب للمانحين"]},"limitations":{"en":["Does not support actual YouTube upload","Requires project name or context detection","Limited to YouTube platform"],"zh":["不支持实际的YouTube上传","需要项目名称或上下文检测","仅限于YouTube平台"],"ja":["実際のYouTubeアップロードをサポートしない","プロジェクト名またはコンテキスト検出を必要とする","YouTubeプラットフォームに限定される"],"ko":["실제 YouTube 업로드를 지원하지 않음","프로젝트 이름 또는 컨텍스트 감지를 필요로 함","YouTube 플랫폼에만 제한됨"],"es":["No admite la subida real a YouTube","Requiere la detección del nombre del proyecto o del contexto","Limitado a la plataforma YouTube"],"fr":["Ne prend pas en charge le téléchargement réel sur YouTube","Nécessite la détection du nom du projet ou du contexte","Limité à la plateforme YouTube"],"de":["Unterstützt keinen tatsächlichen YouTube-Upload","Benötigt die Erkennung des Projektnamens oder des Kontexts","Begrenzt auf die YouTube-Plattform"],"pt":["Não suporta upload real do YouTube","Exige detecção de nome do projeto ou contexto","Limitado à plataforma do YouTube"],"ru":["Не поддерживает фактическую загрузку в YouTube","Требует обнаружения имени проекта или контекста","Ограничен платформой YouTube"],"ar":["لا يدعم التحميل الفعلي على يوتيوب","يتطلب كشف اسم المشروع أو السياق","محدود منصة يوتيوب"]},"version":4},"contentHash":"b157b988cbf8b35432a98ed6676feac83899ef02