INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('LimaTechnologies/admin-telegram-bot/nextjs-app-router', 'nextjs-app-router', 'LimaTechnologies', 'admin-telegram-bot', 'community', 'nextjs-app-router LimaTechnologies admin-telegram-bot community The nextjs-app-router skill provides expert guidance for Next.js 15 App Router, benefiting developers who want to master modern patterns for server and client components. It offers best practices for routing, data fetching, and server actions. Next.js App Router 是一个现代化的路由解决方案，提供服务器组件、客户端组件、服务器操作和数据获取等功能 Next.js App Router は、サーバー コンポーネント、クライアント コンポーネント、サーバー アクション、データ取得などの機能を提供するモダンなルーティング ソリューションです Next.js App Router는 서버 컴포넌트, 클라이언트 컴포넌트, 서버 액션, 데이터 가져오기 등의 기능을 제공하는 현대적인 라우팅 솔루션입니다 Next.js App Router es una característica que permite patrones de renderizado modernos con componentes del servidor y del cliente Next.js App Router est une fonctionnalité qui permet des modèles de rendu modernes avec des composants serveur et client Next.js App Router ist eine Funktion, die moderne Render-Muster mit Server- und Clientkomponenten ermöglicht O Next.js App Router oferece recursos avançados como Server Components, Client Components e Server Actions. Next.js App Router предлагает продвинутые функции, такие как Server Components, Client Components и Server Actions. يقدم Next.js App Router ميزات متقدمة مثل Server Components و Client Components و Server Actions. how to use nextjs-app-router nextjs-app-router setup guide nextjs-app-router vs react-router what is nextjs-app-router nextjs-app-router install nextjs-app-router tutorial for beginners Next.js App Router 服务器组件 客户端组件 服务器操作 数据获取 路由 AIエージェント Next.js 教程 Supports Server Components as the default rendering strategy Enables interactive UI patterns with Client Components using ''use client'' Handles form mutations and data updates with Server Actions Implements caching and revalidation strategies for Data Fetching Manages routing with layouts, loading, and error boundaries nextjs-app-router is a skill that provides expert guidance on using Next.js 15 App Router for building modern web applications with server and client components.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('maneeshanif/AI-Employee-Hackathon-spec-driven/watcher-management', 'community', 'maneeshanif', 'AI-Employee-Hackathon-spec-driven', 'maneeshanif/AI-Employee-Hackathon-spec-driven', 'watcher-management', 0, 0, 39, '2026-03-08T01:57:15.316Z', '2026-03-08T02:02:51.075Z', 'cbf1687ee80bdc07bae6a2e10d5add84b6cdc155d05b059ead873371fb82fdaf', '{"id":"maneeshanif/AI-Employee-Hackathon-spec-driven/watcher-management","name":"watcher-management","description":{"en":"The watcher-management skill manages the perception layer of the Personal AI Employee, monitoring external sources like Gmail and WhatsApp. It benefits developers and AI engineers.","zh":"Watcher Management技能管理个人AI员工的感知层，监视外部源并将数据输入Obsidian vault","ja":"Watcher Managementスキルは、パーソナルAI従業員の認識層を管理し、外部ソースを監視してObsidian vaultにデータを入力する","ko":"Watcher Management 스킬은 개인 AI 직원의 지각 層을 관리하고 외부 소스를 감시하여 Obsidian vault에 데이터를 입력합니다","es":"Watcher Management es una habilidad que gestiona la capa de percepción de los empleados de IA personales, monitoreando fuentes externas y alimentando el vault de Obsidian con datos","fr":"Watcher Management est une compétence qui gère la couche de perception des employés d''IA personnels, en surveillant les sources externes et en alimentant le vault Obsidian avec des données","de":"Watcher Management ist eine Fähigkeit, die die Wahrnehmungsebene der persönlichen IA-Mitarbeiter verwaltet, indem sie externe Quellen überwacht und den Obsidian-Vault mit Daten versorgt","pt":"O watcher-management é uma habilidade que gerencia a camada de percepção do Funcionário de IA Pessoal, monitorando fontes externas e alimentando dados no Obsidian vault","ru":"Смотритель-управление - это навык, который управляет слоем восприятия Личного ИИ-Сотрудника, мониторируя внешние источники и подая данные в хранилище Obsidian","ar":"مدير المتابعة هو مهارة تدير طبقة الإدراك لموظف الذكاء الاصطناعي الشخصي، حيث تراقب المصادر الخارجية وتغذي البيانات في Obsidian vault"},"seo":{"title":{"en":"Watcher-Management: Setup Guide for AI Agents","zh":"Watcher Management Setup Guide - AI工具","ja":"Watcher Management ベストプラクティス - AIエージェント","ko":"Watcher Management 구축 가이드 - AI 에이전트","es":"Guía de configuración de Watcher Management para Agentes ...","fr":"Guide de configuration de Watcher Management pour les out...","de":"Einrichtungsleitfaden für Watcher Management in AI-Tools","pt":"Guia de Configuração do Watcher-Management para Ferrament...","ru":"Настройка Смотрителя-Управления для ИИ Агентов","ar":"دليل إعداد مدير المتابعة لأدوات الذكاء الاصطناعي"},"description":{"en":"Discover how to configure watcher-management for your AI Employee, monitoring Gmail, WhatsApp, and Filesystem sources in real-time. Get started now!","zh":"了解Watcher Management的技术细节，包括Gmail、WhatsApp和文件系统监视器，实现AI工具的高效管理","ja":"Watcher Managementの技術的側面を 探り、Gmail、WhatsApp、ファイルシステムの監視をAIエージェントで実現する","ko":"Watcher Management의 기술적 세부 사항을 알아보고, Gmail, WhatsApp, 파일 시스템 감시기를 AI 에이전트에서 사용하는 방법","es":"Aprende a configurar Watcher Management para monitorizar fuentes externas y alimentar tu vault de Obsidian con datos en tiempo real","fr":"Découvrez comment configurer Watcher Management pour surveiller les sources externes et alimenter votre vault Obsidian avec des données en temps réel","de":"Erfahren Sie, wie Sie Watcher Management einrichten, um externe Quellen zu überwachen und Ihren Obsidian-Vault mit Echtzeit-Daten zu versorgen","pt":"Aprenda a configurar o watcher-management para monitorar fontes externas e alimentar dados no Obsidian vault com nossas dicas e práticas recomendadas","ru":"Узнайте, как настроить смотрителя-управления для мониторинга внешних источников и подачи данных в хранилище Obsidian с нашими советами и рекомендациями","ar":"تعرف على كيفية إعداد مدير المتابعة لمراقبة المصادر الخارجية وإطعام البيانات في Obsidian vault مع نصائحنا وأفضل الممارسات"},"definition":{"en":"Watcher-management is a skill that oversees the watcher processes, feeding data into the Obsidian vault from various sources like Gmail API and WhatsApp Web.","zh":"Watcher Management是管理AI工具的监视器，用于监视Gmail、WhatsApp和文件系统","ja":"Watcher Managementは、AIエージェントの監視器を管理するもので、Gmail、WhatsApp、ファイルシステムを監視する","ko":"Watcher Management는 AI 에이전트의 감시기를 관리하는 것으로, Gmail, WhatsApp, 파일 시스템을 감시합니다","es":"Watcher Management es una habilidad de IA que monitorea fuentes externas como Gmail y WhatsApp","fr":"Watcher Management est une compétence d''IA qui surveille les sources externes comme Gmail et WhatsApp","de":"Watcher Management ist eine IA-Fähigkeit, die externe Quellen wie Gmail und WhatsApp überwacht","pt":"O watcher-management é uma habilidade que gerencia a percepção de fontes externas para alimentar dados no Obsidian vault","ru":"Смотритель-управление - это навык, который управляет восприятием внешних источников для подачи данных в хранилище Obsidian","ar":"مدير المتابعة هو مهارة تدير إدراك المصادر الخارجية لإطعام البيانات في Obsidian vault"},"features":{"en":["Monitors Gmail API every 2 minutes","Tracks WhatsApp Web updates every 30 seconds","Watches Filesystem drop folder in real-time","Feeds data into the Obsidian vault","Supports multiple watcher types, including Gmail and WhatsApp Watchers","Outputs data to specific folders, such as /Needs_Action/"],"zh":["支持Gmail API监视","支持WhatsApp Web监视","支持文件系统实时监视","可配置检查间隔","可指定输出文件夹"],"ja":["Gmail APIの監視をサポート","WhatsApp Webの監視をサポート","ファイルシステムのリアルタイム監視をサポート","チェック間隔の設定","出力フォルダの指定"],"ko":["Gmail API 감시 지원","WhatsApp Web 감시 지원","파일 시스템 실시간 감시 지원","检查 간격 설정","출력 폴더 지정"],"es":["Monitoreo de Gmail mediante la API de Gmail","Monitoreo de WhatsApp mediante WhatsApp Web","Monitoreo del sistema de archivos en tiempo real","Almacenamiento de datos en el vault de Obsidian","Intervalos de verificación personalizables","Compatibilidad con múltiples fuentes de datos"],"fr":["Surveillance de Gmail via l''API Gmail","Surveillance de WhatsApp via WhatsApp Web","Surveillance du système de fichiers en temps réel","Stockage des données dans le vault Obsidian","Intervalle de vérification personnalisable","Compatibilité avec plusieurs sources de données"],"de":["Überwachung von Gmail über die Gmail-API","Überwachung von WhatsApp über WhatsApp Web","Überwachung des Dateisystems in Echtzeit","Speicherung von Daten im Obsidian-Vault","Anpassbare Überprüfungsintervalle","Kompatibilität mit mehreren Datenquellen"],"pt":["Suporte a vários tipos de watchers, incluindo Gmail Watcher e WhatsApp Watcher","Intervalos de verificação personalizáveis para cada watcher","Saída de dados em pastas personalizadas, como /Needs_Action/","Monitoramento em tempo real com o Filesystem Watcher","Integração com a API do Gmail e WhatsApp Web"],"ru":["Поддержка нескольких типов смотрителей, включая Gmail Смотритель и WhatsApp Смотритель","Настраиваемые интервалы проверки для каждого смотрителя","Выход данных в настраиваемые папки, такие как /Needs_Action/","Мониторинг в реальном времени с помощью Filesystem Смотрителя","Интеграция с API Gmail и WhatsApp Web"],"ar":["دعم أنواع متعددة من المتابعين، بما في ذلك متابعة الجيميل ومتابعة الواتساب","فترات تحقق قابلة للتعديل لكل متابعة","إخراج البيانات في مجلدات قابلة للتعديل، مثل /Needs_Action/","مراقبة في الوقت الحقيقي مع متابعة نظام الملفات","التكامل مع واجهة برمجة تطبيقات الجيميل وواتساب ويب"]},"keywords":{"en":["how to use watcher-management","watcher-management setup guide","watcher-management alternative","watcher-management vs obsidian","watcher-management install","what is watcher-management","watcher-management for AI agents","configuring watcher-management","watcher-management best practices"],"zh":["Watcher Management","AI工具","Gmail API","WhatsApp Web","文件系统监视","Obsidian vault","AI代理"],"ja":["Watcher Management","AIエージェント","Gmail API","WhatsApp Web","ファイルシステムの監視","Obsidian vault","AIツール"],"ko":["Watcher Management","AI 에이전트","Gmail API","WhatsApp Web","파일 시스템 감시","Obsidian vault","AI 도구"],"es":["Watcher Management","Agentes de IA","Herramientas de IA","Monitoreo de fuentes externas","Vault de Obsidian","Gmail API","WhatsApp Web","Sistema de archivos en tiempo real"],"fr":["Watcher Management","Outils d''IA","Agents d''IA","Surveillance de sources externes","Vault Obsidian","API Gmail","WhatsApp Web","Système de fichiers en temps réel"],"de":["Watcher Management","AI-Tools","IA-Mitarbeiter","Überwachung von externen Quellen","Obsidian-Vault","Gmail-API","WhatsApp Web","Dateisystem in Echtzeit"],"pt":["watcher-management","ferramentas de ia","monitoramento de fontes externas","obsidian vault","gmail watcher","whatsapp watcher","filesystem watcher","configuração de watcher","guias de configuração"],"ru":["смотритель-управление","ии агенты","мониторинг внешних источников","хранилище obsidian","gmail смотритель","whatsapp смотритель","filesystem смотритель","настройка смотрителя","руководства по настройке"],"ar":["مدير المتابعة","أدوات الذكاء الاصطناعي","مراقبة المصادر الخارجية","خزنة obsidian","متابعة الجيميل","متابعة الواتساب","متابعة نظام الملفات","إعداد متابعة","دليل إعداد"]}},"owner":"maneeshanif","repo":"AI-Employee-Hackathon-spec-driven","repoPath":"maneeshanif/AI-Employee-Hackathon-spec-driven","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.316Z","topics":[],"category":"community","skillMd":{"name":"watcher-management","description":"Manages watcher processes that monitor Gmail, WhatsApp, filesystem, and other external sources. Use when starting, stopping, or monitoring watcher scripts, configuring process management, or troubleshooting watcher issues.","bodyPreview":"# Watcher Management Skill\n\nThis skill manages the perception layer of the Personal AI Employee - the watcher processes that monitor external sources and feed data into the Obsidian vault.\n\n## Watcher Types\n\n| Watcher | Source | Check Interval | Output Folder |\n|---------|--------|----------------|---------------|\n| Gmail Watcher | Gmail API | 2 minutes | /Needs_Action/ |\n| WhatsApp Watcher | WhatsApp Web | 30 seconds | /Needs_Action/ |\n| Filesystem Watcher | Drop folder | Realtime | /Needs_Acti","body":"# Watcher Management Skill\n\nThis skill manages the perception layer of the Personal AI Employee - the watcher processes that monitor external sources and feed data into the Obsidian vault.\n\n## Watcher Types\n\n| Watcher | Source | Check Interval | Output Folder |\n|---------|--------|----------------|---------------|\n| Gmail Watcher | Gmail API | 2 minutes | /Needs_Action/ |\n| WhatsApp Watcher | WhatsApp Web | 30 seconds | /Needs_Action/ |\n| Filesystem Watcher | Drop folder | Realtime | /Needs_Action/ |\n| Finance Watcher | Bank API | 1 hour | /Needs_Action/ |\n\n## Base Watcher Pattern\n\n```python\nclass BaseWatcher(ABC):\n    def __init__(self, vault_path: str, check_interval: int = 60):\n        self.vault_path = Path(vault_path)\n        self.needs_action = self.vault_path / ''Needs_Action''\n        self.check_interval = check_interval\n\n    @abstractmethod\n    def check_for_updates(self) -> list:\n        pass\n\n    @abstractmethod\n    def create_action_file(self, item) -> Path:\n        pass\n\n    def run(self):\n        while True:\n            items = self.check_for_updates()\n            for item in items:\n                self.create_action_file(item)\n            time.sleep(self.check_interval)\n```\n\n## Process Management\n\nUse PM2 or supervisord to keep watchers running:\n\n```bash\n# Start with PM2\npm2 start gmail_watcher.py --interpreter python3\n\n# Save and set to auto-start\npm2 save\npm2 startup\n```\n\n## Reference\n\nFor detailed implementation, see [reference.md](reference.md)\n\nFor watcher examples, see [examples.md](examples.md)\n"},"lastSynced":"2026-03-08T02:02:51.075Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents needing real-time monitoring of external sources like Gmail and WhatsApp.","zh":"适合需要实时监控外部来源（如Gmail和WhatsApp）的AI代理。","ja":"GmailやWhatsAppなどの外部ソースのリアルタイムモニタリングが必要なAIエージェントに適しています。","ko":"Gmail 및 WhatsApp와 같은 외부 소스를 실시간으로 모니터링하는 데 필요한 AI 에이전트에게 적합합니다.","es":"Perfecto para agentes de IA que necesitan un monitoreo en tiempo real de fuentes externas como Gmail y WhatsApp.","fr":"Parfait pour les agents d''IA ayant besoin d''une surveillance en temps réel de sources externes comme Gmail et WhatsApp.","de":"Perfekt für KI-Agents, die ein Echtzeit-Monitoring von externen Quellen wie Gmail und WhatsApp benötigen.","pt":"Perfeito para Agentes de IA que precisam de monitoramento em tempo real de fontes externas como Gmail e WhatsApp.","ru":"Идеально подходит для агентов ИИ, которым требуется мониторинг в реальном времени внешних источников, таких как Gmail и WhatsApp.","ar":"مثالي لعمليات الوكيل الذكي التي تحتاج إلى مراقبة في الوقت الفعلي لمصادر خارجية مثل جيميل وواتساب."},"recommendation":{"en":"Empowers agents to monitor Gmail API and WhatsApp Web in intervals as low as 30 seconds, feeding data into the Obsidian vault using watcher processes, enabling seamless integration with external data sources via protocols like API and web scraping.","zh":"赋予代理监控Gmail API和WhatsApp Web的能力，间隔时间可低至30秒，并通过watcher进程将数据输入Obsidian vault，从而通过API和Web抓取等协议实现与外部数据源的无缝集成。","ja":"エージェントがGmail APIとWhatsApp Webを30秒以下の間隔で監視できるようにし、ウォッチャープロセスを使用してデータをObsidian vaultにフィードし、APIやWebスクレイピングなどのプロトコルを使用して外部データソースとのシームレスな統合を実現します。","ko":"에이전트가 30초 이하의 간격으로 Gmail API 및 WhatsApp Web를 모니터링할 수 있도록 하며, 와처 프로세스를 사용하여 데이터를 Obsidian vault에 제공함으로써 API 및 웹 스크레이핑 등을 통한 외부 데이터 소스와의无缝な 통합을 가능하게 합니다.","es":"Habilita a los agentes a monitorear Gmail API y WhatsApp Web en intervalos tan bajos como 30 segundos, alimentando datos en el vault de Obsidian mediante procesos de vigilancia, permitiendo una integración sin problemas con fuentes de datos externas a través de protocolos como API y scraping web.","fr":"Permet aux agents de surveiller Gmail API et WhatsApp Web à des intervalles aussi bas que 30 secondes, en alimentant les données dans le coffre Obsidian à l''aide de processus de surveillance, permettant une intégration transparente avec des sources de données externes via des protocoles tels que API et scraping web.","de":"Ermöglicht es den Agents, Gmail API und WhatsApp Web in Abständen von bis zu 30 Sekunden zu überwachen, indem Daten in den Obsidian-Vault mittels Watcher-Prozessen eingespeist werden, was eine nahtlose Integration mit externen Datenquellen über Protokolle wie API und Web-Scraping ermöglicht.","pt":"Permite que os agentes monitorem a API do Gmail e o WhatsApp Web em intervalos de até 30 segundos, alimentando dados no cofre Obsidian usando processos de observação, permitindo integração sem problemas com fontes de dados externas via protocolos como API e web scraping.","ru":"Позволяет агентам отслеживать Gmail API и WhatsApp Web с интервалами до 30 секунд, подпитывая данные в хранилище Obsidian с помощью процессов наблюдения, обеспечивая бесшовную интеграцию с внешними источниками данных через протоколы, такие как API и веб-скраппинг.","ar":"تمكين الوكلاء من مراقبة واجهة برمجة تطبيقات جيميل وواتساب ويب في فترات زمنية تصل إلى 30 ثانية، وتغذية البيانات في خزانة أوبسيديان باستخدام عمليات المراقبة، تمكين التكامل السلس مع مصادر البيانات الخارجية عبر بروتوكولات مثل واجهة برمجة التطبيقات وتمشيط الويب."},"useCases":{"en":["Monitoring Gmail inbox for new emails","Tracking WhatsApp messages for keyword triggers","Automating data ingestion from external sources into Obsidian vault"],"zh":["监控Gmail收件箱中的新邮件","跟踪WhatsApp消息中的关键词触发器","从外部来源自动将数据摄取到Obsidian vault"],"ja":["Gmailの受信トレイに新しいメールを監視する","WhatsAppメッセージのキーワードトリガーを追跡する","外部ソースからObsidian vaultにデータを自動で取り込む"],"ko":["Gmail 받은 편지함의 새 이메일 모니터링","WhatsApp 메시지의 키워드 트리거 추적","외부 소스에서 Obsidian vault로 데이터를 자동으로 수집"],"es":["Monitorear el buzón de Gmail para nuevos correos electrónicos","Seguir mensajes de WhatsApp para disparadores de palabras clave","Automatizar la ingesta de datos de fuentes externas en el vault de Obsidian"],"fr":["Surveiller la boîte de réception Gmail pour les nouveaux e-mails","Suivre les messages WhatsApp pour les déclencheurs de mots clés","Automatiser l''ingestion de données à partir de sources externes dans le coffre Obsidian"],"de":["Überwachung des Gmail-Posteingangs für neue E-Mails","Verfolgung von WhatsApp-Nachrichten für Schlüsselwort-Auslöser","Automatisierung der Datenübernahme aus externen Quellen in den Obsidian-Vault"],"pt":["Monitorar caixa de entrada do Gmail para novos e-mails","Rastrear mensagens do WhatsApp para gatilhos de palavras-chave","Automatizar ingestão de dados de fontes externas no cofre Obsidian"],"ru":["Отслеживать входящие сообщения в Gmail","Отслеживать сообщения WhatsApp для ключевых слов-триггеров","Автоматизировать прием данных из внешних источников в хранилище Obsidian"],"ar":["مراقبة صندوق الوارد في جيميل للحصول على رسائل بريد إلكتروني جديدة","تتبع رسائل واتساب لتحفيزات الكلمات الرئيسية","توفير تلقيم البيانات自动ياً من مصادر خارجية إلى خزانة أوبسيديان"]},"limitations":{"en":["Requires Gmail API and WhatsApp Web access","Interval-based checking may lead to delayed notifications","Dependent on stable internet connection for real-time monitoring"],"zh":["需要Gmail API和WhatsApp Web访问","间隔检查可能导致延迟通知","依赖于稳定的互联网连接以实现实时监控"],"ja":["Gmail APIとWhatsApp Webへのアクセスが必要","間隔チェックにより通知が遅れる可能性がある","リアルタイムモニタリングには安定したインターネット接続が必要"],"ko":["Gmail API 및 WhatsApp Web 액세스가 필요합니다.","间隔 체크로 인해 알림이 지연될 수 있습니다.","실시간 모니터링을 위해 안정적인 인터넷 연결이 필요합니다."],"es":["Requiere acceso a Gmail API y WhatsApp Web","La comprobación basada en intervalos puede provocar notificaciones retrasadas","Dependiente de una conexión a Internet estable para la supervisión en tiempo real"],"fr":["Nécessite un accès à Gmail API et WhatsApp Web","La vérification basée sur les intervalles peut entraîner des notifications retardées","Dépend d''une connexion Internet stable pour la surveillance en temps réel"],"de":["Benötigt Zugriff auf Gmail API und WhatsApp Web","Intervallbasierte Überprüfung kann zu verzögerten Benachrichtigungen führen","Abhängig von einer stabilen Internetverbindung für die Echtzeitüberwachung"],"pt":["Exige acesso à API do Gmail e ao WhatsApp Web","Verificação baseada em intervalos pode levar a notificações atrasadas","Dependente de conexão estável com a Internet para monitoramento em tempo real"],"ru":["Требует доступа к Gmail API и WhatsApp Web","Интервальная проверка может привести к задержке уведомлений","Зависит от стабильного интернет-соединения для мониторинга в реальном времени"],"ar":["يتطلب الوصول إلى واجهة برمجة تطبيقات جيميل وواتساب ويب","يمكن أن يؤدي الفحص المبني على الفترات الزمنية إلى إعلامات متأخرة","يعتمد على الاتصال المستقر بالإنترنت لمراقبة في الوقت الفعلي"]},"version":4},"contentHash":"cbf1687ee80bdc07bae6a2e10d5add84b6cdc155d05b059ead873371fb82fdaf","qualityScore":39}');
