INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('maneeshanif/AI-Employee-Hackathon-spec-driven/watcher-management', 'watcher-management', 'maneeshanif', 'AI-Employee-Hackathon-spec-driven', 'community', 'watcher-management maneeshanif AI-Employee-Hackathon-spec-driven community The watcher-management skill manages the perception layer of the Personal AI Employee, monitoring external sources like Gmail and WhatsApp. It benefits developers and AI engineers. Watcher Management技能管理个人AI员工的感知层，监视外部源并将数据输入Obsidian vault Watcher Managementスキルは、パーソナルAI従業員の認識層を管理し、外部ソースを監視してObsidian vaultにデータを入力する Watcher Management 스킬은 개인 AI 직원의 지각 層을 관리하고 외부 소스를 감시하여 Obsidian vault에 데이터를 입력합니다 Watcher Management es una habilidad que gestiona la capa de percepción de los empleados de IA personales, monitoreando fuentes externas y alimentando el vault de Obsidian con datos Watcher Management est une compétence qui gère la couche de perception des employés d''IA personnels, en surveillant les sources externes et en alimentant le vault Obsidian avec des données Watcher Management ist eine Fähigkeit, die die Wahrnehmungsebene der persönlichen IA-Mitarbeiter verwaltet, indem sie externe Quellen überwacht und den Obsidian-Vault mit Daten versorgt O watcher-management é uma habilidade que gerencia a camada de percepção do Funcionário de IA Pessoal, monitorando fontes externas e alimentando dados no Obsidian vault Смотритель-управление - это навык, который управляет слоем восприятия Личного ИИ-Сотрудника, мониторируя внешние источники и подая данные в хранилище Obsidian مدير المتابعة هو مهارة تدير طبقة الإدراك لموظف الذكاء الاصطناعي الشخصي، حيث تراقب المصادر الخارجية وتغذي البيانات في Obsidian vault how to use watcher-management watcher-management setup guide watcher-management alternative watcher-management vs obsidian watcher-management install what is watcher-management watcher-management for AI agents configuring watcher-management watcher-management best practices Watcher Management AI工具 Gmail API WhatsApp Web 文件系统监视 Obsidian vault AI代理 Monitors Gmail API every 2 minutes Tracks WhatsApp Web updates every 30 seconds Watches Filesystem drop folder in real-time Feeds data into the Obsidian vault Supports multiple watcher types, including Gmail and WhatsApp Watchers Outputs data to specific folders, such as /Needs_Action/ Watcher-management is a skill that oversees the watcher processes, feeding data into the Obsidian vault from various sources like Gmail API and WhatsApp Web.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('atlassian/atlassian-mcp-server/generate-status-report', 'community', 'atlassian', 'atlassian-mcp-server', 'atlassian/atlassian-mcp-server', 'generate-status-report', 0, 0, 39, '2026-03-08T01:57:15.320Z', '2026-03-08T02:02:57.078Z', '4af95baa652def9230dd1f87713e779438fe87b3e3da159522288841a5f251d4', '{"id":"atlassian/atlassian-mcp-server/generate-status-report","name":"generate-status-report","description":{"en":"The generate-status-report skill automates project status updates by querying Jira and publishing formatted reports to Confluence, benefiting development teams and project managers.","zh":"生成状态报告技能允许您自动查询 Jira 项目状态，分析问题，并将格式化报告发布到 Confluence","ja":"ステータスレポート生成スキルは、Jira プロジェクトの状態を自動的に照会し、問題を分析し、Confluence に整形されたレポートを公開します","ko":"상태 보고서 생성 스킬을 사용하여 Jira 프로젝트 상태를 자동으로 쿼리하여 문제를 분석하고 Confluence에 형식화된 보고서를 게시합니다","es":"El skill generate-status-report permite la generación automática de informes de estado de proyectos con Jira y Confluence. Analiza issues y publica informes formateados en Confluence.","fr":"Le skill generate-status-report permet la génération automatique de rapports d''état de projets avec Jira et Confluence. Il analyse les problèmes et publie des rapports formatés sur Confluence.","de":"Das Skill generate-status-report ermöglicht die automatische Erstellung von Statusberichten für Projekte mit Jira und Confluence. Es analysiert Issues und veröffentlicht formatierte Berichte in Confluence.","pt":"O Generate Status Report é uma habilidade que permite a integração segura de Jira e Confluence com sua plataforma de IA, IDE ou agente preferida, gerando relatórios de status de projetos automatizados.","ru":"Generate Status Report - это навык, который позволяет безопасно подключить Jira и Confluence к вашей платформе ИИ, IDE или агенту, генерируя автоматические отчеты о статусе проектов.","ar":"تقرير الحالة هو ميزة تتيح تكامل Jira و Confluence مع منصة الوكلاء الذكيين أو بيئة التطوير المتكاملة أو العميل المفضل لديك، وتوليد تقارير حالة المشروع آليًا"},"seo":{"title":{"en":"generate-status-report: Automated Jira and Confluence Rep...","zh":"生成状态报告指南：Jira 和 Confluence 集成","ja":"ステータスレポート生成ツール：Jira と Confluence の連携","ko":"상태 보고서 생성 가이드: Jira 및 Confluence 연동","es":"Guía de configuración de informes de estado con Herramien...","fr":"Guide d''installation de rapports d''état avec Outils d''Int...","de":"Einrichtungsleitfaden für Statusberichte mit KI-Tools","pt":"Guia de Configuração do Generate Status Report para Ferra...","ru":"Настройка ИИ Агентов: Generate Status Report для Jira и C...","ar":"دليل إعداد تقرير الحالة للوكلاء الذكيين"},"description":{"en":"Discover how to streamline project updates with generate-status-report. Learn how to set up automated Jira and Confluence reporting and unlock efficient proj...","zh":"使用 AI エージェント生成状态报告，自动查询 Jira 项目状态，分析问题，并将格式化报告发布到 Confluence","ja":"AIエージェントを使用してステータスレポートを生成し、Jira プロジェクトの状態を自動的に照会し、問題を分析し、Confluence に整形されたレポートを公開します","ko":"AI 에이전트를 사용하여 상태 보고서를 생성하고 Jira 프로젝트 상태를 자동으로 쿼리하여 문제를 분석하고 Confluence에 형식화된 보고서를 게시합니다","es":"Automatice la generación de informes de estado de proyectos con Jira y Confluence mediante Herramientas de Inteligencia Artificial","fr":"Automatisez la génération de rapports d''état de projets avec Jira et Confluence grâce aux Outils d''Intelligence Artificielle","de":"Automatisieren Sie die Erstellung von Statusberichten für Projekte mit Jira und Confluence mithilfe von KI-Tools","pt":"Aprenda a configurar o Generate Status Report para integrar Jira e Confluence com sua plataforma de IA preferida e automatizar relatórios de status de projetos","ru":"Узнайте, как настроить Generate Status Report для интеграции Jira и Confluence с вашей платформой ИИ и автоматизации отчетов о статусе проектов","ar":"تعلم كيفية إعداد تقرير الحالة لتكامل Jira و Confluence مع منصة الوكلاء الذكيين المفضلة لديك وتأتمة تقارير حالة المشروع"},"definition":{"en":"generate-status-report is a remote MCP Server skill that securely connects Jira and Confluence with AI agents or IDEs to generate and publish project status reports.","zh":"生成状态报告是一种 AI 技术，用于自动创建项目状态报告","ja":"ステータスレポート生成は、プロジェクトの状態レポートを自動的に作成する AI 技術です","ko":"상태 보고서 생성은 프로젝트 상태 보고서를 자동으로 생성하는 AI 기술입니다","es":"Un generate-status-report es una herramienta de inteligencia artificial que automatiza la generación de informes de estado de proyectos","fr":"Un generate-status-report est un outil d''intelligence artificielle qui automatise la génération de rapports d''état de projets","de":"Ein generate-status-report ist ein KI-Tool, das die Erstellung von Statusberichten für Projekte automatisiert","pt":"O que é Generate Status Report? É uma habilidade que gera relatórios de status de projetos automatizados a partir de dados de Jira e Confluence","ru":"Что такое Generate Status Report? Это навык, который генерирует автоматические отчеты о статусе проектов на основе данных Jira и Confluence","ar":"ما هو تقرير الحالة؟ هو ميزة توليد تقارير حالة المشروع آليًا من بيانات Jira و Confluence"},"features":{"en":["Automatically queries Jira for project status and issues","Analyzes issues and generates formatted status reports","Publishes reports to Confluence for team visibility","Supports interactive reporting for customized updates","Integrates with LLM, IDE, or agent platforms for seamless workflow"],"zh":["自动查询 Jira 项目状态","分析问题和进展","生成格式化报告","发布报告到 Confluence","支持自定义报告范围和受众","与 Jira 和 Confluence 集成"],"ja":["Jira プロジェクトの状態を自動的に照会","問題と進捗を分析","整形されたレポートを生成","レポートを Confluence に公開","レポートの範囲と対象者をカスタマイズ","Jira と Confluence との統合"],"ko":["Jira 프로젝트 상태를 자동으로 쿼리","문제와 진행 상황을 분석","형식화된 보고서 생성","Confluence에 보고서 게시","보고서 범위와 대상자를 사용자 정의","Jira 및 Confluence와의 통합"],"es":["Conexión segura con Jira y Confluence","Análisis automático de issues","Generación de informes formateados","Publicación en Confluence","Compatibilidad con LLM, IDE y plataformas de agentes","Interactividad para clarificar el alcance de los informes"],"fr":["Connexion sécurisée à Jira et Confluence","Analyse automatique des problèmes","Génération de rapports formatés","Publication sur Confluence","Compatibilité avec LLM, IDE et plateformes d''agents","Interactivité pour clarifier la portée des rapports"],"de":["Sichere Verbindung mit Jira und Confluence","Automatische Analyse von Issues","Erstellung formatierter Berichte","Veröffentlichung in Confluence","Kompatibilität mit LLM, IDE und Agenten-Plattformen","Interaktivität zur Klärung des Berichtsumfangs"],"pt":["Integração segura com Jira e Confluence","Geração automática de relatórios de status de projetos","Análise de problemas e bloqueios de projetos","Publicação de relatórios em Confluence","Suporte a múltiplas plataformas de IA e IDEs","Configuração interativa para definição de escopo e período de tempo"],"ru":["Безопасное подключение к Jira и Confluence","Автоматическая генерация отчетов о статусе проектов","Анализ проблем и блокировок проектов","Публикация отчетов в Confluence","Поддержка нескольких платформ ИИ и IDE","Интерактивная настройка для определения объема и периода времени"],"ar":["تكامل آمن مع Jira و Confluence","توليد آلي لتقارير حالة المشروع","تحليل المشاكل وحواجز المشروع","نشر التقارير في Confluence","دعم منصات الوكلاء الذكيين والبيئات المتكاملة المتعددة","إعداد تفاعلي لتحديد النطاق وفترة الزمن"]},"keywords":{"en":["how to use generate-status-report","generate-status-report setup guide","Jira and Confluence reporting tools","automated project status updates","generate-status-report alternative","generate-status-report vs manual reporting","Confluence report generation","Jira report automation"],"zh":["AI 技术","状态报告","Jira 集成","Confluence 集成","项目管理","自动报告","状态报告生成","AI 에ージェント","生成状态报告"],"ja":["AI 技術","ステータスレポート","Jira 統合","Confluence 統合","プロジェクト管理","自動レポート","ステータスレポート生成","AIエージェント","ステータスレポートツール"],"ko":["AI 기술","상태 보고서","Jira 연동","Confluence 연동","프로젝트 관리","자동 보고서","상태 보고서 생성","AI 에이전트","상태 보고서 생성기"],"es":["informes de estado","proyectos de software","Herramientas de Inteligencia Artificial","Jira","Confluence","LLM","IDE","plataformas de agentes","generación automática de informes","análisis de issues"],"fr":["rapports d''état","projets de logiciel","Outils d''Intelligence Artificielle","Jira","Confluence","LLM","IDE","plateformes d''agents","génération automatique de rapports","analyse de problèmes"],"de":["Statusberichte","Software-Projekte","KI-Tools","Jira","Confluence","LLM","IDE","Agenten-Plattformen","automatische Erstellung von Berichten","Analyse von Issues"],"pt":["Generate Status Report","relatórios de status de projetos","integração Jira Confluence","ferramentas de IA","automatização de relatórios","geração de relatórios","análise de projetos","bloqueios de projetos","publicação em Confluence"],"ru":["Generate Status Report","отчеты о статусе проектов","интеграция Jira Confluence","ИИ Агенты","автоматизация отчетов","генерация отчетов","анализ проектов","блокировки проектов","публикация в Confluence"],"ar":["تقرير الحالة","تقارير حالة المشروع","تكامل Jira Confluence","الوكلاء الذكيين","تأتمة التقارير","توليد التقارير","تحليل المشاريع","حواجز المشاريع","نشر في Confluence"]}},"owner":"atlassian","repo":"atlassian-mcp-server","repoPath":"atlassian/atlassian-mcp-server","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.320Z","topics":[],"category":"community","skillMd":{"name":"generate-status-report","description":"Generate project status reports from Jira issues and publish to Confluence. When Claude needs to: (1) Create a status report for a project, (2) Summarize project progress or updates, (3) Generate weekly/daily reports from Jira, (4) Publish status summaries to Confluence, or (5) Analyze project blockers and completion. Queries Jira issues, categorizes by status/priority, and creates formatted reports for delivery managers and executives.","bodyPreview":"# Generate Status Report\n\n## Keywords\nstatus report, project status, weekly update, daily standup, Jira report, project summary, blockers, progress update, Confluence report, sprint report, project update, publish to Confluence, write to Confluence, post report\n\nAutomatically query Jira for project status, analyze issues, and generate formatted status reports published to Confluence.\n\n**CRITICAL**: This skill should be **interactive**. Always clarify scope (time period, audience, Confluence dest","body":"# Generate Status Report\n\n## Keywords\nstatus report, project status, weekly update, daily standup, Jira report, project summary, blockers, progress update, Confluence report, sprint report, project update, publish to Confluence, write to Confluence, post report\n\nAutomatically query Jira for project status, analyze issues, and generate formatted status reports published to Confluence.\n\n**CRITICAL**: This skill should be **interactive**. Always clarify scope (time period, audience, Confluence destination) with the user before or after generating the report. Do not silently skip Confluence publishing—always offer it.\n\n## Workflow\n\nGenerating a status report follows these steps:\n\n1. **Identify scope** - Determine project, time period, and target audience\n2. **Query Jira** - Fetch relevant issues using JQL queries\n3. **Analyze data** - Categorize issues and identify key insights\n4. **Format report** - Structure content based on audience and purpose\n5. **Publish to Confluence** - Create or update a page with the report\n\n## Step 1: Identify Scope\n\n**IMPORTANT**: If the user''s request is missing key information, ASK before proceeding with queries. Do not assume defaults without confirmation for Confluence publishing.\n\nClarify these details:\n\n**Project identification:**\n- Which Jira project key? (e.g., \"PROJ\", \"ENG\", \"MKTG\")\n- If the user mentions a project by name but not key, search Jira to find the project key\n\n**Time period:**\n- If not specified, ask: \"What time period should this report cover? (default: last 7 days)\"\n- Options: Weekly (7 days), Daily (24 hours), Sprint-based (2 weeks), Custom period\n\n**Target audience:**\n- If not specified, ask: \"Who is this report for? (Executives/Delivery Managers, Team-level, or Daily standup)\"\n- **Executives/Delivery Managers**: High-level summary with key metrics and blockers\n- **Team-level**: Detailed breakdown with issue-by-issue status  \n- **Daily standup**: Brief update on yesterday/today/blockers\n\n**Report destination:**\n- **ALWAYS ASK** if not specified: \"Would you like me to publish this report to Confluence? If so, which space should I use?\"\n- If user says yes: Ask for space name or offer to list available spaces\n- Determine: New page or update existing page?\n- Ask about parent page if creating under a specific section\n\n## Step 2: Query Jira\n\nUse the `searchJiraIssuesUsingJql` tool to fetch issues. Build JQL queries based on report needs.\n\n### Common Query Patterns\n\nFor comprehensive queries, use the `scripts/jql_builder.py` utility to programmatically build JQL strings. For quick queries, reference `references/jql-patterns.md` for examples.\n\n**All open issues in project:**\n```jql\nproject = \"PROJECT_KEY\" AND status != Done ORDER BY priority DESC, updated DESC\n```\n\n**Issues updated in last week:**\n```jql\nproject = \"PROJECT_KEY\" AND updated >= -7d ORDER BY priority DESC\n```\n\n**High priority and blocked issues:**\n```jql\nproject = \"PROJECT_KEY\" AND (priority IN (Highest, High) OR status = Blocked) AND status != Done ORDER BY priority DESC\n```\n\n**Completed in reporting period:**\n```jql\nproject = \"PROJECT_KEY\" AND status = Done AND resolved >= -7d ORDER BY resolved DESC\n```\n\n### Query Strategy\n\nFor most reports, execute multiple targeted queries rather than one large query:\n\n1. **Completed issues**: Get recently resolved tickets\n2. **In-progress issues**: Get active work items\n3. **Blocked issues**: Get blockers requiring attention\n4. **High priority open**: Get critical upcoming work\n\nUse `maxResults: 100` for initial queries. If pagination is needed, use `nextPageToken` from results.\n\n### Data to Extract\n\nFor each issue, capture:\n- `key` (e.g., \"PROJ-123\")\n- `summary` (issue title)\n- `status` (current state)\n- `priority` (importance level)\n- `assignee` (who''s working on it)\n- `created` / `updated` / `resolved` dates\n- `description` (if needed for context on blockers)\n\n## Step 3: Analyze Data\n\nProcess the retrieved issues to identify:\n\n**Metrics:**\n- Total issues by status (Done, In Progress, Blocked, etc.)\n- Completion rate (if historical data available)\n- Number of high priority items\n- Unassigned issue count\n\n**Key insights:**\n- Major accomplishments (recently completed high-value items)\n- Critical blockers (blocked high priority issues)\n- At-risk items (overdue or stuck in progress)\n- Resource bottlenecks (one assignee with many issues)\n\n**Categorization:**\nGroup issues logically:\n- By status (Done, In Progress, Blocked)\n- By priority (Highest → Low)\n- By assignee or team\n- By component or epic (if relevant)\n\n## Step 4: Format Report\n\nSelect the appropriate template based on audience. Templates are in `references/report-templates.md`.\n\n### For Executives and Delivery Managers\n\nUse **Executive Summary Format**:\n- Brief overall status (🟢 On Track / 🟡 At Risk / 🔴 Blocked)\n- Key metrics (total, completed, in progress, blocked)\n- Top 3 highlights (major accomplishments)\n- Critical blockers with impact\n- Upcoming priorities\n\n**Keep it concise** - 1-2 pages maximum. Focus on what matters to decision-makers.\n\n### For Team-Level Reports\n\nUse **Detailed Technical Format**:\n- Completed issues listed with keys\n- In-progress issues with assignee and priority\n- Blocked issues with blocker description and action needed\n- Risks and dependencies\n- Next period priorities\n\n**Include more detail** - Team needs issue-level visibility.\n\n### For Daily Updates\n\nUse **Daily Standup Format**:\n- What was completed yesterday\n- What''s planned for today\n- Current blockers\n- Brief notes\n\n**Keep it brief** - This is a quick sync, not comprehensive analysis.\n\n## Step 5: Publish to Confluence\n\n**After generating the report, ALWAYS offer to publish to Confluence** (unless user explicitly said not to).\n\nIf user hasn''t specified Confluence details yet, ask:\n- \"Would you like me to publish this report to Confluence?\"\n- \"Which Confluence space should I use?\"\n- \"Should this be nested under a specific parent page?\"\n\nUse the `createConfluencePage` tool to publish the report.\n\n**Page creation:**\n```\ncreateConfluencePage(\n    cloudId=\"[obtained from getConfluenceSpaces or URL]\",\n    spaceId=\"[numerical space ID]\",\n    title=\"[Project Name] - Status Report - [Date]\",\n    body=\"[formatted report in Markdown]\",\n    contentFormat=\"markdown\",\n    parentId=\"[optional - parent page ID if nesting under another page]\"\n)\n```\n\n**Title format examples:**\n- \"Project Phoenix - Weekly Status - Dec 3, 2025\"\n- \"Engineering Sprint 23 - Status Report\"\n- \"Q4 Initiatives - Status Update - Week 49\"\n\n**Body formatting:**\nWrite the report content in Markdown. The tool will convert it to Confluence format. Use:\n- Headers (`#`, `##`, `###`) for structure\n- Bullet points for lists\n- Bold (`**text**`) for emphasis\n- Tables for metrics if needed\n- Links to Jira issues: `[PROJ-123](https://yourinstance.atlassian.net/browse/PROJ-123)`\n\n**Best practices:**\n- Include the report date prominently\n- Link directly to relevant Jira issues\n- Use consistent naming conventions for recurring reports\n- Consider creating under a \"Status Reports\" parent page for organization\n\n### Finding the Right Space\n\nIf the user doesn''t specify a Confluence space:\n\n1. Use `getConfluenceSpaces` to list available spaces\n2. Look for spaces related to the project (matching project name or key)\n3. If unsure, ask the user which space to use\n4. Default to creating in the most relevant team or project space\n\n### Updating Existing Reports\n\nIf updating an existing page instead of creating new:\n\n1. Get the current page content:\n```\ngetConfluencePage(\n    cloudId=\"...\",\n    pageId=\"123456\",\n    contentFormat=\"markdown\"\n)\n```\n\n2. Update the page with new content:\n```\nupdateConfluencePage(\n    cloudId=\"...\",\n    pageId=\"123456\",\n    body=\"[updated report content]\",\n    contentFormat=\"markdown\",\n    versionMessage=\"Updated with latest status - Dec 8, 2025\"\n)\n```\n\n## Complete Example Workflow\n\n**User request:** \"Generate a status report for Project Phoenix and publish it to Confluence\"\n\n**Step 1 - Identify scope:**\n- Project: Phoenix (need to find project key)\n- Time period: Last week (default)\n- Audience: Not specified, assume executive level\n- Destination: Confluence, need to find appropriate space\n\n**Step 2 - Query Jira:**\n```python\n# Find project key first\nsearchJiraIssuesUsingJql(\n    cloudId=\"...\",\n    jql=''project = \"PHOENIX\" OR project = \"PHX\"'',\n    maxResults=1\n)\n\n# Query completed issues\nsearchJiraIssuesUsingJql(\n    cloudId=\"...\",\n    jql=''project = \"PHX\" AND status = Done AND resolved >= -7d'',\n    maxResults=50\n)\n\n# Query blocked issues\nsearchJiraIssuesUsingJql(\n    cloudId=\"...\",\n    jql=''project = \"PHX\" AND status = Blocked'',\n    maxResults=50\n)\n\n# Query in-progress high priority\nsearchJiraIssuesUsingJql(\n    cloudId=\"...\",\n    jql=''project = \"PHX\" AND status IN (\"In Progress\", \"In Review\") AND priority IN (Highest, High)'',\n    maxResults=50\n)\n```\n\n**Step 3 - Analyze:**\n- 15 issues completed (metrics)\n- 3 critical blockers (key insight)\n- Major accomplishment: API integration completed (highlight)\n\n**Step 4 - Format:**\nUse Executive Summary Format from templates. Create concise report with metrics, highlights, and blockers.\n\n**Step 5 - Publish:**\n```python\n# Find appropriate space\ngetConfluenceSpaces(cloudId=\"...\")\n\n# Create page\ncreateConfluencePage(\n    cloudId=\"...\",\n    spaceId=\"12345\",\n    title=\"Project Phoenix - Weekly Status - Dec 3, 2025\",\n    body=\"[formatted markdown report]\",\n    contentFormat=\"markdown\"\n)\n```\n\n## Tips for Quality Reports\n\n**Be data-driven:**\n- Include specific numbers and metrics\n- Reference issue keys directly\n- Show trends when possible (e.g., \"completed 15 vs 12 last week\")\n\n**Highlight what matters:**\n- Lead with the most important information\n- Flag blockers prominently\n- Celebrate significant wins\n\n**Make it actionable:**\n- For blockers, state what action is needed and from whom\n- For risks, provide mitigation options\n- For priorities, be specific about next steps\n\n**Keep it consistent:**\n- Use the same format for recurring reports\n- Maintain predictable structure\n- Include comparable metrics week-over-week\n\n**Provide context:**\n- Link to Jira for details\n- Explain the impact of blockers\n- Connect work to business objectives when possible\n\n## Resources\n\n### scripts/jql_builder.py\nPython utility for programmatically building JQL queries. Use this when you need to construct complex or dynamic queries. Import and use the helper functions rather than manually concatenating JQL strings.\n\n### references/jql-patterns.md\nQuick reference of common JQL query patterns for status reports. Use this for standard queries or as a starting point for custom queries.\n\n### references/report-templates.md\nDetailed templates for different report types and audiences. Reference this to select the appropriate format and structure for your report.\n"},"lastSynced":"2026-03-08T02:02:57.078Z","agentAnalysis":{"suitability":{"en":"Ideal for Project Management Agents requiring automated Jira and Confluence integration for status reporting.","zh":"适合需要自动化Jira和Confluence集成以进行状态报告的项目管理代理。","ja":"JiraおよびConfluenceの自動化された統合を必要とするプロジェクト管理エージェントに最適です。","ko":"상태 보고를 위해 자동화된 Jira 및 Confluence 통합을 필요로 하는 프로젝트 관리 에이전트에 적합합니다.","es":"Ideal para Agentes de Gestión de Proyectos que requieren integración automática de Jira y Confluence para informes de estado.","fr":"Idéal pour les agents de gestion de projet nécessitant une intégration automatisée de Jira et Confluence pour les rapports de statut.","de":"Ideal für Projektmanagement-Agenten, die eine automatisierte Jira- und Confluence-Integration für Statusberichte benötigen.","pt":"Ideal para Agentes de Gerenciamento de Projetos que exigem integração automática do Jira e Confluence para relatórios de status.","ru":"Идеально для агентов управления проектами, требующих автоматической интеграции Jira и Confluence для отчетов о статусе.","ar":"مثالي لعمليات إدارة المشاريع التي تتطلب دمجًا تلقائيًا لجيرا وكونفلونس لتقارير الحالة."},"recommendation":{"en":"Empowers agents to generate formatted status reports by querying Jira and publishing to Confluence, utilizing project management protocols and APIs for seamless integration, and supporting daily standups, weekly updates, and sprint reports.","zh":"赋予代理人通过查询Jira并将格式化的状态报告发布到Confluence的能力，利用项目管理协议和API实现无缝集成，并支持每日站立会议、每周更新和冲刺报告。","ja":"エージェントがJiraに照会し、Confluenceにフォーマットされたステータス報告を公開する機能を提供し、プロジェクト管理プロトコルとAPIを使用してシームレスな統合を実現し、毎日の立ち上がり会議、毎週の更新、スプリント報告をサポートします。","ko":"에이전트가 Jira를 쿼리하고 Confluence에 형식화된 상태 보고서를 게시할 수 있는 기능을 제공하여 프로젝트 관리 프로토콜 및 API를 사용하여 무힘한 통합을 지원하며, 일일 스탠드업 미팅, 주간 업데이트 및 스프린트 보고서를 지원합니다.","es":"Habilita a los agentes a generar informes de estado formateados consultando Jira y publicando en Confluence, utilizando protocolos y API de gestión de proyectos para una integración sin problemas, y admitiendo reuniones diarias, actualizaciones semanales e informes de sprint.","fr":"Permet aux agents de générer des rapports de statut formatés en interrogeant Jira et en publiant sur Confluence, en utilisant des protocoles et des API de gestion de projet pour une intégration transparente, et en prenant en charge les réunions quotidiennes, les mises à jour hebdomadaires et les rapports de sprint.","de":"Ermächtigt Agenten, formatierte Statusberichte zu generieren, indem sie Jira abfragen und in Confluence veröffentlichen, wobei Projektmanagementprotokolle und APIs für eine nahtlose Integration verwendet werden und tägliche Stand-ups, wöchentliche Updates und Sprintberichte unterstützt werden.","pt":"Habilita os agentes a gerar relatórios de status formatados, consultando o Jira e publicando no Confluence, utilizando protocolos e APIs de gerenciamento de projetos para integração sem interrupções, e suportando reuniões diárias, atualizações semanais e relatórios de sprint.","ru":"Наделяет агентов возможностью генерировать отформатированные отчеты о статусе, запрашивая Jira и публикуя в Confluence, используя протоколы и API управления проектами для бесшовной интеграции, и поддерживая ежедневные встречи, еженедельные обновления и отчеты о спринте.","ar":"تمكين الوكلاء من توليد تقارير الحالة المنسقة عن طريق استعلام جيرا ونشرها إلى كونفلونس، باستخدام بروتوكولات وواجهات برمجة التطبيقات لإدارة المشاريع من أجل التكامل السلس، ودعم اجتماعات اليومية والتحديثات الأسبوعية وتقارير السبرينت."},"useCases":{"en":["Automating project status updates","Generating daily standup reports","Publishing sprint reports to Confluence","Analyzing Jira issues for blockers and progress updates"],"zh":["自动化项目状态更新","生成每日站立报告","将冲刺报告发布到Confluence","分析Jira问题以获取阻塞器和进度更新"],"ja":["プロジェクトのステータス更新の自動化","毎日の立ち上がり報告の生成","スプリント報告をConfluenceに公開","Jiraの問題を分析してブロッカーと進度更新を取得"],"ko":["프로젝트 상태 업데이트 자동화","일일 스탠드업 보고서 생성","스프린트 보고서를 Confluence에 게시","Jira 문제 분석을 통해 블로커 및 진행 상황 업데이트"],"es":["Automatizar las actualizaciones de estado del proyecto","Generar informes de reuniones diarias","Publicar informes de sprint en Confluence","Analizar problemas de Jira para bloqueos y actualizaciones de progreso"],"fr":["Automatiser les mises à jour de statut de projet","Générer des rapports de réunions quotidiennes","Publier des rapports de sprint sur Confluence","Analyser les problèmes Jira pour les bloqueurs et les mises à jour de progression"],"de":["Automatisierung von Projektstatus-Updates","Generierung von Tagesberichten","Veröffentlichen von Sprintberichten in Confluence","Analyse von Jira-Problemen für Blockierungen und Fortschrittsupdates"],"pt":["Automatizar atualizações de status do projeto","Gerar relatórios de reuniões diárias","Publicar relatórios de sprint no Confluence","Analizar problemas do Jira para bloqueadores e atualizações de progresso"],"ru":["Автоматизировать обновления статуса проекта","Генерировать отчеты о ежедневных встречах","Публиковать отчеты о спринте в Confluence","Анализировать проблемы Jira для блокировщиков и обновлений прогресса"],"ar":["تحديث حالة المشروع تلقائيًا","توليد تقارير للاجتماعات اليومية","نشر تقارير السبرينت في كونفلونس","تحليل مشاكل جيرا للحصول على حجب وتحديثات التقدم"]},"limitations":{"en":["Requires Jira and Confluence access","Needs clarification on scope and audience","Interactive capability is critical"],"zh":["需要Jira和Confluence的访问权限","需要对范围和受众进行澄清","交互能力至关重要"],"ja":["JiraおよびConfluenceへのアクセスが必要","範囲と対象者についての明確化が必要","対話型機能が重要"],"ko":["Jira 및 Confluence에 대한 액세스가 필요함","범위 및 대상에 대한 명확성이 필요함","대화형 기능이 중요함"],"es":["Requiere acceso a Jira y Confluence","Necesita aclaración sobre el alcance y la audiencia","La capacidad interactiva es crítica"],"fr":["Nécessite un accès à Jira et Confluence","A besoin d''une clarification sur la portée et le public","La capacité interactive est critique"],"de":["Benötigt Zugriff auf Jira und Confluence","Benötigt Klarstellung zum Umfang und zur Zielgruppe","Die interaktive Fähigkeit ist kritisch"],"pt":["Exige acesso ao Jira e Confluence","Necessita de esclarecimento sobre o escopo e o público-alvo","A capacidade interativa é crítica"],"ru":["Требует доступа к Jira и Confluence","Требует разъяснения по объему и аудитории","Интерактивная возможность является критической"],"ar":["يتطلب الوصول إلى جيرا وكونفلونس","يحتاج إلى توضيح النطاق والجمهور المستهدف","القابلية التفاعلية هي حرجة"]},"version":4},"contentHash":"4af95baa652def9230dd1f87713e779438fe87b3e3da159522288841a5f251d4","qualityScore":39}');
