INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('atlassian/atlassian-mcp-server/generate-status-report', 'generate-status-report', 'atlassian', 'atlassian-mcp-server', 'community', 'generate-status-report atlassian atlassian-mcp-server community The generate-status-report skill automates project status updates by querying Jira and publishing formatted reports to Confluence, benefiting development teams and project managers. 生成状态报告技能允许您自动查询 Jira 项目状态，分析问题，并将格式化报告发布到 Confluence ステータスレポート生成スキルは、Jira プロジェクトの状態を自動的に照会し、問題を分析し、Confluence に整形されたレポートを公開します 상태 보고서 생성 스킬을 사용하여 Jira 프로젝트 상태를 자동으로 쿼리하여 문제를 분석하고 Confluence에 형식화된 보고서를 게시합니다 El skill generate-status-report permite la generación automática de informes de estado de proyectos con Jira y Confluence. Analiza issues y publica informes formateados en Confluence. Le skill generate-status-report permet la génération automatique de rapports d''état de projets avec Jira et Confluence. Il analyse les problèmes et publie des rapports formatés sur Confluence. Das Skill generate-status-report ermöglicht die automatische Erstellung von Statusberichten für Projekte mit Jira und Confluence. Es analysiert Issues und veröffentlicht formatierte Berichte in Confluence. O Generate Status Report é uma habilidade que permite a integração segura de Jira e Confluence com sua plataforma de IA, IDE ou agente preferida, gerando relatórios de status de projetos automatizados. Generate Status Report - это навык, который позволяет безопасно подключить Jira и Confluence к вашей платформе ИИ, IDE или агенту, генерируя автоматические отчеты о статусе проектов. تقرير الحالة هو ميزة تتيح تكامل Jira و Confluence مع منصة الوكلاء الذكيين أو بيئة التطوير المتكاملة أو العميل المفضل لديك، وتوليد تقارير حالة المشروع آليًا how to use generate-status-report generate-status-report setup guide Jira and Confluence reporting tools automated project status updates generate-status-report alternative generate-status-report vs manual reporting Confluence report generation Jira report automation AI 技术 状态报告 Jira 集成 Confluence 集成 项目管理 自动报告 状态报告生成 AI 에ージェント 生成状态报告 Automatically queries Jira for project status and issues Analyzes issues and generates formatted status reports Publishes reports to Confluence for team visibility Supports interactive reporting for customized updates Integrates with LLM, IDE, or agent platforms for seamless workflow generate-status-report is a remote MCP Server skill that securely connects Jira and Confluence with AI agents or IDEs to generate and publish project status reports.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('backengineering/llvm-msvc/llvm-tooling', 'community', 'backengineering', 'llvm-msvc', 'backengineering/llvm-msvc', 'llvm-tooling', 0, 0, 39, '2026-03-08T01:57:15.324Z', '2026-03-08T02:03:00.247Z', '382d6821ce259cd3d39184233072f00c3a7ae84d222c1de1f4df76e070e33d6e', '{"id":"backengineering/llvm-msvc/llvm-tooling","name":"llvm-tooling","description":{"en":"The llvm-tooling skill enables developers to create tools using LLVM/Clang infrastructure for source code analysis, debugging, and IDE integration, with a focus on Clang plugin development.","zh":"本文介绍LLVM工具开发，使用Clang插件进行源代码分析、调试和IDE集成","ja":"本稿ではLLVM Toolingの開発方法を紹介し、Clangプラグインを使用したソースコード分析、デバッグ、IDE統合を実現します","ko":"본 문서에서는 LLVM 툴링 개발 방법을 소개하고 Clang 플러그인을 사용한 소스 코드 분석, 디버깅, IDE 통합을 실현합니다","es":"llvm-tooling es una bifurcación de LLVM con compatibilidad explícita con MSVC 2022, ideal para desarrollar herramientas de análisis de código fuente","fr":"llvm-tooling est une bifurcation de LLVM avec une compatibilité explicite avec MSVC 2022, idéale pour développer des outils d''analyse de code source","de":"llvm-tooling ist eine Abspaltung von LLVM mit expliziter Kompatibilität mit MSVC 2022, ideal für die Entwicklung von Tools für die Quellcode-Analyse","pt":"O llvm-tooling é uma bifurcação do LLVM com compatibilidade explícita com recursos do MSVC 2022, permitindo o desenvolvimento de ferramentas de análise de código e depuração.","ru":"llvm-tooling - это форк LLVM с явной совместимостью с функциями MSVC 2022, позволяющий разрабатывать инструменты анализа кода и отладки.","ar":"llvm-tooling هو فرع من LLVM مع توافق صريح مع ميزات MSVC 2022، مما يسمح بتصميم أدوات تحليل وتصحيح الأخطاء"},"seo":{"title":{"en":"llvm-tooling: Clang Plugin Development Setup Guide | AI A...","zh":"LLVM工具开发指南：使用Clang插件进行源代码分析","ja":"LLVM Tooling Setup Guide: Clangプラグインを使用したソースコード分析","ko":"