INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('backengineering/llvm-msvc/llvm-tooling', 'llvm-tooling', 'backengineering', 'llvm-msvc', 'community', 'llvm-tooling backengineering llvm-msvc community The llvm-tooling skill enables developers to create tools using LLVM/Clang infrastructure for source code analysis, debugging, and IDE integration, with a focus on Clang plugin development. 本文介绍LLVM工具开发，使用Clang插件进行源代码分析、调试和IDE集成 本稿ではLLVM Toolingの開発方法を紹介し、Clangプラグインを使用したソースコード分析、デバッグ、IDE統合を実現します 본 문서에서는 LLVM 툴링 개발 방법을 소개하고 Clang 플러그인을 사용한 소스 코드 분석, 디버깅, IDE 통합을 실현합니다 llvm-tooling es una bifurcación de LLVM con compatibilidad explícita con MSVC 2022, ideal para desarrollar herramientas de análisis de código fuente llvm-tooling est une bifurcation de LLVM avec une compatibilité explicite avec MSVC 2022, idéale pour développer des outils d''analyse de code source llvm-tooling ist eine Abspaltung von LLVM mit expliziter Kompatibilität mit MSVC 2022, ideal für die Entwicklung von Tools für die Quellcode-Analyse O llvm-tooling é uma bifurcação do LLVM com compatibilidade explícita com recursos do MSVC 2022, permitindo o desenvolvimento de ferramentas de análise de código e depuração. llvm-tooling - это форк LLVM с явной совместимостью с функциями MSVC 2022, позволяющий разрабатывать инструменты анализа кода и отладки. llvm-tooling هو فرع من LLVM مع توافق صريح مع ميزات MSVC 2022، مما يسمح بتصميم أدوات تحليل وتصحيح الأخطاء how to use llvm-tooling llvm-tooling vs clang llvm-tooling install guide what is llvm-tooling clang plugin development tutorial llvm-tooling alternative to gcc LLVM工具开发 Clang插件 源代码分析 调试 IDE集成 RecursiveASTVisitor LLVM/Clang基础设施 Develops Clang plugins as dynamically loaded libraries to extend Clang''s functionality during compilation Utilizes the RecursiveASTVisitor class for source code analysis Includes the clang/Frontend/FrontendPluginRegistry.h header file for plugin registration Leverages the clang/AST/ASTConsumer.h header file for AST consumption Supports integration with MSVC 2022 features llvm-tooling is a fork of LLVM with explicit compatibility with MSVC 2022 features, allowing for the development of tools using LLVM/Clang infrastructure.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('husamql3/pstrack/zustand-state-management', 'community', 'husamql3', 'pstrack', 'husamql3/pstrack', 'zustand-state-management', 0, 0, 39, '2026-03-08T01:57:15.325Z', '2026-03-08T02:03:01.536Z', 'd178465b26c2f4b50da29132b46dc87adc1b03c503877a901c86ecb8254eb38c', '{"id":"husamql3/pstrack/zustand-state-management","name":"zustand-state-management","description":{"en":"zustand-state-management helps React developers solve state management issues. It supports TypeScript 5+ and React 18-19, making it a great tool for building scalable applications","zh":"Zustand状态管理是一个帮助您解决、跟踪和增长的平台，支持TypeScript和React 18-19","ja":"Zustand State Managementは、TypeScriptとReact 18-19をサポートする、解決、追跡、成長を助けるプラットフォームです","ko":"Zustand 상태 관리는 TypeScript 및 React 18-19를 지원하는 해결, 추적, 성장 플랫폼입니다","es":"Zustand State Management es una plataforma que ayuda a resolver, rastrear y crecer en proyectos React con TypeScript y React 18-19","fr":"Zustand State Management est une plateforme qui aide à résoudre, suivre et faire croître les projets React avec TypeScript et React 18-19","de":"Zustand State Management ist eine Plattform, die hilft, Probleme zu lösen, zu verfolgen und zu wachsen in React-Projekten mit TypeScript und React 18-19","pt":"O Zustand State Management é uma plataforma que ajuda a resolver, rastrear e crescer com React e TypeScript","ru":"Zustand State Management - это платформа, которая помогает решать, отслеживать и расти с React и TypeScript","ar":"Zustand State Management هو منصة تساعد على حل وتتبع ونمو مع React و TypeScript"},"seo":{"title":{"en":"zustand-state-management: Setup Guide for React Developer...","zh":" Zustand 状态管理Setup Guide - AIエージェント解决方案","ja":"Zustand State Management Setup Guide - AIエージェントのベストプラクティス","ko":"Zustand 상태 관리 설정 가이드 - AI 툴을 위한 리액트 통합","es":"Guía de configuración de Zustand State Management para React","fr":"Guide de mise en place de Zustand State Management pour R...","de":"Einrichtungsleitfaden für Zustand State Management mit React","pt":"Guia de Configuração do Zustand State Management para Des...","ru":"ИИ Агенты: Руководство по Настройке Zustand State Management","ar":"دليل إعداد Zustand State Management للبرمجة"},"description":{"en":"Get started with zustand-state-management for React 18-19 and TypeScript 5+. Learn how to install and use zustand@5.0.10 for state management","zh":"了解Zustand状态管理的最新版本和依赖项，使用TypeScript和React 18-19构建强大的应用程序","ja":"Zustand State Managementの最新バージョンと依存関係を確認し、TypeScriptとReact 18-19を使用して強力なアプリケーションを構築する","ko":"Zustand 상태 관리의 최신 버전과 종속성을 확인하고 TypeScript 및 React 18-19를 사용하여 강력한 애플리케이션을 구축하세요","es":"Aprende a implementar Zustand State Management en tus proyectos React con nuestra guía paso a paso","fr":"Découvrez comment mettre en place Zustand State Management dans vos projets React avec notre guide étape par étape","de":"Erfahren Sie, wie Sie Zustand State Management in Ihren React-Projekten implementieren können, mit unserer Schritt-für-Schritt-Anleitung","pt":"Aprenda a configurar o Zustand State Management com React e TypeScript para melhorar a gestão de estado em suas aplicações","ru":"Узнайте, как настроить Zustand State Management с React и TypeScript для улучшения управления состоянием в ваших приложениях","ar":"تعرف على كيفية إعداد Zustand State Management مع React و TypeScript لتحسين إدارة الحالة في تطبيقاتك"},"definition":{"en":"zustand-state-management is a platform that provides a simple and efficient way to manage state in React applications using TypeScript","zh":"Zustand状态管理是一种使用TypeScript和React 18-19的状态管理解决方案","ja":"Zustand State Managementは、TypeScriptとReact 18-19を使用した状態管理ソリューションです","ko":"Zustand 상태 관리는 TypeScript 및 React 18-19를 사용하는 상태 관리 솔루션입니다","es":"Zustand State Management es una biblioteca de gestión de estado para React que utiliza TypeScript","fr":"Zustand State Management est une bibliothèque de gestion d''état pour React qui utilise TypeScript","de":"Zustand State Management ist eine Bibliothek für Statusverwaltung in React, die TypeScript verwendet","pt":"O que é Zustand State Management? É uma biblioteca de gerenciamento de estado para React com suporte a TypeScript","ru":"Что такое Zustand State Management? Это библиотека управления состоянием для React с поддержкой TypeScript","ar":"ما هو Zustand State Management؟ هو مكتبة لإدارة الحالة ل React مع دعم TypeScript"},"features":{"en":["Supports React 18-19 for building scalable applications","Compatible with TypeScript 5+ for robust type checking","Uses the `create<T>()()` function for initializing stores","Allows for easy state management using the `set` function","Installs via npm using the `npm install zustand` command","Supports hot-reload for efficient development"],"zh":["支持TypeScript 5+","兼容React 18-19","使用create<T>()()函数创建存储","支持双括号语法","提供increase函数用于更新状态"],"ja":["TypeScript 5+をサポート","React 18-19と互換性がある","create<T>()()関数を使用してストアを作成","二重括弧構文をサポート","increase関数を提供して状態を更新"],"ko":["TypeScript 5+ 지원","React 18-19와 호환","create<T>()() 함수를 사용하여 저장소 생성","이중括호 구문 지원","increase 함수를 제공하여 상태 업데이트하기"],"es":["Compatibilidad con React 18-19","Soporte para TypeScript 5+","Implementación de almacén de estado con create<T>()()","Métodos para aumentar y disminuir el estado","Integración con la CLI de npm"],"fr":["Compatibilité avec React 18-19","Prise en charge de TypeScript 5+","Mise en œuvre d''un magasin d''état avec create<T>()()","Méthodes pour augmenter et diminuer l''état","Intégration avec la CLI de npm"],"de":["Kompatibilität mit React 18-19","Unterstützung für TypeScript 5+","Implementierung eines Statusspeichers mit create<T>()()","Methoden zum Erhöhen und Verringern des Status","Integration mit der npm-CLI"],"pt":["Suporte a React 18-19","Integração com TypeScript 5+","Criação de lojas de estado personalizadas com create<T>()()","Gestão de estado com increase e set","Compatibilidade com npm"],"ru":["Поддержка React 18-19","Интеграция с TypeScript 5+","Создание пользовательских хранилищ состояния с create<T>()()","Управление состоянием с increase и set","Совместимость с npm"],"ar":["دعم React 18-19","التكامل مع TypeScript 5+","إنشاء مخازن الحالة المخصصة مع create<T>()()","إدارة الحالة مع increase و set","التوافق مع npm"]},"keywords":{"en":["how to use zustand-state-management","zustand-state-management alternative","zustand-state-management setup guide","zustand-state-management vs mobx","zustand-state-management install","what is zustand-state-management","zustand-state-management react","zustand-state-management typescript","zustand-state-management tutorial"],"zh":["Zustand状态管理","TypeScript状态管理","React状态管理","AIエージェント解决方案"," Zustand最新版本"," Zustand依赖项"],"ja":["Zustand State Management","TypeScript状態管理","React状態管理","AIエージェントのベストプラクティス"," Zustand最新バージョン"," Zustand依存関係"],"ko":["Zustand 상태 관리","TypeScript 상태 관리","React 상태 관리","AI 툴을 위한 리액트 통합"," Zustand 최신 버전"," Zustand 종속성"],"es":["zustand state management","react state management","typescript react","gestión de estado react","bibliotecas de react","herramientas de desarrollo react","react 18-19","typescript 5+"],"fr":["zustand state management","gestion d''état react","typescript react","bibliothèques react","outils de développement react","react 18-19","typescript 5+","état react"],"de":["zustand state management","react statusverwaltung","typescript react","react-bibliotheken","entwicklertools react","react 18-19","typescript 5+","status react"],"pt":["zustand state management","react state management","typescript state management","gerenciamento de estado react","biblioteca de gerenciamento de estado","configuração do zustand","guia de configuração zustand"],"ru":["zustand state management","react состояние управления","typescript состояние управления","управление состоянием react","библиотека управления состоянием","настройка zustand","руководство по настройке zustand"],"ar":["zustand state management","إدارة الحالة react","typescript إدارة الحالة","مكتبة إدارة الحالة","إعداد zustand","دليل إعداد zustand","أدوات إدارة الحالة"]}},"owner":"husamql3","repo":"pstrack","repoPath":"husamql3/pstrack","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.325Z","topics":[],"category":"community","skillMd":{"name":"zustand-state-management","description":"|","bodyPreview":"# Zustand State Management\n\n**Last Updated**: 2026-01-21\n**Latest Version**: zustand@5.0.10 (released 2026-01-12)\n**Dependencies**: React 18-19, TypeScript 5+\n\n---\n\n## Quick Start\n\n```bash\nnpm install zustand\n```\n\n**TypeScript Store** (CRITICAL: use `create<T>()()` double parentheses):\n\n```typescript\nimport { create } from ''zustand''\n\ninterface BearStore {\n  bears: number\n  increase: (by: number) => void\n}\n\nconst useBearStore = create<BearStore>()((set) => ({\n  bears: 0,\n  increase: (by) => set((","body":"# Zustand State Management\n\n**Last Updated**: 2026-01-21\n**Latest Version**: zustand@5.0.10 (released 2026-01-12)\n**Dependencies**: React 18-19, TypeScript 5+\n\n---\n\n## Quick Start\n\n```bash\nnpm install zustand\n```\n\n**TypeScript Store** (CRITICAL: use `create<T>()()` double parentheses):\n\n```typescript\nimport { create } from ''zustand''\n\ninterface BearStore {\n  bears: number\n  increase: (by: number) => void\n}\n\nconst useBearStore = create<BearStore>()((set) => ({\n  bears: 0,\n  increase: (by) => set((state) => ({ bears: state.bears + by })),\n}))\n```\n\n**Use in Components**:\n\n```tsx\nconst bears = useBearStore((state) => state.bears)  // Only re-renders when bears changes\nconst increase = useBearStore((state) => state.increase)\n```\n\n---\n\n## Core Patterns\n\n**Basic Store** (JavaScript):\n\n```javascript\nconst useStore = create((set) => ({\n  count: 0,\n  increment: () => set((state) => ({ count: state.count + 1 })),\n}))\n```\n\n**TypeScript Store** (Recommended):\n\n```typescript\ninterface CounterStore { count: number; increment: () => void }\nconst useStore = create<CounterStore>()((set) => ({\n  count: 0,\n  increment: () => set((state) => ({ count: state.count + 1 })),\n}))\n```\n\n**Persistent Store** (survives page reloads):\n\n```typescript\nimport { persist, createJSONStorage } from ''zustand/middleware''\n\nconst useStore = create<UserPreferences>()(\n  persist(\n    (set) => ({ theme: ''system'', setTheme: (theme) => set({ theme }) }),\n    { name: ''user-preferences'', storage: createJSONStorage(() => localStorage) },\n  ),\n)\n```\n\n---\n\n## Critical Rules\n\n### Always Do\n\n✅ Use `create<T>()()` (double parentheses) in TypeScript for middleware compatibility\n✅ Define separate interfaces for state and actions\n✅ Use selector functions to extract specific state slices\n✅ Use `set` with updater functions for derived state: `set((state) => ({ count: state.count + 1 }))`\n✅ Use unique names for persist middleware storage keys\n✅ Handle Next.js hydration with `hasHydrated` flag pattern\n✅ Use `useShallow` hook for selecting multiple values\n✅ Keep actions pure (no side effects except state updates)\n\n### Never Do\n\n❌ Use `create<T>(...)` (single parentheses) in TypeScript - breaks middleware types\n❌ Mutate state directly: `set((state) => { state.count++; return state })` - use immutable updates\n❌ Create new objects in selectors: `useStore((state) => ({ a: state.a }))` - causes infinite renders\n❌ Use same storage name for multiple stores - causes data collisions\n❌ Access localStorage during SSR without hydration check\n❌ Use Zustand for server state - use TanStack Query instead\n❌ Export store instance directly - always export the hook\n\n---\n\n## Known Issues Prevention\n\nThis skill prevents **6** documented issues:\n\n### Issue #1: Next.js Hydration Mismatch\n\n**Error**: `\"Text content does not match server-rendered HTML\"` or `\"Hydration failed\"`\n\n**Source**:\n\n- [DEV Community: Persist middleware in Next.js](https://dev.to/abdulsamad/how-to-use-zustands-persist-middleware-in-nextjs-4lb5)\n- GitHub Discussions #2839\n\n**Why It Happens**:\nPersist middleware reads from localStorage on client but not on server, causing state mismatch.\n\n**Prevention**:\n\n```typescript\nimport { create } from ''zustand''\nimport { persist } from ''zustand/middleware''\n\ninterface StoreWithHydration {\n  count: number\n  _hasHydrated: boolean\n  setHasHydrated: (hydrated: boolean) => void\n  increase: () => void\n}\n\nconst useStore = create<StoreWithHydration>()(\n  persist(\n    (set) => ({\n      count: 0,\n      _hasHydrated: false,\n      setHasHydrated: (hydrated) => set({ _hasHydrated: hydrated }),\n      increase: () => set((state) => ({ count: state.count + 1 })),\n    }),\n    {\n      name: ''my-store'',\n      onRehydrateStorage: () => (state) => {\n        state?.setHasHydrated(true)\n      },\n    },\n  ),\n)\n\n// In component\nfunction MyComponent() {\n  const hasHydrated = useStore((state) => state._hasHydrated)\n\n  if (!hasHydrated) {\n    return <div>Loading...</div>\n  }\n\n  // Now safe to render with persisted state\n  return <ActualContent />\n}\n```\n\n### Issue #2: TypeScript Double Parentheses Missing\n\n**Error**: Type inference fails, `StateCreator` types break with middleware\n\n**Source**: [Official Zustand TypeScript Guide](https://zustand.docs.pmnd.rs/guides/typescript)\n\n**Why It Happens**:\nThe currying syntax `create<T>()()` is required for middleware to work with TypeScript inference.\n\n**Prevention**:\n\n```typescript\n// ❌ WRONG - Single parentheses\nconst useStore = create<MyStore>((set) => ({\n  // ...\n}))\n\n// ✅ CORRECT - Double parentheses\nconst useStore = create<MyStore>()((set) => ({\n  // ...\n}))\n```\n\n**Rule**: Always use `create<T>()()` in TypeScript, even without middleware (future-proof).\n\n### Issue #3: Persist Middleware Import Error\n\n**Error**: `\"Attempted import error: ''createJSONStorage'' is not exported from ''zustand/middleware''\"`\n\n**Source**: GitHub Discussion #2839\n\n**Why It Happens**:\nWrong import path or version mismatch between zustand and build tools.\n\n**Prevention**:\n\n```typescript\n// ✅ CORRECT imports for v5\nimport { create } from ''zustand''\nimport { persist, createJSONStorage } from ''zustand/middleware''\n\n// Verify versions\n// zustand@5.0.9 includes createJSONStorage\n// zustand@4.x uses different API\n\n// Check your package.json\n// \"zustand\": \"^5.0.9\"\n```\n\n### Issue #4: Infinite Render Loop\n\n**Error**: Component re-renders infinitely, browser freezes\n\n```\nUncaught Error: Maximum update depth exceeded. This can happen when a component repeatedly calls setState inside componentWillUpdate or componentDidUpdate.\n```\n\n**Source**:\n\n- GitHub Discussions #2642\n- [Issue #2863](https://github.com/pmndrs/zustand/issues/2863)\n\n**Why It Happens**:\nCreating new object references in selectors causes Zustand to think state changed.\n\n**v5 Breaking Change**: Zustand v5 made this error MORE explicit compared to v4. In v4, this behavior was \"non-ideal\" but could go unnoticed. In v5, you''ll immediately see the \"Maximum update depth exceeded\" error.\n\n**Prevention**:\n\n```typescript\nimport { useShallow } from ''zustand/shallow''\n\n// ❌ WRONG - Creates new object every time\nconst { bears, fishes } = useStore((state) => ({\n  bears: state.bears,\n  fishes: state.fishes,\n}))\n\n// ✅ CORRECT Option 1 - Select primitives separately\nconst bears = useStore((state) => state.bears)\nconst fishes = useStore((state) => state.fishes)\n\n// ✅ CORRECT Option 2 - Use useShallow hook for multiple values\nconst { bears, fishes } = useStore(\n  useShallow((state) => ({ bears: state.bears, fishes: state.fishes }))\n)\n```\n\n### Issue #5: Slices Pattern TypeScript Complexity\n\n**Error**: `StateCreator` types fail to infer, complex middleware types break\n\n**Source**: [Official Slices Pattern Guide](https://github.com/pmndrs/zustand/blob/main/docs/guides/slices-pattern.md)\n\n**Why It Happens**:\nCombining multiple slices requires explicit type annotations for middleware compatibility.\n\n**Prevention**:\n\n```typescript\nimport { create, StateCreator } from ''zustand''\n\n// Define slice types\ninterface BearSlice {\n  bears: number\n  addBear: () => void\n}\n\ninterface FishSlice {\n  fishes: number\n  addFish: () => void\n}\n\n// Create slices with proper types\nconst createBearSlice: StateCreator<\n  BearSlice & FishSlice,  // Combined store type\n  [],                      // Middleware mutators (empty if none)\n  [],                      // Chained middleware (empty if none)\n  BearSlice               // This slice''s type\n> = (set) => ({\n  bears: 0,\n  addBear: () => set((state) => ({ bears: state.bears + 1 })),\n})\n\nconst createFishSlice: StateCreator<\n  BearSlice & FishSlice,\n  [],\n  [],\n  FishSlice\n> = (set) => ({\n  fishes: 0,\n  addFish: () => set((state) => ({ fishes: state.fishes + 1 })),\n})\n\n// Combine slices\nconst useStore = create<BearSlice & FishSlice>()((...a) => ({\n  ...createBearSlice(...a),\n  ...createFishSlice(...a),\n}))\n```\n\n### Issue #6: Persist Middleware Race Condition (Fixed v5.0.10+)\n\n**Error**: Inconsistent state during concurrent rehydration attempts\n\n**Source**:\n\n- [GitHub PR #3336](https://github.com/pmndrs/zustand/pull/3336)\n- [Release v5.0.10](https://github.com/pmndrs/zustand/releases/tag/v5.0.10)\n\n**Why It Happens**:\nIn Zustand v5.0.9 and earlier, concurrent calls to rehydrate during persist middleware initialization could cause a race condition where multiple hydration attempts would interfere with each other, leading to inconsistent state.\n\n**Prevention**:\nUpgrade to Zustand v5.0.10 or later. No code changes needed - the fix is internal to the persist middleware.\n\n```bash\nnpm install zustand@latest  # Ensure v5.0.10+\n```\n\n**Note**: This was fixed in v5.0.10 (January 2026). If you''re using v5.0.9 or earlier and experiencing state inconsistencies with persist middleware, upgrade immediately.\n\n---\n\n## Middleware\n\n**Persist** (localStorage):\n\n```typescript\nimport { persist, createJSONStorage } from ''zustand/middleware''\n\nconst useStore = create<MyStore>()(\n  persist(\n    (set) => ({ data: [], addItem: (item) => set((state) => ({ data: [...state.data, item] })) }),\n    {\n      name: ''my-storage'',\n      partialize: (state) => ({ data: state.data }),  // Only persist ''data''\n    },\n  ),\n)\n```\n\n**Devtools** (Redux DevTools):\n\n```typescript\nimport { devtools } from ''zustand/middleware''\n\nconst useStore = create<CounterStore>()(\n  devtools(\n    (set) => ({ count: 0, increment: () => set((s) => ({ count: s.count + 1 }), undefined, ''increment'') }),\n    { name: ''CounterStore'' },\n  ),\n)\n```\n\n**v4→v5 Migration Note**: In Zustand v4, devtools was imported from `''zustand/middleware/devtools''`. In v5, use `''zustand/middleware''` (as shown above). If you see \"Module not found: Can''t resolve ''zustand/middleware/devtools''\", update your import path.\n\n**Combining Middlewares** (order matters):\n\n```typescript\nconst useStore = create<MyStore>()(devtools(persist((set) => ({ /* ... */ }), { name: ''storage'' }), { name: ''MyStore'' }))\n```\n\n---\n\n## Common Patterns\n\n**Computed/Derived Values** (in selector, not stored):\n\n```typescript\nconst count = useStore((state) => state.items.length)  // Computed on read\n```\n\n**Async Actions**:\n\n```typescript\nconst useAsyncStore = create<AsyncStore>()((set) => ({\n  data: null,\n  isLoading: false,\n  fetchData: async () => {\n    set({ isLoading: true })\n    const response = await fetch(''/api/data'')\n    set({ data: await response.text(), isLoading: false })\n  },\n}))\n```\n\n**Resetting Store**:\n\n```typescript\nconst initialState = { count: 0, name: '''' }\nconst useStore = create<ResettableStore>()((set) => ({\n  ...initialState,\n  reset: () => set(initialState),\n}))\n```\n\n**Selector with Params**:\n\n```typescript\nconst todo = useStore((state) => state.todos.find((t) => t.id === id))\n```\n\n---\n\n## Bundled Resources\n\n**Templates**: `basic-store.ts`, `typescript-store.ts`, `persist-store.ts`, `slices-pattern.ts`, `devtools-store.ts`, `nextjs-store.ts`, `computed-store.ts`, `async-actions-store.ts`\n\n**References**: `middleware-guide.md` (persist/devtools/immer/custom), `typescript-patterns.md` (type inference issues), `nextjs-hydration.md` (SSR/hydration), `migration-guide.md` (from Redux/Context/v4)\n\n**Scripts**: `check-versions.sh` (version compatibility)\n\n---\n\n## Advanced Topics\n\n**Vanilla Store** (Without React):\n\n```typescript\nimport { createStore } from ''zustand/vanilla''\n\nconst store = createStore<CounterStore>()((set) => ({ count: 0, increment: () => set((s) => ({ count: s.count + 1 })) }))\nconst unsubscribe = store.subscribe((state) => console.log(state.count))\nstore.getState().increment()\n```\n\n**Custom Middleware**:\n\n```typescript\nconst logger: Logger = (f, name) => (set, get, store) => {\n  const loggedSet: typeof set = (...a) => { set(...a); console.log(`[${name}]:`, get()) }\n  return f(loggedSet, get, store)\n}\n```\n\n**Immer Middleware** (Mutable Updates):\n\n```typescript\nimport { immer } from ''zustand/middleware/immer''\n\nconst useStore = create<TodoStore>()(immer((set) => ({\n  todos: [],\n  addTodo: (text) => set((state) => { state.todos.push({ id: Date.now().toString(), text }) }),\n})))\n```\n\n**v5.0.3→v5.0.4 Migration Note**: If upgrading from v5.0.3 to v5.0.4+ and immer middleware stops working, verify you''re using the import path shown above (`zustand/middleware/immer`). Some users reported issues after the v5.0.4 update that were resolved by confirming the correct import.\n\n**Experimental SSR Safe Middleware** (v5.0.9+):\n\n**Status**: Experimental (API may change)\n\nZustand v5.0.9 introduced experimental `unstable_ssrSafe` middleware for Next.js usage. This provides an alternative approach to the `_hasHydrated` pattern (see Issue #1).\n\n```typescript\nimport { unstable_ssrSafe } from ''zustand/middleware''\n\nconst useStore = create<Store>()(\n  unstable_ssrSafe(\n    persist(\n      (set) => ({ /* state */ }),\n      { name: ''my-store'' }\n    )\n  )\n)\n```\n\n**Recommendation**: Continue using the `_hasHydrated` pattern documented in Issue #1 until this API stabilizes. Monitor [Discussion #2740](https://github.com/pmndrs/zustand/discussions/2740) for updates on when this becomes stable.\n\n---\n\n## Official Documentation\n\n- **Zustand**: <https://zustand.docs.pmnd.rs/>\n- **GitHub**: <https://github.com/pmndrs/zustand>\n- **TypeScript Guide**: <https://zustand.docs.pmnd.rs/guides/typescript>\n- **Context7 Library ID**: `/pmndrs/zustand`\n"},"lastSynced":"2026-03-08T02:03:01.536Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing scalable state management solutions in React applications.","zh":"适用于需要在React应用程序中实现可扩展状态管理解决方案的前端代理。","ja":"Reactアプリケーションでスケーラブルな状態管理ソリューションを必要とするフロントエンドエージェントに最適です。","ko":"React 애플리케이션에서 확장 가능한 상태 관리 솔루션을 필요로 하는 프론트엔드 에이전트에게 적합합니다.","es":"Perfecto para Agentes Frontend que necesitan soluciones de gestión de estado escalables en aplicaciones de React.","fr":"Parfait pour les agents Frontend ayant besoin de solutions de gestion d''état évolutives dans les applications React.","de":"Perfekt für Frontend-Agents, die skalierbare State-Management-Lösungen in React-Anwendungen benötigen.","pt":"Perfeito para Agentes Frontend que precisam de soluções de gerenciamento de estado escaláveis em aplicações React.","ru":"Идеально для фронтенд-агентов, которым необходимы масштабируемые решения управления состоянием в приложениях React.","ar":"مثالي للوكلاء الأماميين الذين يحتاجون إلى حلول إدارة حالة قابلة للتوسيع في تطبيقات React."},"recommendation":{"en":"Empowers agents to manage complex state changes using TypeScript and React, providing a robust and scalable solution with support for React 18-19 and TypeScript 5+.","zh":"赋予代理使用TypeScript和React管理复杂的状态变化，提供一个强大且可扩展的解决方案，支持React 18-19和TypeScript 5+。","ja":"TypeScriptとReactを使用して複雑な状態の変更を管理するエージェントをEmpowerし、React 18-19とTypeScript 5+をサポートする堅牢でスケーラブルなソリューションを提供します。","ko":"에이전트에게 TypeScript와 React를 사용하여 복잡한 상태 변경을 관리할 수 있는 강력하고 확장 가능한 솔루션을 제공하여 React 18-19 및 TypeScript 5+를 지원합니다.","es":"Habilita a los agentes a gestionar cambios de estado complejos utilizando TypeScript y React, proporcionando una solución robusta y escalable con soporte para React 18-19 y TypeScript 5+.","fr":"Permet aux agents de gérer des changements d''état complexes en utilisant TypeScript et React, fournissant une solution robuste et évolutionnaire avec un support pour React 18-19 et TypeScript 5+.","de":"Ermächtigt die Agenten, komplexe Statusänderungen mithilfe von TypeScript und React zu verwalten und bietet eine robuste und skalierbare Lösung mit Unterstützung für React 18-19 und TypeScript 5+.","pt":"Habilita os agentes a gerenciar alterações de estado complexas usando TypeScript e React, fornecendo uma solução robusta e escalável com suporte para React 18-19 e TypeScript 5+.","ru":"Наделяет агентов возможностью управлять сложными изменениями состояния с помощью TypeScript и React, обеспечивая прочное и масштабируемое решение с поддержкой React 18-19 и TypeScript 5+.","ar":"تمكّن الوكلاء من إدارة التغييرات المعقدة للحالة باستخدام TypeScript و React، وتقديم حل قوي وقابل للتوسيع مع دعم React 18-19 وTypeScript 5+."},"useCases":{"en":["Building scalable React applications","Managing global state with TypeScript","Creating reusable state management components"],"zh":["构建可扩展的React应用程序","使用TypeScript管理全局状态","创建可重用的状态管理组件"],"ja":["スケーラブルなReactアプリケーションの構築","TypeScriptを使用したグローバル状態の管理","再利用可能な状態管理コンポーネントの作成"],"ko":["확장 가능한 React 애플리케이션 구축","TypeScript를 사용한 전역 상태 관리","재사용 가능한 상태 관리 컴포넌트 생성"],"es":["Construir aplicaciones de React escalables","Gestionar el estado global con TypeScript","Crear componentes de gestión de estado reutilizables"],"fr":["Créer des applications React évolutives","Gérer l''état global avec TypeScript","Créer des composants de gestion d''état réutilisables"],"de":["Skalierbare React-Anwendungen erstellen","Globalen Status mit TypeScript verwalten","Wiederverwendbare Status-Management-Komponenten erstellen"],"pt":["Construção de aplicações React escaláveis","Gerenciamento de estado global com TypeScript","Criação de componentes de gerenciamento de estado reutilizáveis"],"ru":["Создание масштабируемых приложений React","Управление глобальным состоянием с помощью TypeScript","Создание повторно используемых компонентов управления состоянием"],"ar":["بناء تطبيقات React قابلة للتوسيع","إدارة الحالة العالمية باستخدام TypeScript","إنشاء مكونات إدارة الحالة قابلة لإعادة الاستخدام"]},"limitations":{"en":["Requires React 18-19","TypeScript 5+ only","Limited to frontend state management"],"zh":["需要React 18-19","仅支持TypeScript 5+","仅限前端状态管理"],"ja":["React 18-19が必要","TypeScript 5+のみをサポート","フロントエンド状態管理のみ"],"ko":["React 18-19 필요","TypeScript 5+만 지원","프론트엔드 상태 관리만"],"es":["Requiere React 18-19","Solo TypeScript 5+","Limitado a la gestión de estado frontend"],"fr":["Nécessite React 18-19","TypeScript 5+ uniquement","Limité à la gestion d''état frontend"],"de":["Benötigt React 18-19","Nur TypeScript 5+","Begrenzt auf Frontend-Status-Management"],"pt":["Requer React 18-19","TypeScript 5+ apenas","Limitado ao gerenciamento de estado frontend"],"ru":["Требует React 18-19","Только TypeScript 5+","Ограничен управлением состоянием фронтенда"],"ar":["يتطلب React 18-19","TypeScript 5+ فقط","محدود بإدارة حالة الواجهة الأمامية"]},"version":4},"contentHash":"d178465b26c2f4b50da29132b46dc87adc1b03c503877a901c86ecb8254eb38c","qualityScore":39}');
