INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('husamql3/pstrack/zustand-state-management', 'zustand-state-management', 'husamql3', 'pstrack', 'community', 'zustand-state-management husamql3 pstrack community zustand-state-management helps React developers solve state management issues. It supports TypeScript 5+ and React 18-19, making it a great tool for building scalable applications Zustand状态管理是一个帮助您解决、跟踪和增长的平台，支持TypeScript和React 18-19 Zustand State Managementは、TypeScriptとReact 18-19をサポートする、解決、追跡、成長を助けるプラットフォームです Zustand 상태 관리는 TypeScript 및 React 18-19를 지원하는 해결, 추적, 성장 플랫폼입니다 Zustand State Management es una plataforma que ayuda a resolver, rastrear y crecer en proyectos React con TypeScript y React 18-19 Zustand State Management est une plateforme qui aide à résoudre, suivre et faire croître les projets React avec TypeScript et React 18-19 Zustand State Management ist eine Plattform, die hilft, Probleme zu lösen, zu verfolgen und zu wachsen in React-Projekten mit TypeScript und React 18-19 O Zustand State Management é uma plataforma que ajuda a resolver, rastrear e crescer com React e TypeScript Zustand State Management - это платформа, которая помогает решать, отслеживать и расти с React и TypeScript Zustand State Management هو منصة تساعد على حل وتتبع ونمو مع React و TypeScript how to use zustand-state-management zustand-state-management alternative zustand-state-management setup guide zustand-state-management vs mobx zustand-state-management install what is zustand-state-management zustand-state-management react zustand-state-management typescript zustand-state-management tutorial Zustand状态管理 TypeScript状态管理 React状态管理 AIエージェント解决方案 Zustand最新版本 Zustand依赖项 Supports React 18-19 for building scalable applications Compatible with TypeScript 5+ for robust type checking Uses the `create<T>()()` function for initializing stores Allows for easy state management using the `set` function Installs via npm using the `npm install zustand` command Supports hot-reload for efficient development zustand-state-management is a platform that provides a simple and efficient way to manage state in React applications using TypeScript');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('OrchardCMS/OrchardCore/orchardcore-module-creator', 'community', 'OrchardCMS', 'OrchardCore', 'OrchardCMS/OrchardCore', 'orchardcore-module-creator', 0, 0, 39, '2026-03-08T01:57:15.327Z', '2026-03-08T02:03:03.984Z', '17c0ee0feecd5f70fef44f090ee1af286513da94ff50e2eae99e05b0b01e8fba', '{"id":"OrchardCMS/OrchardCore/orchardcore-module-creator","name":"orchardcore-module-creator","description":{"en":"The orchardcore-module-creator skill helps developers create new OrchardCore modules following project conventions, utilizing ASP.NET Core and .NET SDK 10.0+. It benefits developers looking to build custom modules for their content management system.","zh":"OrchardCore模块创建器是用于创建新OrchardCore模块的工具，支持ASP.NET Core和.NET SDK 10.0+","ja":"OrchardCoreモジュール作成ツールは、AIエージェントを利用した新しいOrchardCoreモジュールを作成するためのツールです","ko":"OrchardCore 모듈 생성기는 새로운 OrchardCore 모듈을 생성하는 데 사용되는 도구입니다. ASP.NET Core와 .NET SDK 10.0+를 지원합니다","es":"El creador de módulos OrchardCore es una herramienta para desarrolladores que les permite crear nuevos módulos siguiendo las convenciones del proyecto. Requiere .NET SDK 10.0+ y el repositorio de OrchardCore","fr":"Le créateur de modules OrchardCore est un outil pour les développeurs qui leur permet de créer de nouveaux modules en suivant les conventions du projet. Il nécessite .NET SDK 10.0+ et le référentiel OrchardCore","de":"Der OrchardCore-Modul-Ersteller ist ein Tool für Entwickler, mit dem sie neue Module erstellen können, die den Projektkonventionen folgen. Es erfordert .NET SDK 10.0+ und das OrchardCore-Repository","pt":"O Criador de Módulos OrchardCore é uma ferramenta para criar novos módulos seguindo as convenções do projeto","ru":"Создатель модулей OrchardCore — это инструмент для создания новых модулей в соответствии с конвенциями проекта","ar":"معمل إنشاء الوحدات في OrchardCore هو أداة لإنشاء وحدات جديدة تتبع اتفاقيات المشروع"},"seo":{"title":{"en":"orchardcore-module-creator: Setup Guide for AI Agents | A...","zh":"OrchardCore 模块创建器 Setup Guide - ASP.NET Core 项目","ja":"OrchardCore モジュール作成ツール - AIエージェントによるASP.NET Core開発","ko":"OrchardCore 모듈 생성기 Setup Guide - .NET SDK 10.0+ 지원","es":"Creador de Módulos OrchardCore: Guía de Configuración","fr":"OrchardCore Module Creator: Guide de Mise en Route","de":"OrchardCore-Modul-Ersteller: Einrichtungsanleitung","pt":"Guia de Configuração do Criador de Módulos OrchardCore","ru":"Руководство по настройке создателя модулей OrchardCore","ar":"دليل إعداد معمل إنشاء الوحدات في OrchardCore"},"description":{"en":"Learn how to create new OrchardCore modules with ease. Get started with our step-by-step guide and master the art of module creation.","zh":"使用OrchardCore模块创建器快速创建新模块，支持ASP.NET Core和.NET SDK 10.0+","ja":"AIエージェントを利用したOrchardCoreモジュール作成ツール。ASP.NET Coreと.NET SDK 10.0+をサポート","ko":"OrchardCore 모듈 생성기를 사용하여 새로운 모듈을 빠르게 생성하세요. ASP.NET Core와 .NET SDK 10.0+를 지원합니다","es":"Aprende a crear módulos personalizados para OrchardCore con nuestra guía paso a paso, incluyendo tipos de módulos y requisitos previos","fr":"Découvrez comment créer des modules personnalisés pour OrchardCore avec notre guide étape par étape, incluant les types de modules et les prérequis","de":"Erfahren Sie, wie Sie benutzerdefinierte Module für OrchardCore erstellen, mit unserer Schritt-für-Schritt-Anleitung, einschließlich Modultypen und Vorausset...","pt":"Aprenda a criar módulos personalizados para o OrchardCore com este guia passo a passo","ru":"Узнайте, как создавать пользовательские модули для OrchardCore с помощью этого пошагового руководства","ar":"تعلم كيفية إنشاء الوحدات المخصصة لبرنامج OrchardCore باستخدام هذا الدليل خطوة بخطوة"},"definition":{"en":"orchardcore-module-creator is a skill that guides developers through creating new OrchardCore modules, following standard project conventions and utilizing key components like Parts, Drivers, and Views.","zh":"OrchardCore模块创建器是一种用于创建新OrchardCore模块的工具","ja":"OrchardCoreモジュール作成ツールは、新しいOrchardCoreモジュールを作成するためのAIエージェントです","ko":"OrchardCore 모듈 생성기는 새로운 OrchardCore 모듈을 생성하는 데 사용되는 도구입니다","es":"El creador de módulos OrchardCore es una herramienta de desarrollo que facilita la creación de módulos personalizados para la plataforma OrchardCore","fr":"Le créateur de modules OrchardCore est un outil de développement qui facilite la création de modules personnalisés pour la plateforme OrchardCore","de":"Der OrchardCore-Modul-Ersteller ist ein Entwicklungstool, das die Erstellung benutzerdefinierter Module für die OrchardCore-Plattform erleichtert","pt":"O que é o Criador de Módulos OrchardCore? É uma ferramenta para criar módulos personalizados para o framework OrchardCore","ru":"Что такое создатель модулей OrchardCore? Это инструмент для создания пользовательских модулей для фреймворка OrchardCore","ar":"ما هو معمل إنشاء الوحدات في OrchardCore? هو أداة لإنشاء الوحدات المخصصة لإطار العمل OrchardCore"},"features":{"en":["Creates new OrchardCore modules following project conventions","Utilizes ASP.NET Core for building modular and multi-tenant applications","Supports .NET SDK 10.0+ for seamless development","Guides through determining module type, including Content Part and Content Field","Follows a step-by-step module creation workflow","Leverages key components like Parts, Drivers, and Views for module development"],"zh":["支持ASP.NET Core","支持.NET SDK 10.0+","模块类型选择：Content Part、Content Field等","快速创建新模块","遵循OrchardCore项目约定"],"ja":["ASP.NET Coreをサポート",".NET SDK 10.0+をサポート","モジュールタイプの選択：Content Part、Content Fieldなど","新しいモジュールを迅速に作成","OrchardCoreプロジェクト規約に準拠"],"ko":["ASP.NET Core 지원",".NET SDK 10.0+ 지원","모듈 유형 선택：Content Part, Content Field 등","新的 모듈을 빠르게 생성","OrchardCore 프로젝트 규약 준수"],"es":["Creación de módulos personalizados para OrchardCore","Seguimiento de las convenciones del proyecto","Requiere .NET SDK 10.0+","Compatibilidad con el repositorio de OrchardCore","Soporte para tipos de módulos como Content Part y Content Field"],"fr":["Création de modules personnalisés pour OrchardCore","Suivi des conventions du projet","Nécessite .NET SDK 10.0+","Compatibilité avec le référentiel OrchardCore","Prise en charge de types de modules tels que Content Part et Content Field"],"de":["Erstellung benutzerdefinierter Module für OrchardCore","Einhaltung der Projektkonventionen","Erfordert .NET SDK 10.0+","Kompatibilität mit dem OrchardCore-Repository","Unterstützung für Modultypen wie Content Part und Content Field"],"pt":["Criação de módulos personalizados para o OrchardCore","Suporte a diferentes tipos de módulos, incluindo Content Part e Content Field","Integração com o .NET SDK 10.0+","Seguimento das convenções do projeto OrchardCore","Suporte a multi-tenancy e modularidade"],"ru":["Создание пользовательских модулей для OrchardCore","Поддержка различных типов модулей, включая Content Part и Content Field","Интеграция с .NET SDK 10.0+","Соблюдение конвенций проекта OrchardCore","Поддержка многоарендности и модульности"],"ar":["إنشاء الوحدات المخصصة لبرنامج OrchardCore","دعم أنواع مختلفة من الوحدات، بما في ذلك Content Part و Content Field","التكامل مع .NET SDK 10.0+","الامتثال لاتفاقيات مشروع OrchardCore","دعم الإيجار المتعدد والتعديل"]},"keywords":{"en":["how to use orchardcore-module-creator","what is orchardcore-module-creator","orchardcore-module-creator alternative","orchardcore-module-creator vs umbraco","orchardcore-module-creator install","orchardcore-module-creator setup guide","asp.net core module creation","orchardcore module development"],"zh":["OrchardCore模块创建器","ASP.NET Core开发","NET SDK 10.0+","模块创建工具","AIエージェント","OrchardCore项目约定"],"ja":["OrchardCoreモジュール作成ツール","ASP.NET Core開発","NET SDK 10.0+","モジュール作成ツール","AIエージェント","OrchardCoreプロジェクト規約"],"ko":["OrchardCore 모듈 생성기","ASP.NET Core 개발","NET SDK 10.0+","모듈 생성 도구","AI 에이전트","OrchardCore 프로젝트 규약"],"es":["OrchardCore","creador de módulos","desarrollo de módulos","ASP.NET Core","CMS","módulos personalizados","tipo de módulo",".NET SDK 10.0+"],"fr":["OrchardCore","créateur de modules","développement de modules","ASP.NET Core","CMS","modules personnalisés","type de module",".NET SDK 10.0+"],"de":["OrchardCore","Modul-Ersteller","Modulentwicklung","ASP.NET Core","CMS","benutzerdefinierte Module","Modultyp",".NET SDK 10.0+"],"pt":["OrchardCore","criador de módulos","módulos personalizados","ASP.NET Core","multi-tenancy","modularidade","desenvolvimento de software","ferramentas de desenvolvimento"],"ru":["OrchardCore","создатель модулей","пользовательские модули","ASP.NET Core","многоарендность","модульность","разработка программного обеспечения","инструменты разработки"],"ar":["OrchardCore","معمل إنشاء الوحدات","الوحدات المخصصة","ASP.NET Core","الإيجار المتعدد","التعديل","تطوير البرمجيات","أدوات التطوير"]}},"owner":"OrchardCMS","repo":"OrchardCore","repoPath":"OrchardCMS/OrchardCore","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.327Z","topics":[],"category":"community","skillMd":{"name":"orchardcore-module-creator","description":"Creates new OrchardCore modules with proper structure, manifest, startup, and patterns. Use when the user needs to create a new module, add content parts, fields, drivers, handlers, or admin functionality.","bodyPreview":"# OrchardCore Module Creator\n\nThis skill guides you through creating new OrchardCore modules following project conventions.\n\n## Prerequisites\n\n- OrchardCore repository at `D:\\orchardcore`\n- .NET SDK 10.0+ installed\n\n## Module Creation Workflow\n\n### Step 1: Determine Module Type\n\n**What kind of module are you creating?**\n\n| Type | Description | Key Components |\n|------|-------------|----------------|\n| **Content Part** | Adds data/behavior to content items | Part, Driver, Views |\n| **Content Fiel","body":"# OrchardCore Module Creator\n\nThis skill guides you through creating new OrchardCore modules following project conventions.\n\n## Prerequisites\n\n- OrchardCore repository at `D:\\orchardcore`\n- .NET SDK 10.0+ installed\n\n## Module Creation Workflow\n\n### Step 1: Determine Module Type\n\n**What kind of module are you creating?**\n\n| Type | Description | Key Components |\n|------|-------------|----------------|\n| **Content Part** | Adds data/behavior to content items | Part, Driver, Views |\n| **Content Field** | Custom field type | Field, Driver, Views |\n| **Settings** | Site-wide configuration | SiteSettings, Driver |\n| **Admin Feature** | Admin pages/tools | Controller, Views, Menu |\n| **API** | REST endpoints | ApiController |\n| **Background Task** | Scheduled jobs | IBackgroundTask |\n\n### Step 2: Create Module Directory\n\n```bash\n# Create module folder\nmkdir src/OrchardCore.Modules/OrchardCore.YourModule\ncd src/OrchardCore.Modules/OrchardCore.YourModule\n```\n\n### Step 3: Create Required Files\n\nEvery module needs these three files:\n\n1. **Manifest.cs** - Module metadata\n2. **Startup.cs** - Service registration  \n3. **OrchardCore.YourModule.csproj** - Project file\n\nSee `references/module-structure.md` for templates.\n\n### Step 4: Add Components Based on Type\n\n**For Content Part modules:**\n```\nModels/YourPart.cs\nViewModels/YourPartViewModel.cs\nDrivers/YourPartDisplayDriver.cs\nViews/YourPart.cshtml\nViews/YourPart_Edit.cshtml\n```\n\n**For Admin modules:**\n```\nControllers/AdminController.cs\nViews/Admin/Index.cshtml\nAdminMenu.cs\nPermissionProvider.cs\n```\n\n**For Data-storing modules:**\n```\nMigrations.cs\nIndexes/YourIndex.cs\n```\n\nSee `references/patterns.md` for code templates.\n\n### Step 5: Register in Startup.cs\n\n```csharp\npublic override void ConfigureServices(IServiceCollection services)\n{\n    // Content part\n    services.AddContentPart<YourPart>()\n        .UseDisplayDriver<YourPartDisplayDriver>();\n    \n    // Services\n    services.AddScoped<IYourService, YourService>();\n    \n    // Migrations (if storing data)\n    services.AddDataMigration<Migrations>();\n    \n    // Permissions (if securing features)\n    services.AddPermissionProvider<PermissionProvider>();\n    \n    // Navigation (if adding admin menu)\n    services.AddNavigationProvider<AdminMenu>();\n}\n```\n\n### Step 6: Build and Test\n\n```bash\n# Build the module\ncd D:\\orchardcore\ndotnet build src/OrchardCore.Modules/OrchardCore.YourModule\n\n# Run the application\ncd src/OrchardCore.Cms.Web\ndotnet run -f net10.0\n\n# Enable the feature in Admin → Features\n```\n\n## Quick Reference\n\n### Naming Conventions\n\n| Item | Convention | Example |\n|------|------------|---------|\n| Module folder | `OrchardCore.ModuleName` | `OrchardCore.Rating` |\n| Namespace | `OrchardCore.ModuleName` | `OrchardCore.Rating` |\n| Feature ID | `OrchardCore.ModuleName` | `OrchardCore.Rating` |\n| Content Part | `NamePart` | `RatingPart` |\n| Driver | `NamePartDisplayDriver` | `RatingPartDisplayDriver` |\n| View | `PartName.cshtml` | `RatingPart.cshtml` |\n| Edit View | `PartName_Edit.cshtml` | `RatingPart_Edit.cshtml` |\n\n### Common Dependencies\n\nAdd to `.csproj` as needed:\n\n```xml\n<!-- Core module support -->\n<ProjectReference Include=\"..\\..\\OrchardCore\\OrchardCore.Module.Targets\\OrchardCore.Module.Targets.csproj\" />\n\n<!-- Content management -->\n<ProjectReference Include=\"..\\..\\OrchardCore\\OrchardCore.ContentManagement\\OrchardCore.ContentManagement.csproj\" />\n\n<!-- Admin UI -->\n<ProjectReference Include=\"..\\..\\OrchardCore\\OrchardCore.Admin\\OrchardCore.Admin.csproj\" />\n```\n\n### Feature Categories\n\nUse in `Manifest.cs`:\n- `Content Management`\n- `Content`\n- `Navigation`\n- `Security`\n- `Infrastructure`\n- `Theming`\n- `Developer`\n\n## References\n\n- `references/module-structure.md` - Directory layout and file templates\n- `references/patterns.md` - Code patterns (parts, drivers, handlers, etc.)\n- `references/examples.md` - Complete module examples\n- `AGENTS.md` (repo root) - Coding conventions and build commands\n"},"lastSynced":"2026-03-08T02:03:03.984Z","agentAnalysis":{"suitability":{"en":"Essential for ASP.NET Core Development Agents specializing in OrchardCore CMS module creation.","zh":"适用于专注于OrchardCore CMS模块创建的ASP.NET Core开发代理。","ja":"OrchardCore CMSモジュール作成を専門とするASP.NET Core開発エージェントに不可欠。","ko":"OrchardCore CMS 모듈 생성을 전문으로하는 ASP.NET Core 개발 에이전트에게 필수적입니다.","es":"Esencial para Agentes de Desarrollo de ASP.NET Core especializados en la creación de módulos de CMS de OrchardCore.","fr":"Essentiel pour les Agents de Développement ASP.NET Core spécialisés dans la création de modules de CMS OrchardCore.","de":"Wesentlich für ASP.NET Core-Entwicklungsagenten, die auf die Erstellung von OrchardCore-CMS-Modulen spezialisiert sind.","pt":"Essencial para Agentes de Desenvolvimento ASP.NET Core especializados na criação de módulos do CMS OrchardCore.","ru":"Необходимо для агентов разработки ASP.NET Core, специализирующихся на создании модулей CMS OrchardCore.","ar":"ضروري لعميل تطوير ASP.NET Core المتخصص في إنشاء وحدة إدارة المحتوى OrchardCore."},"recommendation":{"en":"Automates the generation of OrchardCore module scaffolding following project conventions, including Content Parts, Content Fields, and Widgets with their required components like Drivers and Views. Streamlines development workflow by handling ASP.NET Core project structure and .NET SDK 10.0+ requirements.","zh":"自动化生成OrchardCore模块的脚手架，遵循项目约定，包括内容部分、内容字段和小部件，以及驱动程序和视图等必需组件。通过处理ASP.NET Core项目结构和.NET SDK 10.0+要求来简化开发工作流程。","ja":"プロジェクトの規約に従ってOrchardCoreモジュールのスキャフォールディングを自動生成します。内容部分、内容フィールド、ウィジェットなどとその必要なコンポーネントであるドライバーとビューを含みます。ASP.NET Coreプロジェクト構造と.NET SDK 10.0+の要件を処理することで開発ワークフローを簡素化します。","ko":"프로젝트 규칙에 따라 OrchardCore 모듈의 스캐폴딩을 자동으로 생성하여 콘텐츠 부분, 콘텐츠 필드, 위젯 및 드라이버 및 뷰와 같은 필수 구성 요소를 포함합니다. ASP.NET Core 프로젝트 구조 및 .NET SDK 10.0+ 요구 사항을 처리하여 개발 워크플로우를 간소화합니다.","es":"Automatiza la generación de estructura básica de módulos de OrchardCore siguiendo las convenciones del proyecto, incluyendo Partes de Contenido, Campos de Contenido y Widgets con sus componentes requeridos como Controladores y Vistas. Optimiza el flujo de trabajo de desarrollo al manejar la estructura del proyecto ASP.NET Core y los requisitos de .NET SDK 10.0+.","fr":"Automatise la génération de la structure de base des modules OrchardCore en suivant les conventions du projet, y compris les Parties de Contenu, les Champs de Contenu et les Widgets avec leurs composants requis tels que les Pilotes et les Vues. Rationalise le flux de travail de développement en gérant la structure du projet ASP.NET Core et les exigences de .NET SDK 10.0+.","de":"Automatisiert die Generierung der OrchardCore-Modulstruktur unter Einhaltung der Projektkonventionen, einschließlich InhaltsTeile, InhaltsFelder und Widgets mit ihren erforderlichen Komponenten wie Treibern und Ansichten. Optimiert den Entwicklungsworkflow, indem es die ASP.NET Core-Projektstruktur und die .NET SDK 10.0+-Anforderungen handhabt.","pt":"Automatiza a geração de estrutura de módulo OrchardCore seguindo as convenções do projeto, incluindo Partes de Conteúdo, Campos de Conteúdo e Widgets com seus componentes necessários, como Drivers e Views. Simplifica o fluxo de trabalho de desenvolvimento ao lidar com a estrutura do projeto ASP.NET Core e os requisitos do .NET SDK 10.0+.","ru":"Автоматизирует генерацию структуры модуля OrchardCore в соответствии с проектными конвенциями, включая части контента, поля контента и виджеты с их необходимыми компонентами, такими как драйверы и представления. Упрощает рабочий процесс разработки, обрабатывая структуру проекта ASP.NET Core и требования .NET SDK 10.0+.","ar":"يتوافق مع تلقائي لتوليد هيكل وحدة OrchardCore وفقًا لاتفاقيات المشروع، بما في ذلك أجزاء المحتوى والحقول والwidgets مع المكونات المطلوبة مثل السائقين والمشاهد. يبسط تدفق عمل التطوير عن طريق التعامل مع هيكل مشروع ASP.NET Core ومتطلبات SDK .NET 10.0+."},"useCases":{"en":["Generating Content Part modules with Drivers and Views","Creating Content Field modules with display management","Scaffolding Widget modules for dashboard integration","Automating project structure following OrchardCore conventions"],"zh":["生成包含驱动程序和视图的内容部分模块","创建具有显示管理的内容字段模块","为仪表板集成而创建小部件模块","自动化项目结构以遵循OrchardCore约定"],"ja":["ドライバーとビューを含む内容部分モジュールを生成する","表示管理を含む内容フィールドモジュールを作成する","ダッシュボード統合用のウィジェットモジュールをスキャフォールディングする","OrchardCoreの規約に従ったプロジェクト構造を自動化する"],"ko":["드라이버 및 뷰를 포함하는 콘텐츠 부분 모듈 생성","표시 관리를 포함하는 콘텐츠 필드 모듈 생성","대시보드 통합을 위한 위젯 모듈 스캐폴딩","OrchardCore 규칙에 따라 프로젝트 구조 자동화"],"es":["Generación de módulos de Partes de Contenido con Controladores y Vistas","Creación de módulos de Campos de Contenido con gestión de visualización","Creación de módulos de Widgets para integración de paneles","Automatización de la estructura del proyecto siguiendo las convenciones de OrchardCore"],"fr":["Génération de modules de Parties de Contenu avec Pilotes et Vues","Création de modules de Champs de Contenu avec gestion d''affichage","Création de modules de Widgets pour intégration de tableaux de bord","Automatisation de la structure du projet en suivant les conventions d''OrchardCore"],"de":["Generierung von Modulen für InhaltsTeile mit Treibern und Ansichten","Erstellung von Modulen für InhaltsFelder mit Anzeigeverwaltung","Erstellung von Modulen für Widgets zur Dashboard-Integration","Automatisierung der Projektstruktur unter Einhaltung der OrchardCore-Konventionen"],"pt":["Geração de módulos de Partes de Conteúdo com Drivers e Views","Criação de módulos de Campos de Conteúdo com gerenciamento de exibição","Criação de módulos de Widgets para integração de painel","Automatização da estrutura do projeto seguindo as convenções do OrchardCore"],"ru":["Генерация модулей частей контента с драйверами и представлениями","Создание модулей полей контента с управлением отображением","Создание модулей виджетов для интеграции с панелью управления","Автоматизация структуры проекта в соответствии с конвенциями OrchardCore"],"ar":["توليد وحدات أجزاء المحتوى مع السائقين والمشاهد","إنشاء وحدات حقول المحتوى مع إدارة العرض","إنشاء وحدات widgets لتكامل لوحة القيادة","توسيط هيكل المشروع وفقًا لاتفاقيات OrchardCore"]},"limitations":{"en":["Requires local OrchardCore repository at D:\\orchardcore",".NET SDK 10.0+ dependency","Windows-specific path requirement for repository location"],"zh":["需要在D:\\orchardcore处的本地OrchardCore存储库","依赖于.NET SDK 10.0+","存储库位置需要Windows特定的路径"],"ja":["D:\\orchardcoreにあるローカルのOrchardCoreリポジトリが必要",".NET SDK 10.0+に依存する","リポジトリの場所にはWindows固有のパスが必要"],"ko":["D:\\orchardcore에 있는 로컬 OrchardCore 저장소가 필요합니다.",".NET SDK 10.0+ 종속성","저장소 위치에 Windows 특정 경로 필요"],"es":["Requiere un repositorio local de OrchardCore en D:\\orchardcore","Dependencia de .NET SDK 10.0+","Requisito de ruta específica de Windows para la ubicación del repositorio"],"fr":["Nécessite un référentiel local d''OrchardCore à D:\\orchardcore","Dépendance de .NET SDK 10.0+","Exigence de chemin spécifique à Windows pour l''emplacement du référentiel"],"de":["Benötigt ein lokales OrchardCore-Repository unter D:\\orchardcore",".NET SDK 10.0+-Abhängigkeit","Windows-spezifischer Pfad-Anforderung für den Repository-Standort"],"pt":["Requer repositório local do OrchardCore em D:\\orchardcore","Dependência do .NET SDK 10.0+","Requisito de caminho específico do Windows para localização do repositório"],"ru":["Требуется локальный репозиторий OrchardCore по пути D:\\orchardcore","Зависимость от .NET SDK 10.0+","Требование к пути, специфичному для Windows, для размещения репозитория"],"ar":["يتطلب مستودع محلي لوحدة OrchardCore في D:\\orchardcore","اعتماد على SDK .NET 10.0+","متطلب مسار محدد لنظام التشغيل Windows لموقع المستودع"]},"version":4},"contentHash":"17c0ee0feecd5f70fef44f090ee1af286513da94ff50e2eae99e05b0b01e8fba","qualityScore":39}');
