INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('OrchardCMS/OrchardCore/orchardcore-module-creator', 'orchardcore-module-creator', 'OrchardCMS', 'OrchardCore', 'community', 'orchardcore-module-creator OrchardCMS OrchardCore community The orchardcore-module-creator skill helps developers create new OrchardCore modules following project conventions, utilizing ASP.NET Core and .NET SDK 10.0+. It benefits developers looking to build custom modules for their content management system. OrchardCore模块创建器是用于创建新OrchardCore模块的工具，支持ASP.NET Core和.NET SDK 10.0+ OrchardCoreモジュール作成ツールは、AIエージェントを利用した新しいOrchardCoreモジュールを作成するためのツールです OrchardCore 모듈 생성기는 새로운 OrchardCore 모듈을 생성하는 데 사용되는 도구입니다. ASP.NET Core와 .NET SDK 10.0+를 지원합니다 El creador de módulos OrchardCore es una herramienta para desarrolladores que les permite crear nuevos módulos siguiendo las convenciones del proyecto. Requiere .NET SDK 10.0+ y el repositorio de OrchardCore Le créateur de modules OrchardCore est un outil pour les développeurs qui leur permet de créer de nouveaux modules en suivant les conventions du projet. Il nécessite .NET SDK 10.0+ et le référentiel OrchardCore Der OrchardCore-Modul-Ersteller ist ein Tool für Entwickler, mit dem sie neue Module erstellen können, die den Projektkonventionen folgen. Es erfordert .NET SDK 10.0+ und das OrchardCore-Repository O Criador de Módulos OrchardCore é uma ferramenta para criar novos módulos seguindo as convenções do projeto Создатель модулей OrchardCore — это инструмент для создания новых модулей в соответствии с конвенциями проекта معمل إنشاء الوحدات في OrchardCore هو أداة لإنشاء وحدات جديدة تتبع اتفاقيات المشروع how to use orchardcore-module-creator what is orchardcore-module-creator orchardcore-module-creator alternative orchardcore-module-creator vs umbraco orchardcore-module-creator install orchardcore-module-creator setup guide asp.net core module creation orchardcore module development OrchardCore模块创建器 ASP.NET Core开发 NET SDK 10.0+ 模块创建工具 AIエージェント OrchardCore项目约定 Creates new OrchardCore modules following project conventions Utilizes ASP.NET Core for building modular and multi-tenant applications Supports .NET SDK 10.0+ for seamless development Guides through determining module type, including Content Part and Content Field Follows a step-by-step module creation workflow Leverages key components like Parts, Drivers, and Views for module development orchardcore-module-creator is a skill that guides developers through creating new OrchardCore modules, following standard project conventions and utilizing key components like Parts, Drivers, and Views.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jvegaf/harmony/drizzle-orm', 'community', 'jvegaf', 'harmony', 'jvegaf/harmony', 'drizzle-orm', 0, 0, 39, '2026-03-08T01:57:15.328Z', '2026-03-08T02:03:06.140Z', '61d1f731a9f3e0b764d66a8a1416c8da4c9fa7d30bc796349e3a0ff891d7da1f', '{"id":"jvegaf/harmony/drizzle-orm","name":"drizzle-orm","description":{"en":"drizzle-orm is a modern TypeScript-first Object-Relational Mapping tool that provides compile-time type safety and SQL-like syntax. It benefits developers working with edge runtimes and serverless environments.","zh":"Drizzle ORM是一个现代的TypeScript-first ORM，具有零依赖、编译时类型安全和SQL类似语法。适用于边缘运行时和服务器环境。","ja":"Drizzle ORMはモダンなTypeScript-first ORMであり、ゼロ依存、コンパイル時型安全性、SQLのような構文を備えています。エッジランタイムとサーバーレス環境に最適化されています。","ko":"Drizzle ORM은 현대적인 TypeScript-first ORM으로, 종속성이 없고, 컴파일 타임에 유형 안전성이 보장되며, SQL과 유사한 구문을 제공하여 에지 런타임과 서버리스 환경에 최적화되어 있습니다.","es":"drizzle-orm es un ORM de TypeScript moderno con cero dependencias y seguridad de tipos en tiempo de compilación","fr":"drizzle-orm est un ORM TypeScript moderne avec zéro dépendance et une sécurité de type à la compilation","de":"drizzle-orm ist ein modernes TypeScript-ORM mit null Abhängigkeiten und Kompilierzeit-Typsicherheit","pt":"Drizzle ORM é um ORM moderno em TypeScript com segurança de tipo em tempo de compilação e sintaxe SQL-like. Ideal para ambientes serverless e edge runtimes.","ru":"Drizzle ORM - современный ORM на TypeScript с безопасностью типов во время компиляции и синтаксисом SQL-like. Оптимизирован для серверных и краевых средах и ИИ Агентов","ar":"Drizzle ORM هو ORM حديث في TypeScript مع سلامة النوع في وقت الترجمة و بناء جملة SQL-like.เหมาะ لبيئات الخوادم اللاسلكية و حافة التشغيل"},"seo":{"title":{"en":"drizzle-orm: Modern TypeScript-first ORM Setup Guide | AI...","zh":"Drizzle ORM快速入门指南 - AIエージェント","ja":"Drizzle ORMセットアップガイド - AIエージェント","ko":"Drizzle ORM 설정 가이드 - AI 도구","es":"Guía de configuración de drizzle-orm: ORM de TypeScript","fr":"Guide de configuration de drizzle-orm: ORM TypeScript mod...","de":"Einrichtungsleitfaden für drizzle-orm: Modernes TypeScrip...","pt":"Guia de Configuração do Drizzle ORM: Melhores Práticas","ru":"Настройка Drizzle ORM: Руководство по ИИ Агентам","ar":"دليل إعداد Drizzle ORM: أفضل الممارسات لمنظمات الموسيقى"},"description":{"en":"Unlock efficient database management with drizzle-orm. Learn how to install and set up this zero-dependency ORM for edge runtimes and serverless environments.","zh":"了解Drizzle ORM的优势和特点，包括零依赖、编译时类型安全和SQL类似语法。适用于边缘运行时和服务器环境。","ja":"Drizzle ORMの利点と特徴を学びます。ゼロ依存、コンパイル時型安全性、SQLのような構文を備えており、エッジランタイムとサーバーレス環境に最適化されています。","ko":"Drizzle ORM의 장점과 특징을 알아보세요. 종속성이 없고, 컴파일 타임에 유형 안전성이 보장되며, SQL과 유사한 구문을 제공하여 에지 런타임과 서버리스 환경에 최적화되어 있습니다.","es":"Aprende a configurar drizzle-orm, un ORM de TypeScript con seguridad de tipos en tiempo de compilación y sintaxis similar a SQL","fr":"Découvrez comment configurer drizzle-orm, un ORM TypeScript moderne avec une sécurité de type à la compilation et une syntaxe similaire à SQL","de":"Erfahren Sie, wie Sie drizzle-orm konfigurieren, ein modernes TypeScript-ORM mit Kompilierzeit-Typsicherheit und SQL-ähnlicher Syntax","pt":"Aprenda a configurar o Drizzle ORM com nossas dicas e melhores práticas para um gerenciador de música em Electron","ru":"Узнайте, как настроить Drizzle ORM с нашими советами и лучшими практиками для менеджера музыки в Electron и ИИ Агентов","ar":"تعلم كيفية إعداد Drizzle ORM باستخدام نصائحنا وأفضل الممارسات لمنظمات الموسيقى في Electron"},"definition":{"en":"drizzle-orm is a TypeScript-first ORM with zero dependencies, offering compile-time type safety and SQL-like syntax for efficient database management.","zh":"Drizzle ORM是一个TypeScript-first的对象关系映射器，提供零依赖和编译时类型安全性。","ja":"Drizzle ORMはTypeScript-firstのオブジェクトリレーショナルマッパーであり、ゼロ依存とコンパイル時型安全性を提供します。","ko":"Drizzle ORM은 TypeScript-first의 객체 관계 매퍼로, 종속성이 없고 컴파일 타임에 유형 안전성을 제공합니다.","es":"drizzle-orm es un ORM de TypeScript que ofrece seguridad de tipos en tiempo de compilación y sintaxis similar a SQL","fr":"drizzle-orm est un ORM TypeScript qui offre une sécurité de type à la compilation et une syntaxe similaire à SQL","de":"drizzle-orm ist ein TypeScript-ORM, das Kompilierzeit-Typsicherheit und eine SQL-ähnliche Syntax bietet","pt":"O que é Drizzle ORM? Um ORM em TypeScript com zero dependências e sintaxe SQL-like para gerenciamento de banco de dados","ru":"Что такое Drizzle ORM? ORM на TypeScript с нулевыми зависимостями и синтаксисом SQL-like для управления базами данных и ИИ Агентов","ar":"ما هو Drizzle ORM؟ ORM في TypeScript مع صفر التبعيات و بناء جملة SQL-like لادارة قواعد البيانات"},"features":{"en":["Supports installation via npm with commands like npm install drizzle-orm","Offers database driver support for PostgreSQL, MySQL, and SQLite","Provides Drizzle Kit for migrations with npm install -D drizzle-kit","Allows basic setup with TypeScript, as shown in db/schema.ts examples","Optimized for edge runtimes and serverless environments","Delivers compile-time type safety for robust application development"],"zh":["零依赖","编译时类型安全","SQL类似语法","优化为边缘运行时","支持PostgreSQL、MySQL和SQLite","Drizzle Kit迁移工具"],"ja":["ゼロ依存","コンパイル時型安全性","SQLのような構文","エッジランタイムに最適化","PostgreSQL、MySQL、SQLiteをサポート","Drizzle Kitマイグレーションツール"],"ko":["종속성이 없음","컴파일 타임에 유형 안전성","SQL과 유사한 구문","에지 런타임에 최적화","PostgreSQL, MySQL, SQLite를 지원","Drizzle Kit 마이그레이션 도구"],"es":["Seguridad de tipos en tiempo de compilación","Sintaxis similar a SQL","Cero dependencias","Optimizado para entornos de servidor y edge","Soporte para PostgreSQL, MySQL y SQLite"],"fr":["Sécurité de type à la compilation","Syntaxe similaire à SQL","Zéro dépendance","Optimisé pour les environnements de serveur et edge","Prise en charge de PostgreSQL, MySQL et SQLite"],"de":["Kompilierzeit-Typsicherheit","SQL-ähnliche Syntax","Null Abhängigkeiten","Optimiert für Server- und Edge-Umgebungen","Unterstützung für PostgreSQL, MySQL und SQLite"],"pt":["Zero dependências","Segurança de tipo em tempo de compilação","Sintaxe SQL-like","Optimizado para ambientes serverless e edge runtimes","Suporte a PostgreSQL, MySQL e SQLite"],"ru":["Нулевые зависимости","Безопасность типов во время компиляции","Синтаксис SQL-like","Оптимизирован для серверных и краевых средах","Поддержка PostgreSQL, MySQL и SQLite и ИИ Агентов"],"ar":["صفر التبعيات","سلامة النوع في وقت الترجمة","بناء جملة SQL-like","เหมาะ لبيئات الخوادم اللاسلكية و حافة التشغيل","دعم PostgreSQL و MySQL و SQLite"]},"keywords":{"en":["how to use drizzle-orm","drizzle-orm vs typeorm","drizzle-orm install guide","what is drizzle-orm","drizzle-orm alternative to sequelize","drizzle-orm setup for serverless","drizzle-orm and TypeScript","drizzle-orm database driver support","drizzle-orm migration with Drizzle Kit"],"zh":["Drizzle ORM","TypeScript-first ORM","零依赖","编译时类型安全","SQL类似语法","边缘运行时","服务器环境","AIエージェント"],"ja":["Drizzle ORM","TypeScript-first ORM","ゼロ依存","コンパイル時型安全性","SQLのような構文","エッジランタイム","サーバーレス環境","AIエージェント"],"ko":["Drizzle ORM","TypeScript-first ORM","종속성이 없음","컴파일 타임에 유형 안전성","SQL과 유사한 구문","에지 런타임","서버리스 환경","AI 도구"],"es":["drizzle-orm","ORM de TypeScript","seguridad de tipos en tiempo de compilación","sintaxis similar a SQL","cero dependencias","entornos de servidor","edge","PostgreSQL","MySQL","SQLite"],"fr":["drizzle-orm","ORM TypeScript","sécurité de type à la compilation","syntaxe similaire à SQL","zéro dépendance","environnements de serveur","edge","PostgreSQL","MySQL","SQLite"],"de":["drizzle-orm","TypeScript-ORM","Kompilierzeit-Typsicherheit","SQL-ähnliche Syntax","null Abhängigkeiten","Server-Umgebungen","Edge","PostgreSQL","MySQL","SQLite"],"pt":["drizzle orm","orm typescript","gerenciador de música electron","segurança de tipo","sintaxe sql-like","serverless","edge runtimes","postgresql","mysql","sqlite"],"ru":["drizzle orm","orm на typescript","менеджер музыки electron","безопасность типов","синтаксис sql-like","серверные среды","краевые среды","postgresql","mysql","sqlite","ИИ Агенты"],"ar":["drizzle orm","orm في typescript","منظم الموسيقى إلكترون","سلامة النوع","بناء جملة sql-like","بيئات الخوادم اللاسلكية","حافة التشغيل","postgresql","mysql","sqlite"]}},"owner":"jvegaf","repo":"harmony","repoPath":"jvegaf/harmony","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.328Z","topics":[],"category":"community","skillMd":{"name":"drizzle-orm","description":"Type-safe SQL ORM for TypeScript with zero runtime overhead","bodyPreview":"# Drizzle ORM\n\nModern TypeScript-first ORM with zero dependencies, compile-time type safety, and SQL-like syntax. Optimized for edge runtimes and serverless environments.\n\n## Quick Start\n\n### Installation\n\n```bash\n# Core ORM\nnpm install drizzle-orm\n\n# Database driver (choose one)\nnpm install pg            # PostgreSQL\nnpm install mysql2        # MySQL\nnpm install better-sqlite3 # SQLite\n\n# Drizzle Kit (migrations)\nnpm install -D drizzle-kit\n```\n\n### Basic Setup\n\n```typescript\n// db/schema.ts\nimp","body":"# Drizzle ORM\n\nModern TypeScript-first ORM with zero dependencies, compile-time type safety, and SQL-like syntax. Optimized for edge runtimes and serverless environments.\n\n## Quick Start\n\n### Installation\n\n```bash\n# Core ORM\nnpm install drizzle-orm\n\n# Database driver (choose one)\nnpm install pg            # PostgreSQL\nnpm install mysql2        # MySQL\nnpm install better-sqlite3 # SQLite\n\n# Drizzle Kit (migrations)\nnpm install -D drizzle-kit\n```\n\n### Basic Setup\n\n```typescript\n// db/schema.ts\nimport { pgTable, serial, text, timestamp } from ''drizzle-orm/pg-core'';\n\nexport const users = pgTable(''users'', {\n  id: serial(''id'').primaryKey(),\n  email: text(''email'').notNull().unique(),\n  name: text(''name'').notNull(),\n  createdAt: timestamp(''created_at'').defaultNow(),\n});\n\n// db/client.ts\nimport { drizzle } from ''drizzle-orm/node-postgres'';\nimport { Pool } from ''pg'';\nimport * as schema from ''./schema'';\n\nconst pool = new Pool({ connectionString: process.env.DATABASE_URL });\nexport const db = drizzle(pool, { schema });\n```\n\n### First Query\n\n```typescript\nimport { db } from ''./db/client'';\nimport { users } from ''./db/schema'';\nimport { eq } from ''drizzle-orm'';\n\n// Insert\nconst newUser = await db\n  .insert(users)\n  .values({\n    email: ''user@example.com'',\n    name: ''John Doe'',\n  })\n  .returning();\n\n// Select\nconst allUsers = await db.select().from(users);\n\n// Where\nconst user = await db.select().from(users).where(eq(users.id, 1));\n\n// Update\nawait db.update(users).set({ name: ''Jane Doe'' }).where(eq(users.id, 1));\n\n// Delete\nawait db.delete(users).where(eq(users.id, 1));\n```\n\n## Schema Definition\n\n### Column Types Reference\n\n| PostgreSQL    | MySQL         | SQLite      | TypeScript |\n| ------------- | ------------- | ----------- | ---------- |\n| `serial()`    | `serial()`    | `integer()` | `number`   |\n| `text()`      | `text()`      | `text()`    | `string`   |\n| `integer()`   | `int()`       | `integer()` | `number`   |\n| `boolean()`   | `boolean()`   | `integer()` | `boolean`  |\n| `timestamp()` | `datetime()`  | `integer()` | `Date`     |\n| `json()`      | `json()`      | `text()`    | `unknown`  |\n| `uuid()`      | `varchar(36)` | `text()`    | `string`   |\n\n### Common Schema Patterns\n\n```typescript\nimport { pgTable, serial, text, varchar, integer, boolean, timestamp, json, unique } from ''drizzle-orm/pg-core'';\n\nexport const users = pgTable(\n  ''users'',\n  {\n    id: serial(''id'').primaryKey(),\n    email: varchar(''email'', { length: 255 }).notNull().unique(),\n    passwordHash: varchar(''password_hash'', { length: 255 }).notNull(),\n    role: text(''role'', { enum: [''admin'', ''user'', ''guest''] }).default(''user''),\n    metadata: json(''metadata'').$type<{ theme: string; locale: string }>(),\n    isActive: boolean(''is_active'').default(true),\n    createdAt: timestamp(''created_at'').defaultNow().notNull(),\n    updatedAt: timestamp(''updated_at'').defaultNow().notNull(),\n  },\n  table => ({\n    emailIdx: unique(''email_unique_idx'').on(table.email),\n  }),\n);\n\n// Infer TypeScript types\ntype User = typeof users.$inferSelect;\ntype NewUser = typeof users.$inferInsert;\n```\n\n## Relations\n\n### One-to-Many\n\n```typescript\nimport { pgTable, serial, text, integer } from ''drizzle-orm/pg-core'';\nimport { relations } from ''drizzle-orm'';\n\nexport const authors = pgTable(''authors'', {\n  id: serial(''id'').primaryKey(),\n  name: text(''name'').notNull(),\n});\n\nexport const posts = pgTable(''posts'', {\n  id: serial(''id'').primaryKey(),\n  title: text(''title'').notNull(),\n  authorId: integer(''author_id'')\n    .notNull()\n    .references(() => authors.id),\n});\n\nexport const authorsRelations = relations(authors, ({ many }) => ({\n  posts: many(posts),\n}));\n\nexport const postsRelations = relations(posts, ({ one }) => ({\n  author: one(authors, {\n    fields: [posts.authorId],\n    references: [authors.id],\n  }),\n}));\n\n// Query with relations\nconst authorsWithPosts = await db.query.authors.findMany({\n  with: { posts: true },\n});\n```\n\n### Many-to-Many\n\n```typescript\nexport const users = pgTable(''users'', {\n  id: serial(''id'').primaryKey(),\n  name: text(''name'').notNull(),\n});\n\nexport const groups = pgTable(''groups'', {\n  id: serial(''id'').primaryKey(),\n  name: text(''name'').notNull(),\n});\n\nexport const usersToGroups = pgTable(\n  ''users_to_groups'',\n  {\n    userId: integer(''user_id'')\n      .notNull()\n      .references(() => users.id),\n    groupId: integer(''group_id'')\n      .notNull()\n      .references(() => groups.id),\n  },\n  table => ({\n    pk: primaryKey({ columns: [table.userId, table.groupId] }),\n  }),\n);\n\nexport const usersRelations = relations(users, ({ many }) => ({\n  groups: many(usersToGroups),\n}));\n\nexport const groupsRelations = relations(groups, ({ many }) => ({\n  users: many(usersToGroups),\n}));\n\nexport const usersToGroupsRelations = relations(usersToGroups, ({ one }) => ({\n  user: one(users, { fields: [usersToGroups.userId], references: [users.id] }),\n  group: one(groups, { fields: [usersToGroups.groupId], references: [groups.id] }),\n}));\n```\n\n## Queries\n\n### Filtering\n\n```typescript\nimport { eq, ne, gt, gte, lt, lte, like, ilike, inArray, isNull, isNotNull, and, or, between } from ''drizzle-orm'';\n\n// Equality\nawait db.select().from(users).where(eq(users.email, ''user@example.com''));\n\n// Comparison\nawait db.select().from(users).where(gt(users.id, 10));\n\n// Pattern matching\nawait db.select().from(users).where(like(users.name, ''%John%''));\n\n// Multiple conditions\nawait db\n  .select()\n  .from(users)\n  .where(and(eq(users.role, ''admin''), gt(users.createdAt, new Date(''2024-01-01''))));\n\n// IN clause\nawait db\n  .select()\n  .from(users)\n  .where(inArray(users.id, [1, 2, 3]));\n\n// NULL checks\nawait db.select().from(users).where(isNull(users.deletedAt));\n```\n\n### Joins\n\n```typescript\nimport { eq } from ''drizzle-orm'';\n\n// Inner join\nconst result = await db\n  .select({\n    user: users,\n    post: posts,\n  })\n  .from(users)\n  .innerJoin(posts, eq(users.id, posts.authorId));\n\n// Left join\nconst result = await db\n  .select({\n    user: users,\n    post: posts,\n  })\n  .from(users)\n  .leftJoin(posts, eq(users.id, posts.authorId));\n\n// Multiple joins with aggregation\nimport { count, sql } from ''drizzle-orm'';\n\nconst result = await db\n  .select({\n    authorName: authors.name,\n    postCount: count(posts.id),\n  })\n  .from(authors)\n  .leftJoin(posts, eq(authors.id, posts.authorId))\n  .groupBy(authors.id);\n```\n\n### Pagination & Sorting\n\n```typescript\nimport { desc, asc } from ''drizzle-orm'';\n\n// Order by\nawait db.select().from(users).orderBy(desc(users.createdAt));\n\n// Limit & offset\nawait db.select().from(users).limit(10).offset(20);\n\n// Pagination helper\nfunction paginate(page: number, pageSize: number = 10) {\n  return db\n    .select()\n    .from(users)\n    .limit(pageSize)\n    .offset(page * pageSize);\n}\n```\n\n## Transactions\n\n```typescript\n// Auto-rollback on error\nawait db.transaction(async (tx) => {\n  await tx.insert(users).values({ email: ''user@example.com'', name: ''John'' });\n  await tx.insert(posts).values({ title: ''First Post'', authorId: 1 });\n  // If any query fails, entire transaction rolls back\n});\n\n// Manual control\nconst tx = db.transaction(async (tx) => {\n  const user = await tx.insert(users).values({ ... }).returning();\n\n  if (!user) {\n    tx.rollback();\n    return;\n  }\n\n  await tx.insert(posts).values({ authorId: user.id });\n});\n```\n\n## Migrations\n\n### Drizzle Kit Configuration\n\n```typescript\n// drizzle.config.ts\nimport type { Config } from ''drizzle-kit'';\n\nexport default {\n  schema: ''./db/schema.ts'',\n  out: ''./drizzle'',\n  dialect: ''postgresql'',\n  dbCredentials: {\n    url: process.env.DATABASE_URL!,\n  },\n} satisfies Config;\n```\n\n### Migration Workflow\n\n```bash\n# Generate migration\nnpx drizzle-kit generate\n\n# View SQL\ncat drizzle/0000_migration.sql\n\n# Apply migration\nnpx drizzle-kit migrate\n\n# Introspect existing database\nnpx drizzle-kit introspect\n\n# Drizzle Studio (database GUI)\nnpx drizzle-kit studio\n```\n\n### Example Migration\n\n```sql\n-- drizzle/0000_initial.sql\nCREATE TABLE IF NOT EXISTS \"users\" (\n  \"id\" serial PRIMARY KEY NOT NULL,\n  \"email\" varchar(255) NOT NULL,\n  \"name\" text NOT NULL,\n  \"created_at\" timestamp DEFAULT now() NOT NULL,\n  CONSTRAINT \"users_email_unique\" UNIQUE(\"email\")\n);\n```\n\n## Navigation\n\n### Detailed References\n\n- **[🏗️ Advanced Schemas](./references/advanced-schemas.md)** - Custom types, composite keys, indexes, constraints, multi-tenant patterns. Load when designing complex database schemas.\n\n- **[🔍 Query Patterns](./references/query-patterns.md)** - Subqueries, CTEs, raw SQL, prepared statements, batch operations. Load when optimizing queries or handling complex filtering.\n\n- **[⚡ Performance](./references/performance.md)** - Connection pooling, query optimization, N+1 prevention, prepared statements, edge runtime integration. Load when scaling or optimizing database performance.\n\n- **[🔄 vs Prisma](./references/vs-prisma.md)** - Feature comparison, migration guide, when to choose Drizzle over Prisma. Load when evaluating ORMs or migrating from Prisma.\n\n## Red Flags\n\n**Stop and reconsider if:**\n\n- Using `any` or `unknown` for JSON columns without type annotation\n- Building raw SQL strings without using `sql` template (SQL injection risk)\n- Not using transactions for multi-step data modifications\n- Fetching all rows without pagination in production queries\n- Missing indexes on foreign keys or frequently queried columns\n- Using `select()` without specifying columns for large tables\n\n## Performance Benefits vs Prisma\n\n| Metric              | Drizzle           | Prisma                |\n| ------------------- | ----------------- | --------------------- |\n| **Bundle Size**     | ~35KB             | ~230KB                |\n| **Cold Start**      | ~10ms             | ~250ms                |\n| **Query Speed**     | Baseline          | ~2-3x slower          |\n| **Memory**          | ~10MB             | ~50MB                 |\n| **Type Generation** | Runtime inference | Build-time generation |\n\n## Integration\n\n- **typescript-core**: Type-safe schema inference with `satisfies`\n- **nextjs-core**: Server Actions, Route Handlers, Middleware integration\n- **Database Migration**: Safe schema evolution patterns\n\n## Related Skills\n\nWhen using Drizzle, these skills enhance your workflow:\n\n- **prisma**: Alternative ORM comparison: Drizzle vs Prisma trade-offs\n- **typescript**: Advanced TypeScript patterns for type-safe queries\n- **nextjs**: Drizzle with Next.js Server Actions and API routes\n- **sqlalchemy**: SQLAlchemy patterns for Python developers learning Drizzle\n\n[Full documentation available in these skills if deployed in your bundle]\n"},"lastSynced":"2026-03-08T02:03:06.140Z","agentAnalysis":{"suitability":{"en":"Ideal for TypeScript-focused AI Agents requiring efficient Object-Relational Mapping with compile-time type safety and SQL-like syntax.","zh":"适用于需要高效对象关系映射、编译时类型安全和类SQL语法的TypeScript专注AI代理的理想选择。","ja":"TypeScriptに特化したAIエージェントで、効率的なオブジェクト関係マッピングとコンパイル時タイプセーフティ、およびSQLのような構文が必要な場合に最適です。","ko":"효율적인 객체 관계 매핑 및 컴파일 타임 타입 안전성과 SQL과 같은 구문을 필요로 하는 TypeScript 중심의 AI 에이전트에 적합합니다.","es":"Ideal para agentes de inteligencia artificial enfocados en TypeScript que requieren un mapeo relacional de objetos eficiente con seguridad de tipo en tiempo de compilación y sintaxis similar a SQL.","fr":"Idéal pour les agents d''intelligence artificielle axés sur TypeScript nécessitant un mappage relationnel d''objets efficace avec une sécurité de type en temps de compilation et une syntaxe similaire à SQL.","de":"Ideal für TypeScript-fokussierte KI-Agents, die ein effizientes Object-Relational Mapping mit Kompilierzeit-Typsicherheit und SQL-ähnlicher Syntax erfordern.","pt":"Ideal para Agentes de IA focados em TypeScript que exigem mapeamento objeto-relacional eficiente com segurança de tipo em tempo de compilação e sintaxe semelhante ao SQL.","ru":"Идеально подходит для агентов ИИ, ориентированных на TypeScript, требующих эффективного объектно-реляционного сопоставления с безопасностью типов во время компиляции и синтаксисом, похожим на SQL.","ar":"مثالي لعميل الذكاء الاصطناعي المتمركز على TypeScript الذي يتطلب تعيينًا كفؤًا للكائن-المرتبط مع أمان النوع في وقت الترجمة وسyntax شبيهة بـ SQL."},"recommendation":{"en":"Empowers agents to interact with databases using zero-dependency, TypeScript-first ORM, optimized for edge runtimes and serverless environments, with support for PostgreSQL, MySQL, and SQLite via libraries like pg, mysql2, and better-sqlite3.","zh":"赋予代理使用零依赖、TypeScript优先的ORM与数据库交互，针对边缘运行时和无服务器环境进行优化，并通过类似pg、mysql2和better-sqlite3的库支持PostgreSQL、MySQL和SQLite。","ja":"エージェントに、ゼロ依存、TypeScriptファーストのORMを使用してデータベースとやり取りする能力を与え、エッジランタイムとサーバーレス環境に最適化し、pg、mysql2、better-sqlite3などのライブラリを介してPostgreSQL、MySQL、SQLiteをサポートします。","ko":"에이전트에게 데이터베이스와 상호 작용하기 위해 의존성 없는 TypeScript 우선 ORM을 사용하여 에지 런타임 및 서버리스 환경을 최적화하고 pg, mysql2, better-sqlite3와 같은 라이브러리를 통해 PostgreSQL, MySQL, SQLite를 지원하는 기능을 제공합니다.","es":"Habilita a los agentes a interactuar con bases de datos utilizando un ORM de cero dependencias, primero en TypeScript, optimizado para entornos de ejecución de borde y entornos sin servidor, con soporte para PostgreSQL, MySQL y SQLite a través de bibliotecas como pg, mysql2 y better-sqlite3.","fr":"Permet aux agents d''interagir avec les bases de données en utilisant un ORM sans dépendance, premièrement en TypeScript, optimisé pour les environnements d''exécution de bord et les environnements sans serveur, avec un support pour PostgreSQL, MySQL et SQLite via des bibliothèques comme pg, mysql2 et better-sqlite3.","de":"Ermächtigt Agents, mit Datenbanken zu interagieren, indem sie ein zero-Abhängigkeits-ORM, erste TypeScript-ORM, verwenden, das für Edge-Laufzeiten und serverlose Umgebungen optimiert ist, mit Unterstützung für PostgreSQL, MySQL und SQLite über Bibliotheken wie pg, mysql2 und better-sqlite3.","pt":"Habilita os agentes a interagir com bancos de dados usando ORM de zero dependência, primeiro TypeScript, otimizado para ambientes de tempo de execução de borda e sem servidor, com suporte para PostgreSQL, MySQL e SQLite por meio de bibliotecas como pg, mysql2 e better-sqlite3.","ru":"Наделяет агентов возможностью взаимодействовать с базами данных, используя ORM с нулевой зависимостью, ориентированный на TypeScript, оптимизированный для краевых сред выполнения и серверных окружений, с поддержкой PostgreSQL, MySQL и SQLite через библиотеки seperti pg, mysql2 и better-sqlite3.","ar":"تمكّن العميل من التفاعل مع قواعد البيانات باستخدام ORM من عدم الاعتماد، أولاً TypeScript، محسّن لبيئات وقت التشغيل الحرج وبدون خادم، مع دعم لـ PostgreSQL و MySQL و SQLite من خلال مكتبات مثل pg و mysql2 و better-sqlite3."},"useCases":{"en":["Building serverless applications with secure database connections","Migrating existing databases to edge runtimes using Drizzle Kit","Generating type-safe database queries with SQL-like syntax"],"zh":["使用安全的数据库连接构建无服务器应用程序","使用Drizzle Kit将现有数据库迁移到边缘运行时","使用类SQL语法生成类型安全的数据库查询"],"ja":["セキュアなデータベース接続を使用してサーバーレスアプリケーションを構築する","Drizzle Kitを使用して既存のデータベースをエッジランタイムに移行する","SQLのような構文を使用してタイプセーフなデータベースクエリを生成する"],"ko":["보안된 데이터베이스 연결을 사용하여 서버리스 애플리케이션을 구축하는 것","Drizzle Kit를 사용하여 기존 데이터베이스를 에지 런타임으로 마이그레이션하는 것","SQL과 같은 구문을 사용하여 타입 안전한 데이터베이스 쿼리를 생성하는 것"],"es":["Construir aplicaciones sin servidor con conexiones de base de datos seguras","Migrar bases de datos existentes a entornos de ejecución de borde utilizando Drizzle Kit","Generar consultas de base de datos seguras con sintaxis similar a SQL"],"fr":["Construire des applications sans serveur avec des connexions de base de données sécurisées","Migrer des bases de données existantes vers des environnements d''exécution de bord en utilisant Drizzle Kit","Générer des requêtes de base de données sécurisées avec une syntaxe similaire à SQL"],"de":["Bauen von serverlosen Anwendungen mit sicheren Datenbankverbindungen","Migrieren von bestehenden Datenbanken in Edge-Laufzeiten mit Drizzle Kit","Erzeugen von typsicheren Datenbankabfragen mit SQL-ähnlicher Syntax"],"pt":["Construir aplicações sem servidor com conexões de banco de dados seguras","Migrar bancos de dados existentes para ambientes de tempo de execução de borda usando Drizzle Kit","Gerar consultas de banco de dados seguras com sintaxe semelhante ao SQL"],"ru":["Построение серверных приложений с безопасными соединениями с базами данных","Миграция существующих баз данных в краевые среды выполнения с помощью Drizzle Kit","Генерация безопасных запросов к базе данных с синтаксисом, похожим на SQL"],"ar":["بناء تطبيقات بدون خادم مع الاتصالات الآمنة لقواعد البيانات","نقل قواعد البيانات الحالية إلى بيئات وقت التشغيل الحرج باستخدام Drizzle Kit","جعل استفسارات قواعد البيانات آمنة مع بنية شبيهة بـ SQL"]},"limitations":{"en":["Requires TypeScript environment","Limited to supported databases (PostgreSQL, MySQL, SQLite)"],"zh":["需要TypeScript环境","仅限支持的数据库（PostgreSQL、MySQL、SQLite）"],"ja":["TypeScript環境が必要","サポートされているデータベース（PostgreSQL、MySQL、SQLite）に限定される"],"ko":["TypeScript 환경이 필요함","지원되는 데이터베이스(PostgreSQL, MySQL, SQLite)로 제한됨"],"es":["Requiere entorno de TypeScript","Limitado a bases de datos admitidas (PostgreSQL, MySQL, SQLite)"],"fr":["Nécessite un environnement TypeScript","Limité aux bases de données prises en charge (PostgreSQL, MySQL, SQLite)"],"de":["Benötigt eine TypeScript-Umgebung","Begrenzt auf unterstützte Datenbanken (PostgreSQL, MySQL, SQLite)"],"pt":["Exige ambiente TypeScript","Limitado a bancos de dados suportados (PostgreSQL, MySQL, SQLite)"],"ru":["Требуется среда TypeScript","Ограничен поддерживаемыми базами данных (PostgreSQL, MySQL, SQLite)"],"ar":["يتطلب بيئة TypeScript","محدود بقواعد البيانات المدعومة (PostgreSQL و MySQL و SQLite)"]},"version":4},"contentHash":"61d1f731a9f3e0b764d66a8a1416c8da4c9fa7d30bc796349e3a0ff891d7da1f","qualityScore":39}');
