INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('jvegaf/harmony/drizzle-orm', 'drizzle-orm', 'jvegaf', 'harmony', 'community', 'drizzle-orm jvegaf harmony community drizzle-orm is a modern TypeScript-first Object-Relational Mapping tool that provides compile-time type safety and SQL-like syntax. It benefits developers working with edge runtimes and serverless environments. Drizzle ORM是一个现代的TypeScript-first ORM，具有零依赖、编译时类型安全和SQL类似语法。适用于边缘运行时和服务器环境。 Drizzle ORMはモダンなTypeScript-first ORMであり、ゼロ依存、コンパイル時型安全性、SQLのような構文を備えています。エッジランタイムとサーバーレス環境に最適化されています。 Drizzle ORM은 현대적인 TypeScript-first ORM으로, 종속성이 없고, 컴파일 타임에 유형 안전성이 보장되며, SQL과 유사한 구문을 제공하여 에지 런타임과 서버리스 환경에 최적화되어 있습니다. drizzle-orm es un ORM de TypeScript moderno con cero dependencias y seguridad de tipos en tiempo de compilación drizzle-orm est un ORM TypeScript moderne avec zéro dépendance et une sécurité de type à la compilation drizzle-orm ist ein modernes TypeScript-ORM mit null Abhängigkeiten und Kompilierzeit-Typsicherheit Drizzle ORM é um ORM moderno em TypeScript com segurança de tipo em tempo de compilação e sintaxe SQL-like. Ideal para ambientes serverless e edge runtimes. Drizzle ORM - современный ORM на TypeScript с безопасностью типов во время компиляции и синтаксисом SQL-like. Оптимизирован для серверных и краевых средах и ИИ Агентов Drizzle ORM هو ORM حديث في TypeScript مع سلامة النوع في وقت الترجمة و بناء جملة SQL-like.เหมาะ لبيئات الخوادم اللاسلكية و حافة التشغيل how to use drizzle-orm drizzle-orm vs typeorm drizzle-orm install guide what is drizzle-orm drizzle-orm alternative to sequelize drizzle-orm setup for serverless drizzle-orm and TypeScript drizzle-orm database driver support drizzle-orm migration with Drizzle Kit Drizzle ORM TypeScript-first ORM 零依赖 编译时类型安全 SQL类似语法 边缘运行时 服务器环境 AIエージェント Supports installation via npm with commands like npm install drizzle-orm Offers database driver support for PostgreSQL, MySQL, and SQLite Provides Drizzle Kit for migrations with npm install -D drizzle-kit Allows basic setup with TypeScript, as shown in db/schema.ts examples Optimized for edge runtimes and serverless environments Delivers compile-time type safety for robust application development drizzle-orm is a TypeScript-first ORM with zero dependencies, offering compile-time type safety and SQL-like syntax for efficient database management.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('withzombies/hyperpowers/debugging-with-tools', 'community', 'withzombies', 'hyperpowers', 'withzombies/hyperpowers', 'debugging-with-tools', 0, 0, 39, '2026-03-08T01:57:15.328Z', '2026-03-08T02:03:06.166Z', 'd3980914f5dc48666cf345e9a6cb56d90edda5c7d774f9c7fdfc3c0e6599ef31', '{"id":"withzombies/hyperpowers/debugging-with-tools","name":"debugging-with-tools","description":{"en":"The debugging-with-tools skill enables AI agents to efficiently debug code using tools like Codex and TodoWrite, benefiting developers by reducing random fixes and new bugs.","zh":"debugging-with-tools 是一种使用工具来理解代码根源的调试方法，通过 beads 任务跟踪和细化来优化代码","ja":"debugging-with-tools は、コードの根本原因を理解するためにツールを使用するデバッグ方法で、beads タスク追跡とリファインメントを使用してコードを最適化します","ko":"debugging-with-tools는 코드의 근본 원인을 이해하기 위해 도구를 사용하는 디버깅 방법으로, 비즈 태스크 추적 및 세부화를 통해 코드를 최적화합니다","es":"La depuración con herramientas como Claude Code y Codex es crucial para entender las causas raíz de los errores en tus Agentes de IA","fr":"Le débogage avec des outils comme Claude Code et Codex est essentiel pour comprendre les causes profondes des erreurs dans vos Agents d''IA","de":"Das Debuggen mit Tools wie Claude Code und Codex ist entscheidend, um die Ursachen von Fehlern in Ihren KI-Agenten zu verstehen","pt":"O skill ''debugging-with-tools'' fornece superpoderes de codificação com beads para rastreamento e refinamento de tarefas, permitindo uma depuração mais eficiente","ru":"Умение ''debugging-with-tools'' предоставляет суперпowers кодирования с beads для отслеживания и совершенствования задач, позволяя более эффективно отлаживать код","ar":"المهارة ''debugging-with-tools'' توفر قوى خارقة للترميز مع beads لتتبع وتحسين المهام، مما يسمح بتصحيح أخطاء أكثر كفاءة"},"seo":{"title":{"en":"Debugging-with-Tools: Efficient Bug Fixing Setup Guide | ...","zh":"AI工具调试最佳实践 - debugging-with-tools Setup Guide","ja":"AIエージェントを使用したデバッグ - debugging-with-tools チュートリアル","ko":"AI 에이전트调试 방법 - debugging-with-tools 사용 가이드","es":"Guía de configuración de depuración con herramientas para...","fr":"Guide de configuration de débogage avec outils pour les A...","de":"Einrichtungsleitfaden für Debugging mit Tools für KI-Agenten","pt":"Guia de Configuração de Depuração com Ferramentas de AI","ru":"Настройка отладки с инструментами ИИ Агентов","ar":"دليل إعداد أدوات تصحيح الأخطاء مع وكلاء الذكاء الاصطناعي"},"description":{"en":"Unlock efficient debugging with tools! Learn how to use Codex compatibility and TodoWrite for checklist management. Get started now and refine your task trac...","zh":"学习如何使用 debugging-with-tools 优化代码调试流程，提高开发效率","ja":"debugging-with-tools を使用してコードのデバッグを最適化し、開発効率を向上させる方法を学びましょう","ko":"debugging-with-tools를 사용하여 코드 디버깅 프로세스를 최적화하고 개발 효율을 향상시키는 방법을 알아보세요","es":"Aprende a depurar con herramientas como Claude Code y Codex para mejorar la eficiencia de tus Agentes de IA","fr":"Découvrez comment déboguer avec des outils comme Claude Code et Codex pour améliorer l''efficacité de vos Agents d''IA","de":"Erfahren Sie, wie Sie mit Tools wie Claude Code und Codex debuggen, um die Effizienz Ihrer KI-Agenten zu verbessern","pt":"Aprenda a depurar com eficiência usando ferramentas de AI, reduzindo tempo e erros. Descubra como o skill ''debugging-with-tools'' pode ajudar","ru":"Эффективно отладите код с помощью инструментов ИИ Агентов, сократите время и ошибки. Узнайте, как умение ''debugging-with-tools'' может помочь","ar":"تعلم كيفية تصحيح الأخطاء بفعالية باستخدام أدوات وكلاء الذكاء الاصطناعي، وتقليل الوقت والأخطاء. اكتشف كيف يمكن لمهارة ''debugging-with-tools'' المساعدة"},"definition":{"en":"debugging-with-tools is a skill that utilizes tools like Codex compatibility and TodoWrite to streamline the debugging process, focusing on root cause analysis","zh":"debugging-with-tools 是一种代码调试方法，使用 beads 任务跟踪和细化来优化代码","ja":"debugging-with-tools は、コードのデバッグ方法で、beads タスク追跡とリファインメントを使用してコードを最適化します","ko":"debugging-with-tools는 코드 디버깅 방법으로, 비즈 태스크 추적 및 세부화를 통해 코드를 최적화하는 데 사용됩니다","es":"Depuración con herramientas es una técnica para identificar y solucionar errores en Agentes de IA utilizando herramientas especializadas","fr":"Le débogage avec outils est une technique pour identifier et résoudre les erreurs dans les Agents d''IA en utilisant des outils spécialisés","de":"Debugging mit Tools ist eine Technik, um Fehler in KI-Agenten mit spezialisierten Tools zu identifizieren und zu lösen","pt":"Depuração com ferramentas de AI é uma técnica que utiliza instrumentos de Inteligência Artificial para identificar e corrigir erros de codificação de forma eficiente","ru":"Отладка с инструментами ИИ - это техника, которая использует инструменты искусственного интеллекта для выявления и исправления ошибок кодирования эффективно","ar":"تصحيح الأخطاء بأدوات الذكاء الاصطناعي هو تقنية تستخدم أدوات الذكاء الاصطناعي لتحديد وتصحيح أخطاء الترميز بفعالية"},"features":{"en":["Utilizes Codex compatibility for efficient skill execution","Employs TodoWrite for creating and maintaining checklist sections","Supports Task() function for parallel dispatch via multi_tool_use.parallel","Reads skill''s SKILL.md file from disk for configuration","Refines task tracking and debugging processes using beads"],"zh":["使用 beads 任务跟踪和细化来优化代码","支持 Codex 兼容性","使用 TodoWrite 创建和维护检查清单","使用 Task() Dispatch 并行任务"],"ja":["beads タスク追跡とリファインメントを使用してコードを最適化","Codex との互換性をサポート","TodoWrite を使用してチェックリストを作成および維持","Task() を使用して並列タスクを Dispatch"],"ko":["비즈 태스크 추적 및 세부화를 통해 코드를 최적화","Codex 호환성 지원","TodoWrite를 사용하여 체크리스트を作成 및 유지","Task()를 사용하여 병렬 태스크 Dispatch"],"es":["Utiliza Claude Code para realizar un seguimiento de tareas y refinamiento","Integra con Codex para mejorar la eficiencia de la depuración","Permite la creación y mantenimiento de secciones de lista de tareas","Soporta la ejecución paralela de tareas con multi_tool_use.parallel","Incluye compatibilidad con SKILL.md para leer habilidades desde disco","Ofrece capacidades de depuración avanzadas con Task() y spawn_agent"],"fr":["Utilisez Claude Code pour suivre les tâches et le raffinement","Intégrez avec Codex pour améliorer l''efficacité du débogage","Permet la création et la maintenance de sections de liste de tâches","Prend en charge l''exécution parallèle de tâches avec multi_tool_use.parallel","Inclut la compatibilité avec SKILL.md pour lire les compétences depuis le disque","Offre des capacités de débogage avancées avec Task() et spawn_agent"],"de":["Verwenden Sie Claude Code, um Aufgaben und Raffinierung zu verfolgen","Integrieren Sie mit Codex, um die Effizienz des Debuggens zu verbessern","Ermöglicht die Erstellung und Wartung von Aufgabenlisten","Unterstützt die parallele Ausführung von Aufgaben mit multi_tool_use.parallel","Enthält die Kompatibilität mit SKILL.md, um Fähigkeiten von der Festplatte zu lesen","Bietet erweiterte Debugging-Funktionen mit Task() und spawn_agent"],"pt":["Utiliza beads para rastreamento e refinamento de tarefas","Fornece superpoderes de codificação com Claude Code","Permite a criação e manutenção de uma seção de checklist","Suporta a execução paralela de tarefas com multi_tool_use.parallel","Não requer hooks e comandos específicos de Claude"],"ru":["Использует beads для отслеживания и совершенствования задач","Предоставляет суперпowers кодирования с Claude Code","Позволяет создавать и поддерживать раздел списка задач","Поддерживает параллельное выполнение задач с multi_tool_use.parallel","Не требует хуков и команд, специфичных для Claude"],"ar":["يستخدم beads لتتبع وتحسين المهام","توفر قوى خارقة للترميز مع Claude Code","يسمح بإنشاءและการحفاظ على قسم قائمة المهام","يدعم تنفيذ المهام بالتوازي مع multi_tool_use.parallel","لا يتطلب hooks وأوامر محددة لشركة Claude"]},"keywords":{"en":["how to use debugging-with-tools","debugging-with-tools setup guide","Codex compatibility tutorial","TodoWrite checklist management","debugging-with-tools vs manual debugging","debugging-with-tools install for AI agents","what is debugging-with-tools","debugging-with-tools alternative tools","debugging-with-tools efficient bug fixing"],"zh":["AI工具调试","debugging-with-tools","代码调试最佳实践","Codex 兼容性","beads 任务跟踪","TodoWrite","Task() Dispatch"],"ja":["AIエージェントを使用したデバッグ","debugging-with-tools","コードデバッグベストプラクティス","Codex との互換性","beads タスク追跡","TodoWrite","Task() Dispatch"],"ko":["AI 에이전트 디버깅","debugging-with-tools","코드 디버깅 방법","Codex 호환성","비즈 태스크 추적","TodoWrite","Task() Dispatch"],"es":["depuración con herramientas","Agentes de IA","Claude Code","Codex","SKILL.md","Task()","spawn_agent","multi_tool_use.parallel","depuración avanzada","eficiencia de la depuración"],"fr":["débogage avec outils","Agents d''IA","Claude Code","Codex","SKILL.md","Task()","spawn_agent","multi_tool_use.parallel","débogage avancé","efficacité du débogage"],"de":["Debugging mit Tools","KI-Agenten","Claude Code","Codex","SKILL.md","Task()","spawn_agent","multi_tool_use.parallel","erweitertes Debugging","Effizienz des Debuggens"],"pt":["depuração com ferramentas de AI","ferramentas de depuração de código","Claude Code","beads para rastreamento de tarefas","superpoderes de codificação","multi_tool_use.parallel","desenvolvimento de software com AI"],"ru":["отладка с инструментами ИИ","инструменты отладки кода","Claude Code","beads для отслеживания задач","суперпowers кодирования","multi_tool_use.parallel","разработка программного обеспечения с ИИ"],"ar":["تصحيح الأخطاء بأدوات الذكاء الاصطناعي","أدوات تصحيح أخطاء الترميز","Claude Code","beads لتتبع المهام","قوى خارقة للترميز","multi_tool_use.parallel","تطوير البرمجيات مع الذكاء الاصطناعي"]}},"owner":"withzombies","repo":"hyperpowers","repoPath":"withzombies/hyperpowers","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.328Z","topics":[],"category":"community","skillMd":{"name":"debugging-with-tools","description":"Use when encountering bugs or test failures - systematic debugging using debuggers, internet research, and agents to find root cause before fixing","bodyPreview":"<codex_compat>\nThis skill was ported from Claude Code. In Codex:\n- \"Skill tool\" means read the skill''s `SKILL.md` from disk.\n- \"TodoWrite\" means create and maintain a checklist section in your response.\n- \"Task()\" means `spawn_agent` (dispatch in parallel via `multi_tool_use.parallel` when needed).\n- Claude-specific hooks and slash commands are not available; skip those steps.\n</codex_compat>\n\n\n<skill_overview>\nRandom fixes waste time and create new bugs. Always use tools to understand root caus","body":"<codex_compat>\nThis skill was ported from Claude Code. In Codex:\n- \"Skill tool\" means read the skill''s `SKILL.md` from disk.\n- \"TodoWrite\" means create and maintain a checklist section in your response.\n- \"Task()\" means `spawn_agent` (dispatch in parallel via `multi_tool_use.parallel` when needed).\n- Claude-specific hooks and slash commands are not available; skip those steps.\n</codex_compat>\n\n\n<skill_overview>\nRandom fixes waste time and create new bugs. Always use tools to understand root cause BEFORE attempting fixes. Symptom fixes are failure.\n</skill_overview>\n\n<rigidity_level>\nMEDIUM FREEDOM - Must complete investigation phases (tools → hypothesis → test) before fixing.\n\nCan adapt tool choice to language/context. Never skip investigation or guess at fixes.\n</rigidity_level>\n\n<quick_reference>\n\n| Phase | Tools to Use | Output |\n|-------|--------------|--------|\n| **1. Investigate** | Error messages, internet-researcher agent, debugger, codebase-investigator | Root cause understanding |\n| **2. Hypothesize** | Form theory based on evidence (not guesses) | Testable hypothesis |\n| **3. Test** | Validate hypothesis with minimal change | Confirms or rejects theory |\n| **4. Fix** | Implement proper fix for root cause | Problem solved permanently |\n\n**FORBIDDEN:** Skip investigation → guess at fix → hope it works\n**REQUIRED:** Tools → evidence → hypothesis → test → fix\n\n**Key agents:**\n- `internet-researcher` - Search error messages, known bugs, solutions\n- `codebase-investigator` - Understand code structure, find related code\n- `test-runner` - Run tests without output pollution\n\n</quick_reference>\n\n<when_to_use>\n**Use for ANY technical issue:**\n- Test failures\n- Bugs in production or development\n- Unexpected behavior\n- Build failures\n- Integration issues\n- Performance problems\n\n**ESPECIALLY when:**\n- \"Just one quick fix\" seems obvious\n- Under time pressure (emergencies make guessing tempting)\n- Error message is unclear\n- Previous fix didn''t work\n</when_to_use>\n\n<the_process>\n\n## Phase 1: Tool-Assisted Investigation\n\n**BEFORE attempting ANY fix, gather evidence with tools:**\n\n### 1. Read Complete Error Messages\n\n- Entire error message (not just first line)\n- Complete stack trace (all frames)\n- Line numbers, file paths, error codes\n- Stack traces show exact execution path\n\n### 2. Search Internet FIRST (Use internet-researcher Agent)\n\n**Dispatch internet-researcher with:**\n```\n\"Search for error: [exact error message]\n- Check Stack Overflow solutions\n- Look for GitHub issues in [library] version [X]\n- Find official documentation explaining this error\n- Check if this is a known bug\"\n```\n\n**What agent should find:**\n- Exact matches to your error\n- Similar symptoms and solutions\n- Known bugs in your dependency versions\n- Workarounds that worked for others\n\n### 3. Use Debugger to Inspect State\n\n**Claude cannot run debuggers directly. Instead:**\n\n**Option A - Recommend debugger to user:**\n```\n\"Let''s use lldb/gdb/DevTools to inspect state at error location.\nPlease run: [specific commands]\nWhen breakpoint hits: [what to inspect]\nShare output with me.\"\n```\n\n**Option B - Add instrumentation Claude can add:**\n```rust\n// Add logging\nprintln!(\"DEBUG: var = {:?}, state = {:?}\", var, state);\n\n// Add assertions\nassert!(condition, \"Expected X but got {:?}\", actual);\n```\n\n### 4. Investigate Codebase (Use codebase-investigator Agent)\n\n**Dispatch codebase-investigator with:**\n```\n\"Error occurs in function X at line Y.\nFind:\n- How is X called? What are the callers?\n- What does variable Z contain at this point?\n- Are there similar functions that work correctly?\n- What changed recently in this area?\"\n```\n\n## Phase 2: Form Hypothesis\n\n**Based on evidence (not guesses):**\n\n1. **State what you know** (from investigation)\n2. **Propose theory** explaining the evidence\n3. **Make prediction** that tests the theory\n\n**Example:**\n```\nKnown: Error \"null pointer\" at auth.rs:45 when email is empty\nTheory: Empty email bypasses validation, passes null to login()\nPrediction: Adding validation before login() will prevent error\nTest: Add validation, verify error doesn''t occur with empty email\n```\n\n**NEVER:**\n- Guess without evidence\n- Propose fix without hypothesis\n- Skip to \"try this and see\"\n\n## Phase 3: Test Hypothesis\n\n**Minimal change to validate theory:**\n\n1. Make smallest change that tests hypothesis\n2. Run test/reproduction case\n3. Observe result\n\n**If confirmed:** Proceed to Phase 4\n**If rejected:** Return to Phase 1 with new information\n\n## Phase 4: Implement Fix\n\n**After understanding root cause:**\n\n1. Write test reproducing bug (RED phase - use test-driven-development skill)\n2. Implement proper fix addressing root cause\n3. Verify test passes (GREEN phase)\n4. Run full test suite (regression check)\n5. Commit fix\n\n**The fix should:**\n- Address root cause (not symptom)\n- Be minimal and focused\n- Include test preventing regression\n\n</the_process>\n\n<examples>\n\n<example>\n<scenario>Developer encounters test failure, immediately tries \"obvious\" fix without investigation</scenario>\n\n<code>\nTest error:\n```\nFAIL: test_login_expired_token\nAssertionError: Expected Err(TokenExpired), got Ok(User)\n```\n\nDeveloper thinks: \"Obviously the token expiration check is wrong\"\n\nMakes change without investigation:\n```rust\n// \"Fix\" - just check if token is expired\nif token.expires_at < now() {\n    return Err(AuthError::TokenExpired);\n}\n```\n\nCommits without testing other cases.\n</code>\n\n<why_it_fails>\n**No investigation:**\n- Didn''t read error completely\n- Didn''t check what `expires_at` contains\n- Didn''t debug to see token state\n- Didn''t search for similar issues\n\n**What actually happened:** Token `expires_at` was being parsed incorrectly, always showing future date. The \"fix\" adds dead code that never runs.\n\n**Result:** Bug not fixed, new dead code added, time wasted.\n</why_it_fails>\n\n<correction>\n**Phase 1 - Investigate with tools:**\n\n```bash\n# 1. Read complete error\nFAIL: test_login_expired_token at line 45\nExpected: Err(TokenExpired)\nGot: Ok(User { id: 123 })\nToken: { expires_at: \"2099-01-01\", ... }\n```\n\n**Dispatch internet-researcher:**\n```\n\"Search for: token expiration always showing future date\n- Check date parsing bugs\n- Look for timezone issues\n- Find JWT expiration handling\"\n```\n\n**Add instrumentation:**\n```rust\nprintln!(\"DEBUG: expires_at = {:?}, now = {:?}, expired = {:?}\",\n         token.expires_at, now(), token.expires_at < now());\n```\n\n**Run test again:**\n```\nDEBUG: expires_at = 2099-01-01T00:00:00Z, now = 2024-01-15T10:30:00Z, expired = false\n```\n\n**Phase 2 - Hypothesis:**\n\"Token `expires_at` is being set to 2099, not actual expiration. Problem is in token creation, not validation.\"\n\n**Phase 3 - Test:**\nCheck token creation code:\n```rust\n// Found the bug!\nfn create_token() -> Token {\n    Token {\n        expires_at: \"2099-01-01\".parse()?, // HARDCODED!\n        ...\n    }\n}\n```\n\n**Phase 4 - Fix root cause:**\n```rust\nfn create_token(duration: Duration) -> Token {\n    Token {\n        expires_at: now() + duration,  // Correct\n        ...\n    }\n}\n```\n\n**Result:** Root cause fixed, test passes, no dead code.\n</correction>\n</example>\n\n<example>\n<scenario>Developer skips internet search, reinvents solution to known problem</scenario>\n\n<code>\nError:\n```\nerror: linking with `cc` failed: exit status: 1\nld: symbol(s) not found for architecture arm64\n```\n\nDeveloper thinks: \"Must be a linking issue, I''ll add flags\"\n\nSpends 2 hours trying different linker flags:\n```toml\n[target.aarch64-apple-darwin]\nrustflags = [\"-C\", \"link-arg=-undefined dynamic_lookup\"]\n# Doesn''t work, tries more flags...\n```\n</code>\n\n<why_it_fails>\n**Skipped internet search:**\n- This is a common error with known solutions\n- Stack Overflow has exact fix\n- Official docs explain the issue\n- Wasted 2 hours reinventing solution\n\n**Why it happens:** Impatience, thinking \"I can figure this out faster\"\n</why_it_fails>\n\n<correction>\n**Dispatch internet-researcher FIRST:**\n\n```\n\"Search for: ''symbol not found for architecture arm64'' Rust linking\n- Check Stack Overflow solutions\n- Look for Xcode/macOS specific fixes\n- Find Cargo configuration for Apple Silicon\"\n```\n\n**Agent returns (30 seconds):**\n```\nFound on Stack Overflow (2.4k upvotes):\nThis occurs when Xcode Command Line Tools aren''t installed or outdated.\n\nSolution:\nxcode-select --install\n\nOr update existing:\nsoftwareupdate --all --install --force\n```\n\n**Apply solution:**\n```bash\nxcode-select --install\n# Wait for installation\ncargo build\n# Success!\n```\n\n**Result:** Fixed in 5 minutes, not 2 hours.\n</correction>\n</example>\n\n<example>\n<scenario>Developer fixes symptom without understanding root cause, bug returns different way</scenario>\n\n<code>\nBug: Users can delete other users'' posts\n\nDeveloper notices: DELETE /posts/:id doesn''t check ownership\n\n\"Fix\":\n```python\n@app.delete(\"/posts/{post_id}\")\ndef delete_post(post_id: int, user: User):\n    post = get_post(post_id)\n    if post.author_id != user.id:\n        raise Forbidden()\n    delete(post)\n```\n\nBug \"fixed\"... but bug report comes back: \"Users can edit other users'' posts\"\n</code>\n\n<why_it_fails>\n**Symptom fix:**\n- Fixed DELETE endpoint\n- Didn''t investigate root cause\n- Didn''t check other endpoints\n\n**Root cause:** No authorization middleware checking ownership across ALL endpoints.\n\n**Result:** Whack-a-mole fixing symptoms, not the underlying issue.\n</why_it_fails>\n\n<correction>\n**Phase 1 - Investigate with codebase-investigator:**\n\n```\n\"User can delete other users'' posts. Investigate:\n- What authorization exists across all post endpoints?\n- Is there a pattern for ownership checks?\n- Which other endpoints access posts?\n- Is there middleware handling this?\"\n```\n\n**Agent reports:**\n```\nFound:\n- DELETE /posts/:id - NO ownership check\n- PUT /posts/:id - NO ownership check\n- GET /posts/:id - NO ownership check (allows viewing private posts!)\n- No authorization middleware found\n- Similar pattern in comments, likes endpoints\n```\n\n**Phase 2 - Hypothesis:**\n\"Missing authorization layer. Need middleware checking resource ownership across ALL endpoints.\"\n\n**Phase 4 - Fix root cause:**\n```python\n# Add authorization middleware\nclass OwnershipMiddleware:\n    def check_ownership(self, resource, user):\n        if resource.author_id != user.id:\n            raise Forbidden()\n\n# Apply to all endpoints\n@app.delete(\"/posts/{post_id}\")\n@require_ownership(Post)\ndef delete_post(...):\n    ...\n\n@app.put(\"/posts/{post_id}\")\n@require_ownership(Post)\ndef update_post(...):\n    ...\n```\n\n**Result:** Root cause fixed, ALL endpoints secured, not just one symptom.\n</correction>\n</example>\n\n</examples>\n\n<critical_rules>\n\n## Rules That Have No Exceptions\n\n1. **Tools before fixes** → Never guess without investigation\n   - Use internet-researcher for errors\n   - Use debugger or instrumentation for state\n   - Use codebase-investigator for context\n\n2. **Evidence-based hypotheses** → Not guesses or hunches\n   - State what tools revealed\n   - Propose theory explaining evidence\n   - Make testable prediction\n\n3. **Test hypothesis before fixing** → Minimal change to validate\n   - Smallest change that tests theory\n   - Observe result\n   - If wrong, return to investigation\n\n4. **Fix root cause, not symptom** → One fix, many symptoms prevented\n   - Understand why problem occurred\n   - Fix the underlying issue\n   - Don''t play whack-a-mole\n\n## Common Excuses\n\nAll of these mean: Stop, use tools to investigate:\n- \"The fix is obvious\"\n- \"I know what this is\"\n- \"Just a quick try\"\n- \"No time for debugging\"\n- \"Error message is clear enough\"\n- \"Internet search will take too long\"\n\n</critical_rules>\n\n<verification_checklist>\n\nBefore proposing any fix:\n- [ ] Read complete error message (not just first line)\n- [ ] Dispatched internet-researcher for unclear errors\n- [ ] Used debugger or added instrumentation to inspect state\n- [ ] Dispatched codebase-investigator to understand context\n- [ ] Formed hypothesis based on evidence (not guesses)\n- [ ] Tested hypothesis with minimal change\n- [ ] Verified hypothesis confirmed before fixing\n\nBefore committing fix:\n- [ ] Written test reproducing bug (RED phase)\n- [ ] Verified test fails before fix\n- [ ] Implemented fix addressing root cause\n- [ ] Verified test passes after fix (GREEN phase)\n- [ ] Ran full test suite (regression check)\n\n</verification_checklist>\n\n<integration>\n\n**This skill calls:**\n- internet-researcher (search errors, known bugs, solutions)\n- codebase-investigator (understand code structure, find related code)\n- test-driven-development (write test for bug, implement fix)\n- test-runner (run tests without output pollution)\n\n**This skill is called by:**\n- fixing-bugs (complete bug fix workflow)\n- root-cause-tracing (deep debugging for complex issues)\n- Any skill when encountering unexpected behavior\n\n**Agents used:**\n- hyperpowers:internet-researcher (search for error solutions)\n- hyperpowers:codebase-investigator (understand codebase context)\n- hyperpowers:test-runner (run tests, return summary only)\n\n</integration>\n\n<resources>\n\n**Detailed guides:**\n- [Debugger reference](resources/debugger-reference.md) - LLDB, GDB, DevTools commands\n- [Debugging session example](resources/debugging-session-example.md) - Complete walkthrough\n\n**When stuck:**\n- Error unclear → Dispatch internet-researcher with exact error text\n- Don''t understand code flow → Dispatch codebase-investigator\n- Need to inspect runtime state → Recommend debugger to user or add instrumentation\n- Tempted to guess → Stop, use tools to gather evidence first\n\n</resources>"},"lastSynced":"2026-03-08T02:03:06.166Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Analysis Agents needing efficient debugging capabilities with tools like Codex and TodoWrite.","zh":"适用于需要高效调试功能的代码分析代理，尤其是与Codex和TodoWrite等工具配合使用时。","ja":"CodexやTodoWriteなどのツールを使用して効率的なデバッグ機能を必要とするコード分析エージェントに適しています。","ko":"Codex 및 TodoWrite와 같은 도구를 사용하여 효율적인 디버깅 기능이 필요한 코드 분석 에이전트에 적합합니다.","es":"Perfecto para Agentes de Análisis de Código que necesitan capacidades de depuración eficientes con herramientas como Codex y TodoWrite.","fr":"Parfait pour les Agents d''Analyse de Code ayant besoin de capacités de débogage efficaces avec des outils comme Codex et TodoWrite.","de":"Perfekt für Code-Analyse-Agents, die effiziente Debugging-Funktionen mit Tools wie Codex und TodoWrite benötigen.","pt":"Perfeito para Agentes de Análise de Código que precisam de capacidades de depuração eficientes com ferramentas como Codex e TodoWrite.","ru":"Идеально подходит для агентов анализа кода, которым необходимы эффективные возможности отладки с помощью инструментов, таких как Codex и TodoWrite.","ar":"مثالي للعملاء قادرون على تحليل الشفرة الذين يحتاجون إلى إمكانيات فحص فعالة بأدوات مثل Codex و TodoWrite."},"recommendation":{"en":"Empowers agents to systematically debug code, reducing random fixes and new bugs by leveraging tools like Codex for code analysis and TodoWrite for task management, utilizing protocols such as multi_tool_use.parallel for parallel task execution.","zh":"赋予代理系统地调试代码的能力，通过利用Codex进行代码分析和TodoWrite进行任务管理，使用诸如multi_tool_use.parallel的协议来实现并行任务执行，从而减少随机修复和新错误。","ja":"エージェントにコードを体系的にデバッグする能力を与え、Codexを使用したコード分析とTodoWriteを使用したタスク管理を活用し、multi_tool_use.parallelなどのプロトコルを使用して並列タスクの実行を実現し、ランダムな修正と新しいバグを減らします。","ko":"에이전트가 코드를 체계적으로 디버깅할 수 있는 능력을 부여하여 Codex를 사용한 코드 분석과 TodoWrite를 사용한 작업 관리를 활용하고 multi_tool_use.parallel과 같은 프로토콜을 사용하여 병렬 작업 실행을 구현함으로써 임의의 수정과 새로운 오류를 줄입니다.","es":"Habilita a los agentes a depurar sistemáticamente el código, reduciendo las soluciones aleatorias y los nuevos errores al aprovechar herramientas como Codex para el análisis de código y TodoWrite para la gestión de tareas, utilizando protocolos como multi_tool_use.parallel para la ejecución de tareas paralelas.","fr":"Permet aux agents de déboguer systématiquement le code, en réduisant les solutions aléatoires et les nouveaux bogues en exploitant des outils comme Codex pour l''analyse de code et TodoWrite pour la gestion de tâches, en utilisant des protocoles tels que multi_tool_use.parallel pour l''exécution de tâches parallèles.","de":"Ermächtigt die Agenten, den Code systematisch zu debuggen, indem sie zufällige Lösungen und neue Fehler durch die Nutzung von Tools wie Codex für die Code-Analyse und TodoWrite für das Task-Management reduzieren, unter Nutzung von Protokollen wie multi_tool_use.parallel für die parallele Aufgabenausführung.","pt":"Habilita os agentes a depurar sistematicamente o código, reduzindo reparos aleatórios e novos bugs, aproveitando ferramentas como Codex para análise de código e TodoWrite para gerenciamento de tarefas, utilizando protocolos como multi_tool_use.parallel para execução de tarefas paralelas.","ru":"Позволяет агентам систематически отлаживать код, снижая количество случайных исправлений и новых ошибок, используя инструменты, такие как Codex для анализа кода и TodoWrite для управления задачами, используя протоколы, такие как multi_tool_use.parallel для параллельного выполнения задач.","ar":"يمنح العملاء القدرة على فحص الشفرة بشكل منهجي، مما يقلل من الإصلاحات العشوائية والاخطاء الجديدة من خلال استخدام أدوات مثل Codex لتحليل الشفرة و TodoWrite لإدارة المهام، باستخدام بروتوكولات مثل multi_tool_use.parallel لتنفيذ المهام الموازية."},"useCases":{"en":["Debugging code issues with Codex","Creating and maintaining checklists with TodoWrite","Automating bug fixing workflows"],"zh":["使用Codex调试代码问题","使用TodoWrite创建和维护检查清单","自动化错误修复工作流"],"ja":["Codexを使用したコードの問題のデバッグ","TodoWriteを使用したチェックリストの作成と維持","バグ修正ワークフローの自動化"],"ko":["Codex를 사용한 코드 문제 디버깅","TodoWrite를 사용한 체크리스트 생성 및 유지","오류 수정 워크플로 자동화"],"es":["Depuración de problemas de código con Codex","Creación y mantenimiento de listas de verificación con TodoWrite","Automatización de flujos de trabajo de solución de errores"],"fr":["Débogage des problèmes de code avec Codex","Création et maintenance de listes de contrôle avec TodoWrite","Automatisation des flux de travail de correction de bogues"],"de":["Fehlerbehebung von Codeproblemen mit Codex","Erstellung und Wartung von Prüflisten mit TodoWrite","Automatisierung von Fehlernbehebungs-Workflows"],"pt":["Depuração de problemas de código com Codex","Criação e manutenção de listas de verificação com TodoWrite","Automação de fluxos de trabalho de reparo de bugs"],"ru":["Отладка проблем кода с помощью Codex","Создание и поддержание списков проверки с помощью TodoWrite","Автоматизация рабочих процессов исправления ошибок"],"ar":["فحص مشاكل الشفرة مع Codex","إنشاء وقائمة الصيانة مع TodoWrite","تأتمة تدفقات العمل لتصحيح الأخطاء"]},"limitations":{"en":["Requires access to Codex and TodoWrite tools","Claude-specific hooks and slash commands are not supported"],"zh":["需要访问Codex和TodoWrite工具","不支持Claude特定的钩子和斜杠命令"],"ja":["CodexとTodoWriteのツールへのアクセスが必要","Claude固有のフックとスラッシュコマンドはサポートされていません"],"ko":["Codex 및 TodoWrite 도구에 대한 액세스가 필요함","Claude 특有的 후크 및 슬래시 명령어는 지원되지 않음"],"es":["Requiere acceso a las herramientas Codex y TodoWrite","No se admiten ganchos ni comandos de barra específicos de Claude"],"fr":["Nécessite l''accès aux outils Codex et TodoWrite","Les crochets et les commandes de barre spécifiques à Claude ne sont pas pris en charge"],"de":["Erfordert den Zugriff auf die Tools Codex und TodoWrite","Claude-spezifische Hooks und Slash-Befehle werden nicht unterstützt"],"pt":["Requer acesso às ferramentas Codex e TodoWrite","Ganchos e comandos específicos do Claude não são suportados"],"ru":["Требуется доступ к инструментам Codex и TodoWrite","Крючки и команды, специфичные для Claude, не поддерживаются"],"ar":["ي_requires الوصول إلى أدوات Codex و TodoWrite","الخطافات والأوامر المحددة ل Claude غير مدعومة"]},"version":4},"contentHash":"d3980914f5dc48666cf345e9a6cb56d90edda5c7d774f9c7fdfc3c0e6599ef31","qualityScore":39}');
