INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('withzombies/hyperpowers/debugging-with-tools', 'debugging-with-tools', 'withzombies', 'hyperpowers', 'community', 'debugging-with-tools withzombies hyperpowers community The debugging-with-tools skill enables AI agents to efficiently debug code using tools like Codex and TodoWrite, benefiting developers by reducing random fixes and new bugs. debugging-with-tools 是一种使用工具来理解代码根源的调试方法，通过 beads 任务跟踪和细化来优化代码 debugging-with-tools は、コードの根本原因を理解するためにツールを使用するデバッグ方法で、beads タスク追跡とリファインメントを使用してコードを最適化します debugging-with-tools는 코드의 근본 원인을 이해하기 위해 도구를 사용하는 디버깅 방법으로, 비즈 태스크 추적 및 세부화를 통해 코드를 최적화합니다 La depuración con herramientas como Claude Code y Codex es crucial para entender las causas raíz de los errores en tus Agentes de IA Le débogage avec des outils comme Claude Code et Codex est essentiel pour comprendre les causes profondes des erreurs dans vos Agents d''IA Das Debuggen mit Tools wie Claude Code und Codex ist entscheidend, um die Ursachen von Fehlern in Ihren KI-Agenten zu verstehen O skill ''debugging-with-tools'' fornece superpoderes de codificação com beads para rastreamento e refinamento de tarefas, permitindo uma depuração mais eficiente Умение ''debugging-with-tools'' предоставляет суперпowers кодирования с beads для отслеживания и совершенствования задач, позволяя более эффективно отлаживать код المهارة ''debugging-with-tools'' توفر قوى خارقة للترميز مع beads لتتبع وتحسين المهام، مما يسمح بتصحيح أخطاء أكثر كفاءة how to use debugging-with-tools debugging-with-tools setup guide Codex compatibility tutorial TodoWrite checklist management debugging-with-tools vs manual debugging debugging-with-tools install for AI agents what is debugging-with-tools debugging-with-tools alternative tools debugging-with-tools efficient bug fixing AI工具调试 debugging-with-tools 代码调试最佳实践 Codex 兼容性 beads 任务跟踪 TodoWrite Task() Dispatch Utilizes Codex compatibility for efficient skill execution Employs TodoWrite for creating and maintaining checklist sections Supports Task() function for parallel dispatch via multi_tool_use.parallel Reads skill''s SKILL.md file from disk for configuration Refines task tracking and debugging processes using beads debugging-with-tools is a skill that utilizes tools like Codex compatibility and TodoWrite to streamline the debugging process, focusing on root cause analysis');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('scotttrinh/nook/effect-patterns-scheduling-periodic-tasks', 'community', 'scotttrinh', 'nook', 'scotttrinh/nook', 'effect-patterns-scheduling-periodic-tasks', 0, 0, 39, '2026-03-08T01:57:15.332Z', '2026-03-08T02:03:15.779Z', '2a13914b47db688bdd1705a78a6ed6d1965f35c90a558f8e3a46471f76e1d295', '{"id":"scotttrinh/nook/effect-patterns-scheduling-periodic-tasks","name":"effect-patterns-scheduling-periodic-tasks","description":{"en":"This skill provides curated Effect-TS patterns for scheduling periodic tasks, useful for tasks related to scheduling and best practices in Effect-TS applications.","zh":"Effect-TS 模块为隔离工作树容器提供了 3 个精选的调度周期任务模式","ja":"Effect-TS モジュールは、分離されたワークツリーコンテナー用に 3 つのカリブレーションされた周期タスクのスケジューリングパターンを提供","ko":"Effect-TS 모듈은 분리된 작업 트리 컨테이너를 위한 3개의 커리브레이션된 정기 작업 스케줄링 패턴을 제공","es":"El módulo NixOS para contenedores de worktree aislados proporciona patrones de Effect-TS para programar tareas periódicas","fr":"Le module NixOS pour les conteneurs de worktree isolés fournit des modèles Effect-TS pour planifier des tâches périodiques","de":"Das NixOS-Modul für isolierte Worktree-Container bietet Effect-TS-Muster für die Planung von periodischen Aufgaben","pt":"O Effect-TS Patterns fornece 3 padrões curados para agendamento de tarefas periódicas, incluindo debounce e throttle para execução de tarefas críticas.","ru":"Effect-TS Patterns предоставляет 3 проверенных шаблона для планирования периодических задач, включая debounce и throttle для критических задач","ar":"نمط Effect-TS يوفر 3 أنماط مدروسة لجدولة المهام الدورية، بما في ذلك إيقاف التشغيل والتثبيط للعمليات الحاسمة"},"seo":{"title":{"en":"effect-patterns-scheduling-periodic-tasks: Scheduling Per...","zh":"Effect-TS 定期任务调度最佳实践","ja":"Effect-TS Periodic Task スケジューリングガイド","ko":"Effect-TS 정기 작업 스케줄링 설정 가이드","es":"Guía de Configuración de Tareas Periódicas con Effect-TS","fr":"Guide de Configuration des Tâches Périodiques avec Effect-TS","de":"Einrichtungsleitfaden für periodische Aufgaben mit Effect-TS","pt":"Guia de Configuração do Effect-TS Patterns: Scheduling Pe...","ru":"ИИ Агенты: Настройка Effect-TS Patterns для планирования ...","ar":"دليل إعداد Effect-TS Patterns لجدولة المهام الدورية"},"description":{"en":"Discover how to schedule periodic tasks with Effect-TS patterns. Learn best practices and real-world solutions for isolated worktree containers in NixOS.","zh":"使用 Effect-TS 模块实现隔离的工作树容器，并学习调度周期任务的最佳实践","ja":"Effect-TS モジュールを使用して分離されたワークツリーコンテナーを実装し、周期タスクのスケジューリングのベストプラクティスを学ぶ","ko":"Effect-TS 모듈을 사용하여 분리된 작업 트리 컨테이너를 구현하고 정기 작업 스케줄링의最佳实践을 학습","es":"Aprende a programar tareas periódicas con Effect-TS y sigue las mejores prácticas para aplicaciones Effect-TS","fr":"Découvrez comment planifier des tâches périodiques avec Effect-TS et suivez les meilleures pratiques pour les applications Effect-TS","de":"Erfahren Sie, wie Sie periodische Aufgaben mit Effect-TS planen und folgen Sie den besten Praktiken für Effect-TS-Anwendungen","pt":"Aprenda a utilizar o módulo NixOS para contêineres de worktree isolados e melhore suas habilidades em Effect-TS","ru":"Откройте для себя возможности Effect-TS Patterns для планирования периодических задач и узнайте, как использовать модуль NixOS для изолированных контейнеров ...","ar":"تعرف على كيفية استخدام نمط Effect-TS لجدولة المهام الدورية وتحسين مهاراتك في تطوير التطبيقات"},"definition":{"en":"effect-patterns-scheduling-periodic-tasks is a NixOS Module for isolated worktree containers, providing patterns for scheduling periodic tasks.","zh":"Effect-TS 是一种用于调度周期任务的模块，提供了隔离工作树容器的功能","ja":"Effect-TS は、分離されたワークツリーコンテナーを提供する周期タスクのスケジューリング用モジュール","ko":"Effect-TS 는 분리된 작업 트리 컨테이너를 제공하는 정기 작업 스케줄링용 모듈","es":"¿Qué es Effect-TS? Es un conjunto de patrones para programar tareas periódicas en aplicaciones Effect-TS","fr":"Qu''est-ce que Effect-TS? C''est un ensemble de modèles pour planifier des tâches périodiques dans les applications Effect-TS","de":"Was ist Effect-TS? Es ist eine Sammlung von Mustern für die Planung von periodischen Aufgaben in Effect-TS-Anwendungen","pt":"O que é Effect-TS Patterns? É um conjunto de padrões para agendamento de tarefas periódicas em aplicações Effect-TS","ru":"Что такое Effect-TS Patterns? Это набор шаблонов для планирования периодических задач в приложениях Effect-TS","ar":"ما هو نمط Effect-TS؟ هو مجموعة من الأنماط لجدولة المهام الدورية في التطبيقات Effect-TS"},"features":{"en":["Provides 3 curated Effect-TS patterns for scheduling periodic tasks","Includes Scheduling Pattern 4: Debounce and Throttle Execution for critical task management","Supports isolated worktree containers in NixOS","Offers best practices in Effect-TS applications","Includes real-world patterns and solutions for periodic task scheduling"],"zh":["使用 Debounce 和 Throttle 执行调度","提供 3 个精选的调度周期任务模式","支持隔离工作树容器","适用于 Effect-TS 应用程序的最佳实践","提供实用模式和解决方案"],"ja":["Debounce と Throttle を使用したスケジューリングの実行","3 つのカリブレーションされた周期タスクのスケジューリングパターンを提供","分離されたワークツリーコンテナーのサポート","Effect-TS アプリケーションのベストプラクティス","実用的なパターンとソリューションの提供"],"ko":["Debounce 와 Throttle 을 사용한 스케줄링 실행","3개의 커리브레이션된 정기 작업 스케줄링 패턴을 제공","분리된 작업 트리 컨테이너의 지원","Effect-TS 애플리케이션의最佳实践","실용적인 패턴과 솔루션의 제공"],"es":["Patrones de Effect-TS para programar tareas periódicas","Uso de debounce y throttle para limitar la frecuencia de ejecución","Mejores prácticas para aplicaciones Effect-TS","Soluciones reales para programar tareas periódicas","Integración con contenedores de worktree aislados de NixOS"],"fr":["Modèles Effect-TS pour planifier des tâches périodiques","Utilisation de debounce et throttle pour limiter la fréquence d''exécution","Meilleures pratiques pour les applications Effect-TS","Solutions réelles pour planifier des tâches périodiques","Intégration avec les conteneurs de worktree isolés de NixOS"],"de":["Effect-TS-Muster für die Planung von periodischen Aufgaben","Verwendung von Debounce und Throttle zur Begrenzung der Ausführungshäufigkeit","Beste Praktiken für Effect-TS-Anwendungen","Reale Lösungen für die Planung von periodischen Aufgaben","Integration mit isolierten Worktree-Containern von NixOS"],"pt":["Utilização do módulo NixOS para contêineres de worktree isolados","Padrões de agendamento de tarefas periódicas com debounce e throttle","Melhoria das habilidades em Effect-TS com padrões de execução de tarefas críticas"],"ru":["Использование модуля NixOS для изолированных контейнеров worktree","Шаблоны планирования периодических задач с debounce и throttle","Улучшение навыков в Effect-TS с помощью шаблонов выполнения критических задач"],"ar":["استخدام وحدة NixOS لتحديد حاويات worktree معزولة","أنماط جدولة المهام الدورية مع إيقاف التشغيل والتثبيط","تحسين المهارات في تطوير التطبيقات Effect-TS باستخدام أنماط تنفيذ العمليات الحاسمة"]},"keywords":{"en":["how to use effect-patterns-scheduling-periodic-tasks","effect-patterns-scheduling-periodic-tasks alternative","effect-patterns-scheduling-periodic-tasks setup guide","what is effect-patterns-scheduling-periodic-tasks","effect-patterns-scheduling-periodic-tasks vs NixOS","effect-patterns-scheduling-periodic-tasks install"],"zh":["Effect-TS","调度周期任务","隔离工作树容器","Debounce 和 Throttle","Effect-TS 应用程序","最佳实践","实用模式和解决方案"],"ja":["Effect-TS","周期タスクのスケジューリング","分離されたワークツリーコンテナー","Debounce と Throttle","Effect-TS アプリケーション","ベストプラクティス","実用的なパターンとソリューション"],"ko":["Effect-TS","정기 작업 스케줄링","분리된 작업 트리 컨테이너","Debounce 와 Throttle","Effect-TS 애플리케이션","최佳实践","실용적인 패턴과 솔루션"],"es":["programar tareas periódicas","Effect-TS","NixOS","contenedores de worktree aislados","patrones de Effect-TS","mejores prácticas para aplicaciones Effect-TS","debounce y throttle","planificación de tareas periódicas"],"fr":["planifier des tâches périodiques","Effect-TS","NixOS","conteneurs de worktree isolés","modèles Effect-TS","meilleures pratiques pour les applications Effect-TS","debounce et throttle","planification de tâches périodiques"],"de":["periodische Aufgaben planen","Effect-TS","NixOS","isolierte Worktree-Container","Effect-TS-Muster","beste Praktiken für Effect-TS-Anwendungen","Debounce und Throttle","Planung von periodischen Aufgaben"],"pt":["Effect-TS Patterns","agendamento de tarefas periódicas","debounce e throttle","NixOS","contêineres de worktree isolados","melhoria das habilidades em Effect-TS"],"ru":["ИИ Агенты","Effect-TS Patterns","планирование периодических задач","debounce и throttle","NixOS","изолированные контейнеры worktree"],"ar":["نمط Effect-TS","جدولة المهام الدورية","إيقاف التشغيل والتثبيط","NixOS","حاويات worktree معزولة","تحسين المهارات في تطوير التطبيقات Effect-TS"]}},"owner":"scotttrinh","repo":"nook","repoPath":"scotttrinh/nook","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.332Z","topics":[],"category":"community","skillMd":{"name":"effect-patterns-scheduling-periodic-tasks","description":"Effect-TS patterns for Scheduling Periodic Tasks. Use when working with scheduling periodic tasks in Effect-TS applications.","bodyPreview":"# Effect-TS Patterns: Scheduling Periodic Tasks\nThis skill provides 3 curated Effect-TS patterns for scheduling periodic tasks.\nUse this skill when working on tasks related to:\n- scheduling periodic tasks\n- Best practices in Effect-TS applications\n- Real-world patterns and solutions\n\n---\n\n## 🟡 Intermediate Patterns\n\n### Scheduling Pattern 4: Debounce and Throttle Execution\n\n**Rule:** Use debounce to wait for silence before executing, and throttle to limit execution frequency, both critical for","body":"# Effect-TS Patterns: Scheduling Periodic Tasks\nThis skill provides 3 curated Effect-TS patterns for scheduling periodic tasks.\nUse this skill when working on tasks related to:\n- scheduling periodic tasks\n- Best practices in Effect-TS applications\n- Real-world patterns and solutions\n\n---\n\n## 🟡 Intermediate Patterns\n\n### Scheduling Pattern 4: Debounce and Throttle Execution\n\n**Rule:** Use debounce to wait for silence before executing, and throttle to limit execution frequency, both critical for handling rapid events.\n\n**Good Example:**\n\nThis example demonstrates debouncing and throttling for common scenarios.\n\n```typescript\nimport { Effect, Schedule, Ref } from \"effect\";\n\ninterface SearchQuery {\n  readonly query: string;\n  readonly timestamp: Date;\n}\n\n// Simulate API search\nconst performSearch = (query: string): Effect.Effect<string[]> =>\n  Effect.gen(function* () {\n    yield* Effect.log(`[API] Searching for: \"${query}\"`);\n\n    yield* Effect.sleep(\"100 millis\"); // Simulate API delay\n\n    return [\n      `Result 1 for ${query}`,\n      `Result 2 for ${query}`,\n      `Result 3 for ${query}`,\n    ];\n  });\n\n// Main: demonstrate debounce and throttle\nconst program = Effect.gen(function* () {\n  console.log(`\\n[DEBOUNCE/THROTTLE] Handling rapid events\\n`);\n\n  // Example 1: Debounce search input\n  console.log(`[1] Debounced search (wait for silence):\\n`);\n\n  const searchQueries = [\"h\", \"he\", \"hel\", \"hell\", \"hello\"];\n\n  const debouncedSearches = yield* Ref.make<Effect.Effect<string[]>[]>([]);\n\n  for (const query of searchQueries) {\n    yield* Effect.log(`[INPUT] User typed: \"${query}\"`);\n\n    // In real app, this would be debounced\n    yield* Effect.sleep(\"150 millis\"); // User typing\n  }\n\n  // After user stops, execute search\n  yield* Effect.log(`[DEBOUNCE] User silent for 200ms, executing search`);\n\n  const searchResults = yield* performSearch(\"hello\");\n\n  yield* Effect.log(`[RESULTS] ${searchResults.length} results found\\n`);\n\n  // Example 2: Throttle scroll events\n  console.log(`[2] Throttled scroll handler (max 10/sec):\\n`);\n\n  const scrollEventCount = yield* Ref.make(0);\n  const updateCount = yield* Ref.make(0);\n\n  // Simulate 100 rapid scroll events\n  for (let i = 0; i < 100; i++) {\n    yield* Ref.update(scrollEventCount, (c) => c + 1);\n\n    // In real app, scroll handler would be throttled\n    if (i % 10 === 0) {\n      // Simulate throttled update (max 10 per second)\n      yield* Ref.update(updateCount, (c) => c + 1);\n    }\n  }\n\n  const events = yield* Ref.get(scrollEventCount);\n  const updates = yield* Ref.get(updateCount);\n\n  yield* Effect.log(\n    `[THROTTLE] ${events} scroll events → ${updates} updates (${(updates / events * 100).toFixed(1)}% update rate)\\n`\n  );\n\n  // Example 3: Deduplication\n  console.log(`[3] Deduplicating rapid events:\\n`);\n\n  const userClicks = [\"click\", \"click\", \"click\", \"dblclick\", \"click\"];\n\n  const lastClick = yield* Ref.make<string | null>(null);\n  const clickCount = yield* Ref.make(0);\n\n  for (const click of userClicks) {\n    const prev = yield* Ref.get(lastClick);\n\n    if (click !== prev) {\n      yield* Effect.log(`[CLICK] Processing: ${click}`);\n      yield* Ref.update(clickCount, (c) => c + 1);\n      yield* Ref.set(lastClick, click);\n    } else {\n      yield* Effect.log(`[CLICK] Duplicate: ${click} (skipped)`);\n    }\n  }\n\n  const processed = yield* Ref.get(clickCount);\n\n  yield* Effect.log(\n    `\\n[DEDUPE] ${userClicks.length} clicks → ${processed} processed\\n`\n  );\n\n  // Example 4: Exponential backoff on repeated errors\n  console.log(`[4] Throttled retry on errors:\\n`);\n\n  let retryCount = 0;\n\n  const operation = Effect.gen(function* () {\n    retryCount++;\n\n    if (retryCount < 3) {\n      yield* Effect.fail(new Error(\"Still failing\"));\n    }\n\n    yield* Effect.log(`[SUCCESS] Succeeded on attempt ${retryCount}`);\n\n    return \"done\";\n  }).pipe(\n    Effect.retry(\n      Schedule.exponential(\"100 millis\").pipe(\n        Schedule.upTo(\"1 second\"),\n        Schedule.recurs(5)\n      )\n    )\n  );\n\n  yield* operation;\n});\n\nEffect.runPromise(program);\n```\n\n---\n\n**Rationale:**\n\nDebounce and throttle manage rapid events:\n\n- **Debounce**: Wait for silence (delay after last event), then execute once\n- **Throttle**: Execute at most once per interval\n- **Deduplication**: Skip duplicate events\n- **Rate limiting**: Limit events per second\n\nPattern: `Schedule.debounce(duration)` or `Schedule.throttle(maxEvents, duration)`\n\n---\n\n\nRapid events without debounce/throttle cause problems:\n\n**Debounce example**: Search input\n- User types \"hello\" character by character\n- Without debounce: 5 API calls (one per character)\n- With debounce: 1 API call after user stops typing\n\n**Throttle example**: Scroll events\n- Scroll fires 100+ times per second\n- Without throttle: Updates lag, GC pressure\n- With throttle: Update max 60 times per second\n\nReal-world issues:\n- **API overload**: Search queries hammer backend\n- **Rendering lag**: Too many DOM updates\n- **Resource exhaustion**: Event handlers never catch up\n\nDebounce/throttle enable:\n- **Efficiency**: Fewer operations\n- **Responsiveness**: UI stays smooth\n- **Resource safety**: Prevent exhaustion\n- **Sanity**: Predictable execution\n\n---\n\n---\n\n### Scheduling Pattern 3: Schedule Tasks with Cron Expressions\n\n**Rule:** Use cron expressions to schedule periodic tasks at specific calendar times, enabling flexible scheduling beyond simple fixed intervals.\n\n**Good Example:**\n\nThis example demonstrates scheduling a daily report generation using cron, with timezone support.\n\n```typescript\nimport { Effect, Schedule, Console } from \"effect\";\nimport { DateTime } from \"luxon\"; // For timezone handling\n\ninterface ReportConfig {\n  readonly cronExpression: string;\n  readonly timezone?: string;\n  readonly jobName: string;\n}\n\ninterface ScheduledReport {\n  readonly timestamp: Date;\n  readonly jobName: string;\n  readonly result: string;\n}\n\n// Simple cron parser (in production, use a library like cron-parser)\nconst parseCronExpression = (\n  expression: string\n): {\n  minute: number[];\n  hour: number[];\n  dayOfMonth: number[];\n  month: number[];\n  dayOfWeek: number[];\n} => {\n  const parts = expression.split(\" \");\n\n  const parseField = (field: string, max: number): number[] => {\n    if (field === \"*\") {\n      return Array.from({ length: max + 1 }, (_, i) => i);\n    }\n\n    if (field.includes(\",\")) {\n      return field.split(\",\").flatMap((part) => parseField(part, max));\n    }\n\n    if (field.includes(\"-\")) {\n      const [start, end] = field.split(\"-\").map(Number);\n      return Array.from({ length: end - start + 1 }, (_, i) => start + i);\n    }\n\n    return [Number(field)];\n  };\n\n  return {\n    minute: parseField(parts[0], 59),\n    hour: parseField(parts[1], 23),\n    dayOfMonth: parseField(parts[2], 31),\n    month: parseField(parts[3], 12),\n    dayOfWeek: parseField(parts[4], 6),\n  };\n};\n\n// Check if current time matches cron expression\nconst shouldRunNow = (parsed: ReturnType<typeof parseCronExpression>): boolean => {\n  const now = new Date();\n\n  return (\n    parsed.minute.includes(now.getUTCMinutes()) &&\n    parsed.hour.includes(now.getUTCHours()) &&\n    parsed.dayOfMonth.includes(now.getUTCDate()) &&\n    parsed.month.includes(now.getUTCMonth() + 1) &&\n    parsed.dayOfWeek.includes(now.getUTCDay())\n  );\n};\n\n// Generate a report\nconst generateReport = (jobName: string): Effect.Effect<ScheduledReport> =>\n  Effect.gen(function* () {\n    yield* Console.log(`[REPORT] Generating ${jobName}...`);\n\n    // Simulate report generation\n    yield* Effect.sleep(\"100 millis\");\n\n    return {\n      timestamp: new Date(),\n      jobName,\n      result: `Report generated at ${new Date().toISOString()}`,\n    };\n  });\n\n// Schedule with cron expression\nconst scheduleWithCron = (config: ReportConfig) =>\n  Effect.gen(function* () {\n    const parsed = parseCronExpression(config.cronExpression);\n\n    yield* Console.log(\n      `[SCHEDULER] Scheduling job: ${config.jobName}`\n    );\n    yield* Console.log(`[SCHEDULER] Cron: ${config.cronExpression}`);\n    yield* Console.log(`[SCHEDULER] Timezone: ${config.timezone || \"UTC\"}\\n`);\n\n    // Create schedule that checks every minute\n    const schedule = Schedule.fixed(\"1 minute\").pipe(\n      Schedule.untilInputEffect((report: ScheduledReport) =>\n        Effect.gen(function* () {\n          const isPastTime = shouldRunNow(parsed);\n\n          if (isPastTime) {\n            yield* Console.log(\n              `[SCHEDULED] ✓ Running at ${report.timestamp.toISOString()}`\n            );\n            return true; // Stop scheduling\n          }\n\n          return false; // Continue scheduling\n        })\n      )\n    );\n\n    // Generate report with cron schedule\n    yield* generateReport(config.jobName).pipe(\n      Effect.repeat(schedule)\n    );\n  });\n\n// Demonstrate multiple cron schedules\nconst program = Effect.gen(function* () {\n  console.log(\n    `\\n[START] Scheduling multiple jobs with cron expressions\\n`\n  );\n\n  // Schedule examples (note: in real app, these would run at actual times)\n  const jobs = [\n    {\n      cronExpression: \"0 9 * * 1-5\", // 9 AM weekdays\n      jobName: \"Daily Standup Report\",\n      timezone: \"America/New_York\",\n    },\n    {\n      cronExpression: \"0 0 * * *\", // Midnight daily\n      jobName: \"Nightly Backup\",\n      timezone: \"UTC\",\n    },\n    {\n      cronExpression: \"0 0 1 * *\", // Midnight on 1st of month\n      jobName: \"Monthly Summary\",\n      timezone: \"Europe/London\",\n    },\n  ];\n\n  yield* Console.log(\"[JOBS] Scheduled:\");\n  jobs.forEach((job) => {\n    console.log(\n      `  - ${job.jobName}: ${job.cronExpression} (${job.timezone})`\n    );\n  });\n});\n\nEffect.runPromise(program);\n```\n\n---\n\n**Rationale:**\n\nUse cron expressions for scheduling that aligns with business calendars:\n\n- **Hourly backups**: `0 * * * *` (at :00 every hour)\n- **Daily reports**: `0 9 * * 1-5` (9 AM weekdays)\n- **Monthly cleanup**: `0 0 1 * *` (midnight on 1st of month)\n- **Business hours**: `0 9-17 * * 1-5` (9 AM-5 PM, Mon-Fri)\n\nFormat: `minute hour day month weekday`\n\n---\n\n\nFixed intervals don''t align with business needs:\n\n**Fixed interval** (every 24 hours):\n- If task takes 2 hours, next run is 26 hours later\n- Drifts over time\n- No alignment with calendar\n- Fails during daylight saving time changes\n\n**Cron expressions**:\n- Specific calendar times (e.g., always 9 AM)\n- Independent of execution duration\n- Aligns with business hours\n- Natural DST handling (clock adjusts, cron resyncs)\n- Human-readable vs. milliseconds\n\nReal-world example: Daily report at 9 AM\n- **Fixed interval**: Scheduled at 9:00, takes 1 hour → next at 10:00 → drift until 5 PM\n- **Cron `0 9 * * *`**: Always runs at 9:00 regardless of duration or previous delays\n\n---\n\n---\n\n\n## 🟠 Advanced Patterns\n\n### Scheduling Pattern 5: Advanced Retry Chains and Circuit Breakers\n\n**Rule:** Use retry chains with circuit breakers to handle complex failure scenarios, detect cascade failures early, and prevent resource exhaustion.\n\n**Good Example:**\n\nThis example demonstrates circuit breaker and fallback chain patterns.\n\n```typescript\nimport { Effect, Schedule, Ref, Data } from \"effect\";\n\n// Error classification\nclass RetryableError extends Data.TaggedError(\"RetryableError\")<{\n  message: string;\n  code: string;\n}> {}\n\nclass NonRetryableError extends Data.TaggedError(\"NonRetryableError\")<{\n  message: string;\n  code: string;\n}> {}\n\nclass CircuitBreakerOpenError extends Data.TaggedError(\"CircuitBreakerOpenError\")<{\n  message: string;\n}> {}\n\n// Circuit breaker state\ninterface CircuitBreakerState {\n  status: \"closed\" | \"open\" | \"half-open\";\n  failureCount: number;\n  lastFailureTime: Date | null;\n  successCount: number;\n}\n\n// Create circuit breaker\nconst createCircuitBreaker = (config: {\n  failureThreshold: number;\n  resetTimeoutMs: number;\n  halfOpenRequests: number;\n}) =>\n  Effect.gen(function* () {\n    const state = yield* Ref.make<CircuitBreakerState>({\n      status: \"closed\",\n      failureCount: 0,\n      lastFailureTime: null,\n      successCount: 0,\n    });\n\n    const recordSuccess = Effect.gen(function* () {\n      yield* Ref.modify(state, (s) => {\n        if (s.status === \"half-open\") {\n          return [\n            undefined,\n            {\n              ...s,\n              successCount: s.successCount + 1,\n              status: s.successCount + 1 >= config.halfOpenRequests\n                ? \"closed\"\n                : \"half-open\",\n              failureCount: 0,\n            },\n          ];\n        }\n        return [undefined, s];\n      });\n    });\n\n    const recordFailure = Effect.gen(function* () {\n      yield* Ref.modify(state, (s) => {\n        const newFailureCount = s.failureCount + 1;\n        const newStatus = newFailureCount >= config.failureThreshold\n          ? \"open\"\n          : s.status;\n\n        return [\n          undefined,\n          {\n            ...s,\n            failureCount: newFailureCount,\n            lastFailureTime: new Date(),\n            status: newStatus,\n          },\n        ];\n      });\n    });\n\n    const canExecute = Effect.gen(function* () {\n      const current = yield* Ref.get(state);\n\n      if (current.status === \"closed\") {\n        return true;\n      }\n\n      if (current.status === \"open\") {\n        const timeSinceFailure = Date.now() - (current.lastFailureTime?.getTime() ?? 0);\n\n        if (timeSinceFailure > config.resetTimeoutMs) {\n          yield* Ref.modify(state, (s) => [\n            undefined,\n            {\n              ...s,\n              status: \"half-open\",\n              failureCount: 0,\n              successCount: 0,\n            },\n          ]);\n          return true;\n        }\n\n        return false;\n      }\n\n      // half-open: allow limited requests\n      return true;\n    });\n\n    return { recordSuccess, recordFailure, canExecute, state };\n  });\n\n// Main example\nconst program = Effect.gen(function* () {\n  console.log(`\\n[ADVANCED RETRY] Circuit breaker and fallback chains\\n`);\n\n  // Create circuit breaker\n  const cb = yield* createCircuitBreaker({\n    failureThreshold: 3,\n    resetTimeoutMs: 1000,\n    halfOpenRequests: 2,\n  });\n\n  // Example 1: Circuit breaker in action\n  console.log(`[1] Circuit breaker state transitions:\\n`);\n\n  let requestCount = 0;\n\n  const callWithCircuitBreaker = (shouldFail: boolean) =>\n    Effect.gen(function* () {\n      const canExecute = yield* cb.canExecute;\n\n      if (!canExecute) {\n        yield* Effect.fail(\n          new CircuitBreakerOpenError({\n            message: \"Circuit breaker is open\",\n          })\n        );\n      }\n\n      requestCount++;\n\n      if (shouldFail) {\n        yield* cb.recordFailure;\n        yield* Effect.log(\n          `[REQUEST ${requestCount}] FAILED (Circuit: ${(yield* Ref.get(cb.state)).status})`\n        );\n        yield* Effect.fail(\n          new RetryableError({\n            message: \"Service error\",\n            code: \"500\",\n          })\n        );\n      } else {\n        yield* cb.recordSuccess;\n        yield* Effect.log(\n          `[REQUEST ${requestCount}] SUCCESS (Circuit: ${(yield* Ref.get(cb.state)).status})`\n        );\n        return \"success\";\n      }\n    });\n\n  // Simulate failures then recovery\n  const failSequence = [true, true, true, false, false, false];\n\n  for (const shouldFail of failSequence) {\n    yield* callWithCircuitBreaker(shouldFail).pipe(\n      Effect.catchAll((error) =>\n        Effect.gen(function* () {\n          if (error._tag === \"CircuitBreakerOpenError\") {\n            yield* Effect.log(\n              `[REQUEST ${requestCount + 1}] REJECTED (Circuit open)`\n            );\n          } else {\n            yield* Effect.log(\n              `[REQUEST ${requestCount + 1}] ERROR caught`\n            );\n          }\n        })\n      )\n    );\n\n    // Add delay between requests\n    yield* Effect.sleep(\"100 millis\");\n  }\n\n  // Example 2: Fallback chain\n  console.log(`\\n[2] Fallback chain (primary → secondary → cache):\\n`);\n\n  const endpoints = {\n    primary: \"https://api.primary.com/data\",\n    secondary: \"https://api.secondary.com/data\",\n    cache: \"cached-data\",\n  };\n\n  const callEndpoint = (name: string, shouldFail: boolean) =>\n    Effect.gen(function* () {\n      yield* Effect.log(`[CALL] Trying ${name}`);\n\n      if (shouldFail) {\n        yield* Effect.sleep(\"50 millis\");\n        yield* Effect.fail(\n          new RetryableError({\n            message: `${name} failed`,\n            code: \"500\",\n          })\n        );\n      }\n\n      yield* Effect.sleep(\"50 millis\");\n      return `data-from-${name}`;\n    });\n\n  const fallbackChain = callEndpoint(\"primary\", true).pipe(\n    Effect.orElse(() => callEndpoint(\"secondary\", false)),\n    Effect.orElse(() => {\n      yield* Effect.log(`[FALLBACK] Using cached data`);\n      return Effect.succeed(endpoints.cache);\n    })\n  );\n\n  const result = yield* fallbackChain;\n\n  yield* Effect.log(`[RESULT] Got: ${result}\\n`);\n\n  // Example 3: Error-specific retry strategy\n  console.log(`[3] Error classification and adaptive retry:\\n`);\n\n  const classifyError = (code: string) => {\n    if ([\"502\", \"503\", \"504\"].includes(code)) {\n      return \"retryable-service-error\";\n    }\n    if ([\"408\", \"429\"].includes(code)) {\n      return \"retryable-rate-limit\";\n    }\n    if ([\"404\", \"401\", \"403\"].includes(code)) {\n      return \"non-retryable\";\n    }\n    if (code === \"timeout\") {\n      return \"retryable-network\";\n    }\n    return \"unknown\";\n  };\n\n  const errorCodes = [\"500\", \"404\", \"429\", \"503\", \"timeout\"];\n\n  for (const code of errorCodes) {\n    const classification = classifyError(code);\n    const shouldRetry = !classification.startsWith(\"non-retryable\");\n\n    yield* Effect.log(\n      `[ERROR ${code}] → ${classification} (Retry: ${shouldRetry})`\n    );\n  }\n\n  // Example 4: Bulkhead pattern\n  console.log(`\\n[4] Bulkhead isolation (limit concurrency per endpoint):\\n`);\n\n  const bulkheads = {\n    \"primary-api\": { maxConcurrent: 5, currentCount: 0 },\n    \"secondary-api\": { maxConcurrent: 3, currentCount: 0 },\n  };\n\n  const acquirePermit = (endpoint: string) =>\n    Effect.gen(function* () {\n      const bulkhead = bulkheads[endpoint as keyof typeof bulkheads];\n\n      if (!bulkhead) {\n        return false;\n      }\n\n      if (bulkhead.currentCount < bulkhead.maxConcurrent) {\n        bulkhead.currentCount++;\n        return true;\n      }\n\n      yield* Effect.log(\n        `[BULKHEAD] ${endpoint} at capacity (${bulkhead.currentCount}/${bulkhead.maxConcurrent})`\n      );\n\n      return false;\n    });\n\n  // Simulate requests\n  for (let i = 0; i < 10; i++) {\n    const endpoint = i < 6 ? \"primary-api\" : \"secondary-api\";\n    const acquired = yield* acquirePermit(endpoint);\n\n    if (acquired) {\n      yield* Effect.log(\n        `[REQUEST] Acquired permit for ${endpoint}`\n      );\n    }\n  }\n});\n\nEffect.runPromise(program);\n```\n\n---\n\n**Rationale:**\n\nAdvanced retry strategies handle multiple failure types:\n\n- **Circuit breaker**: Stop retrying when error rate is high\n- **Bulkhead**: Limit concurrency per operation\n- **Fallback chain**: Try multiple approaches in order\n- **Adaptive retry**: Adjust strategy based on failure pattern\n- **Health checks**: Verify recovery before resuming\n\nPattern: Combine `Schedule.retry`, `Ref` state, and error classification\n\n---\n\n\nSimple retry fails in production:\n\n**Scenario 1: Cascade Failure**\n- Service A calls Service B (down)\n- Retries pile up, consuming resources\n- A gets overloaded trying to recover B\n- System collapses\n\n**Scenario 2: Mixed Failures**\n- 404 (not found) - retrying won''t help\n- 500 (server error) - retrying might help\n- Network timeout - retrying might help\n- Same retry strategy for all = inefficient\n\n**Scenario 3: Thundering Herd**\n- 10,000 clients all retrying at once\n- Server recovers, gets hammered again\n- Needs coordinated backoff + jitter\n\nSolutions:\n\n**Circuit breaker**:\n- Monitor error rate\n- Stop requests when high\n- Resume gradually\n- Prevent cascade failures\n\n**Fallback chain**:\n- Try primary endpoint\n- Try secondary endpoint\n- Use cache\n- Return degraded result\n\n**Adaptive retry**:\n- Classify error type\n- Use appropriate strategy\n- Skip unretryable errors\n- Adjust backoff dynamically\n\n---\n\n---\n\n\n"},"lastSynced":"2026-03-08T02:03:15.779Z","agentAnalysis":{"suitability":{"en":"Ideal for Effect-TS Agents requiring efficient scheduling of periodic tasks and best practices implementation.","zh":"适用于需要高效地调度周期性任务和实施最佳实践的 Effect-TS 代理。","ja":"Effect-TS エージェントが周期的なタスクの効率的なスケジューリングとベストプラクティスの実装を必要とする場合に適しています。","ko":"정기적인 작업을 효율적으로 예약하고 최고의实践을 구현해야 하는 Effect-TS 에이전트에 적합합니다.","es":"Ideal para Agentes Effect-TS que requieren una programación eficiente de tareas periódicas y la implementación de las mejores prácticas.","fr":"Idéal pour les agents Effect-TS nécessitant une planification efficace de tâches périodiques et une mise en œuvre des meilleures pratiques.","de":"Ideal für Effect-TS-Agents, die eine effiziente Planung von periodischen Aufgaben und die Umsetzung von Best Practices erfordern.","pt":"Ideal para Agentes Effect-TS que exigem agendamento eficiente de tarefas periódicas e implementação de melhores práticas.","ru":"Идеально для агентов Effect-TS, требующих эффективного планирования периодических задач и реализации最佳 практик.","ar":"مثالي للوكلاء Effect-TS الذين يتطلبون جدولة فعالة للمهام الدورية وتنفيذ أفضل الممارسات."},"recommendation":{"en":"Empowers agents to utilize curated Effect-TS patterns for scheduling periodic tasks, including debounce and throttle execution, enhancing their ability to manage tasks effectively using Effect-TS applications and real-world patterns.","zh":"赋予代理使用 Effect-TS 模式来调度周期性任务的能力，包括去抖和节流执行，从而提高其使用 Effect-TS 应用程序和现实世界模式有效管理任务的能力。","ja":"エージェントが Effect-TS パターンを使用して周期的なタスクをスケジュールし、デバウンスとスロットル実行を含む機能を提供し、Effect-TS アプリケーションとリアルワールド パターンを使用してタスクを効果的に管理する能力を高めることができます。","ko":"에이전트가 Effect-TS 패턴을 사용하여 정기적인 작업을 예약할 수 있으며, 디바운스 및 스로틀 실행을 포함하여 Effect-TS 애플리케이션 및 실제 패턴을 사용하여 작업을 효과적으로 관리할 수 있는 기능을 제공합니다.","es":"Permite a los agentes utilizar patrones Effect-TS curados para programar tareas periódicas, incluyendo la ejecución con debounce y throttle, lo que mejora su capacidad para gestionar tareas de manera efectiva utilizando aplicaciones y patrones del mundo real de Effect-TS.","fr":"Permet aux agents d''utiliser des modèles Effect-TS curés pour planifier des tâches périodiques, y compris l''exécution avec debounce et throttle, améliorant ainsi leur capacité à gérer les tâches de manière efficace en utilisant des applications et des modèles du monde réel d''Effect-TS.","de":"Ermächtigt die Agenten, kuratierte Effect-TS-Muster für die Planung von periodischen Aufgaben zu nutzen, einschließlich der Ausführung mit debounce und throttle, was ihre Fähigkeit verbessert, Aufgaben effektiv zu verwalten, indem sie Effect-TS-Anwendungen und Echtzeitmuster verwenden.","pt":"Habilita os agentes a utilizarem padrões curados Effect-TS para agendar tarefas periódicas, incluindo execução com debounce e throttle, melhorando sua capacidade de gerenciar tarefas de forma eficaz usando aplicações e padrões do mundo real Effect-TS.","ru":"Наделяет агентов возможностью использовать отобранные шаблоны Effect-TS для планирования периодических задач, включая выполнение с debounce и throttle, повышая их способность эффективно управлять задачами с помощью приложений и реальных шаблонов Effect-TS.","ar":"يمنح الوكلاء القدرة على استخدام أنماط Effect-TS المعدة لجدولة المهام الدورية، بما في ذلك تنفيذ الإبطاء والتثبيط، مما يعزز قدرتهم على إدارة المهام بفعالية باستخدام تطبيقات وأنماط العالم الحقيقي Effect-TS."},"useCases":{"en":["Scheduling recurring tasks with precision","Implementing best practices in Effect-TS applications","Optimizing task execution frequency with debounce and throttle techniques"],"zh":["使用精度调度重复任务","在 Effect-TS 应用程序中实施最佳实践","使用去抖和节流技术优化任务执行频率"],"ja":["精度の高い周期的なタスクのスケジューリング","Effect-TS アプリケーションでのベストプラクティスの実装","デバウンスとスロットル技術を使用したタスク実行頻度の最適化"],"ko":["정밀한 반복 작업 예약","Effect-TS 애플리케이션에서 최고의 실践을 구현","디바운스 및 스로틀 기술을 사용한 작업 실행 빈도 최적화"],"es":["Programación de tareas recurrentes con precisión","Implementación de las mejores prácticas en aplicaciones Effect-TS","Optimización de la frecuencia de ejecución de tareas con técnicas de debounce y throttle"],"fr":["Planification de tâches récurrentes avec précision","Mise en œuvre de meilleures pratiques dans les applications Effect-TS","Optimisation de la fréquence d''exécution des tâches avec des techniques de debounce et throttle"],"de":["Planung von wiederkehrenden Aufgaben mit Präzision","Umsetzung von Best Practices in Effect-TS-Anwendungen","Optimierung der Ausführungshäufigkeit von Aufgaben mit debounce- und throttle-Techniken"],"pt":["Agendamento de tarefas recorrentes com precisão","Implementação de melhores práticas em aplicações Effect-TS","Otimização da frequência de execução de tarefas com técnicas de debounce e throttle"],"ru":["Планирование повторяющихся задач с точностью","Реализация лучших практик в приложениях Effect-TS","Оптимизация частоты выполнения задач с помощью техник debounce и throttle"],"ar":["جدولة المهام المتكررة بدقة","تنفيذ أفضل الممارسات في تطبيقات Effect-TS","تحسين تردد تنفيذ المهام باستخدام تقنيات الإبطاء والتثبيط"]},"limitations":{"en":["Requires understanding of Effect-TS patterns and applications","Limited to scheduling periodic tasks"],"zh":["需要了解 Effect-TS 模式和应用程序","仅限于调度周期性任务"],"ja":["Effect-TS パターンとアプリケーションの理解が必要","周期的なタスクのスケジューリングのみ"],"ko":["Effect-TS 패턴 및 애플리케이션에 대한 이해가 필요","주기적인 작업 예약만"],"es":["Requiere una comprensión de los patrones y aplicaciones Effect-TS","Limitado a la programación de tareas periódicas"],"fr":["Nécessite une compréhension des modèles et des applications Effect-TS","Limité à la planification de tâches périodiques"],"de":["Erfordert ein Verständnis von Effect-TS-Mustern und -Anwendungen","Begrenzt auf die Planung von periodischen Aufgaben"],"pt":["Exige compreensão de padrões e aplicações Effect-TS","Limitado ao agendamento de tarefas periódicas"],"ru":["Требует понимания шаблонов и приложений Effect-TS","Ограничен планированием периодических задач"],"ar":["يتطلب فهم أنماط وتطبيقات Effect-TS","محدود بجدولة المهام الدورية"]},"version":4},"contentHash":"2a13914b47db688bdd1705a78a6ed6d1965f35c90a558f8e3a46471f76e1d295","qualityScore":39}');
